const SettingsView: React.FC<SettingsProps> = ({ state, setState, addLog }) => {
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [newCatName, setNewCatName] = useState('');
  const [showPassInForm, setShowPassInForm] = useState(false);

  const currentUser = state.currentUser;
  const isGlobalManager = currentUser?.role === 'مدير';

  const [userFormData, setUserFormData] = useState<Partial<AppUser>>({
    username: '',
    role: 'إداري فئة',
    password: '',
    restrictedCategory: ''
  });

  const roles: UserRole[] = ['مدير', 'إداري فئة', 'مشاهد'];

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userFormData.username || !userFormData.password) return alert('يرجى إكمال كافة البيانات المطلوبة');

    if (editingUserId) {
      setState(prev => ({
        ...prev,
        users: prev.users.map(u => u.id === editingUserId ? { ...u, ...userFormData } as AppUser : u)
      }));
      addLog?.('تعديل صلاحية مستخدم', `تم تحديث بيانات المستخدم: ${userFormData.username}`, 'info');
    } else {
      const newUser: AppUser = {
        id: generateUUID(),
        username: userFormData.username!.trim(),
        role: userFormData.role as UserRole,
        password: userFormData.password!,
        restrictedCategory: userFormData.role === 'إداري فئة' ? userFormData.restrictedCategory : undefined
      };
      setState(prev => ({ ...prev, users: [...prev.users, newUser] }));
      addLog?.('إنشاء حساب مستخدم', `تم إنشاء مستخدم جديد بنجاح: ${newUser.username} برتبة ${newUser.role}`, 'success');
    }

    setIsUserModalOpen(false);
    setEditingUserId(null);
    setUserFormData({ username: '', role: 'إداري فئة', password: '', restrictedCategory: '' });
  };

  const handleAddCategory = () => {
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) return alert('هذه الفئة موجودة مسبقاً في النظام.');

    setState(prev => ({ ...prev, categories: [...prev.categories, newCatName.trim()] }));
    addLog?.('إضافة فئة رياضية', `تم إدراج فئة جديدة بالنظام: ${newCatName.trim()}`, 'success');
    setNewCatName('');
  };

  const removeCategory = (cat: string) => {
    if (confirm(`هل أنت متأكد من حذف فئة ${cat}؟ سيتم فصل كافة اللاعبين المرتبطين بها.`)) {
      setState(prev => ({ ...prev, categories: prev.categories.filter(c => c !== cat) }));
      addLog?.('حذف فئة رياضية', `تم مسح الفئة: ${cat}`, 'warning');
    }
  };

  const exportData = () => {
    const dataStr = JSON.stringify(state, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `alkaramah_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    addLog?.('تصدير قاعدة البيانات', 'تم إنشاء وتنزيل نسخة احتياطية شاملة للنظام.');
  };

  const deleteUser = async (id: string, name: string) => {
    if (name.toUpperCase() === 'IZZAT') return alert('لا يمكن حذف الحساب الجذري للنظام.');
    if (confirm(`هل أنت متأكد من حذف حساب ${name}؟`)) {
      await supabase.from('users').delete().eq('id', id);
      setState(p => ({ ...p, users: p.users.filter(u => u.id !== id) }));
      addLog?.('حذف مستخدم', `تم حذف حساب المستخدم: ${name}`, 'error');
    }
  };

  const labelClass = "text-[10px] font-black text-slate-500 mr-2 uppercase block mb-1.5";
  const fieldClass = "w-full bg-slate-50 border-2 border-slate-200 rounded-xl py-3 px-4 font-black text-slate-800 outline-none focus:border-orange-600 transition-all";

  return (
    <div className="max-w-6xl mx-auto space-y-12 pb-24">
      {isGlobalManager && (
        <div className="bg-white p-10 rounded-[3rem] shadow-sm border-2 border-slate-900">
           <div className="flex justify-between items-center mb-8">
              <div>
                <h3 className="text-2xl font-black text-slate-900 flex items-center gap-3">
                  <ShieldCheck size={28} className="text-[#001F3F]" /> مركز التحكم في الحسابات والأدوار
                </h3>
                <p className="text-[10px] font-black text-slate-400 mt-1 uppercase tracking-widest">إدارة الدخول، الصلاحيات، وكلمات السر (خاص بالمديرين)</p>
              </div>
              <button onClick={() => { setEditingUserId(null); setIsUserModalOpen(true); }} className="bg-[#001F3F] text-white px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg border-b-4 border-black">
                <UserPlus size={18}/> إضافة حساب جديد
              </button>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {state.users.map(user => (
                <div key={user.id} className="bg-slate-50 p-6 rounded-[2rem] border-2 border-slate-200 relative overflow-hidden group">
                   <div className="absolute top-0 right-0 w-1.5 h-full bg-[#001F3F]"></div>
                   <div className="flex justify-between items-start mb-4">
                      <div className="w-10 h-10 bg-white border border-slate-200 rounded-xl flex items-center justify-center">
                         <Key size={18} className="text-orange-600"/>
                      </div>
                      <span className={`text-[9px] font-black px-3 py-1 rounded-lg uppercase border ${user.role === 'مدير' ? 'bg-orange-600 text-white border-orange-700' : user.role === 'مشاهد' ? 'bg-slate-200 text-slate-600' : 'bg-[#001F3F] text-white border-black'}`}>
                        {user.role}
                      </span>
                   </div>
                   <h4 className="font-black text-lg text-slate-900">{user.username}</h4>
                   <p className="text-[9px] font-black text-slate-400 mt-1 uppercase tracking-tighter">
                      {user.restrictedCategory ? `مخصص لفئة: ${user.restrictedCategory}` : 'صلاحيات وصول شاملة'}
                   </p>
                   <div className="mt-6 pt-4 border-t border-slate-200 flex justify-between items-center">
                      <p className="text-[10px] font-black text-slate-300">PASS: {user.password ? '****' : 'N/A'}</p>
                      <div className="flex gap-2">
                         <button onClick={() => { setEditingUserId(user.id); setUserFormData(user); setIsUserModalOpen(true); }} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"><Edit2 size={16}/></button>
                         {user.username.toUpperCase() !== 'IZZAT' && (
                           <button onClick={() => deleteUser(user.id, user.username)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={16}/></button>
                         )}
                      </div>
                   </div>
                </div>
              ))}
           </div>
        </div>
      )}

      <div className="bg-white p-12 rounded-[4rem] shadow-sm border border-slate-100">
        <h3 className="text-3xl font-black text-slate-800 mb-10">إدارة الفئات الرياضية</h3>
        <div className="flex flex-col md:flex-row gap-6 mb-12">
          <input 
            type="text" 
            value={newCatName} 
            onChange={e => setNewCatName(e.target.value)}
            placeholder="مثال: فئة البراعم.."
            className="flex-1 bg-slate-50 border-4 border-slate-100 rounded-[2rem] p-6 font-black text-2xl outline-none focus:border-orange-600 transition-all"
          />
          <button 
            onClick={handleAddCategory}
            disabled={!isGlobalManager}
            className="bg-[#001F3F] text-white px-12 py-6 rounded-[2rem] font-black disabled:opacity-30"
          >
            تثبيت الفئة الجديدة
          </button>
        </div>
        <div className="flex flex-wrap gap-4">
           {state.categories.map(cat => (
             <div key={cat} className="bg-slate-50 border-2 border-slate-200 px-6 py-3 rounded-2xl flex items-center gap-4 group">
                <span className="font-black text-slate-700">{cat}</span>
                {isGlobalManager && (
                  <button onClick={() => removeCategory(cat)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-opacity"><X size={16}/></button>
                )}
             </div>
           ))}
        </div>
      </div>

      <div className="bg-[#001F3F] p-16 rounded-[5rem] shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-32 -mt-32"></div>
        <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-10">
           <div className="text-white">
              <h3 className="text-3xl font-black mb-2">نسخة الحماية والنسخ الاحتياطي</h3>
              <p className="font-black text-orange-400 uppercase tracking-widest text-sm">تصدير كافة البيانات المسجلة على النظام في ملف واحد</p>
           </div>
           <button onClick={exportData} className="bg-white text-[#001F3F] font-black px-12 py-6 rounded-[2.5rem] flex items-center justify-center gap-5 text-2xl shadow-xl hover:scale-105 transition-all">
             <Database size={32}/> تصدير قاعدة البيانات (JSON)
           </button>
        </div>
      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/90 backdrop-blur-3xl flex items-center justify-center z-[500] p-6 no-print overflow-y-auto">
          <div className="bg-white rounded-[4rem] w-full max-w-xl shadow-2xl border-[10px] border-white p-12">
            <div className="flex justify-between items-center mb-10">
               <h3 className="text-2xl font-black text-[#001F3F] uppercase tracking-tighter">إعدادات دخول الحساب</h3>
               <button onClick={() => setIsUserModalOpen(false)} className="bg-slate-100 p-3 rounded-full"><X/></button>
            </div>
            <form onSubmit={handleSaveUser} className="space-y-6">
              <div>
                <label className={labelClass}>اسم المستخدم (الاسم الحقيقي أو الكنية)</label>
                <input required type="text" value={userFormData.username || ''} onChange={e => setUserFormData({ ...userFormData, username: e.target.value })}
                  className={fieldClass} placeholder="مثال: Ahmed_KSC" />
              </div>

              <div>
                <label className={labelClass}>كلمة المرور الخاصة بالحساب</label>
                <div className="relative">
                   <input required type={showPassInForm ? "text" : "password"} value={userFormData.password || ''} onChange={e => setUserFormData({ ...userFormData, password: e.target.value })}
                    className={fieldClass} placeholder="اكتب كلمة سر قوية.." />
                   <button type="button" onClick={() => setShowPassInForm(!showPassInForm)} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
                      {showPassInForm ? <EyeOff size={20}/> : <Eye size={20}/>}
                   </button>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className={labelClass}>رتبة الصلاحية</label>
                    <select className={fieldClass}
                      value={userFormData.role} onChange={e => setUserFormData({ ...userFormData, role: e.target.value as UserRole, restrictedCategory: '' })}>
                      {roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                 </div>
                 {userFormData.role === 'إداري فئة' && (
                    <div>
                      <label className={labelClass}>الفئة المخصصة</label>
                      <select required className={fieldClass}
                        value={userFormData.restrictedCategory} onChange={e => setUserFormData({ ...userFormData, restrictedCategory: e.target.value })}>
                        <option value="">-- اختر الفئة --</option>
                        {state.categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                      </select>
                    </div>
                 )}
              </div>

              <div className="bg-blue-50 p-4 rounded-2xl border-2 border-blue-100 flex items-start gap-3">
                 <ShieldAlert className="text-blue-600 shrink-0" size={20}/>
                 <p className="text-[10px] font-black text-blue-900 leading-relaxed uppercase">
                    تنبيه: "إداري الفئة" سيقتصر وصوله فقط على البيانات الخاصة بفئته المحددة أعلاه، ولن يتمكن من تعديل الحضور بعد رصده للمرة الأولى.
                 </p>
              </div>

              <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-6 rounded-[2.5rem] shadow-2xl text-2xl hover:bg-black transition-all">
                {editingUserId ? 'تحديث بيانات الحساب' : 'تثبيت الحساب في النظام'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Users, Calendar, ClipboardCheck, LayoutDashboard, Settings, LogOut, Menu, X, Trophy, Bell, RefreshCw, User, CloudCheck, CloudOff, Cloud
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { AppUser, AppState, Person, AppNotification } from './types';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';

// Helper: Standard UUID v4 Generator for Supabase Compatibility
export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

// Supabase Configuration
const supabaseUrl = 'https://kfwqoigsghlgigjriyxf.supabase.co';
const supabaseAnonKey = 'sb_publishable_O2vR2yKUG-FVeaydD4z6Lg_tjFcKDic';
export const supabase = createClient(supabaseUrl, supabaseAnonKey);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'error' | 'syncing'>('synced');

  const [state, setState] = useState<AppState>(() => {
    const defaultAdmin: AppUser = { id: generateUUID(), username: 'IZZAT', role: 'مدير', password: 'KSC@2026' };
    const saved = localStorage.getItem('alkarama_cloud_v4');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return { ...parsed, currentUser: null }; 
      } catch (e) { console.error(e); }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      attendance: [],
      users: [defaultAdmin],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  useEffect(() => {
    localStorage.setItem('alkarama_cloud_v4', JSON.stringify(state));
  }, [state]);

  const addLog = useCallback((message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: generateUUID(),
      message, details, type, timestamp: Date.now(), isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  }, []);

  const sanitize = (data: any[]) => {
    return data.map(item => {
      const cleanItem = JSON.parse(JSON.stringify(item));
      Object.keys(cleanItem).forEach(key => {
        if (cleanItem[key] === undefined || cleanItem[key] === "") {
          cleanItem[key] = null;
        }
      });
      return cleanItem;
    });
  };

  const fetchData = useCallback(async () => {
    if (!state.currentUser) return;

    setIsSyncing(true);
    setSyncStatus('syncing');
    try {
      const [
        { data: cats },
        { data: ppl },
        { data: sess },
        { data: mtch },
        { data: attn },
        { data: usrs }
      ] = await Promise.all([
        supabase.from('categories').select('name'),
        supabase.from('people').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
        supabase.from('users').select('*'),
      ]);

      setState(prev => ({
        ...prev,
        categories: (cats && cats.length > 0) ? cats.map(c => c.name) : prev.categories,
        people: ppl || [],
        sessions: sess || [],
        matches: mtch || [],
        attendance: attn || [],
        users: usrs || prev.users
      }));
      setSyncStatus('synced');
    } catch (error: any) {
      console.error("❌ Fetch Error:", error);
      setSyncStatus('error');
      addLog('خطأ في جلب البيانات', error.message || 'فشل الوصول للسحاب.', 'error');
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser, addLog]);

  // Realtime Listener Logic
  useEffect(() => {
    if (!state.currentUser) return;

    const tables = ['people', 'sessions', 'matches', 'attendance', 'users'];
    const channels = tables.map(tableName => {
      return supabase
        .channel(`public:${tableName}-changes`)
        .on('postgres_changes', { event: '*', schema: 'public', table: tableName }, () => {
          fetchData();
        })
        .subscribe();
    });

    return () => {
      channels.forEach(channel => supabase.removeChannel(channel));
    };
  }, [state.currentUser, fetchData]);

  const pushData = useCallback(async (updatedState: AppState) => {
    if (!updatedState.currentUser) return;

    setSyncStatus('syncing');
    try {
      const tables = [
        { name: 'people', data: updatedState.people },
        { name: 'sessions', data: updatedState.sessions },
        { name: 'matches', data: updatedState.matches },
        { name: 'attendance', data: updatedState.attendance },
        { name: 'users', data: updatedState.users }
      ];

      for (const table of tables) {
        if (table.data.length > 0) {
          const { error } = await supabase
            .from(table.name)
            .upsert(sanitize(table.data), { onConflict: 'id' });

          if (error) {
            const msg = typeof error === 'string' ? error : (error.message || JSON.stringify(error));
            throw new Error(`${table.name}: ${msg}`);
          }
        }
      }

      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
      const errorMsg = error.message || 'خطأ غير معروف في السحاب';
      addLog('فشل مزامنة الجداول', errorMsg, 'error');
      console.error("❌ Sync Error:", errorMsg);
    }
  }, [addLog]);

  useEffect(() => {
    if (state.currentUser) {
      fetchData();
    }
  }, [state.currentUser, fetchData]);

  const updateStateAndSync = async (updater: (prev: AppState) => AppState) => {
    let nextState: AppState | null = null;
    setState(prev => {
      nextState = updater(prev);
      return nextState;
    });

    if (nextState) {
      await pushData(nextState);
    }
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setActiveTab('dashboard');
  };

  if (!state.currentUser) {
    return <Login onLogin={(user) => setState(prev => ({ ...prev, currentUser: user }))} state={state} />;
  }

  const navItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'إدارة الفريق', icon: Users },
    { id: 'attendance', label: 'نظام الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  const unreadCount = state.notifications.filter(n => !n.isRead).length;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#001F3F] text-white transform transition-transform duration-300 lg:translate-x-0 lg:static lg:inset-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print shadow-2xl`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between border-b border-white/10">
            <div className="flex items-center gap-3">
              <ClubLogo size={40} />
              <span className="font-black text-lg tracking-tight">نادي الكرامة</span>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2"><X size={24} /></button>
          </div>
          <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1 custom-scrollbar">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-orange-600 text-white shadow-lg shadow-orange-600/20' : 'text-white/70 hover:bg-white/5 hover:text-white'}`}>
                <item.icon size={20} />
                <span className="font-bold">{item.label}</span>
              </button>
            ))}
          </nav>
          <div className="p-4 border-t border-white/10">
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-400/10 transition-colors font-bold">
              <LogOut size={20} /> <span>تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/90 backdrop-blur-md border-b sticky top-0 z-40 px-4 lg:px-8 py-4 flex items-center justify-between shadow-sm no-print">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 bg-slate-100 rounded-lg"><Menu size={24} /></button>
            <h1 className="text-xl font-black text-slate-800">
              {navItems.find(i => i.id === activeTab)?.label || (activeTab === 'report' ? 'التقرير الفني' : 'تفاصيل')}
            </h1>
          </div>

          <div className="flex items-center gap-4">
            {/* Sync Status Indicator */}
            <div className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-slate-50 border border-slate-100 transition-all duration-300">
              {syncStatus === 'synced' ? (
                <div className="flex items-center gap-1.5 text-emerald-600" title="تمت المزامنة بنجاح">
                  <CloudCheck size={18} />
                  <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                </div>
              ) : syncStatus === 'error' ? (
                <div className="flex items-center gap-1.5 text-red-600" title="خطأ في المزامنة">
                  <CloudOff size={18} />
                  <div className="w-2 h-2 rounded-full bg-red-500"></div>
                </div>
              ) : (
                <div className="flex items-center gap-1.5 text-orange-500" title="جاري المزامنة">
                  <Cloud size={18} className="animate-bounce" />
                </div>
              )}
            </div>

            <div className="hidden md:flex flex-col items-end px-4 border-r-2 border-orange-500">
              <span className="text-[10px] font-black text-slate-400 uppercase leading-none mb-1">المسؤول الحالي</span>
              <div className="flex items-center gap-2">
                <span className="text-sm font-black text-[#001F3F]">{state.currentUser.username}</span>
                <User size={14} className="text-orange-600" />
              </div>
            </div>

            <button onClick={fetchData} className="p-2.5 rounded-xl bg-slate-100 text-slate-600 hover:bg-slate-200 transition-all">
              <RefreshCw size={20} className={isSyncing ? 'animate-spin' : ''} />
            </button>

            <div className="relative">
              <button onClick={() => setShowNotifications(!showNotifications)} className={`p-2.5 rounded-xl relative border ${showNotifications ? 'bg-orange-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}>
                <Bell size={20} />
                {unreadCount > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-600 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white">{unreadCount}</span>}
              </button>
              {showNotifications && (
                <div className="absolute left-0 top-12 w-80 bg-white rounded-2xl shadow-2xl border-2 border-slate-900 overflow-hidden z-[100] text-right">
                  <div className="p-4 border-b bg-slate-50 flex justify-between items-center">
                    <h3 className="font-black text-xs uppercase text-slate-800">تنبيهات النظام</h3>
                    <button onClick={() => setState(p => ({ ...p, notifications: p.notifications.map(n => ({...n, isRead: true})) }))} className="text-[10px] text-blue-600 font-bold">قراءة الكل</button>
                  </div>
                  <div className="max-h-96 overflow-y-auto custom-scrollbar">
                    {state.notifications.length === 0 ? (
                      <div className="p-8 text-center text-slate-400 text-xs italic opacity-50">لا توجد تنبيهات</div>
                    ) : (
                      state.notifications.map(n => (
                        <div key={n.id} className={`p-4 border-b hover:bg-slate-50 transition-colors ${!n.isRead ? 'bg-orange-50/50' : ''}`}>
                          <p className="text-[11px] font-black text-slate-700 leading-tight">{n.message}</p>
                          <span className="text-[9px] text-slate-400 mt-1 block">{new Date(n.timestamp).toLocaleTimeString('ar-SY')}</span>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto space-y-6 pb-20">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} addLog={addLog} />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <footer className="bg-white/95 backdrop-blur-md border-t py-1.5 px-5 flex justify-between items-center no-print z-40">
           <p className="text-[7px] font-black text-slate-500 tracking-tighter">نادي الكرامة الرياضي - مكتب كرة القدم المركزي</p>
           <p className="text-[7px] font-black text-[#001F3F] border-r-2 border-orange-500 pr-2">By: Izzat Amer Al-Shikha | النسخة السحابية الموحدة (V4)</p>
        </footer>
      </main>

      {showNotifications && (
        <div className="fixed inset-0 z-30" onClick={() => setShowNotifications(false)}></div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  UserPlus, Trash2, Search, X, Shield, Award, Layers, Home, Plus, AlertCircle, Calendar,
  MapPin, Hash, UserCheck, ChevronLeft, FolderPlus, Filter, Settings2, BookOpen, Globe, CreditCard, Map,
  Briefcase, Printer, FileSpreadsheet, Eye, FileText, Users, ChevronRight
} from 'lucide-react';
import { AppState, Person, Role, Category } from '../types';
import ClubLogo from './ClubLogo';
import { generateUUID, supabase } from '../App';

interface SquadManagementProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  onOpenReport?: (player: Person) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, addLog }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [localCategoryFilter, setLocalCategoryFilter] = useState<string>('الكل');
  const [activeSubTab, setActiveSubTab] = useState<'players' | 'staff'>('players');
  const [showFullReportView, setShowFullReportView] = useState(false);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: restrictedCat || state.categories[0] || '',
    joinDate: new Date().toISOString().split('T')[0]
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return null;
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    if (isViewer) return;
    e.preventDefault();
    if (!formData.name) return;

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => {
          if (person.id === editingId) {
             const updated = { ...person, ...formData };
             return updated as Person;
          }
          return person;
        })
      }));
      addLog?.('تعديل عضو', `تم تحديث ملف العضو: ${formData.name}`, 'info');
    } else {
      const newPerson: Person = {
        id: generateUUID(),
        name: formData.name || '',
        fatherName: formData.fatherName || '',
        motherName: formData.motherName || '',
        birthDate: formData.birthDate || '',
        birthPlace: formData.birthPlace || '',
        khana: formData.khana || '',
        nationalId: formData.nationalId || '',
        federalNumber: formData.federalNumber || '',
        internationalId: formData.internationalId || '',
        address: formData.address || '',
        category: formData.category || restrictedCat || state.categories[0],
        role: formData.role || 'لاعب',
        number: formData.number || 0,
        phone: formData.phone || '',
        joinDate: formData.joinDate || new Date().toISOString().split('T')[0],
        contractStart: formData.contractStart || undefined,
        contractEnd: formData.contractEnd || undefined,
        contractValue: formData.contractValue || undefined,
        coachingCertificate: formData.coachingCertificate || undefined,
        academicDegree: formData.academicDegree || undefined,
        medicalHistory: undefined,
        injuries: undefined,
        penalties: undefined,
        notes: undefined
      };

      setState(p => ({ ...p, people: [...p.people, newPerson] }));
      addLog?.('تسجيل عضو جديد', `تم تسجيل ${newPerson.role}: ${newPerson.name}`, 'success');
    }
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleDeletePlayer = async (person: Person) => {
    if (isViewer) return;
    if (confirm(`هل أنت متأكد من حذف ${person.name}؟`)) {
      try {
        const { error } = await supabase.from('people').delete().eq('id', person.id);
        if (error) throw error;

        setState(p => ({
          ...p,
          people: p.people.filter(x => x.id !== person.id)
        }));
        addLog?.('حذف عضو', `تم مسح ملف: ${person.name}`, 'error');
      } catch (err: any) {
        alert("حدث خطأ أثناء الحذف من السحاب: " + err.message);
      }
    }
  };

  const baseFiltered = state.people.filter(p => {
    const matchCat = restrictedCat ? p.category === restrictedCat : (localCategoryFilter === 'الكل' ? true : p.category === localCategoryFilter);
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                      (p.number?.toString().includes(searchTerm));
    return matchCat && matchSearch;
  });

  const filteredPlayers = baseFiltered.filter(p => p.role === 'لاعب');
  const filteredStaff = baseFiltered.filter(p => p.role !== 'لاعب');
  const displayList = activeSubTab === 'players' ? filteredPlayers : filteredStaff;

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-2.5 px-4 font-black text-slate-900 outline-none focus:ring-4 focus:ring-orange-600/10 focus:border-orange-600 transition-all placeholder:text-slate-500 text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";

  if (showFullReportView) {
    const activeCategory = restrictedCat || localCategoryFilter;
    const reportList = baseFiltered.sort((a,b) => (a.number || 0) - (b.number || 0));
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <div className="flex justify-between items-center no-print">
           <button onClick={() => setShowFullReportView(false)} className="flex items-center gap-2 text-slate-500 font-black hover:text-[#001F3F] transition-all">
             <ChevronRight size={20}/> العودة للإدارة
           </button>
           <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-xl hover:bg-black transition-all border-b-4 border-black">
             <Printer size={18}/> طباعة الكشف PDF
           </button>
        </div>

        <div className="bg-white p-10 rounded-[2.5rem] border-4 border-slate-900 shadow-xl print:border-2 print:rounded-none print:shadow-none print:p-4">
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-6 mb-8 print:mb-4">
              <div className="flex items-center gap-4">
                 <ClubLogo size={80} />
                 <div>
                    <h2 className="text-2xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-sm font-black text-orange-600">مكتب كرة القدم المركزي</p>
                 </div>
              </div>
              <div className="text-left font-black">
                 <p className="text-xl">كشف الفئة الشامل</p>
                 <p className="text-sm text-slate-400">فئة: {activeCategory}</p>
                 <p className="text-[10px] mt-1">تاريخ الاستخراج: {new Date().toLocaleDateString('ar-SY')}</p>
              </div>
           </div>

           <div className="overflow-x-auto">
              <table className="w-full text-right border-collapse">
                 <thead>
                    <tr className="bg-slate-100 border-y-2 border-slate-900">
                       <th className="p-3 text-[10px] font-black border-l border-slate-200">الاسم الكامل</th>
                       <th className="p-3 text-[10px] font-black border-l border-slate-200 text-center">الرقم</th>
                       <th className="p-3 text-[10px] font-black border-l border-slate-200 text-center">الصفة</th>
                       <th className="p-3 text-[10px] font-black border-l border-slate-200 text-center">تاريخ الميلاد</th>
                       <th className="p-3 text-[10px] font-black border-l border-slate-200 text-center">الرقم الوطني</th>
                       <th className="p-3 text-[10px] font-black text-center">رقم القيد</th>
                    </tr>
                 </thead>
                 <tbody>
                    {reportList.map((p, idx) => (
                       <tr key={p.id} className="border-b border-slate-100 hover:bg-slate-50">
                          <td className="p-3 text-xs font-black border-l border-slate-200">{p.name}</td>
                          <td className="p-3 text-xs font-black border-l border-slate-200 text-center">{p.number || '--'}</td>
                          <td className="p-3 text-xs font-black border-l border-slate-200 text-center">{p.role}</td>
                          <td className="p-3 text-xs font-black border-l border-slate-200 text-center">{p.birthDate}</td>
                          <td className="p-3 text-xs font-black border-l border-slate-200 text-center">{p.nationalId || '--'}</td>
                          <td className="p-3 text-xs font-black text-center">{p.khana || '--'}</td>
                       </tr>
                    ))}
                 </tbody>
              </table>
           </div>

           <div className="mt-16 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">توقيع مدرب الفئة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">توقيع إداري الفئة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">مدير مكتب كرة القدم</p>
                 <p className="font-black text-xs text-blue-900">عزت عامر الشيخة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
           </div>
           <div className="mt-10 pt-4 border-t border-slate-200 text-center hidden print:block">
              <p className="text-[8px] font-black text-slate-400">وثيقة رسمية صادرة عن النظام الإلكتروني لنادي الكرامة الرياضي - مكتب كرة القدم</p>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 no-print space-y-6">
        <div className="flex flex-col lg:flex-row gap-4 items-center">
          <div className="flex-1 relative w-full">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-900" size={18} />
            <input 
              type="text" 
              placeholder="البحث بالاسم أو رقم القميص..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
              className={`${fieldClass} pr-12 h-12 text-lg`} 
            />
          </div>

          <div className="flex items-center gap-3 w-full lg:w-auto">
            {!restrictedCat && (
              <select 
                value={localCategoryFilter}
                onChange={e => setLocalCategoryFilter(e.target.value)}
                className="bg-slate-100 border-2 border-slate-900 rounded-xl py-2 pr-4 pl-10 font-black text-sm text-slate-900 outline-none h-12 appearance-none cursor-pointer hover:bg-white transition-colors min-w-[140px]"
              >
                <option value="الكل">جميع الفئات</option>
                {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            )}

            <button 
              onClick={() => {
                if (!restrictedCat && localCategoryFilter === 'الكل') { alert("يرجى اختيار فئة محددة أولاً لاستخراج الكشف الشامل."); return; }
                setShowFullReportView(true);
              }}
              className="bg-emerald-600 text-white px-6 h-12 rounded-xl font-black text-sm flex items-center gap-3 hover:bg-black transition-all shadow-lg shrink-0 border-b-4 border-black group"
            >
              <FileText size={20} className="group-hover:scale-110" /> كشف الفئة الشامل
            </button>

            {!isViewer && (
              <button 
                onClick={() => { 
                  setEditingId(null); 
                  setFormData({ role: 'لاعب', category: restrictedCat || (localCategoryFilter !== 'الكل' ? localCategoryFilter : (state.categories[0] || '')), joinDate: new Date().toISOString().split('T')[0] }); 
                  setIsModalOpen(true); 
                }} 
                className="bg-[#001F3F] text-white px-8 h-12 rounded-xl font-black text-sm flex items-center gap-3 hover:bg-black transition-all shadow-lg shrink-0 border-b-4 border-black"
              >
                <UserPlus size={20} /> إضافة عضو
              </button>
            )}
          </div>
        </div>

        <div className="flex p-1.5 bg-slate-100 border-2 border-slate-900 rounded-2xl w-fit mx-auto md:mx-0">
          <button 
            onClick={() => setActiveSubTab('players')}
            className={`flex items-center gap-2 px-8 py-2.5 rounded-xl font-black text-sm transition-all ${activeSubTab === 'players' ? 'bg-[#001F3F] text-white shadow-md scale-105' : 'text-slate-500 hover:text-slate-900'}`}
          >
            اللاعبين
            <span className={`px-2 py-0.5 rounded-md text-[10px] ${activeSubTab === 'players' ? 'bg-orange-500 text-white' : 'bg-slate-200 text-slate-600'}`}>
              {filteredPlayers.length}
            </span>
          </button>
          <button 
            onClick={() => setActiveSubTab('staff')}
            className={`flex items-center gap-2 px-8 py-2.5 rounded-xl font-black text-sm transition-all ${activeSubTab === 'staff' ? 'bg-[#001F3F] text-white shadow-md scale-105' : 'text-slate-500 hover:text-slate-900'}`}
          >
            الكوادر الفنية والإدارية
            <span className={`px-2 py-0.5 rounded-md text-[10px] ${activeSubTab === 'staff' ? 'bg-orange-500 text-white' : 'bg-slate-200 text-slate-600'}`}>
              {filteredStaff.length}
            </span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 no-print">
        {displayList.map(person => (
          <div key={person.id} className="bg-white p-5 rounded-[2rem] shadow-sm border-2 border-slate-900 group relative transition-all hover:shadow-xl border-b-[8px] hover:border-orange-600">
             <div className="flex justify-between items-start mb-4">
               <div className="w-12 h-12 bg-slate-100 border-2 border-slate-900 rounded-xl flex items-center justify-center font-black text-slate-900 text-lg shadow-inner group-hover:bg-[#001F3F] group-hover:text-white transition-colors">
                 {person.name.charAt(0).toUpperCase()}
               </div>
               <div className="flex flex-col items-end">
                  <span className={`text-[10px] font-black px-3 py-1 rounded-lg uppercase tracking-wider ${person.role === 'لاعب' ? 'bg-orange-600 text-white shadow-sm' : 'bg-[#001F3F] text-white shadow-sm'}`}>
                    {person.role}
                  </span>
                  <span className="text-[11px] font-black text-slate-900 mt-2 flex items-center gap-1 opacity-70">
                    <Layers size={12} /> {person.category}
                  </span>
               </div>
             </div>

             <div className="space-y-2">
               <h4 className="font-black text-xl text-slate-900 leading-tight group-hover:text-blue-900 transition-colors">{person.name}</h4>
               <div className="flex flex-wrap gap-3 pt-1 text-[11px] font-black text-slate-600">
                 <span className="flex items-center gap-1.5 bg-slate-50 px-2 py-1 rounded-lg border border-slate-100"><MapPin size={12} className="text-orange-600" /> {person.birthPlace}</span>
                 <span className="flex items-center gap-1.5 bg-slate-50 px-2 py-1 rounded-lg border border-slate-100"><Calendar size={12} className="text-[#001F3F]" /> {calculateAge(person.birthDate)} سنة</span>
               </div>
             </div>

             <div className="mt-6 pt-4 border-t-2 border-slate-100 flex justify-between items-center">
                <div className="flex items-center gap-3">
                   <div className="bg-[#001F3F] text-white w-9 h-9 rounded-xl flex items-center justify-center font-black text-lg border-2 border-black shadow-md">
                     #{person.number || '00'}
                   </div>
                   <button onClick={() => onOpenReport?.(person)} className="text-slate-900 text-xs font-black hover:text-orange-600 underline underline-offset-4 decoration-2 decoration-orange-600/30 hover:decoration-orange-600 transition-all">الملف الفني الشامل</button>
                </div>
                {!isViewer && (
                  <div className="flex gap-2">
                    <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-2.5 bg-slate-100 text-slate-900 hover:bg-[#001F3F] hover:text-white rounded-xl border-2 border-slate-900 transition-all shadow-sm"><Plus size={16}/></button>
                    <button onClick={() => handleDeletePlayer(person)} className="p-2.5 bg-red-50 text-red-600 hover:bg-red-600 hover:text-white rounded-xl border-2 border-red-900 transition-all shadow-sm"><Trash2 size={16}/></button>
                  </div>
                )}
             </div>
          </div>
        ))}
      </div>

      {isModalOpen && !isViewer && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[250] p-4 no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-4xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 border-[6px] border-slate-900 flex flex-col h-[90vh]">
            <div className="p-5 border-b-2 bg-slate-50 flex justify-between items-center shrink-0">
              <h3 className="text-md font-black text-slate-900 uppercase tracking-wider">{editingId ? 'تحديث بيانات الكادر' : 'تسجيل عضو جديد بنادي الكرامة'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2.5 rounded-xl text-slate-900 hover:text-red-600 transition-all hover:rotate-90"><X size={22} /></button>
            </div>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto custom-scrollbar p-8 space-y-10">
              <div className="space-y-6">
                <h4 className="text-[12px] font-black text-[#001F3F] flex items-center gap-2 border-r-4 border-orange-600 pr-3 uppercase">البيانات الشخصية والولادة</h4>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div className="space-y-1 col-span-1 md:col-span-2">
                    <label className={labelClass}>الاسم الثنائي الكامل</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} className={fieldClass} />
                  </div>
