                       <textarea className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-4 font-black text-xs h-32 outline-none focus:border-orange-600 transition-all" value={activeMatch.notes || ''} onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})} placeholder="سجل تقريرك الفني المختصر للمباراة هنا..."></textarea>
                    </section>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React from 'react';
import { Users, Calendar, Trophy, Clock, MapPin, AlertCircle, ChevronLeft, ShieldAlert, Filter, Printer, FileText, ClipboardCheck } from 'lucide-react';
import { AppState, Person } from '../types';

interface DashboardProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onMatchClick: (id: string) => void;
  onSessionClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setState, onMatchClick, onSessionClick }) => {
  const today = new Date();
  const todayStr = today.toISOString().split('T')[0];
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  // فرض الفئة المقيدة إذا وجدت، وإلا استخدام الفلتر العالمي
  const activeCategory = restrictedCat || state.globalCategoryFilter;

  const upcomingMatches = state.matches
    .filter(m => {
      const matchCat = activeCategory === 'الكل' ? true : m.category === activeCategory;
      return matchCat && m.date >= todayStr && !m.isCompleted;
    })
    .sort((a, b) => a.date.localeCompare(b.date));

  const upcomingSessions = state.sessions
    .filter(s => {
      const matchCat = activeCategory === 'الكل' ? true : s.category === activeCategory;
      return matchCat && s.date >= todayStr && !s.isCompleted;
    })
    .sort((a, b) => a.date.localeCompare(b.date));

  // نظام فحص العقود (أقل من 3 أشهر = 90 يوماً)
  const expiringContracts = state.people.filter(p => {
    const matchCat = activeCategory === 'الكل' ? true : p.category === activeCategory;
    if (!matchCat || !p.contractEnd) return false;
    const end = new Date(p.contractEnd);
    const diffTime = end.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 && diffDays <= 90;
  });

  const stats = [
    { 
      label: 'الكوادر المسجلة', 
      value: state.people.filter(p => activeCategory === 'الكل' ? true : p.category === activeCategory).length, 
      icon: Users, 
      color: 'blue' 
    },
    { label: 'المواجهات القادمة', value: upcomingMatches.length, icon: Trophy, color: 'emerald' },
    { label: 'التمارين المجدولة', value: upcomingSessions.length, icon: Calendar, color: 'orange' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Category Filter Dropdown */}
      <div className="bg-white p-5 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print">
        <h3 className="text-md font-black text-slate-900 flex items-center gap-3">
          <Filter size={20} className="text-[#001F3F]" /> تصفية البيانات في لوحة التحكم
        </h3>
        <div className="flex items-center gap-3 mt-3 md:mt-0">
          <label className="text-[10px] font-black text-slate-500 uppercase">عرض بيانات فئة:</label>
          <select 
