export default PlayerReport;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
export type UserRole = 'مدير' | 'إداري فئة' | 'مشاهد';
export type MatchType = 'دوري' | 'كأس' | 'ودية' | 'بطولة ودية' | 'مباراة دولية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface Person {
  id: string;
  name: string;
  fatherName: string;
  motherName: string;
  birthDate: string;
  birthPlace: string;
  khana: string;
  nationalId: string;
  federalNumber: string;
  internationalId: string;
  address: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  contractStart?: string;
  contractEnd?: string;
  contractValue?: string;
  medicalHistory?: string;
  injuries?: string;
  penalties?: string;
  notes?: string;
  coachingCertificate?: string;
  academicDegree?: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  excuse?: string;
  fine?: string;
  isLocked?: boolean;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  objective: string;
  isCompleted?: boolean;
}

export interface MatchEvent {
  id: string;
  type: 'goal' | 'assist' | 'yellow' | 'red' | 'injury';
  player: string; // الاسم أو ID
  minute: string;
  note?: string;
}

export interface Match {
  id: string;
  category: Category;
  matchType: MatchType;
  opponent: string;
  pitch?: string;
  date: string;
  time: string;
  advancePayment: string;
  isCompleted: boolean;
  ourScore: string;
  opponentScore: string;
  events: MatchEvent[];
  lineup: {
    starters: { playerId: string; name: string; number: string; minutesPlayed?: string }[];
    subs: { 
      playerId: string; 
      name: string; 
      number: string; 
      minutesPlayed?: string;
      substitutionMinute?: string;
      replacedPlayerId?: string;
    }[];
    staff: { role: string; name: string }[];
    captain: string;
  };
  notes?: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  categories: Category[];
  currentUser: AppUser | null;
  notifications: AppNotification[];
  globalCategoryFilter: Category | 'الكل';
}

import React from 'react';
import { Users, Calendar, Trophy, Clock, MapPin, AlertCircle, ChevronLeft, ShieldAlert, Filter, Printer, FileText, ClipboardCheck } from 'lucide-react';
import { AppState, Person } from '../types';

interface DashboardProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onMatchClick: (id: string) => void;
  onSessionClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, setState, onMatchClick, onSessionClick }) => {
  const today = new Date();
  const todayStr = today.toISOString().split('T')[0];
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  // فرض الفئة المقيدة إذا وجدت، وإلا استخدام الفلتر العالمي
  const activeCategory = restrictedCat || state.globalCategoryFilter;

  const upcomingMatches = state.matches
    .filter(m => {
      const matchCat = activeCategory === 'الكل' ? true : m.category === activeCategory;
      return matchCat && m.date >= todayStr && !m.isCompleted;
    })
    .sort((a, b) => a.date.localeCompare(b.date));

  const upcomingSessions = state.sessions
    .filter(s => {
      const matchCat = activeCategory === 'الكل' ? true : s.category === activeCategory;
      return matchCat && s.date >= todayStr && !s.isCompleted;
    })
    .sort((a, b) => a.date.localeCompare(b.date));

  // نظام فحص العقود (أقل من 3 أشهر = 90 يوماً)
  const expiringContracts = state.people.filter(p => {
    const matchCat = activeCategory === 'الكل' ? true : p.category === activeCategory;
    if (!matchCat || !p.contractEnd) return false;
    const end = new Date(p.contractEnd);
    const diffTime = end.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 && diffDays <= 90;
  });

  const stats = [
    { 
      label: 'الكوادر المسجلة', 
      value: state.people.filter(p => activeCategory === 'الكل' ? true : p.category === activeCategory).length, 
      icon: Users, 
      color: 'blue' 
    },
    { label: 'المواجهات القادمة', value: upcomingMatches.length, icon: Trophy, color: 'emerald' },
    { label: 'التمارين المجدولة', value: upcomingSessions.length, icon: Calendar, color: 'orange' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Category Filter Dropdown */}
      <div className="bg-white p-5 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print">
        <h3 className="text-md font-black text-slate-900 flex items-center gap-3">
          <Filter size={20} className="text-[#001F3F]" /> تصفية البيانات في لوحة التحكم
        </h3>
        <div className="flex items-center gap-3 mt-3 md:mt-0">
          <label className="text-[10px] font-black text-slate-500 uppercase">عرض بيانات فئة:</label>
          <select 
            disabled={!!restrictedCat}
            value={activeCategory}
            onChange={e => setState(p => ({ ...p, globalCategoryFilter: e.target.value as any }))}
            className="bg-slate-100 border-2 border-slate-900 rounded-xl py-2 px-4 font-black text-[12px] text-slate-900 outline-none h-11 appearance-none cursor-pointer hover:bg-white transition-colors min-w-[150px] disabled:opacity-60 disabled:cursor-not-allowed"
          >
            {!restrictedCat && <option value="الكل">جميع الفئات</option>}
            {state.categories
              .filter(c => !restrictedCat || c === restrictedCat)
              .map(c => <option key={c} value={c}>{c}</option>)
            }
          </select>
        </div>
      </div>

      {/* Quick Report Center */}
      <div className="bg-slate-900 p-8 rounded-[3rem] border-4 border-orange-600 shadow-xl no-print">
         <div className="flex items-center gap-4 mb-6">
            <Printer className="text-orange-400" size={28}/>
            <h3 className="text-xl font-black text-white uppercase tracking-tight">مركز التقارير المركزية السريعة</h3>
         </div>
         <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-white/10 p-5 rounded-2xl border border-white/10 flex flex-col items-center text-center space-y-3">
               <FileText className="text-emerald-400" size={32}/>
               <p className="text-white font-black text-sm uppercase">كشوفات الفئات</p>
               <p className="text-[9px] text-slate-400">طباعة القوائم الكاملة للاعبين والكوادر والبيانات الثبوتية</p>
            </div>
            <div className="bg-white/10 p-5 rounded-2xl border border-white/10 flex flex-col items-center text-center space-y-3">
               <ClipboardCheck className="text-blue-400" size={32}/>
               <p className="text-white font-black text-sm uppercase">تقارير الانضباط</p>
               <p className="text-[9px] text-slate-400">طباعة سجلات الحضور الشهرية والغيابات والالتزام بالتمارين</p>
            </div>
            <div className="bg-white/10 p-5 rounded-2xl border border-white/10 flex flex-col items-center text-center space-y-3">
               <Trophy className="text-orange-400" size={32}/>
               <p className="text-white font-black text-sm uppercase">أجندة المباريات</p>
               <p className="text-[9px] text-slate-400">طباعة جداول المواجهات القادمة ونتائج الموسم للفئات</p>
            </div>
         </div>
      </div>

      {/* Contract Expiry Alert Section */}
      {expiringContracts.length > 0 && (
        <div className="bg-red-50 border-4 border-red-900 rounded-[2.5rem] p-6 shadow-xl animate-pulse no-print">
           <div className="flex items-center gap-4 mb-4">
              <div className="p-3 bg-red-900 text-white rounded-2xl shadow-lg"><ShieldAlert size={28} /></div>
              <h3 className="text-xl font-black text-red-900 uppercase">تنبيهات إدارية: عقود توشك على الانتهاء</h3>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
              {expiringContracts.map(p => {
                const end = new Date(p.contractEnd!);
                const diffDays = Math.ceil((end.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
                return (
                  <div key={p.id} className="bg-white border-2 border-red-900 p-4 rounded-2xl flex justify-between items-center shadow-sm">
                    <div>
                      <p className="font-black text-slate-900 text-sm">{p.name}</p>
                      <p className="text-[10px] font-black text-red-600 uppercase">متبقي: {diffDays} يوم</p>
                    </div>
                    <span className="bg-red-900 text-white text-[9px] font-black px-3 py-1 rounded-lg">{p.category}</span>
                  </div>
                );
              })}
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {stats.map((s, i) => (
          <div key={i} className="bg-white p-8 rounded-[2.5rem] shadow-sm border-2 border-slate-900 flex flex-col items-center hover:bg-slate-50 transition-all group">
             <div className={`p-4 rounded-2xl mb-4 transition-transform group-hover:scale-110 ${s.color === 'blue' ? 'bg-blue-100 text-blue-900 border border-blue-900' : s.color === 'emerald' ? 'bg-emerald-100 text-emerald-900 border border-emerald-900' : 'bg-orange-100 text-orange-900 border border-orange-900'}`}>
               <s.icon size={30} />
             </div>
             <h3 className="text-slate-900 text-[10px] font-black uppercase tracking-widest">{s.label}</h3>
             <p className="text-4xl font-black text-slate-900 mt-2">{s.value}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-[3rem] shadow-sm border-2 border-slate-900">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-3">
              <Trophy size={20} className="text-blue-900" /> الأجندة التنافسية
            </h3>
            <span className="text-[9px] bg-blue-100 text-blue-900 px-3 py-1 rounded-full font-black uppercase border-2 border-blue-900">القادمة</span>
          </div>
          <div className="space-y-4">
            {upcomingMatches.length > 0 ? upcomingMatches.map(m => (
              <button key={m.id} onClick={() => onMatchClick(m.id)} className="w-full text-right p-5 rounded-2xl bg-slate-100 border-2 border-slate-900 hover:bg-white transition-all group flex items-center justify-between shadow-sm">
                <div>
                  <h4 className="font-black text-sm text-slate-900">الكرامة × {m.opponent}</h4>
                  <p className="text-[10px] font-black text-slate-900 mt-1 uppercase tracking-wider">{m.date} | {m.time} - {m.category}</p>
                </div>
                <ChevronLeft size={20} className="text-slate-900 group-hover:-translate-x-1 transition-transform" />
              </button>
            )) : (
              <p className="py-10 text-center text-slate-900 font-black italic text-xs uppercase opacity-30 tracking-widest">لا توجد مباريات قادمة</p>
            )}
          </div>
        </div>

        <div className="bg-white p-8 rounded-[3rem] shadow-sm border-2 border-slate-900">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-3">
              <Calendar size={20} className="text-orange-600" /> برنامج التمارين
            </h3>
            <span className="text-[9px] bg-orange-100 text-orange-900 px-3 py-1 rounded-full font-black uppercase border-2 border-orange-900">المجدولة</span>
          </div>
          <div className="space-y-4">
            {upcomingSessions.length > 0 ? upcomingSessions.map(s => (
              <button key={s.id} onClick={() => onSessionClick(s.id)} className="w-full text-right p-5 rounded-2xl bg-slate-100 border-2 border-slate-900 hover:bg-white transition-all group flex items-center justify-between shadow-sm">
                <div>
                  <h4 className="font-black text-sm text-slate-900">{s.objective}</h4>
                  <p className="text-[10px] font-black text-slate-900 mt-1 uppercase tracking-wider">{s.date} | {s.time} - {s.category}</p>
                </div>
                <ChevronLeft size={20} className="text-slate-900 group-hover:-translate-x-1 transition-transform" />
              </button>
            )) : (
              <p className="py-10 text-center text-slate-900 font-black italic text-xs uppercase opacity-30 tracking-widest">لا توجد تمارين قادمة</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Calendar as CalendarIcon, MapPin, Clock, Plus, Trash2, Edit, X, Printer, FileText, CheckCircle, ShieldCheck, Lock, AlertCircle, Map, ChevronRight, BarChart3, PieChart, Users, User, TrendingUp, CalendarDays } from 'lucide-react';
import { AppState, TrainingSession, Category, Person, AttendanceRecord } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

export default function TrainingPlanner({ state, setState, defaultSelectedId, addLog }: TrainingPlannerProps) {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري فئة';
  // Permit both managers and category admins (restricted or global) to add/modify
  const canModifyConfig = isManager || isCatAdmin;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showPrintView, setShowPrintView] = useState(false);
  const [activeTab, setActiveTab] = useState<'agenda' | 'stats'>('agenda');
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);

  const [reportType, setReportType] = useState<'category' | 'player'>('category');
  const [selectedCatForReport, setSelectedCatForReport] = useState<string>(restrictedCat || state.categories[0] || '');
  const [selectedPlayerId, setSelectedPlayerId] = useState<string>('');
  const [reportPeriod, setReportPeriod] = useState<{ month: string, year: string }>({
    month: (new Date().getMonth() + 1).toString().padStart(2, '0'),
    year: new Date().getFullYear().toString()
  });
  const [printData, setPrintData] = useState<any>(null);

  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'الرجال'),
    date: new Date().toISOString().split('T')[0],
    time: '16:00'
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.time) return;

    const selectedDateTime = new Date(`${formData.date}T${formData.time}`);
    const now = new Date();
    if (!editingSessionId && selectedDateTime < now) {
      alert("تنبيه: لا يمكن جدولة تمرين في تاريخ أو وقت سابق للوقت الحالي.");
      return;
    }

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s)
      }));
      addLog?.('تعديل موعد تمرين', `تم تحديث بيانات تمرين فئة ${formData.category}`, 'info');
    } else {
      const newSession: TrainingSession = {
        id: generateUUID(),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        objective: formData.objective || 'تمرين عام',
        isCompleted: false
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
      addLog?.('إضافة موعد تمرين', `تمت جدولة تمرين جديد لفئة ${newSession.category}`, 'info');
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const handleDeleteSession = async (sessionId: string) => {
    if (confirm('هل أنت متأكد من حذف هذا التمرين؟')) {
      try {
        const { error } = await supabase.from('sessions').delete().eq('id', sessionId);
        if (error) throw error;

        setState(prev => ({
          ...prev,
          sessions: prev.sessions.filter(s => s.id !== sessionId)
        }));
        addLog?.('حذف تمرين', 'تم إزالة الحصة التدريبية من الأجندة', 'error');
      } catch (err: any) {
        alert("فشل حذف التمرين من السحاب: " + err.message);
      }
    }
  };

  const toggleSessionComplete = (id: string, currentStatus: boolean) => {
    setState(prev => ({
      ...prev,
      sessions: prev.sessions.map(s => s.id === id ? { ...s, isCompleted: !currentStatus } : m)
    }));
    addLog?.('تحديث حالة تمرين', currentStatus ? 'تم إعادة فتح التمرين' : 'تم تأشير التمرين كمنتهي', 'info');
  };

  const filteredSessions = useMemo(() => {
    return (restrictedCat 
      ? state.sessions.filter(s => s.category === restrictedCat)
      : state.sessions.filter(s => (state.globalCategoryFilter === 'الكل' || s.category === state.globalCategoryFilter)))
      .sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [state.sessions, restrictedCat, state.globalCategoryFilter]);

  const isSessionLocked = (session: TrainingSession) => {
    const sessionTime = new Date(`${session.date}T${session.time}`);
    const now = new Date();
    const diffInMinutes = (now.getTime() - sessionTime.getTime()) / (1000 * 60);
    return diffInMinutes > 30;
  };

  const generateReport = () => {
    const isCategory = reportType === 'category';
    const period = `${reportPeriod.year}-${reportPeriod.month}`;

    if (isCategory) {
      const catSessions = state.sessions.filter(s => s.category === selectedCatForReport && s.date.startsWith(period));
      const catPlayers = state.people.filter(p => p.role === 'لاعب' && p.category === selectedCatForReport);

      let totalPresence = 0;
      let totalLates = 0;
      let totalAbsence = 0;
      let totalExcused = 0;

      catSessions.forEach(s => {
        const records = state.attendance.filter(a => a.sessionId === s.id);
        totalPresence += records.filter(r => r.status === 'حاضر').length;
        totalLates += records.filter(r => r.status === 'متأخر').length;
        totalAbsence += records.filter(r => r.status === 'غائب').length;
        totalExcused += records.filter(r => r.status === 'غياب بعذر').length;
      });

      const totalPossible = catSessions.length * catPlayers.length;
      const attendanceRate = totalPossible > 0 ? Math.round((totalPresence / totalPossible) * 100) : 0;

      setPrintData({
        type: 'category',
        title: `تقرير أداء فئة: ${selectedCatForReport}`,
        period: `${reportPeriod.month} / ${reportPeriod.year}`,
        sessions: catSessions,
        stats: { totalSessions: catSessions.length, attendanceRate, totalPresence, totalLates, totalAbsence, totalExcused, playersCount: catPlayers.length }
      });
    } else {
      const player = state.people.find(p => p.id === selectedPlayerId);
      if (!player) return alert('يرجى اختيار اللاعب أولاً');

      const playerRecords = state.attendance.filter(a => a.personId === player.id && a.date.startsWith(period));
      const playerSessions = state.sessions.filter(s => s.category === player.category && s.date.startsWith(period));

      const present = playerRecords.filter(r => r.status === 'حاضر').length;
      const late = playerRecords.filter(r => r.status === 'متأخر').length;
      const absent = playerRecords.filter(r => r.status === 'غائب').length;
      const excused = playerRecords.filter(r => r.status === 'غياب بعذر').length;

      const score = playerSessions.length > 0 ? Math.round(((present + (late * 0.5)) / playerSessions.length) * 100) : 0;

      setPrintData({
        type: 'player',
        player,
        title: `تقرير التزام اللاعب: ${player.name}`,
        period: `${reportPeriod.month} / ${reportPeriod.year}`,
        stats: { present, late, absent, excused, total: playerSessions.length, score },
        records: playerRecords.map(r => {
          const s = state.sessions.find(ses => ses.id === r.sessionId);
          return { ...r, objective: s?.objective || 'تمرين عام' };
        })
      });
    }
    setShowPrintView(true);
  };

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-4 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";

  if (showPrintView && printData) {
    return (
      <div className="fixed inset-0 bg-white z-[600] overflow-y-auto p-12 dir-rtl text-right">
        <div className="max-w-5xl mx-auto border-4 border-slate-900 p-12 print:border-2">
           <div className="no-print flex justify-between items-center mb-10 border-b pb-4">
              <button onClick={() => setShowPrintView(false)} className="flex items-center gap-2 font-black text-slate-500 hover:text-red-600 transition-all"><ChevronRight/> إغلاق المعاينة</button>
              <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-10 py-4 rounded-2xl font-black flex items-center gap-3 shadow-2xl"><Printer size={20}/> طباعة التقرير الفني PDF</button>
           </div>
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-8 mb-10">
              <div className="flex items-center gap-4">
                 <ClubLogo size={100} />
                 <div>
                    <h2 className="text-3xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-md font-black text-orange-600">مكتب كرة القدم المركزي - قسم الإحصاء</p>
                 </div>
              </div>
              <div className="text-left font-black">
                 <p className="text-2xl uppercase tracking-tighter">{printData.title}</p>
                 <p className="text-sm text-slate-500">الفترة: {printData.period}</p>
                 <p className="text-[10px] mt-2">تاريخ الإصدار: {new Date().toLocaleString('ar-SY')}</p>
              </div>
           </div>
           {printData.type === 'category' ? (
              <div className="space-y-10">
                 <div className="grid grid-cols-4 gap-4">
                    <div className="bg-slate-50 p-6 border-2 border-slate-900 text-center">
                       <p className="text-[10px] font-black text-slate-400 uppercase">إجمالي الحصص</p>
                       <p className="text-3xl font-black">{printData.stats.totalSessions}</p>
                    </div>
                    <div className="bg-emerald-50 p-6 border-2 border-emerald-900 text-center">
                       <p className="text-[10px] font-black text-emerald-600 uppercase">معدل الحضور</p>
                       <p className="text-3xl font-black text-emerald-700">%{printData.stats.attendanceRate}</p>
                    </div>
                    <div className="bg-orange-50 p-6 border-2 border-orange-900 text-center">
                       <p className="text-[10px] font-black text-orange-600 uppercase">حالات التأخير</p>
                       <p className="text-3xl font-black text-orange-700">{printData.stats.totalLates}</p>
                    </div>
                    <div className="bg-red-50 p-6 border-2 border-red-900 text-center">
                       <p className="text-[10px] font-black text-red-600 uppercase">حالات الغياب</p>
                       <p className="text-3xl font-black text-red-700">{printData.stats.totalAbsence}</p>
                    </div>
                 </div>
                 <h4 className="text-lg font-black border-r-4 border-blue-900 pr-3">سجل التدريبات خلال الفترة</h4>
                 <table className="w-full text-right border-collapse">
                    <thead>
                       <tr className="bg-slate-100 border-y-2 border-slate-900 text-xs font-black">
                          <th className="p-4 border-l border-slate-200">التاريخ</th>
                          <th className="p-4 border-l border-slate-200">موضوع التمرين</th>
                          <th className="p-4 border-l border-slate-200 text-center">حاضر</th>
                          <th className="p-4 text-center">غائب</th>
                       </tr>
                    </thead>
                    <tbody>
                       {printData.sessions.map((s: any) => {
                          const att = state.attendance.filter(a => a.sessionId === s.id);
                          return (
                             <tr key={s.id} className="border-b border-slate-200 text-sm font-black">
