           ) : (
              <div className="space-y-10">
                 <div className="flex items-center gap-8 bg-slate-50 p-8 border-4 border-slate-900 rounded-[2rem]">
                    <div className="w-32 h-32 bg-white border-4 border-slate-900 rounded-3xl flex items-center justify-center font-black text-5xl text-[#001F3F] shadow-lg">
                       {printData.player.name.charAt(0)}
                    </div>
                    <div className="space-y-2">
                       <h3 className="text-3xl font-black text-slate-900">{printData.player.name}</h3>
                       <p className="text-md font-black text-blue-900">المركز: {printData.player.role} | الفئة: {printData.player.category}</p>
                       <div className="flex items-center gap-4 mt-4">
                          <span className="bg-emerald-600 text-white px-4 py-1 rounded-lg text-xs font-black shadow-md">درجة الالتزام: {printData.stats.score}%</span>
                       </div>
                    </div>
                 </div>
                 <div className="grid grid-cols-4 gap-4">
                    <div className="text-center p-4 border-2 border-slate-200">
                       <p className="text-[10px] font-black text-slate-400">حاضر</p>
                       <p className="text-2xl font-black">{printData.stats.present}</p>
                    </div>
                    <div className="text-center p-4 border-2 border-slate-200">
                       <p className="text-[10px] font-black text-slate-400">متأخر</p>
                       <p className="text-2xl font-black text-orange-600">{printData.stats.late}</p>
                    </div>
                    <div className="text-center p-4 border-2 border-slate-200">
                       <p className="text-[10px] font-black text-slate-400">غياب بعذر</p>
                       <p className="text-2xl font-black text-blue-600">{printData.stats.excused}</p>
                    </div>
                    <div className="text-center p-4 border-2 border-slate-200">
                       <p className="text-[10px] font-black text-slate-400">غائب</p>
                       <p className="text-2xl font-black text-red-600">{printData.stats.absent}</p>
                    </div>
                 </div>
                 <table className="w-full text-right border-collapse">
                    <thead>
                       <tr className="bg-slate-100 border-y-2 border-slate-900 text-xs font-black">
                          <th className="p-4 border-l border-slate-200">التاريخ</th>
                          <th className="p-4 border-l border-slate-200">التمرين</th>
                          <th className="p-4 border-l border-slate-200 text-center">الحالة</th>
                          <th className="p-4">ملاحظات العذر</th>
                       </tr>
                    </thead>
                    <tbody>
                       {printData.records.map((r: any) => (
                          <tr key={r.id} className="border-b border-slate-200 text-sm font-black">
                             <td className="p-4 border-l border-slate-200">{r.date}</td>
                             <td className="p-4 border-l border-slate-200 text-xs">{r.objective}</td>
                             <td className="p-4 border-l border-slate-200 text-center">
                                <span className={r.status === 'حاضر' ? 'text-emerald-600' : 'text-red-600'}>{r.status}</span>
                             </td>
                             <td className="p-4 text-[10px] italic text-slate-500">{r.excuse || '--'}</td>
                          </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           )}
           <div className="mt-24 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">توقيع مدرب الفئة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">مدير مكتب كرة القدم</p>
                 <p className="font-black text-xs text-blue-900">عزت عامر الشيخة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-2 rounded-2xl border-2 border-slate-900 flex gap-2 w-fit no-print mx-auto mb-8 shadow-sm">
         <button 
           onClick={() => setActiveTab('agenda')}
           className={`px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 transition-all ${activeTab === 'agenda' ? 'bg-[#001F3F] text-white shadow-lg scale-105' : 'text-slate-500 hover:bg-slate-100'}`}
         >
            <CalendarIcon size={18}/> الأجندة التدريبية
         </button>
         <button 
           onClick={() => setActiveTab('stats')}
           className={`px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 transition-all ${activeTab === 'stats' ? 'bg-[#001F3F] text-white shadow-lg scale-105' : 'text-slate-500 hover:bg-slate-100'}`}
         >
            <BarChart3 size={18}/> التقارير والإحصائيات
         </button>
      </div>

      {activeTab === 'agenda' ? (
        <>
          <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
            <div>
               <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">
                 <CalendarIcon size={24} className="text-blue-900" /> أجندة التدريبات المركزية (الجدولة)
               </h3>
               <p className="text-[10px] font-black text-slate-400 mt-1">تنظيم مواعيد التدريب لجميع الفئات - ميزة التعديل محصورة بمدير المكتب أو الإداريين المخولين</p>
            </div>
            <div className="flex gap-3">
              <button 
                onClick={() => {
                    if (state.globalCategoryFilter === 'الكل') return alert("يرجى اختيار فئة محددة أولاً لطباعة البرنامج.");
                    const catSessions = state.sessions.filter(s => s.category === state.globalCategoryFilter).sort((a,b) => a.date.localeCompare(b.date));
                    setPrintData({
                      type: 'category',
                      title: `أجندة تمارين فئة: ${state.globalCategoryFilter}`,
                      period: 'كامل الأجندة المتاحة',
                      sessions: catSessions,
                      stats: { totalSessions: catSessions.length, attendanceRate: 'N/A', totalPresence: 'N/A', totalLates: 'N/A', totalAbsence: 'N/A', totalExcused: 'N/A' }
                    });
                    setShowPrintView(true);
                }} 
                className="bg-white text-slate-900 border-2 border-slate-900 px-6 py-3 rounded-xl font-black text-sm flex items-center gap-2 hover:bg-slate-50 transition-all"
              >
                <Printer size={18}/> طباعة البرنامج
              </button>
              {canModifyConfig && (
                <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
                  className="bg-[#001F3F] text-white px-8 py-3 rounded-xl flex items-center gap-2 font-black text-sm shadow-lg border-b-4 border-black hover:bg-black transition-all">
                  <Plus size={20} /> إضافة حصة تدريبية جديدة
                </button>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
            {filteredSessions.map(session => {
              const locked = isSessionLocked(session);
              const isComp = session.isCompleted;
              return (
                <div key={session.id} className={`bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-8 transition-all no-print ${locked ? 'border-slate-300 opacity-80' : isComp ? 'border-emerald-600' : 'hover:border-blue-900'}`}>
                  <div className="flex justify-between items-center mb-4">
                     <span className="bg-[#001F3F] text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{session.category}</span>
                     <div className="flex gap-1">
                        {isComp && (
                           <span className="text-[9px] font-black text-white flex items-center gap-1 bg-emerald-600 px-2 py-1 rounded-lg border border-emerald-700"><CheckCircle size={12}/> انتهى</span>
                        )}
                        {canModifyConfig && (
                          <div className="flex gap-1">
                            <button onClick={() => { setEditingSessionId(session.id); setFormData(session); setIsModalOpen(true); }} className="p-2 bg-slate-100 text-slate-900 rounded-lg hover:bg-blue-900 hover:text-white transition-all"><Edit size={14}/></button>
                            <button onClick={() => handleDeleteSession(session.id)} className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-all"><Trash2 size={14}/></button>
                          </div>
                        )}
                     </div>
                  </div>
                  <h4 className="text-lg font-black text-slate-900 mb-4">{session.objective}</h4>
                  <div className="space-y-2 text-[11px] font-black text-slate-500 uppercase tracking-tighter">
                     <p className="flex items-center gap-2"><CalendarIcon size={14} className="text-orange-600"/> {session.date}</p>
                     <p className="flex items-center gap-2"><Clock size={14} className="text-[#001F3F]"/> {session.time}</p>
                  </div>
                  <button 
                    onClick={() => toggleSessionComplete(session.id, !!isComp)}
                    className={`mt-6 w-full py-2.5 rounded-xl font-black text-[10px] flex items-center justify-center gap-2 border-2 transition-all ${isComp ? 'bg-emerald-50 border-emerald-600 text-emerald-700' : 'bg-slate-100 border-slate-900 text-slate-900 hover:bg-emerald-50'}`}
                  >
                     <CheckCircle size={14}/> {isComp ? 'إعادة فتح التمرين' : 'تأشير كتم الإنجاز'}
                  </button>
                </div>
              );
            })}
            {filteredSessions.length === 0 && (
               <div className="col-span-full py-20 text-center opacity-30 italic font-black text-sm uppercase tracking-widest">لا توجد تمارين مجدولة حالياً لهذه الفئة</div>
            )}
          </div>
        </>
      ) : (
        <div className="bg-white p-10 rounded-[3rem] border-2 border-slate-900 shadow-sm no-print">
           <div className="flex items-center gap-4 mb-10">
              <BarChart3 className="text-blue-900" size={32}/>
              <h3 className="text-2xl font-black text-slate-900">محرك استخراج التقارير الفنية</h3>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
              <div className="space-y-4">
                 <label className={labelClass}>نوع التقرير</label>
                 <div className="flex bg-slate-100 p-1 rounded-xl border-2 border-slate-200">
                    <button onClick={() => setReportType('category')} className={`flex-1 py-3 rounded-lg font-black text-xs transition-all ${reportType === 'category' ? 'bg-[#001F3F] text-white shadow-md' : 'text-slate-500'}`}>تقرير فئة</button>
                    <button onClick={() => setReportType('player')} className={`flex-1 py-3 rounded-lg font-black text-xs transition-all ${reportType === 'player' ? 'bg-[#001F3F] text-white shadow-md' : 'text-slate-500'}`}>تقرير لاعب</button>
                 </div>
              </div>
              {reportType === 'category' ? (
                <div className="space-y-2">
                   <label className={labelClass}>الفئة المستهدفة</label>
                   <select value={selectedCatForReport} onChange={e => setSelectedCatForReport(e.target.value)} className={fieldClass}>
                      {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                   </select>
                </div>
              ) : (
                <div className="space-y-2">
                   <label className={labelClass}>البحث عن لاعب</label>
                   <select value={selectedPlayerId} onChange={e => setSelectedPlayerId(e.target.value)} className={fieldClass}>
                      <option value="">-- اختر لاعب من القائمة --</option>
                      {state.people.filter(p => p.role === 'لاعب').sort((a,b) => a.name.localeCompare(b.name)).map(p => (
                         <option key={p.id} value={p.id}>{p.name} ({p.category})</option>
                      ))}
                   </select>
                </div>
              )}
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-2">
                    <label className={labelClass}>الشهر</label>
                    <select value={reportPeriod.month} onChange={e => setReportPeriod({...reportPeriod, month: e.target.value})} className={fieldClass}>
                       {Array.from({length:12}).map((_,i) => {
                          const val = (i+1).toString().padStart(2, '0');
                          return <option key={val} value={val}>{val}</option>;
                       })}
                    </select>
                 </div>
                 <div className="space-y-2">
                    <label className={labelClass}>السنة</label>
                    <select value={reportPeriod.year} onChange={e => setReportPeriod({...reportPeriod, year: e.target.value})} className={fieldClass}>
                       {['2024','2025','2026'].map(y => <option key={y} value={y}>{y}</option>)}
                    </select>
                 </div>
              </div>
              <div className="flex items-end">
                 <button onClick={generateReport} className="w-full bg-[#001F3F] text-white py-4 rounded-2xl font-black text-md shadow-xl hover:bg-black transition-all border-b-4 border-black">استخراج ومعاينة التقرير</button>
              </div>
           </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[500] p-4 no-print">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl border-[6px] border-slate-900 overflow-hidden">
              <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center">
                 <h3 className="font-black text-slate-900 uppercase">{editingSessionId ? 'تحديث موعد تمرين' : 'جدولة تمرين مركزي جديد'}</h3>
                 <button onClick={() => setIsModalOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900"><X size={20}/></button>
              </div>
              <form onSubmit={handleSave} className="p-8 space-y-5">
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className={labelClass}>الفئة</label>
                       <select required className={fieldClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                 </div>
                 <div className="space-y-1">
                    <label className={labelClass}>موضوع / هدف التمرين</label>
                    <input required type="text" className={fieldClass} value={formData.objective || ''} onChange={e => setFormData({...formData, objective: e.target.value})} placeholder="مثلاً: تكتيك هجومي.." />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className={labelClass}>التاريخ</label>
                       <input required type="date" className={fieldClass} value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>التوقيت</label>
                       <input required type="time" className={fieldClass} value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black shadow-xl hover:bg-black transition-all mt-4 uppercase">حفظ وتثبيت التمرين</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Calendar as CalendarIcon, MapPin, Clock, Plus, Trash2, Edit, X, Printer, FileText, CheckCircle, ShieldCheck, Lock, AlertCircle, Map, ChevronRight, BarChart3, PieChart, Users, User, TrendingUp, CalendarDays } from 'lucide-react';
import { AppState, TrainingSession, Category, Person, AttendanceRecord } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

export default function TrainingPlanner({ state, setState, defaultSelectedId, addLog }: TrainingPlannerProps) {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري فئة';
  // Permit both managers and category admins (restricted or global) to add/modify
  const canModifyConfig = isManager || isCatAdmin;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showPrintView, setShowPrintView] = useState(false);
  const [activeTab, setActiveTab] = useState<'agenda' | 'stats'>('agenda');
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);

  const [reportType, setReportType] = useState<'category' | 'player'>('category');
  const [selectedCatForReport, setSelectedCatForReport] = useState<string>(restrictedCat || state.categories[0] || '');
  const [selectedPlayerId, setSelectedPlayerId] = useState<string>('');
  const [reportPeriod, setReportPeriod] = useState<{ month: string, year: string }>({
    month: (new Date().getMonth() + 1).toString().padStart(2, '0'),
    year: new Date().getFullYear().toString()
  });
  const [printData, setPrintData] = useState<any>(null);

  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'الرجال'),
    date: new Date().toISOString().split('T')[0],
    time: '16:00'
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.time) return;

    const selectedDateTime = new Date(`${formData.date}T${formData.time}`);
    const now = new Date();
    if (!editingSessionId && selectedDateTime < now) {
      alert("تنبيه: لا يمكن جدولة تمرين في تاريخ أو وقت سابق للوقت الحالي.");
      return;
    }

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s)
      }));
      addLog?.('تعديل موعد تمرين', `تم تحديث بيانات تمرين فئة ${formData.category}`, 'info');
    } else {
      const newSession: TrainingSession = {
        id: generateUUID(),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        objective: formData.objective || 'تمرين عام',
        isCompleted: false
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
      addLog?.('إضافة موعد تمرين', `تمت جدولة تمرين جديد لفئة ${newSession.category}`, 'info');
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const handleDeleteSession = async (sessionId: string) => {
    if (confirm('هل أنت متأكد من حذف هذا التمرين؟')) {
      try {
        const { error } = await supabase.from('sessions').delete().eq('id', sessionId);
        if (error) throw error;

        setState(prev => ({
          ...prev,
          sessions: prev.sessions.filter(s => s.id !== sessionId)
        }));
        addLog?.('حذف تمرين', 'تم إزالة الحصة التدريبية من الأجندة', 'error');
      } catch (err: any) {
        alert("فشل حذف التمرين من السحاب: " + err.message);
      }
    }
  };

  const toggleSessionComplete = (id: string, currentStatus: boolean) => {
    setState(prev => ({
      ...prev,
      // Fix: Changed 'm' to 's' to correctly refer to the session object being mapped
      sessions: prev.sessions.map(s => s.id === id ? { ...s, isCompleted: !currentStatus } : s)
    }));
    addLog?.('تحديث حالة تمرين', currentStatus ? 'تم إعادة فتح التمرين' : 'تم تأشير التمرين كمنتهي', 'info');
  };

  const filteredSessions = useMemo(() => {
    return (restrictedCat 
      ? state.sessions.filter(s => s.category === restrictedCat)
      : state.sessions.filter(s => (state.globalCategoryFilter === 'الكل' || s.category === state.globalCategoryFilter)))
      .sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [state.sessions, restrictedCat, state.globalCategoryFilter]);

  const isSessionLocked = (session: TrainingSession) => {
    const sessionTime = new Date(`${session.date}T${session.time}`);
    const now = new Date();
    const diffInMinutes = (now.getTime() - sessionTime.getTime()) / (1000 * 60);
    return diffInMinutes > 30;
  };

  const generateReport = () => {
    const isCategory = reportType === 'category';
    const period = `${reportPeriod.year}-${reportPeriod.month}`;

    if (isCategory) {
      const catSessions = state.sessions.filter(s => s.category === selectedCatForReport && s.date.startsWith(period));
      const catPlayers = state.people.filter(p => p.role === 'لاعب' && p.category === selectedCatForReport);

      let totalPresence = 0;
      let totalLates = 0;
      let totalAbsence = 0;
      let totalExcused = 0;

      catSessions.forEach(s => {
        const records = state.attendance.filter(a => a.sessionId === s.id);
        totalPresence += records.filter(r => r.status === 'حاضر').length;
        totalLates += records.filter(r => r.status === 'متأخر').length;
        totalAbsence += records.filter(r => r.status === 'غائب').length;
        totalExcused += records.filter(r => r.status === 'غياب بعذر').length;
      });

      const totalPossible = catSessions.length * catPlayers.length;
      const attendanceRate = totalPossible > 0 ? Math.round((totalPresence / totalPossible) * 100) : 0;

      setPrintData({
        type: 'category',
        title: `تقرير أداء فئة: ${selectedCatForReport}`,
        period: `${reportPeriod.month} / ${reportPeriod.year}`,
        sessions: catSessions,
        stats: { totalSessions: catSessions.length, attendanceRate, totalPresence, totalLates, totalAbsence, totalExcused, playersCount: catPlayers.length }
      });
    } else {
      const player = state.people.find(p => p.id === selectedPlayerId);
      if (!player) return alert('يرجى اختيار اللاعب أولاً');

      const playerRecords = state.attendance.filter(a => a.personId === player.id && a.date.startsWith(period));
      const playerSessions = state.sessions.filter(s => s.category === player.category && s.date.startsWith(period));

      const present = playerRecords.filter(r => r.status === 'حاضر').length;
      const late = playerRecords.filter(r => r.status === 'متأخر').length;
      const absent = playerRecords.filter(r => r.status === 'غائب').length;
      const excused = playerRecords.filter(r => r.status === 'غياب بعذر').length;

      const score = playerSessions.length > 0 ? Math.round(((present + (late * 0.5)) / playerSessions.length) * 100) : 0;

      setPrintData({
        type: 'player',
        player,
        title: `تقرير التزام اللاعب: ${player.name}`,
        period: `${reportPeriod.month} / ${reportPeriod.year}`,
        stats: { present, late, absent, excused, total: playerSessions.length, score },
        records: playerRecords.map(r => {
          const s = state.sessions.find(ses => ses.id === r.sessionId);
          return { ...r, objective: s?.objective || 'تمرين عام' };
        })
      });
    }
    setShowPrintView(true);
  };

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-4 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";

  if (showPrintView && printData) {
    return (
      <div className="fixed inset-0 bg-white z-[600] overflow-y-auto p-12 dir-rtl text-right">
        <div className="max-w-5xl mx-auto border-4 border-slate-900 p-12 print:border-2">
           <div className="no-print flex justify-between items-center mb-10 border-b pb-4">
              <button onClick={() => setShowPrintView(false)} className="flex items-center gap-2 font-black text-slate-500 hover:text-red-600 transition-all"><ChevronRight/> إغلاق المعاينة</button>
              <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-10 py-4 rounded-2xl font-black flex items-center gap-3 shadow-2xl"><Printer size={20}/> طباعة التقرير الفني PDF</button>
           </div>
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-8 mb-10">
              <div className="flex items-center gap-4">
                 <ClubLogo size={100} />
                 <div>
                    <h2 className="text-3xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-md font-black text-orange-600">مكتب كرة القدم المركزي - قسم الإحصاء</p>
                 </div>
              </div>
              <div className="text-left font-black">
                 <p className="text-2xl uppercase tracking-tighter">{printData.title}</p>
                 <p className="text-sm text-slate-500">الفترة: {printData.period}</p>
                 <p className="text-[10px] mt-2">تاريخ الإصدار: {new Date().toLocaleString('ar-SY')}</p>
              </div>
           </div>
           {printData.type === 'category' ? (
              <div className="space-y-10">
                 <div className="grid grid-cols-4 gap-4">
                    <div className="bg-slate-50 p-6 border-2 border-slate-900 text-center">
                       <p className="text-[10px] font-black text-slate-400 uppercase">إجمالي الحصص</p>
                       <p className="text-3xl font-black">{printData.stats.totalSessions}</p>
                    </div>
                    <div className="bg-emerald-50 p-6 border-2 border-emerald-900 text-center">
                       <p className="text-[10px] font-black text-emerald-600 uppercase">معدل الحضور</p>
                       <p className="text-3xl font-black text-emerald-700">%{printData.stats.attendanceRate}</p>
                    </div>
                    <div className="bg-orange-50 p-6 border-2 border-orange-900 text-center">
                       <p className="text-[10px] font-black text-orange-600 uppercase">حالات التأخير</p>
                       <p className="text-3xl font-black text-orange-700">{printData.stats.totalLates}</p>
                    </div>
                    <div className="bg-red-50 p-6 border-2 border-red-900 text-center">
                       <p className="text-[10px] font-black text-red-600 uppercase">حالات الغياب</p>
                       <p className="text-3xl font-black text-red-700">{printData.stats.totalAbsence}</p>
                    </div>
                 </div>
                 <h4 className="text-lg font-black border-r-4 border-blue-900 pr-3">سجل التدريبات خلال الفترة</h4>
                 <table className="w-full text-right border-collapse">
                    <thead>
                       <tr className="bg-slate-100 border-y-2 border-slate-900 text-xs font-black">
                          <th className="p-4 border-l border-slate-200">التاريخ</th>
                          <th className="p-4 border-l border-slate-200">موضوع التمرين</th>
                          <th className="p-4 border-l border-slate-200 text-center">حاضر</th>
                          <th className="p-4 text-center">غائب</th>
                       </tr>
                    </thead>
                    <tbody>
                       {printData.sessions.map((s: any) => {
                          const att = state.attendance.filter(a => a.sessionId === s.id);
                          return (
                             <tr key={s.id} className="border-b border-slate-200 text-sm font-black">
                                <td className="p-4 border-l border-slate-200">{s.date}</td>
                                <td className="p-4 border-l border-slate-200 text-xs">{s.objective}</td>
                                <td className="p-4 border-l border-slate-200 text-center text-emerald-600">{att.filter(r => r.status === 'حاضر').length}</td>
                                <td className="p-4 text-center text-red-600">{att.filter(r => r.status === 'غائب').length}</td>
                             </tr>
                          );
                       })}
                    </tbody>
                 </table>
              </div>
           ) : (
              <div className="space-y-10">
                 <div className="flex items-center gap-8 bg-slate-50 p-8 border-4 border-slate-900 rounded-[2rem]">
                    <div className="w-32 h-32 bg-white border-4 border-slate-900 rounded-3xl flex items-center justify-center font-black text-5xl text-[#001F3F] shadow-lg">
                       {printData.player.name.charAt(0)}
                    </div>
                    <div className="space-y-2">
                       <h3 className="text-3xl font-black text-slate-900">{printData.player.name}</h3>
                       <p className="text-md font-black text-blue-900">المركز: {printData.player.role} | الفئة: {printData.player.category}</p>
                       <div className="flex items-center gap-4 mt-4">
                          <span className="bg-emerald-600 text-white px-4 py-1 rounded-lg text-xs font-black shadow-md">درجة الالتزام: {printData.stats.score}%</span>
                       </div>
                    </div>
                 </div>
                 <div className="grid grid-cols-4 gap-4">
                    <div className="text-center p-4 border-2 border-slate-200">
                       <p className="text-[10px] font-black text-slate-400">حاضر</p>
                       <p className="text-2xl font-black">{printData.stats.present}</p>
                    </div>
                    <div className="text-center p-4 border-2 border-slate-200">
                       <p className="text-[10px] font-black text-slate-400">متأخر</p>
                       <p className="text-2xl font-black text-orange-600">{printData.stats.late}</p>
                    </div>
                    <div className="text-center p-4 border-2 border-slate-200">
                       <p className="text-[10px] font-black text-slate-400">غياب بعذر</p>
                       <p className="text-2xl font-black text-blue-600">{printData.stats.excused}</p>
                    </div>
                    <div className="text-center p-4 border-2 border-slate-200">
                       <p className="text-[10px] font-black text-slate-400">غائب</p>
                       <p className="text-2xl font-black text-red-600">{printData.stats.absent}</p>
                    </div>
                 </div>
                 <table className="w-full text-right border-collapse">
                    <thead>
                       <tr className="bg-slate-100 border-y-2 border-slate-900 text-xs font-black">
                          <th className="p-4 border-l border-slate-200">التاريخ</th>
                          <th className="p-4 border-l border-slate-200">التمرين</th>
                          <th className="p-4 border-l border-slate-200 text-center">الحالة</th>
                          <th className="p-4">ملاحظات العذر</th>
                       </tr>
                    </thead>
                    <tbody>
                       {printData.records.map((r: any) => (
                          <tr key={r.id} className="border-b border-slate-200 text-sm font-black">
                             <td className="p-4 border-l border-slate-200">{r.date}</td>
                             <td className="p-4 border-l border-slate-200 text-xs">{r.objective}</td>
                             <td className="p-4 border-l border-slate-200 text-center">
                                <span className={r.status === 'حاضر' ? 'text-emerald-600' : 'text-red-600'}>{r.status}</span>
                             </td>
                             <td className="p-4 text-[10px] italic text-slate-500">{r.excuse || '--'}</td>
                          </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           )}
           <div className="mt-24 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">توقيع مدرب الفئة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">مدير مكتب كرة القدم</p>
                 <p className="font-black text-xs text-blue-900">عزت عامر الشيخة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-2 rounded-2xl border-2 border-slate-900 flex gap-2 w-fit no-print mx-auto mb-8 shadow-sm">
         <button 
           onClick={() => setActiveTab('agenda')}
           className={`px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 transition-all ${activeTab === 'agenda' ? 'bg-[#001F3F] text-white shadow-lg scale-105' : 'text-slate-500 hover:bg-slate-100'}`}
         >
            <CalendarIcon size={18}/> الأجندة التدريبية
         </button>
         <button 
           onClick={() => setActiveTab('stats')}
           className={`px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 transition-all ${activeTab === 'stats' ? 'bg-[#001F3F] text-white shadow-lg scale-105' : 'text-slate-500 hover:bg-slate-100'}`}
         >
            <BarChart3 size={18}/> التقارير والإحصائيات
         </button>
      </div>

      {activeTab === 'agenda' ? (
        <>
          <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
            <div>
               <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">
                 <CalendarIcon size={24} className="text-blue-900" /> أجندة التدريبات المركزية (الجدولة)
               </h3>
               <p className="text-[10px] font-black text-slate-400 mt-1">تنظيم مواعيد التدريب لجميع الفئات - ميزة التعديل محصورة بمدير المكتب أو الإداريين المخولين</p>
            </div>
            <div className="flex gap-3">
              <button 
                onClick={() => {
                    if (state.globalCategoryFilter === 'الكل') return alert("يرجى اختيار فئة محددة أولاً لطباعة البرنامج.");
                    const catSessions = state.sessions.filter(s => s.category === state.globalCategoryFilter).sort((a,b) => a.date.localeCompare(b.date));
                    setPrintData({
                      type: 'category',
                      title: `أجندة تمارين فئة: ${state.globalCategoryFilter}`,
                      period: 'كامل الأجندة المتاحة',
                      sessions: catSessions,
                      stats: { totalSessions: catSessions.length, attendanceRate: 'N/A', totalPresence: 'N/A', totalLates: 'N/A', totalAbsence: 'N/A', totalExcused: 'N/A' }
                    });
                    setShowPrintView(true);
                }} 
                className="bg-white text-slate-900 border-2 border-slate-900 px-6 py-3 rounded-xl font-black text-sm flex items-center gap-2 hover:bg-slate-50 transition-all"
              >
                <Printer size={18}/> طباعة البرنامج
              </button>
              {canModifyConfig && (
                <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
                  className="bg-[#001F3F] text-white px-8 py-3 rounded-xl flex items-center gap-2 font-black text-sm shadow-lg border-b-4 border-black hover:bg-black transition-all">
                  <Plus size={20} /> إضافة حصة تدريبية جديدة
                </button>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
            {filteredSessions.map(session => {
              const locked = isSessionLocked(session);
              const isComp = session.isCompleted;
              return (
                <div key={session.id} className={`bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-8 transition-all no-print ${locked ? 'border-slate-300 opacity-80' : isComp ? 'border-emerald-600' : 'hover:border-blue-900'}`}>
                  <div className="flex justify-between items-center mb-4">
                     <span className="bg-[#001F3F] text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{session.category}</span>
                     <div className="flex gap-1">
                        {isComp && (
                           <span className="text-[9px] font-black text-white flex items-center gap-1 bg-emerald-600 px-2 py-1 rounded-lg border border-emerald-700"><CheckCircle size={12}/> انتهى</span>
                        )}
                        {canModifyConfig && (
                          <div className="flex gap-1">
                            <button onClick={() => { setEditingSessionId(session.id); setFormData(session); setIsModalOpen(true); }} className="p-2 bg-slate-100 text-slate-900 rounded-lg hover:bg-blue-900 hover:text-white transition-all"><Edit size={14}/></button>
                            <button onClick={() => handleDeleteSession(session.id)} className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-all"><Trash2 size={14}/></button>
                          </div>
                        )}
                     </div>
                  </div>
                  <h4 className="text-lg font-black text-slate-900 mb-4">{session.objective}</h4>
                  <div className="space-y-2 text-[11px] font-black text-slate-500 uppercase tracking-tighter">
                     <p className="flex items-center gap-2"><CalendarIcon size={14} className="text-orange-600"/> {session.date}</p>
                     <p className="flex items-center gap-2"><Clock size={14} className="text-[#001F3F]"/> {session.time}</p>
                  </div>
                  <button 
                    onClick={() => toggleSessionComplete(session.id, !!isComp)}
                    className={`mt-6 w-full py-2.5 rounded-xl font-black text-[10px] flex items-center justify-center gap-2 border-2 transition-all ${isComp ? 'bg-emerald-50 border-emerald-600 text-emerald-700' : 'bg-slate-100 border-slate-900 text-slate-900 hover:bg-emerald-50'}`}
                  >
                     <CheckCircle size={14}/> {isComp ? 'إعادة فتح التمرين' : 'تأشير كتم الإنجاز'}
                  </button>
                </div>
              );
            })}
            {filteredSessions.length === 0 && (
               <div className="col-span-full py-20 text-center opacity-30 italic font-black text-sm uppercase tracking-widest">لا توجد تمارين مجدولة حالياً لهذه الفئة</div>
            )}
          </div>
        </>
      ) : (
        <div className="bg-white p-10 rounded-[3rem] border-2 border-slate-900 shadow-sm no-print">
           <div className="flex items-center gap-4 mb-10">
              <BarChart3 className="text-blue-900" size={32}/>
              <h3 className="text-2xl font-black text-slate-900">محرك استخراج التقارير الفنية</h3>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
              <div className="space-y-4">
                 <label className={labelClass}>نوع التقرير</label>
                 <div className="flex bg-slate-100 p-1 rounded-xl border-2 border-slate-200">
                    <button onClick={() => setReportType('category')} className={`flex-1 py-3 rounded-lg font-black text-xs transition-all ${reportType === 'category' ? 'bg-[#001F3F] text-white shadow-md' : 'text-slate-500'}`}>تقرير فئة</button>
                    <button onClick={() => setReportType('player')} className={`flex-1 py-3 rounded-lg font-black text-xs transition-all ${reportType === 'player' ? 'bg-[#001F3F] text-white shadow-md' : 'text-slate-500'}`}>تقرير لاعب</button>
                 </div>
              </div>
              {reportType === 'category' ? (
                <div className="space-y-2">
                   <label className={labelClass}>الفئة المستهدفة</label>
                   <select value={selectedCatForReport} onChange={e => setSelectedCatForReport(e.target.value)} className={fieldClass}>
                      {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                   </select>
                </div>
              ) : (
                <div className="space-y-2">
                   <label className={labelClass}>البحث عن لاعب</label>
                   <select value={selectedPlayerId} onChange={e => setSelectedPlayerId(e.target.value)} className={fieldClass}>
                      <option value="">-- اختر لاعب من القائمة --</option>
                      {state.people.filter(p => p.role === 'لاعب').sort((a,b) => a.name.localeCompare(b.name)).map(p => (
                         <option key={p.id} value={p.id}>{p.name} ({p.category})</option>
                      ))}
                   </select>
                </div>
              )}
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-2">
                    <label className={labelClass}>الشهر</label>
                    <select value={reportPeriod.month} onChange={e => setReportPeriod({...reportPeriod, month: e.target.value})} className={fieldClass}>
                       {Array.from({length:12}).map((_,i) => {
                          const val = (i+1).toString().padStart(2, '0');
                          return <option key={val} value={val}>{val}</option>;
                       })}
                    </select>
                 </div>
                 <div className="space-y-2">
                    <label className={labelClass}>السنة</label>
                    <select value={reportPeriod.year} onChange={e => setReportPeriod({...reportPeriod, year: e.target.value})} className={fieldClass}>
                       {['2024','2025','2026'].map(y => <option key={y} value={y}>{y}</option>)}
                    </select>
                 </div>
              </div>
              <div className="flex items-end">
                 <button onClick={generateReport} className="w-full bg-[#001F3F] text-white py-4 rounded-2xl font-black text-md shadow-xl hover:bg-black transition-all border-b-4 border-black">استخراج ومعاينة التقرير</button>
              </div>
           </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[500] p-4 no-print">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl border-[6px] border-slate-900 overflow-hidden">
              <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center">
                 <h3 className="font-black text-slate-900 uppercase">{editingSessionId ? 'تحديث موعد تمرين' : 'جدولة تمرين مركزي جديد'}</h3>
                 <button onClick={() => setIsModalOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900"><X size={20}/></button>
              </div>
              <form onSubmit={handleSave} className="p-8 space-y-5">
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className={labelClass}>الفئة</label>
                       <select required className={fieldClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                 </div>
                 <div className="space-y-1">
                    <label className={labelClass}>موضوع / هدف التمرين</label>
                    <input required type="text" className={fieldClass} value={formData.objective || ''} onChange={e => setFormData({...formData, objective: e.target.value})} placeholder="مثلاً: تكتيك هجومي.." />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className={labelClass}>التاريخ</label>
                       <input required type="date" className={fieldClass} value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>التوقيت</label>
                       <input required type="time" className={fieldClass} value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black shadow-xl hover:bg-black transition-all mt-4 uppercase">حفظ وتثبيت التمرين</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
}

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
export type UserRole = 'مدير' | 'إداري فئة' | 'مشاهد';
export type MatchType = 'دوري' | 'كأس' | 'ودية' | 'بطولة ودية' | 'مباراة دولية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface Person {
  id: string;
  name: string;
  fatherName: string;
  motherName: string;
  birthDate: string;
  birthPlace: string;
  khana: string;
  nationalId: string;
  federalNumber: string;
  internationalId: string;
  address: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  contractStart?: string;
  contractEnd?: string;
  contractValue?: string;
  medicalHistory?: string;
  injuries?: string;
  penalties?: string;
  notes?: string;
  coachingCertificate?: string;
  academicDegree?: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  excuse?: string;
  fine?: string;
  isLocked?: boolean;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  pitch?: string;
  objective: string;
  isCompleted?: boolean;
}

export interface MatchEvent {
  id: string;
  type: 'goal' | 'assist' | 'yellow' | 'red' | 'injury';
  player: string; // الاسم أو ID
  minute: string;
  note?: string;
}

export interface Match {
  id: string;
  category: Category;
  matchType: MatchType;
  opponent: string;
  pitch?: string;
  date: string;
  time: string;
  advancePayment: string;
  isCompleted: boolean;
  ourScore: string;
  opponentScore: string;
  stoppageTime?: string; // الوقت بدل الضائع
  events: MatchEvent[];
  lineup: {
    starters: { playerId: string; name: string; number: string; minutesPlayed?: string }[];
    subs: { 
      playerId: string; 
      name: string; 
      number: string; 
      minutesPlayed?: string;
      substitutionMinute?: string;
      replacedPlayerId?: string;
    }[];
    staff: { role: string; name: string }[];
    captain: string;
  };
  notes?: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  categories: Category[];
  currentUser: AppUser | null;
  notifications: AppNotification[];
  globalCategoryFilter: Category | 'الكل';
}

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter)
  });

  const matchTypes: MatchType[] = ['دوري', 'كأس', 'ودية', 'بطولة ودية', 'مباراة دولية'];

  useEffect(() => {
    if (isAddOpen) {
      setFormData(prev => ({
        ...prev,
        category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter)
      }));
    }
  }, [isAddOpen, state.globalCategoryFilter, state.categories, restrictedCat]);

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date || !formData.time || !formData.category) return;

    const newMatch: Match = {
      id: generateUUID(),
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time,
      category: formData.category,
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime: '0',
      events: [],
      lineup: { 
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '90' })), 
        subs: [], 
        staff: [], 
        captain: '' 
      },
      notes: ''
    };

    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ${newMatch.matchType} ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
  };

  const handleDeleteMatch = async (matchId: string) => {
    if (confirm('هل أنت متأكد من حذف هذه المباراة؟ لن يتم التمكن من استعادتها.')) {
      try {
        const { error } = await supabase.from('matches').delete().eq('id', matchId);
        if (error) throw error;

        setState(p => ({
          ...p,
          matches: p.matches.filter(x => x.id !== matchId)
        }));
      } catch (err: any) {
        alert("فشل الحذف من السحاب: " + err.message);
      }
    }
  };

  const toggleMatchComplete = (id: string, currentStatus: boolean) => {
    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === id ? { ...m, isCompleted: !currentStatus } : m)
    }));
    addLog?.('تحديث حالة مباراة', currentStatus ? 'تم إعادة فتح المباراة' : 'تم تأشير المباراة كمنتهية', 'info');
  };

  const updateActiveMatchLineup = (index: number, playerId: string, isStarter: boolean) => {
    if (!activeMatch) return;
    const person = state.people.find(p => p.id === playerId);
    if (!person) return;

    const newLineup = { ...activeMatch.lineup };
    if (isStarter) {
      newLineup.starters[index] = { ...newLineup.starters[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const toggleCaptain = (playerId: string) => {
    if (!activeMatch || !playerId) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.captain = newLineup.captain === playerId ? '' : playerId;
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateMinutes = (index: number, minutes: string, isStarter: boolean) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    if (isStarter) {
      newLineup.starters[index].minutesPlayed = minutes;
    } else {
      newLineup.subs[index].minutesPlayed = minutes;
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  // دالة الحساب المحدثة لتشمل الوقت الضائع وتتبع المنطق المطلوب
  const handleSubstitutionCalculation = (subIndex: number, replacedPlayerId: string, subMinute: string) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    const minute = parseInt(subMinute) || 0;
    const stoppage = parseInt(activeMatch.stoppageTime || '0') || 0;

    newLineup.subs[subIndex].replacedPlayerId = replacedPlayerId;
    newLineup.subs[subIndex].substitutionMinute = subMinute;

    // اللاعب الداخل يحسب له ما تبقى من المباراة + الوقت الضائع
    newLineup.subs[subIndex].minutesPlayed = ((90 + stoppage) - minute).toString();

    // اللاعب الخارج يحسب له الدقائق حتى لحظة التبديل
    const starterIdx = newLineup.starters.findIndex(s => s.playerId === replacedPlayerId);
    if (starterIdx !== -1) {
      newLineup.starters[starterIdx].minutesPlayed = subMinute;
    }

    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addSub = () => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      lineup: {
        ...activeMatch.lineup,
        subs: [...activeMatch.lineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0', substitutionMinute: '', replacedPlayerId: '' }]
      }
    });
  };

  const updateSub = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const person = state.people.find(p => p.id === playerId);
    if (!person) return;
    const newSubs = [...activeMatch.lineup.subs];
    newSubs[index] = { ...newSubs[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const removeSub = (index: number) => {
    if (!activeMatch) return;
    const newSubs = activeMatch.lineup.subs.filter((_, i) => i !== index);
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = {
      id: generateUUID(),
      type,
      player: '',
      minute: '',
      note: ''
    };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const removeEvent = (eventId: string) => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      events: activeMatch.events.filter(e => e.id !== eventId)
    });
  };

  const saveMatchDetails = () => {
    if (!activeMatch) return;
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? activeMatch : m)
    }));
    addLog?.('تحديث المباراة', `تم حفظ تفاصيل مباراة ${activeMatch.opponent}`, 'info');
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [
      ...activeMatch!.lineup.starters.map(s => s.playerId),
      ...activeMatch!.lineup.subs.map(s => s.playerId)
    ].filter(id => id && id !== currentId);
    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const fieldClass = "w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-[#001F3F] mr-2 uppercase block mb-1.5";

  if (showPrintView) {
    return (
      <div className="fixed inset-0 bg-white z-[500] overflow-y-auto p-12 text-right dir-rtl">
        <div className="max-w-5xl mx-auto border-4 border-slate-900 p-12 print:border-2">
           <div className="no-print flex justify-between items-center mb-10 border-b pb-4">
              <button onClick={() => setShowPrintView(false)} className="flex items-center gap-2 font-black text-slate-500"><ChevronRight/> العودة للأجندة</button>
              <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black flex items-center gap-2 shadow-xl"><Printer size={18}/> طباعة الأجندة PDF</button>
           </div>
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-8 mb-10">
              <div className="flex items-center gap-4">
                 <ClubLogo size={90} />
                 <div>
                    <h2 className="text-3xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-md font-black text-orange-600 uppercase">مكتب كرة القدم المركزي</p>
                 </div>
              </div>
              <div className="text-left font-black">
                 <p className="text-2xl uppercase">أجندة المباريات والنتائج</p>
                 <p className="text-sm text-slate-500">الفئة: {state.globalCategoryFilter}</p>
                 <p className="text-[10px] mt-1">تاريخ التقرير: {new Date().toLocaleDateString('ar-SY')}</p>
              </div>
           </div>
           <table className="w-full text-right border-collapse">
              <thead>
                 <tr className="bg-slate-100 border-y-2 border-slate-900 text-xs font-black">
                    <th className="p-4 border-l border-slate-300">التاريخ</th>
                    <th className="p-4 border-l border-slate-300">المنافس</th>
                    <th className="p-4 border-l border-slate-300 text-center">النوع</th>
                    <th className="p-4 border-l border-slate-300 text-center">النتيجة</th>
                    <th className="p-4">الملعب</th>
                 </tr>
              </thead>
              <tbody>
                 {filteredMatches.map(m => (
                    <tr key={m.id} className="border-b border-slate-200 text-sm font-black">
                       <td className="p-4 border-l border-slate-200">{m.date} - {m.time}</td>
                       <td className="p-4 border-l border-slate-200">{m.opponent}</td>
                       <td className="p-4 border-l border-slate-200 text-center text-[10px]">{m.matchType}</td>
                       <td className="p-4 border-l border-slate-200 text-center bg-slate-50">
                          {m.isCompleted ? `${m.ourScore} - ${m.opponentScore}` : 'لم تلعب'}
                       </td>
                       <td className="p-4 text-xs italic text-slate-500">{m.pitch || 'غير محدد'}</td>
                    </tr>
                 ))}
              </tbody>
           </table>
           <div className="mt-24 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12">
                 <p className="font-black text-sm uppercase">توقيع إداري الفريق</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm uppercase">توقيع مدرب الفريق</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm uppercase">مشرف مكتب كرة القدم</p>
                 <p className="font-black text-xs text-blue-900">عزت عامر الشيخة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div>
           <h2 className="text-xl font-black text-slate-900 flex items-center gap-3">
             <Trophy size={24} className="text-orange-600" /> إدارة أجندة المباريات المركزية
           </h2>
           <p className="text-[10px] font-black text-slate-400 mt-1">تنسيق التشكيلة، دقائق اللعب، الأهداف، والبطاقات للفئات</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={() => {
              if (state.globalCategoryFilter === 'الكل' && !restrictedCat) return alert("يرجى اختيار فئة محددة أولاً لطباعة الأجندة.");
              setShowPrintView(true);
            }} 
            className="bg-white text-slate-900 border-2 border-slate-900 px-6 py-3 rounded-xl font-black text-sm flex items-center gap-2 hover:bg-slate-50 transition-all"
          >
            <Printer size={18}/> طباعة الأجندة
          </button>
          <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-lg border-b-4 border-black hover:bg-black transition-all">
            <Plus size={20} /> جدولة مواجهة جديدة
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-8 transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-6">
                <div className="flex gap-1">
                   <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                   {m.isCompleted && <span className="bg-emerald-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase flex items-center gap-1"><CheckCircle size={10}/> منتهية</span>}
                </div>
                <span className="text-[10px] font-black text-slate-400 flex items-center gap-1"><Calendar size={12}/> {m.date} - {m.category}</span>
             </div>

             <div className="flex items-center justify-between gap-4 mb-4">
                <div className="text-center flex-1">
                   <div className="w-14 h-14 bg-slate-100 border-2 border-slate-900 rounded-2xl flex items-center justify-center mx-auto mb-2 font-black text-xl">K</div>
                   <p className="font-black text-xs">الكرامة</p>
                </div>
                <div className="text-center px-4">
                   <p className="text-3xl font-black text-slate-900">{m.ourScore} - {m.opponentScore}</p>
                   <p className="text-[9px] font-black text-slate-400 uppercase mt-2">{m.time}</p>
                </div>
                <div className="text-center flex-1">
                   <div className="w-14 h-14 bg-slate-100 border-2 border-slate-900 rounded-2xl flex items-center justify-center mx-auto mb-2 font-black text-xl">{m.opponent.charAt(0)}</div>
                   <p className="font-black text-xs truncate max-w-[80px]">{m.opponent}</p>
                </div>
             </div>
             <div className="mb-6 flex flex-col gap-1 px-2">
                {m.pitch && (
                  <div className="flex items-center gap-2 text-[10px] font-black text-slate-500">
                     <Map size={12} className="text-emerald-600" /> {m.pitch}
                  </div>
                )}
             </div>
             <div className="flex flex-col gap-2">
                <div className="flex gap-2">
                  <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 hover:bg-black transition-all">
                    <BookOpen size={16}/> التشكيل والتقرير
                  </button>
                  <button onClick={() => handleDeleteMatch(m.id)} className="p-3 bg-red-50 text-red-600 rounded-xl border-2 border-red-900 hover:bg-red-600 hover:text-white transition-all"><Trash2 size={16}/></button>
                </div>
                <button 
                  onClick={() => toggleMatchComplete(m.id, !!m.isCompleted)}
                  className={`w-full py-2.5 rounded-xl font-black text-[10px] flex items-center justify-center gap-2 border-2 transition-all ${m.isCompleted ? 'bg-emerald-50 border-emerald-600 text-emerald-700' : 'bg-slate-100 border-slate-900 text-slate-900 hover:bg-emerald-50'}`}
                >
                  <CheckCircle size={14}/> {m.isCompleted ? 'إعادة فتح المباراة' : 'إنهاء المباراة (إخفاء من اللوحة)'}
                </button>
             </div>
          </div>
        ))}
      </div>

      {isAddOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-md flex items-center justify-center z-[300] p-4 no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl border-[6px] border-slate-900 overflow-hidden">
             <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center">
                <h3 className="font-black text-slate-900 uppercase">جدولة مواجهة جديدة</h3>
                <button onClick={() => setIsAddOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900"><X size={20}/></button>
             </div>
             <form onSubmit={handleAddMatch} className="p-8 space-y-5">
                <div className="grid grid-cols-2 gap-4">
                   <div>
                      <label className={labelClass}>الفئة</label>
                      <select disabled={!!restrictedCat} required className={fieldClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                   </div>
                   <div>
                      <label className={labelClass}>نوع المباراة</label>
                      <select required className={fieldClass} value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as MatchType})}>
                        {matchTypes.map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                   </div>
                </div>
                <div>
                   <label className={labelClass}>اسم الخصم</label>
                   <input required type="text" className={fieldClass} value={formData.opponent || ''} onChange={e => setFormData({...formData, opponent: e.target.value})} />
                </div>
                <div>
                   <label className={labelClass}>الملعب</label>
                   <input type="text" className={fieldClass} value={formData.pitch || ''} onChange={e => setFormData({...formData, pitch: e.target.value})} placeholder="مثلاً: ملعب الباسل.." />
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div>
                      <label className={labelClass}>التاريخ</label>
                      <input required type="date" className={fieldClass} value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                   </div>
                   <div>
                      <label className={labelClass}>التوقيت</label>
                      <input required type="time" className={fieldClass} value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                   </div>
                </div>
                <button type="submit" className="w-full bg-[#001F3F] text-white py-4 rounded-xl font-black shadow-xl hover:bg-black transition-all mt-4 uppercase">تثبيت الجدولة المركزية</button>
             </form>
          </div>
        </div>
      )}

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl z-[400] overflow-y-auto custom-scrollbar p-4 lg:p-10 no-print">
           <div className="max-w-6xl mx-auto bg-white rounded-[3rem] border-[8px] border-slate-900 min-h-screen flex flex-col shadow-2xl">
              <header className="p-8 border-b-4 border-slate-900 bg-slate-50 flex flex-col md:flex-row justify-between items-center gap-6">
                 <div className="flex items-center gap-4">
                    <div className="bg-[#001F3F] text-white w-16 h-16 rounded-2xl flex items-center justify-center font-black text-2xl border-4 border-slate-900">K</div>
                    <div>
                       <h2 className="text-2xl font-black text-slate-900">إدارة تفاصيل المباراة والتشكيل</h2>
                       <p className="text-sm font-black text-orange-600 tracking-widest uppercase">نادي الكرامة × {activeMatch.opponent} ({activeMatch.matchType}) {activeMatch.pitch ? `| ${activeMatch.pitch}` : ''}</p>
                    </div>
                 </div>
                 <div className="flex gap-3">
                    <button onClick={saveMatchDetails} className="bg-emerald-600 text-white px-8 py-3 rounded-xl font-black flex items-center gap-2 border-b-4 border-black hover:bg-emerald-700">
                       <Save size={20}/> حفظ التغييرات والتشكيل
                    </button>
                    <button onClick={() => setActiveMatch(null)} className="bg-red-50 text-red-600 px-6 py-3 rounded-xl font-black border-2 border-red-900">
                       إلغاء التعديل
                    </button>
                 </div>
              </header>
              <div className="flex-1 p-8 grid grid-cols-1 lg:grid-cols-3 gap-10">
                 <div className="lg:col-span-2 space-y-10">
                    <section>
                       <h3 className="text-lg font-black text-slate-900 mb-6 flex items-center gap-3 border-r-4 border-orange-600 pr-4">
                          <Users size={22}/> التشكيل الأساسي واختيار القائد
                       </h3>
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {activeMatch.lineup.starters.map((s, idx) => {
                             const isCaptain = activeMatch.lineup.captain === s.playerId;
                             return (
                             <div key={idx} className={`flex flex-col gap-2 bg-slate-50 p-4 rounded-xl border-2 transition-all ${isCaptain ? 'border-orange-600 bg-orange-50/50 shadow-md ring-2 ring-orange-100' : 'border-slate-200'}`}>
                                <div className="flex items-center gap-3">
                                   <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-xs shrink-0">{idx + 1}</span>
                                   <select className="flex-1 bg-white border-2 border-slate-300 rounded-lg p-2 font-black text-xs outline-none focus:border-blue-600" value={s.playerId} onChange={e => updateActiveMatchLineup(idx, e.target.value, true)}>
                                      <option value="">-- اختر اللاعب --</option>
                                      {getAvailablePlayers(s.playerId).map(p => (
                                         <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                      ))}
                                   </select>
                                   <div className="w-12 text-center bg-[#001F3F] text-white border-2 border-slate-900 rounded-lg p-2 font-black text-xs">#{s.number || '--'}</div>
