                                  <Trash2 size={16}/>
                                </button>
                             </div>
                          ))}
                       </div>
                       {activeMatch.lineup.subs.length === 0 && <p className="text-center py-12 text-slate-300 italic font-black text-xs border-2 border-dashed border-slate-100 rounded-[2.5rem]">لا يوجد تبديلات مسجلة لهذه المباراة</p>}
