                            <label className="text-[9px] font-black uppercase mb-1 block">الكرامة</label>
                            <input type="number" className="w-20 h-20 bg-white text-slate-900 rounded-2xl text-center font-black text-4xl border-4 border-orange-600 outline-none" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                          </div>
                          <span className="text-4xl font-black mt-4">:</span>
                          <div className="text-center">
                            <label className="text-[9px] font-black uppercase mb-1 block">الخصم</label>
