                                      {ev.type === 'assist' && '👟 تمريرة حاسمة'}
                                      {ev.type === 'yellow' && '🟨 إنذار أصفر'}
                                      {ev.type === 'red' && '🟥 طرد مباشر'}
                                   </span>
                                   <button onClick={() => removeEvent(ev.id)} className="text-red-500 hover:text-red-700"><X size={14}/></button>
