                                <div className="flex gap-2">
                                   <select className="flex-1 bg-white border border-slate-300 rounded-lg p-2 text-[10px] font-black outline-none" value={ev.player} onChange={e => { const updatedEvents = [...activeMatch.events]; updatedEvents[idx].player = e.target.value; setActiveMatch({...activeMatch, events: updatedEvents}); }}>
