                                   </select>
                                   <input type="text" placeholder="الدقيقة" className="w-16 bg-white border border-slate-300 rounded-lg p-2 text-[10px] font-black text-center outline-none" value={ev.minute} onChange={e => { const updatedEvents = [...activeMatch.events]; updatedEvents[idx].minute = e.target.value; setActiveMatch({...activeMatch, events: updatedEvents}); }} />
                                </div>
                             </div>
                          ))}
                          {activeMatch.events.length === 0 && <p className="text-center py-10 text-slate-300 font-black italic text-[10px]">لا يوجد أحداث مسجلة لهذه المباراة</p>}
