         <button onClick={() => setActiveTab('stats')} className={`px-8 py-3 rounded-xl font-black text-sm transition-all ${activeTab === 'stats' ? 'bg-[#001F3F] text-white shadow-lg' : 'text-slate-500'}`}>التقارير والإحصائيات</button>
      </div>

      {activeTab === 'agenda' ? (
        <>
          <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><CalendarIcon size={24} className="text-blue-900" /> أجندة التدريبات المركزية</h3>
            {canModifyConfig && (
                <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl flex items-center gap-2 font-black text-sm shadow-lg border-b-4 border-black">
