import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, ShieldAlert, History, Search, ShieldCheck, Lock, Clock, Calendar as CalendarIcon, AlertCircle, Printer, ChevronRight, FileText } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord, TrainingSession } from '../types';
import { generateUUID } from '../App';
import ClubLogo from './ClubLogo';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus; excuse?: string; time?: string; date?: string }>>({});
  const [showPrintView, setShowPrintView] = useState(false);

  const currentUser = state.currentUser!;
  const restrictedCat = currentUser.restrictedCategory;
  const isViewer = currentUser.role === 'مشاهد';
  const isCatAdmin = currentUser.role === 'إداري فئة';

  const sessions = state.sessions
    .filter(s => restrictedCat ? s.category === restrictedCat : (state.globalCategoryFilter === 'الكل' || s.category === state.globalCategoryFilter))
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);
  const players = state.people.filter(p => p.role === 'لاعب' && (activeSession ? p.category === activeSession.category : true));
  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    if (isViewer) return;
    if (isCatAdmin && savedRecords.some(r => r.personId === pid)) {
      alert('نظام الحماية: لا يمكنك تعديل حضور تم رصده مسبقاً.');
      return;
    }
    const now = new Date();
    setLocalRecords(prev => ({ 
      ...prev, 
      [pid]: { ...prev[pid], status, time: now.toLocaleTimeString('ar-SY', {hour: '2-digit', minute:'2-digit'}), date: now.toISOString().split('T')[0] } 
    }));
  };

  const saveAttendance = () => {
    const entries = Object.entries(localRecords);
    if (entries.length === 0) return;

    const newRecords: AttendanceRecord[] = entries.map(([pid, data]) => ({
      id: generateUUID(),
      personId: pid,
      sessionId: selectedSessionId,
      date: data.date || activeSession!.date,
      time: data.time || '',
      status: (data as any).status,
      excuse: (data as any).excuse,
      isLocked: true
    }));

    setState(p => ({
      ...p,
      attendance: [...p.attendance.filter(a => !(a.sessionId === selectedSessionId && localRecords[a.personId])), ...newRecords],
    }));
    setLocalRecords({});
    alert('تم تثبيت سجل الحضور بنجاح.');
  };

  if (showPrintView && activeSession) {
    return (
      <div className="fixed inset-0 bg-white z-[500] p-12 dir-rtl text-right overflow-y-auto">
        <div className="max-w-4xl mx-auto border-4 border-slate-900 p-10 print:border-2">
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-6 mb-8">
              <div className="flex items-center gap-4"><ClubLogo size={80} /><div><h2 className="text-2xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2><p className="text-sm font-black text-orange-600">كشف حضور التمرين</p></div></div>
              <div className="text-left font-black"><p className="text-xl uppercase">{activeSession.objective}</p><p className="text-sm text-slate-500">{activeSession.category} | {activeSession.date}</p></div>
           </div>
           <table className="w-full text-right border-collapse">
              <thead><tr className="bg-slate-100 border-y-2 border-slate-900 text-xs font-black"><th className="p-3">اسم اللاعب</th><th className="p-3 text-center">الرقم</th><th className="p-3 text-center">الحالة</th><th className="p-3">الملاحظات</th></tr></thead>
              <tbody>{players.map(p => { const r = savedRecords.find(rec => rec.personId === p.id); return (<tr key={p.id} className="border-b border-slate-200 text-xs font-black"><td className="p-3">{p.name}</td><td className="p-3 text-center">{p.number || '--'}</td><td className="p-3 text-center">{r?.status || '--'}</td><td className="p-3 text-[10px]">{r?.excuse || '--'}</td></tr>)})}</tbody>
           </table>
           <div className="mt-20 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12"><p className="font-black text-sm uppercase">إداري الفريق</p><p className="text-[10px]">..........................</p></div>
              <div className="text-center space-y-12"><p className="font-black text-sm uppercase">مدرب الفريق</p><p className="text-[10px]">..........................</p></div>
              <div className="text-center space-y-12"><p className="font-black text-sm uppercase">مشرف مكتب كرة القدم</p><p className="font-black text-xs text-blue-900">عزت عامر الشيخة</p><p className="text-[10px]">..........................</p></div>
           </div>
        </div>
        <button onClick={() => setShowPrintView(false)} className="no-print mt-4 bg-slate-100 p-2 rounded">إغلاق</button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[2.5rem] border-2 border-slate-900 flex flex-col md:flex-row gap-6 items-end">
        <div className="flex-1 w-full">
           <label className="text-[10px] font-black uppercase mb-1.5 block">اختيار تمرين نشط</label>
           <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); }}
            className="w-full bg-slate-100 border-2 border-slate-900 rounded-xl p-4 font-black text-slate-900 outline-none">
             <option value="">-- اختر التمرين من القائمة --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} | {s.objective} ({s.category})</option>)}
           </select>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowPrintView(true)} disabled={!selectedSessionId} className="bg-white border-2 border-slate-900 px-6 py-4 rounded-xl font-black shadow-sm">كشف ورقي</button>
          {!isViewer && <button onClick={saveAttendance} disabled={!selectedSessionId} className="bg-[#001F3F] text-white px-10 py-4 rounded-xl font-black border-b-4 border-black">تثبيت النهائي</button>}
        </div>
      </div>

      {activeSession && (
        <div className="bg-white rounded-[2.5rem] border-2 border-slate-900 overflow-hidden">
          <table className="w-full text-right">
            <thead className="bg-slate-200 border-b-2 border-slate-900"><tr><th className="px-6 py-4 text-[10px] font-black">اللاعب</th><th className="px-6 py-4 text-[10px] font-black text-center">الحالة</th><th className="px-6 py-4 text-[10px] font-black">عذر / ملاحظة</th></tr></thead>
            <tbody className="divide-y-2 divide-slate-200">
              {players.map(p => {
                const saved = savedRecords.find(r => r.personId === p.id);
                const local = localRecords[p.id];
                const status = local?.status || saved?.status;
                const isDisabled = isCatAdmin && saved && saved.status;
                return (
                  <tr key={p.id} className="hover:bg-blue-50/30">
                    <td className="px-6 py-5 font-black text-sm">{p.name} (#{p.number || '??'})</td>
                    <td className="px-6 py-5 flex justify-center gap-1">
                      {['حاضر', 'متأخر', 'غائب', 'غياب بعذر'].map(st => (
                        <button key={st} disabled={isDisabled || isViewer} onClick={() => handleSetStatus(p.id, st as any)}
                          className={`px-3 py-1.5 rounded-lg text-[9px] font-black border-2 transition-all ${status === st ? 'bg-slate-900 text-white' : 'bg-white'}`}>
                          {st}
                        </button>
                      ))}
                    </td>
                    <td className="px-6 py-5"><input disabled={isDisabled || isViewer} type="text" placeholder="..." className="bg-slate-50 border rounded px-2 py-1 text-[10px] w-full" value={local?.excuse || saved?.excuse || ''} onChange={e => setLocalRecords(prev => ({...prev, [p.id]: {...prev[p.id], excuse: e.target.value}}))}/></td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default AttendanceTracker;

import React, { useState, useMemo, useEffect } from 'react';
