interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [formData, setFormData] = useState<Partial<Match>>({ matchType: 'دوري' });

  useEffect(() => {
    if (isAddOpen) setFormData(p => ({ ...p, category: restrictedCat || state.categories[0] }));
  }, [isAddOpen, restrictedCat, state.categories]);

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => restrictedCat ? m.category === restrictedCat : (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter))
    .sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleSubstitutionCalculation = (subIndex: number, replacedPlayerId: string, subMinute: string) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    const minute = parseInt(subMinute) || 0;
    const stoppage = parseInt(activeMatch.stoppageTime || '0') || 0;

    newLineup.subs[subIndex].replacedPlayerId = replacedPlayerId;
    newLineup.subs[subIndex].substitutionMinute = subMinute;

    // منطق المطلوب: الداخل يحصل على (90+الضائع)-الدقيقة. الخارج يحصل على الدقيقة نفسها.
    newLineup.subs[subIndex].minutesPlayed = ((90 + stoppage) - minute).toString();

    const starterIdx = newLineup.starters.findIndex(s => s.playerId === replacedPlayerId);
    if (starterIdx !== -1) newLineup.starters[starterIdx].minutesPlayed = subMinute;

    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatch: Match = {
      id: generateUUID(),
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent || 'خصم غير محدد',
      date: formData.date || '',
      time: formData.time || '',
      category: formData.category || '',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime: '0',
      events: [],
      lineup: { starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '90' })), subs: [], staff: [], captain: '' },
      notes: ''
    };
    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    setIsAddOpen(false);
  };

  const saveMatchDetails = () => {
    if (!activeMatch) return;
    setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? activeMatch : m) }));
    setActiveMatch(null);
  };

  const fieldClass = "w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-slate-900 outline-none";
  const labelClass = "text-[10px] font-black uppercase mb-1.5 block";

  if (showPrintView) {
    return (
      <div className="fixed inset-0 bg-white z-[500] p-12 dir-rtl text-right overflow-y-auto">
        <div className="max-w-5xl mx-auto border-4 border-slate-900 p-12 print:border-2">
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-8 mb-10">
              <div className="flex items-center gap-4"><ClubLogo size={80} /><div><h2 className="text-2xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2><p className="text-md font-black text-orange-600">أجندة المباريات والنتائج</p></div></div>
           </div>
           {/* قائمة المباريات وتواقيع المسؤولين */}
           <div className="mt-24 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12"><p className="font-black text-sm uppercase">إداري الفريق</p><p className="text-[10px]">..........................</p></div>
              <div className="text-center space-y-12"><p className="font-black text-sm uppercase">مدرب الفريق</p><p className="text-[10px]">..........................</p></div>
              <div className="text-center space-y-12"><p className="font-black text-sm uppercase">مشرف مكتب كرة القدم</p><p className="font-black text-xs text-blue-900">عزت عامر الشيخة</p><p className="text-[10px]">..........................</p></div>
           </div>
        </div>
        <button onClick={() => setShowPrintView(false)} className="no-print mt-4">إغلاق</button>
      </div>
    );
  }

  return (
