import React, { useState, useMemo } from 'react';
import { Calendar as CalendarIcon, MapPin, Clock, Plus, Trash2, Edit, X, Printer, FileText, CheckCircle, ShieldCheck, Lock, AlertCircle, Map, ChevronRight, BarChart3, PieChart, Users, User, TrendingUp, CalendarDays } from 'lucide-react';
import { AppState, TrainingSession, Category, Person, AttendanceRecord } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

export default function TrainingPlanner({ state, setState, defaultSelectedId, addLog }: TrainingPlannerProps) {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري fئة';
  const canModifyConfig = isManager || isCatAdmin;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showPrintView, setShowPrintView] = useState(false);
  const [activeTab, setActiveTab] = useState<'agenda' | 'stats'>('agenda');
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);

  const [reportType, setReportType] = useState<'category' | 'player'>('category');
  const [selectedCatForReport, setSelectedCatForReport] = useState<string>(restrictedCat || state.categories[0] || '');
  const [selectedPlayerId, setSelectedPlayerId] = useState<string>('');
  const [reportPeriod, setReportPeriod] = useState<{ month: string, year: string }>({
    month: (new Date().getMonth() + 1).toString().padStart(2, '0'),
    year: new Date().getFullYear().toString()
  });
  const [printData, setPrintData] = useState<any>(null);

  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'الرجال'),
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    pitch: ''
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.time) return;

    // منع إضافة تمرين بتاريخ قديم
    const today = new Date().toISOString().split('T')[0];
    if (formData.date < today) {
      alert('عذراً، لا يمكن جدولة أو تعديل تمرين بتاريخ قديم. يرجى اختيار تاريخ اليوم أو تاريخ مستقبلي.');
      return;
    }

    // التأكد من أن إداري الفئة لا يغير الفئة
    const finalCategory = restrictedCat || formData.category;

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData, category: finalCategory } as TrainingSession : s)
      }));
      addLog?.('تعديل موعد تمرين', `تم تحديث بيانات تمرين فئة ${finalCategory}`, 'info');
    } else {
      const newSession: TrainingSession = {
        id: generateUUID(),
        category: finalCategory as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        objective: formData.objective || 'تمرين عام',
        pitch: formData.pitch || '',
        isCompleted: false
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
      addLog?.('إضافة موعد تمرين', `تمت جدولة تمرين جديد لفئة ${newSession.category}`, 'info');
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const handleDeleteSession = async (session: TrainingSession) => {
    // التحقق من الصلاحية: مدير أو إداري لنفس الفئة
    if (!isManager && restrictedCat !== session.category) {
      alert('لا تملك صلاحية حذف تمارين هذه الفئة.');
      return;
    }

    if (confirm(`هل أنت متأكد من حذف تمرين فئة ${session.category} نهائياً؟`)) {
      try {
        const { error } = await supabase.from('sessions').delete().eq('id', session.id);
        if (error) throw error;

        setState(prev => ({
          ...prev,
          sessions: prev.sessions.filter(s => s.id !== session.id)
        }));
        addLog?.('حذف تمرين', `تم إزالة حصة تدريبية لفئة ${session.category}`, 'error');
      } catch (err: any) {
        alert("فشل حذف التمرين من السحاب: " + err.message);
      }
    }
  };

  const filteredSessions = useMemo(() => {
    return (restrictedCat 
      ? state.sessions.filter(s => s.category === restrictedCat)
      : state.sessions.filter(s => (state.globalCategoryFilter === 'الكل' || s.category === state.globalCategoryFilter)))
      .sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [state.sessions, restrictedCat, state.globalCategoryFilter]);

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-4 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";

  if (showPrintView && printData) {
    return (
      <div className="fixed inset-0 bg-white z-[600] overflow-y-auto p-12 dir-rtl text-right">
        <div className="max-w-5xl mx-auto border-4 border-slate-900 p-12 print:border-2">
           <div className="no-print flex justify-between items-center mb-10 border-b pb-4">
              <button onClick={() => setShowPrintView(false)} className="flex items-center gap-2 font-black text-slate-500 hover:text-red-600 transition-all"><ChevronRight/> إغلاق المعاينة</button>
              <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-10 py-4 rounded-2xl font-black flex items-center gap-3 shadow-2xl"><Printer size={20}/> طباعة التقرير الفني PDF</button>
           </div>
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-8 mb-10">
              <div className="flex items-center gap-4">
                 <ClubLogo size={100} />
                 <div>
                    <h2 className="text-3xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-md font-black text-orange-600">مكتب كرة القدم المركزي</p>
                 </div>
              </div>
              <div className="text-left font-black">
                 <p className="text-2xl uppercase tracking-tighter">{printData.title}</p>
                 <p className="text-sm text-slate-500">الفترة: {printData.period}</p>
              </div>
           </div>
           <div className="mt-24 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12">
                 <p className="font-black text-sm uppercase">توقيع إداري الفريق</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm uppercase">توقيع مدرب الفريق</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm uppercase">مشرف مكتب كرة القدم</p>
                 <p className="font-black text-xs text-blue-900">عزت عامر الشيخة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-2 rounded-2xl border-2 border-slate-900 flex gap-2 w-fit no-print mx-auto mb-8 shadow-sm">
         <button onClick={() => setActiveTab('agenda')} className={`px-8 py-3 rounded-xl font-black text-sm transition-all ${activeTab === 'agenda' ? 'bg-[#001F3F] text-white shadow-lg' : 'text-slate-500'}`}>الأجندة التدريبية</button>
         <button onClick={() => setActiveTab('stats')} className={`px-8 py-3 rounded-xl font-black text-sm transition-all ${activeTab === 'stats' ? 'bg-[#001F3F] text-white shadow-lg' : 'text-slate-500'}`}>التقارير والإحصائيات</button>
      </div>

      {activeTab === 'agenda' ? (
        <>
          <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><CalendarIcon size={24} className="text-blue-900" /> أجندة التدريبات المركزية</h3>
            {canModifyConfig && (
                <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl flex items-center gap-2 font-black text-sm shadow-lg border-b-4 border-black">
                  <Plus size={20} /> إضافة حصة تدريبية
                </button>
            )}
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredSessions.map(session => (
                <div key={session.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative border-b-8">
                  <div className="flex justify-between items-center mb-4">
                     <span className="bg-[#001F3F] text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{session.category}</span>
                     {canModifyConfig && (
                        <div className="flex gap-1">
                          {(isManager || restrictedCat === session.category) && (
                            <>
                              <button onClick={() => { setEditingSessionId(session.id); setFormData(session); setIsModalOpen(true); }} className="p-2 bg-slate-100 rounded-lg"><Edit size={14}/></button>
                              <button onClick={() => handleDeleteSession(session)} className="p-2 bg-red-50 text-red-600 rounded-lg"><Trash2 size={14}/></button>
                            </>
                          )}
                        </div>
                     )}
                  </div>
                  <h4 className="text-lg font-black text-slate-900 mb-4">{session.objective}</h4>
                  <div className="space-y-1.5 text-xs font-black text-slate-500">
                    <p className="flex items-center gap-2"><CalendarIcon size={14} className="text-orange-600"/> {session.date} | {session.time}</p>
                    {session.pitch && <p className="flex items-center gap-2"><MapPin size={14} className="text-emerald-600"/> {session.pitch}</p>}
                  </div>
                </div>
            ))}
          </div>
        </>
      ) : (
        <div className="bg-white p-10 rounded-[3rem] border-2 border-slate-900 shadow-sm">
           <h3 className="text-2xl font-black text-slate-900 mb-10">محرك استخراج التقارير الفنية</h3>
           <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
              <div className="space-y-4">
                 <label className={labelClass}>نوع التقرير</label>
                 <select value={reportType} onChange={e => setReportType(e.target.value as any)} className={fieldClass}>
                    <option value="category">تقرير فئة</option>
                    <option value="player">تقرير لاعب</option>
                 </select>
              </div>
              <div className="flex items-end"><button onClick={() => {}} className="w-full bg-[#001F3F] text-white py-4 rounded-2xl font-black shadow-xl">استخراج ومعاينة التقرير</button></div>
           </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[500] p-4">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg border-[6px] border-slate-900 overflow-hidden">
              <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center">
                 <h3 className="font-black">جدولة تمرين جديد</h3>
                 <button onClick={() => setIsModalOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900"><X size={20}/></button>
              </div>
              <form onSubmit={handleSave} className="p-8 space-y-5">
                 <div className="space-y-1">
                    <label className={labelClass}>الفئة</label>
                    <select required disabled={!!restrictedCat} className={fieldClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                 </div>
                 <div className="space-y-1">
                    <label className={labelClass}>موضوع التمرين</label>
                    <input required type="text" className={fieldClass} value={formData.objective || ''} onChange={e => setFormData({...formData, objective: e.target.value})} />
                 </div>
                 <div className="space-y-1">
                    <label className={labelClass}>مكان التمرين (الملعب)</label>
                    <input type="text" className={fieldClass} value={formData.pitch || ''} onChange={e => setFormData({...formData, pitch: e.target.value})} placeholder="مثلاً: الملعب الصناعي.." />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <input required type="date" className={fieldClass} value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                    <input required type="time" className={fieldClass} value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black">حفظ الحصة التدريبية</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo, useEffect } from 'react';
import { Trophy, MapPin, Clock, Plus, X, Trash2, Target, UserPlus, Printer, FileText, Users, Save, CheckCircle, Timer, Crown, LogOut, ChevronRight, BookOpen } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [formData, setFormData] = useState<Partial<Match>>({ matchType: 'دوري' });

  useEffect(() => {
    if (isAddOpen) setFormData(p => ({ ...p, category: restrictedCat || state.categories[0] }));
  }, [isAddOpen, restrictedCat, state.categories]);

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => restrictedCat ? m.category === restrictedCat : (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter))
    .sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isViewer) return;

    const finalCategory = restrictedCat || formData.category;

    const newMatch: Match = {
      id: generateUUID(),
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent || 'خصم غير محدد',
      date: formData.date || '',
      time: formData.time || '',
      category: finalCategory || '',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime: '0',
      events: [],
      lineup: { starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '90' })), subs: [], staff: [], captain: '' },
      notes: ''
    };
    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مباراة ضد ${newMatch.opponent} لفئة ${newMatch.category}`, 'success');
    setIsAddOpen(false);
  };

  const handleDeleteMatch = async (match: Match) => {
    if (isViewer) return;
    if (!isManager && restrictedCat !== match.category) {
      alert('لا تملك صلاحية حذف مباريات هذه الفئة.');
      return;
    }

    if(confirm(`هل أنت متأكد من حذف مباراة ${match.opponent} لفئة ${match.category}؟`)) {
      try {
        const { error } = await supabase.from('matches').delete().eq('id', match.id);
        if (error) throw error;

        setState(p => ({...p, matches: p.matches.filter(x => x.id !== match.id)}));
        addLog?.('حذف مباراة', `تم مسح مباراة ${match.opponent} من الأجندة`, 'error');
      } catch (err: any) {
        alert("فشل الحذف من السحاب: " + err.message);
      }
    }
  };

  const saveMatchDetails = () => {
    if (!activeMatch || isViewer) return;
    setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? activeMatch : m) }));
    setActiveMatch(null);
  };

  const fieldClass = "w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-slate-900 outline-none";
  const labelClass = "text-[10px] font-black uppercase mb-1.5 block";

  if (showPrintView) {
    return (
      <div className="fixed inset-0 bg-white z-[500] p-12 dir-rtl text-right overflow-y-auto">
        <div className="max-w-5xl mx-auto border-4 border-slate-900 p-12 print:border-2">
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-8 mb-10">
              <div className="flex items-center gap-4"><ClubLogo size={80} /><div><h2 className="text-2xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2><p className="text-md font-black text-orange-600">أجندة المباريات والنتائج</p></div></div>
           </div>
           <div className="mt-24 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12"><p className="font-black text-sm uppercase">إداري الفريق</p><p className="text-[10px]">..........................</p></div>
              <div className="text-center space-y-12"><p className="font-black text-sm uppercase">مدرب الفريق</p><p className="text-[10px]">..........................</p></div>
              <div className="text-center space-y-12"><p className="font-black text-sm uppercase">مشرف مكتب كرة القدم</p><p className="font-black text-xs text-blue-900">عزت عامر الشيخة</p><p className="text-[10px]">..........................</p></div>
           </div>
        </div>
        <button onClick={() => setShowPrintView(false)} className="no-print mt-4">إغلاق</button>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[2rem] border-2 border-slate-900 flex justify-between items-center no-print">
        <h2 className="text-xl font-black flex items-center gap-3"><Trophy size={24} className="text-orange-600" /> أجندة المباريات المركزية</h2>
        <div className="flex gap-2">
           <button onClick={() => setShowPrintView(true)} className="bg-white border-2 border-slate-900 px-6 py-3 rounded-xl font-black">طباعة</button>
           {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black">جدولة مباراة</button>}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredMatches.map(m => (
          <div key={m.id} className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 relative border-b-8">
             <div className="flex justify-between items-center mb-6">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400">{m.date} - {m.category}</span>
             </div>
             <div className="text-center mb-6">
                <p className="text-3xl font-black">{m.ourScore} - {m.opponentScore}</p>
                <p className="text-sm font-black text-slate-900 mt-2 uppercase tracking-tighter">ضد: {m.opponent}</p>
             </div>
             <div className="flex gap-2">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs">التشكيل والتقرير</button>
                {!isViewer && (isManager || restrictedCat === m.category) && (
                  <button onClick={() => handleDeleteMatch(m)} className="p-3 bg-red-50 text-red-600 rounded-xl border-2 border-red-900"><Trash2 size={16}/></button>
                )}
             </div>
          </div>
        ))}
      </div>

      {isAddOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[500] p-4">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg border-[6px] border-slate-900 overflow-hidden">
              <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center">
                 <h3 className="font-black">جدولة مباراة جديدة</h3>
                 <button onClick={() => setIsAddOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900"><X size={20}/></button>
              </div>
              <form onSubmit={handleAddMatch} className="p-8 space-y-5">
                 <div className="space-y-1">
                    <label className={labelClass}>الفئة</label>
                    <select required disabled={!!restrictedCat} className={fieldClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                 </div>
                 <div className="space-y-1">
                    <label className={labelClass}>الخصم</label>
                    <input required type="text" className={fieldClass} value={formData.opponent || ''} onChange={e => setFormData({...formData, opponent: e.target.value})} />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <input required type="date" className={fieldClass} value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                    <input required type="time" className={fieldClass} value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black">حفظ المباراة</button>
              </form>
           </div>
        </div>
      )}

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl z-[400] overflow-y-auto p-4">
           <div className="max-w-6xl mx-auto bg-white rounded-[3rem] border-[8px] border-slate-900 p-8">
              <div className="flex justify-between items-center mb-10 border-b-4 pb-4">
                 <h2 className="text-2xl font-black">الكرامة × {activeMatch.opponent} ({activeMatch.category})</h2>
                 <div className="flex gap-3">
                    {!isViewer && (isManager || restrictedCat === activeMatch.category) && (
                      <button onClick={saveMatchDetails} className="bg-emerald-600 text-white px-8 py-3 rounded-xl font-black border-b-4 border-black">حفظ التعديلات</button>
                    )}
                    <button onClick={() => setActiveMatch(null)} className="text-red-600 font-black">إغلاق</button>
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                 <div className="md:col-span-2 space-y-8">
                    <section>
                       <h3 className="font-black mb-4 flex items-center gap-2 border-r-4 border-orange-600 pr-3">التشكيلة والتبديلات</h3>
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                          {activeMatch.lineup.starters.map((s, idx) => (
                             <div key={idx} className="bg-slate-50 p-3 rounded-xl border flex items-center gap-2">
                                <select disabled={isViewer || (!isManager && restrictedCat !== activeMatch.category)} className="flex-1 text-xs font-black p-1 border rounded" value={s.playerId} 
                                   onChange={e => {
                                      const p = state.people.find(x => x.id === e.target.value);
                                      if(!p) return;
                                      const nl = {...activeMatch.lineup};
                                      nl.starters[idx] = {playerId: p.id, name: p.name, number: p.number?.toString() || '', minutesPlayed: '90'};
                                      setActiveMatch({...activeMatch, lineup: nl});
                                   }}>
                                   <option value="">-- لاعب --</option>
                                   {state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch.category).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                </select>
                             </div>
                          ))}
                       </div>
                    </section>
                 </div>
                 <div className="space-y-6">
                    <section className="bg-slate-900 text-white p-6 rounded-2xl border-4 border-orange-600">
                       <h3 className="font-black text-xs uppercase mb-4 text-orange-400 text-center">النتيجة</h3>
                       <div className="flex justify-center gap-4 mb-4">
                          <input disabled={isViewer || (!isManager && restrictedCat !== activeMatch.category)} type="number" className="w-16 h-16 bg-white text-slate-900 rounded-lg text-center font-black text-3xl" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                          <span className="text-3xl font-black mt-3">:</span>
                          <input disabled={isViewer || (!isManager && restrictedCat !== activeMatch.category)} type="number" className="w-16 h-16 bg-white text-slate-900 rounded-lg text-center font-black text-3xl" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                       </div>
                    </section>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

