                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <input required type="date" className={fieldClass} value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                    <input required type="time" className={fieldClass} value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black">حفظ الحصة التدريبية</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo, useEffect } from 'react';
import { Trophy, MapPin, Clock, Plus, X, Trash2, Target, UserPlus, Printer, FileText, Users, Save, CheckCircle, Timer, Crown, LogOut, ChevronRight, BookOpen } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [formData, setFormData] = useState<Partial<Match>>({ matchType: 'دوري' });

  useEffect(() => {
    if (isAddOpen) setFormData(p => ({ ...p, category: restrictedCat || state.categories[0] }));
  }, [isAddOpen, restrictedCat, state.categories]);

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => restrictedCat ? m.category === restrictedCat : (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter))
    .sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isViewer) return;

    const finalCategory = restrictedCat || formData.category;

    const newMatch: Match = {
      id: generateUUID(),
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent || 'خصم غير محدد',
      pitch: formData.pitch || '',
      date: formData.date || '',
      time: formData.time || '',
      category: finalCategory || '',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime: '0',
      events: [],
      lineup: { starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '90' })), subs: [], staff: [], captain: '' },
      notes: ''
    };
    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مباراة ضد ${newMatch.opponent} لفئة ${newMatch.category}`, 'success');
    setIsAddOpen(false);
  };

  const handleDeleteMatch = async (match: Match) => {
    if (isViewer) return;
    if (!isManager && restrictedCat !== match.category) {
      alert('لا تملك صلاحية حذف مباريات هذه الفئة.');
      return;
    }

    if(confirm(`هل أنت متأكد من حذف مباراة ${match.opponent} لفئة ${match.category}؟`)) {
      try {
        const { error } = await supabase.from('matches').delete().eq('id', match.id);
        if (error) throw error;

        setState(p => ({...p, matches: p.matches.filter(x => x.id !== match.id)}));
        addLog?.('حذف مباراة', `تم مسح مباراة ${match.opponent} من الأجندة`, 'error');
      } catch (err: any) {
        alert("فشل الحذف من السحاب: " + err.message);
      }
    }
  };

  const saveMatchDetails = () => {
