           </div>
           <div className="mt-24 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12"><p className="font-black text-sm uppercase">إداري الفريق</p><p className="text-[10px]">..........................</p></div>
              <div className="text-center space-y-12"><p className="font-black text-sm uppercase">مدرب الفريق</p><p className="text-[10px]">..........................</p></div>
