                <p className="text-sm font-black text-slate-900 mt-2 uppercase tracking-tighter">ضد: {m.opponent}</p>
                {m.pitch && <p className="text-[10px] font-black text-slate-400 mt-1 flex items-center justify-center gap-1"><MapPin size={10}/> {m.pitch}</p>}
             </div>
             <div className="flex gap-2">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs">التشكيل والتقرير</button>
                {!isViewer && (isManager || restrictedCat === m.category) && (
                  <button onClick={() => handleDeleteMatch(m)} className="p-3 bg-red-50 text-red-600 rounded-xl border-2 border-red-900"><Trash2 size={16}/></button>
                )}
             </div>
          </div>
        ))}
      </div>

      {isAddOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[500] p-4">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg border-[6px] border-slate-900 overflow-hidden">
              <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center">
                 <h3 className="font-black">جدولة مباراة جديدة</h3>
                 <button onClick={() => setIsAddOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900"><X size={20}/></button>
              </div>
              <form onSubmit={handleAddMatch} className="p-8 space-y-5">
