              <div className="flex justify-between items-center mb-10 border-b-4 pb-4">
                 <h2 className="text-2xl font-black">الكرامة × {activeMatch.opponent} ({activeMatch.category})</h2>
                 <div className="flex gap-3">
                    {!isViewer && (isManager || restrictedCat === activeMatch.category) && (
                      <button onClick={saveMatchDetails} className="bg-emerald-600 text-white px-8 py-3 rounded-xl font-black border-b-4 border-black">حفظ التعديلات</button>
                    )}
                    <button onClick={() => setActiveMatch(null)} className="text-red-600 font-black">إغلاق</button>
                 </div>
