                                      if(!p) return;
                                      const nl = {...activeMatch.lineup};
                                      nl.starters[idx] = {playerId: p.id, name: p.name, number: p.number?.toString() || '', minutesPlayed: '90'};
                                      setActiveMatch({...activeMatch, lineup: nl});
                                   }}>
                                   <option value="">-- لاعب --</option>
                                   {state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch.category).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
