          <ChevronRight size={20} /> العودة لقائمة الفريق
        </button>
        <div className="flex items-center gap-3">
           <button 
             onClick={handleGenerateAiAnalysis} 
             disabled={loadingAi}
             className="bg-gradient-to-r from-orange-600 to-orange-500 text-white px-6 py-3 rounded-xl font-black text-xs flex items-center gap-3 shadow-lg hover:shadow-orange-600/20 transition-all border-b-4 border-orange-800 disabled:opacity-50 group"
           >
             {loadingAi ? <Loader2 className="animate-spin" size={18}/> : <Sparkles className="group-hover:rotate-12 transition-transform" size={18} />}
             تحليل تقني ذكي (AI)
           </button>
           <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg hover:bg-black transition-all border-b-4 border-black">
             <Printer size={18} /> طباعة التقرير
           </button>
        </div>
      </div>

      {aiAnalysis && (
        <div className="bg-gradient-to-br from-white to-orange-50/30 p-8 rounded-[3rem] border-4 border-orange-600 shadow-xl animate-in zoom-in-95 duration-500 no-print relative overflow-hidden">
           <div className="absolute top-0 left-0 w-32 h-32 bg-orange-600/5 rounded-full -ml-16 -mt-16"></div>
           <div className="flex justify-between items-start mb-6">
              <h3 className="text-xl font-black text-orange-600 flex items-center gap-3 uppercase tracking-tighter">
                <Sparkles size={24}/> التقرير الفني المولد بالذكاء الاصطناعي
              </h3>
              <button onClick={() => setAiAnalysis(null)} className="text-slate-400 hover:text-red-600 transition-colors"><X size={20}/></button>
           </div>
           <div className="prose prose-slate max-w-none text-right font-black leading-loose text-slate-700 whitespace-pre-wrap">
              {aiAnalysis}
           </div>
           <div className="mt-6 pt-4 border-t border-orange-200 flex justify-between items-center">
              <p className="text-[9px] font-black text-orange-400 uppercase tracking-widest">تحليل مدعوم بموديل Gemini 3 Pro • نادي الكرامة</p>
              <button onClick={handleGenerateAiAnalysis} className="text-[10px] font-black text-blue-600 underline">تحديث التحليل</button>
           </div>
        </div>
      )}

      <div className="bg-white rounded-[3rem] shadow-xl border-4 border-slate-900 overflow-hidden relative">
        <div className="bg-[#001F3F] h-32 relative">
