    return data.map(item => {
      const cleanItem = JSON.parse(JSON.stringify(item));
      Object.keys(cleanItem).forEach(key => {
        if (cleanItem[key] === undefined || cleanItem[key] === "") {
          cleanItem[key] = null;
        }
      });
      return cleanItem;
    });
  };

  const fetchData = useCallback(async (force = false) => {
    if (!state.currentUser || (syncLockRef.current && !force)) return;

    setIsSyncing(true);
    setSyncStatus('syncing');
    try {
      const [
        { data: cats },
        { data: ppl },
        { data: sess },
        { data: mtch },
        { data: attn },
        { data: usrs }
      ] = await Promise.all([
        supabase.from('categories').select('name'),
        supabase.from('people').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
        supabase.from('users').select('*'),
      ]);

      setState(prev => ({
        ...prev,
        categories: (cats && cats.length > 0) ? cats.map(c => c.name) : prev.categories,
        people: ppl || [],
        sessions: sess || [],
        matches: mtch || [],
        attendance: attn || [],
        users: usrs || prev.users
      }));
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
      addLog('خطأ في جلب البيانات', error.message || 'فشل الوصول للسحاب.', 'error');
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser, addLog]);

  useEffect(() => {
    if (!state.currentUser) return;

    const channels = ['people', 'sessions', 'matches', 'attendance', 'users'].map(table => 
      supabase
        .channel(`public:${table}`)
        .on('postgres_changes', { event: '*', schema: 'public', table: table }, () => {
          if (!syncLockRef.current) fetchData();
        })
        .subscribe()
    );

    return () => {
      channels.forEach(channel => supabase.removeChannel(channel));
    };
  }, [state.currentUser, fetchData]);

  const pushData = useCallback(async (updatedState: AppState) => {
    if (!updatedState.currentUser) return;

    syncLockRef.current = true;
    setSyncStatus('syncing');
    try {
      const tables = [
        { name: 'people', data: updatedState.people },
        { name: 'sessions', data: updatedState.sessions },
        { name: 'matches', data: updatedState.matches },
        { name: 'attendance', data: updatedState.attendance },
        { name: 'users', data: updatedState.users }
      ];

      for (const table of tables) {
        if (table.data.length > 0) {
          const { error } = await supabase
            .from(table.name)
            .upsert(sanitize(table.data), { onConflict: 'id' });

          if (error) throw new Error(`${table.name}: ${error.message}`);
        }
      }

      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
      addLog('فشل مزامنة الجداول', error.message || 'خطأ غير معروف', 'error');
    } finally {
      setTimeout(() => {
        syncLockRef.current = false;
      }, 500);
    }
  }, [addLog]);

  useEffect(() => {
    if (state.currentUser) fetchData(true);
  }, [state.currentUser, fetchData]);

  const updateStateAndSync = async (updater: (prev: AppState) => AppState) => {
    let nextState: AppState | null = null;
    setState(prev => {
      nextState = updater(prev);
      return nextState;
    });

    if (nextState) await pushData(nextState);
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setActiveTab('dashboard');
  };

  if (!state.currentUser) {
    return <Login onLogin={(user) => setState(prev => ({ ...prev, currentUser: user }))} state={state} />;
  }

  const navItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'إدارة الفريق', icon: Users },
    { id: 'attendance', label: 'نظام الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'ai', label: 'المحلل الذكي (AI)', icon: Sparkles },
    { id: 'logistics', label: 'المساعد اللوجستي', icon: Map },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#001F3F] text-white transform transition-transform duration-300 lg:translate-x-0 lg:static lg:inset-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print shadow-2xl`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between border-b border-white/10">
            <div className="flex items-center gap-3">
              <ClubLogo size={40} />
              <span className="font-black text-lg tracking-tight">نادي الكرامة</span>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2"><X size={24} /></button>
          </div>
          <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1 custom-scrollbar">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-orange-600 text-white shadow-lg shadow-orange-600/20' : 'text-white/70 hover:bg-white/5 hover:text-white'}`}>
                <item.icon size={20} className={item.id === 'ai' ? 'animate-pulse' : ''} />
                <span className="font-bold">{item.label}</span>
              </button>
            ))}
          </nav>
          <div className="p-4 border-t border-white/10">
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-400/10 transition-colors font-bold">
              <LogOut size={20} /> <span>تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/90 backdrop-blur-md border-b sticky top-0 z-40 px-4 lg:px-8 py-4 flex items-center justify-between shadow-sm no-print">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 bg-slate-100 rounded-lg"><Menu size={24} /></button>
            <h1 className="text-xl font-black text-slate-800">
              {navItems.find(i => i.id === activeTab)?.label || (activeTab === 'report' ? 'التقرير الفني' : 'تفاصيل')}
            </h1>
          </div>

          <div className="flex items-center gap-4">
            <div className={`flex items-center gap-2 px-4 py-2 rounded-2xl border transition-all duration-500 ${
              syncStatus === 'synced' ? 'bg-emerald-50 border-emerald-200 text-emerald-700' :
              syncStatus === 'error' ? 'bg-red-50 border-red-200 text-red-700 animate-pulse' :
              'bg-orange-50 border-orange-200 text-orange-700'
            }`}>
               {syncStatus === 'synced' && <CloudCheck size={18} />}
               {syncStatus === 'error' && <CloudOff size={18} />}
               {syncStatus === 'syncing' && <Cloud size={18} className="animate-bounce" />}
               <span className="text-[10px] font-black uppercase whitespace-nowrap hidden sm:inline">
                 {syncStatus === 'synced' ? 'مزامنة كاملة' : syncStatus === 'error' ? 'خطأ بالربط' : 'جاري الرفع...'}
               </span>
            </div>
            <button onClick={() => fetchData(true)} className="p-2.5 rounded-xl bg-slate-100 text-slate-600 hover:bg-slate-200 transition-all">
              <RefreshCw size={20} className={isSyncing ? 'animate-spin' : ''} />
            </button>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto space-y-6 pb-20">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} addLog={addLog} />}
            {activeTab === 'ai' && <AIAssistant state={state} />}
            {activeTab === 'logistics' && <LocationAssistant />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Sparkles, Send, Bot, User, Loader2, BrainCircuit, Zap, X } from 'lucide-react';
import { AppState } from '../types';

interface AIAssistantProps {
  state: AppState;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ state }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleAsk = async () => {
    if (!input.trim() || loading) return;

    const userQuery = input;
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setInput('');
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // إعداد السياق للذكاء الاصطناعي بناءً على بيانات النادي الحالية
      const context = `
        أنت المحلل الذكي الرسمي لنادي الكرامة الرياضي. بيانات النادي المتوفرة:
        - عدد الكوادر: ${state.people.length}
        - المباريات: ${state.matches.length}
        - التمارين: ${state.sessions.length}
        - الفئات: ${state.categories.join(', ')}

        بيانات اللاعبين: ${state.people.filter(p => p.role === 'لاعب').map(p => `${p.name} (#${p.number} - ${p.category})`).join(', ')}
        نتائج آخر المباريات: ${state.matches.filter(m => m.isCompleted).map(m => `ضد ${m.opponent} (${m.ourScore}-${m.opponentScore})`).join(' | ')}

        أجب باحترافية رياضية وباللغة العربية الفصحى. كن فخوراً بعراقة نادي الكرامة السوري.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `${context}\nالمستخدم يسأل: ${userQuery}`,
      });

      setMessages(prev => [...prev, { role: 'ai', text: response.text || "عذراً، لم أستطع تحليل الطلب." }]);
    } catch (error: any) {
      setMessages(prev => [...prev, { role: 'ai', text: "حدث خطأ في الاتصال بـ Gemini: " + error.message }]);
    } finally {
      setLoading(false);
    }
  };

  const suggestions = [
    "حلل أداء فئة الشباب في المباريات الأخيرة",
    "اقترح لي تمرين لتقوية الدفاع",
    "من هم أبرز هدافي النادي حالياً؟",
    "اعطني ملخصاً عن التزام اللاعبين بالتمارين"
  ];

  return (
    <div className="flex flex-col h-[calc(100vh-180px)] space-y-4 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 shadow-sm flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-orange-500 to-orange-600 p-3 rounded-2xl shadow-lg">
            <Sparkles className="text-white" size={24} />
          </div>
          <div>
            <h2 className="text-xl font-black text-slate-900">مساعد "الكرامة" الذكي (AI)</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">تحليل فني وإداري متقدم بذكاء Gemini</p>
          </div>
        </div>
        <div className="hidden md:flex gap-2">
           <span className="bg-blue-50 text-blue-700 text-[9px] font-black px-3 py-1 rounded-lg border border-blue-100 flex items-center gap-1"><BrainCircuit size={12}/> تحليل البيانات الحية</span>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[3rem] border-2 border-slate-900 shadow-inner overflow-hidden flex flex-col relative">
        <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center space-y-6 opacity-40">
              <Bot size={80} className="text-slate-200" />
              <div>
                <p className="font-black text-slate-400 text-lg">أنا جاهز لتحليل بيانات النادي وإفادتك..</p>
                <p className="text-xs font-black text-slate-300 mt-1">اطرح سؤالاً عن أداء أي لاعب أو فئة أو اطلب نصيحة تدريبية</p>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3 w-full max-w-lg">
                {suggestions.map((s, i) => (
                  <button key={i} onClick={() => setInput(s)} className="p-3 bg-slate-50 border-2 border-dashed border-slate-300 rounded-xl text-[10px] font-black hover:border-orange-600 hover:text-orange-600 transition-all text-right">
                    {s}
                  </button>
                ))}
              </div>
            </div>
          )}

          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-start' : 'justify-end'} animate-in slide-in-from-bottom-2`}>
              <div className={`max-w-[85%] p-5 rounded-[2rem] flex gap-4 ${msg.role === 'user' ? 'bg-slate-100 border-2 border-slate-900 text-slate-900 rounded-tr-none' : 'bg-[#001F3F] text-white rounded-tl-none shadow-xl border-b-4 border-orange-600'}`}>
                <div className={`shrink-0 w-8 h-8 rounded-full flex items-center justify-center ${msg.role === 'user' ? 'bg-slate-900 text-white' : 'bg-orange-600 text-white'}`}>
                  {msg.role === 'user' ? <User size={16}/> : <Bot size={16}/>}
                </div>
                <div className="text-sm font-medium leading-relaxed whitespace-pre-wrap">
                  {msg.text}
                </div>
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-end">
              <div className="bg-[#001F3F] text-white p-5 rounded-[2rem] rounded-tl-none flex items-center gap-3 shadow-lg">
                <Loader2 className="animate-spin" size={20} />
                <span className="text-xs font-black animate-pulse">جاري التفكير وتحليل قاعدة البيانات...</span>
              </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        <div className="p-6 bg-slate-50 border-t-2 border-slate-900 flex gap-3 items-center">
          <input 
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleAsk()}
            placeholder="اسأل المحلل الذكي عن أي شيء يخص النادي..."
            className="flex-1 bg-white border-2 border-slate-900 rounded-2xl px-6 py-4 font-black text-slate-900 outline-none focus:ring-4 focus:ring-orange-600/10 transition-all"
          />
          <button 
            onClick={handleAsk}
            disabled={loading || !input.trim()}
            className="bg-[#001F3F] text-white p-4 rounded-2xl hover:bg-black transition-all shadow-lg disabled:opacity-50"
          >
            <Send size={24} />
          </button>
        </div>
      </div>
    </div>
  );
};

