    { id: 'logistics', label: 'المساعد اللوجستي', icon: Map },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  const unreadCount = state.notifications.filter(n => !n.isRead).length;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#001F3F] text-white transform transition-transform duration-300 lg:translate-x-0 lg:static lg:inset-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print shadow-2xl`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between border-b border-white/10">
            <div className="flex items-center gap-3">
              <ClubLogo size={40} />
              <span className="font-black text-lg tracking-tight">نادي الكرامة</span>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2"><X size={24} /></button>
          </div>
          <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1 custom-scrollbar">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-orange-600 text-white shadow-lg shadow-orange-600/20' : 'text-white/70 hover:bg-white/5 hover:text-white'}`}>
                <item.icon size={20} className={item.id === 'ai' ? 'animate-pulse text-orange-400' : ''} />
                <span className="font-bold">{item.label}</span>
              </button>
            ))}
          </nav>
          <div className="p-4 border-t border-white/10">
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-400/10 transition-colors font-bold">
              <LogOut size={20} /> <span>تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/90 backdrop-blur-md border-b sticky top-0 z-40 px-4 lg:px-8 py-4 flex items-center justify-between shadow-sm no-print">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 bg-slate-100 rounded-lg"><Menu size={24} /></button>
            <h1 className="text-xl font-black text-slate-800">
              {navItems.find(i => i.id === activeTab)?.label || (activeTab === 'report' ? 'التقرير الفني' : 'تفاصيل')}
            </h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-4 ml-6 border-l pl-6 border-slate-200">
               <div className="flex items-center gap-3">
                  <div className="text-left">
                    <p className="text-xs font-black text-slate-900 leading-none">{state.currentUser.username}</p>
                    <p className="text-[9px] font-black text-orange-600 uppercase tracking-widest mt-1">{state.currentUser.role}</p>
                  </div>
                  <div className="w-10 h-10 bg-[#001F3F] text-white rounded-xl flex items-center justify-center font-black shadow-lg border-2 border-white ring-2 ring-slate-100">
                    <User size={20} />
                  </div>
               </div>
            </div>

            <div className="flex items-center gap-2">
              <div className="relative">
                <button 
                  onClick={() => setShowNotifications(!showNotifications)}
                  className={`p-2.5 rounded-xl transition-all relative ${unreadCount > 0 ? 'bg-orange-50 text-orange-600' : 'bg-slate-100 text-slate-400'}`}
                >
                  <Bell size={20} />
                  {unreadCount > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[8px] font-black w-4 h-4 rounded-full flex items-center justify-center border-2 border-white animate-bounce">{unreadCount}</span>}
                </button>
                {showNotifications && (
                  <div className="absolute left-0 mt-3 w-80 bg-white border-2 border-slate-900 rounded-[2rem] shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2">
                    <div className="p-4 bg-slate-100 border-b-2 border-slate-900 font-black text-xs flex justify-between">
                       <span>آخر التنبيهات والعمليات</span>
                       <button onClick={() => setState(p => ({...p, notifications: []}))} className="text-red-600">مسح الكل</button>
                    </div>
                    <div className="max-h-96 overflow-y-auto custom-scrollbar p-2 space-y-2">
                       {state.notifications.length === 0 ? (
                         <p className="py-8 text-center text-[10px] font-black text-slate-400 italic">لا يوجد إشعارات حالياً</p>
                       ) : state.notifications.map(n => (
                         <div key={n.id} className="p-3 bg-slate-50 border border-slate-200 rounded-xl">
                            <p className="text-[11px] font-black text-slate-900">{n.message}</p>
                            <p className="text-[9px] font-medium text-slate-400 mt-1">{new Date(n.timestamp).toLocaleTimeString()}</p>
                         </div>
                       ))}
                    </div>
                  </div>
                )}
              </div>

              <div className={`flex items-center gap-2 px-4 py-2 rounded-2xl border transition-all duration-500 ${
                syncStatus === 'synced' ? 'bg-emerald-50 border-emerald-200 text-emerald-700' :
                syncStatus === 'error' ? 'bg-red-50 border-red-200 text-red-700 animate-pulse' :
                'bg-orange-50 border-orange-200 text-orange-700'
              }`}>
                 {syncStatus === 'synced' && <CloudCheck size={18} />}
                 {syncStatus === 'error' && <CloudOff size={18} />}
                 {syncStatus === 'syncing' && <Cloud size={18} className="animate-bounce" />}
                 <span className="text-[10px] font-black uppercase whitespace-nowrap hidden sm:inline">
                   {syncStatus === 'synced' ? 'مزامنة كاملة' : syncStatus === 'error' ? 'خطأ بالربط' : 'جاري الرفع...'}
                 </span>
              </div>
              <button onClick={() => fetchData(true)} className="p-2.5 rounded-xl bg-slate-100 text-slate-600 hover:bg-slate-200 transition-all shadow-sm">
                <RefreshCw size={20} className={isSyncing ? 'animate-spin' : ''} />
              </button>
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto space-y-6 pb-20">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} addLog={addLog} />}
            {activeTab === 'ai' && <AIAssistant state={state} />}
            {activeTab === 'logistics' && <LocationAssistant />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        {/* بوت الدردشة العائم متاح في كامل أرجاء التطبيق */}
        <ChatBot />
      </main>
    </div>
  );
};

export default App;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
export type UserRole = 'مدير' | 'إداري فئة' | 'مشاهد';
export type MatchType = 'دوري' | 'كأس' | 'ودية' | 'بطولة ودية' | 'مباراة دولية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface Person {
  id: string;
  name: string;
  fatherName: string;
  motherName: string;
  birthDate: string;
  birthPlace: string;
  khana: string;
  nationalId: string;
  federalNumber: string;
  internationalId: string;
  address: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  contractStart?: string;
  contractEnd?: string;
  contractValue?: string;
  medicalHistory?: string;
  injuries?: string;
  penalties?: string;
  notes?: string;
  coachingCertificate?: string;
  academicDegree?: string;
  // حقول التتبع اللحظي الجديدة
  lat?: number;
  lng?: number;
  lastLocationUpdate?: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  excuse?: string;
  fine?: string;
  isLocked?: boolean;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  pitch?: string;
  objective: string;
  isCompleted?: boolean;
}

export interface MatchEvent {
  id: string;
  type: 'goal' | 'assist' | 'yellow' | 'red' | 'injury' | 'substitution';
  player: string; 
  minute: string;
  note?: string;
}

export interface Match {
  id: string;
  category: Category;
  matchType: MatchType;
  opponent: string;
  pitch?: string;
  date: string;
  time: string;
  advancePayment: string;
  isCompleted: boolean;
  ourScore: string;
  opponentScore: string;
  stoppageTime?: string; // للحفاظ على التوافق القديم
  stoppageTime1?: string; // وقت ضائع شوط أول
  stoppageTime2?: string; // وقت ضائع شوط ثاني
  events: MatchEvent[];
  lineup: {
    starters: { playerId: string; name: string; number: string; minutesPlayed?: string }[];
    subs: { 
      playerId: string; 
      name: string; 
      number: string; 
      minutesPlayed?: string;
      substitutionMinute?: string;
      replacedPlayerId?: string;
    }[];
    staff: { role: string; name: string }[];
    captain: string;
  };
  notes?: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  categories: Category[];
  currentUser: AppUser | null;
  notifications: AppNotification[];
  globalCategoryFilter: Category | 'الكل';
}

import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { 
  MapPin, Search, Navigation, Hospital, Utensils, Trophy, 
  ExternalLink, Loader2, Info, Zap, Users, Radio, Crosshair, 
  Map as MapIcon, ChevronLeft, Signal, RefreshCw
} from 'lucide-react';
import { AppState, Person } from '../types';

interface LocationAssistantProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const LocationAssistant: React.FC<LocationAssistantProps> = ({ state, setState }) => {
  const [activeMode, setActiveMode] = useState<'search' | 'tracking'>('tracking');
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [response, setResponse] = useState<{ text: string, links: any[] } | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);

  // إحداثيات حمص الافتراضية
  const defaultCenter = { lat: 34.7324, lng: 36.7137 };

  const searchLocations = async (type: string) => {
    setLoading(true);
    setResponse(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let latLng = defaultCenter;

      try {
        const pos = await new Promise<GeolocationPosition>((res, rej) => 
          navigator.geolocation.getCurrentPosition(res, rej)
        );
        latLng = { lat: pos.coords.latitude, lng: pos.coords.longitude };
      } catch (e) {
        console.warn("Geolocation denied, using default coordinates.");
      }

      const prompt = `بناءً على موقعي الحالي، أريد معلومات دقيقة عن ${type === 'custom' ? query : type} في مدينة حمص أو المناطق المحيطة بها، مع التركيز على المرافق الرياضية المناسبة لنادي الكرامة.`;

      const result = await ai.models.generateContent({
        model: "gemini-flash-lite-latest",
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: { latitude: latLng.lat, longitude: latLng.lng }
            }
          }
        },
      });

      const text = result.text || "لم يتم العثور على تفاصيل محددة.";
      const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

      const links = chunks
        .filter((chunk: any) => chunk.maps)
        .map((chunk: any) => ({
          title: chunk.maps.title,
          uri: chunk.maps.uri
        }));

      setResponse({ text, links });
    } catch (error: any) {
      alert("حدث خطأ أثناء الاتصال بخدمة الخرائط: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const simulatePlayerMove = (playerId: string) => {
    // دالة للمحاكاة - تقوم بتحديث موقع لاعب عشوائياً بالقرب من حمص لغرض العرض اللحظي
    setState(prev => ({
      ...prev,
      people: prev.people.map(p => {
        if (p.id === playerId) {
          const newLat = 34.7324 + (Math.random() - 0.5) * 0.01;
          const newLng = 36.7137 + (Math.random() - 0.5) * 0.01;
          return { ...p, lat: newLat, lng: newLng, lastLocationUpdate: new Date().toISOString() };
        }
        return p;
      })
    }));
  };

  const activePlayers = state.people.filter(p => p.role === 'لاعب' && (state.globalCategoryFilter === 'الكل' || p.category === state.globalCategoryFilter));
  const trackingPlayers = activePlayers.filter(p => p.lat && p.lng);

  const quickButtons = [
    { id: 'stadiums', label: 'ملاعب قريبة', icon: Trophy, prompt: 'الملاعب الرياضية والمجمعات التدريبية' },
    { id: 'medical', label: 'عيادات رياضية', icon: Hospital, prompt: 'مراكز الطب الرياضي والمشافي القريبة' },
    { id: 'food', label: 'مطاعم صحية', icon: Utensils, prompt: 'مطاعم تقدم وجبات صحية مناسبة للرياضيين' },
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Tab Switcher */}
      <div className="flex bg-white p-2 rounded-[2rem] border-2 border-slate-900 w-fit no-print mx-auto mb-4 shadow-sm">
         <button 
           onClick={() => setActiveMode('tracking')}
           className={`flex items-center gap-2 px-8 py-3 rounded-xl font-black text-sm transition-all ${activeMode === 'tracking' ? 'bg-orange-600 text-white shadow-lg scale-105' : 'text-slate-500 hover:bg-slate-100'}`}
         >
            <Radio size={18} className={activeMode === 'tracking' ? 'animate-pulse' : ''} /> تتبع اللاعبين (Squad Tracking)
         </button>
         <button 
           onClick={() => setActiveMode('search')}
           className={`flex items-center gap-2 px-8 py-3 rounded-xl font-black text-sm transition-all ${activeMode === 'search' ? 'bg-[#001F3F] text-white shadow-lg scale-105' : 'text-slate-500 hover:bg-slate-100'}`}
         >
            <MapIcon size={18}/> البحث اللوجستي السريع
         </button>
      </div>

      {activeMode === 'search' ? (
        <>
          <div className="bg-white p-8 rounded-[3rem] border-2 border-slate-900 shadow-sm overflow-hidden relative">
            <div className="absolute top-0 right-0 w-2 h-full bg-orange-600"></div>
            <div className="flex flex-col md:flex-row justify-between items-center gap-6">
              <div>
                <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
                  <Navigation size={32} className="text-[#001F3F] animate-pulse" /> المساعد اللوجستي الفوري
                  <span className="bg-emerald-100 text-emerald-700 text-[9px] px-2 py-1 rounded flex items-center gap-1"><Zap size={10}/> Fast Lite Mode</span>
                </h2>
                <p className="text-[10px] font-black text-slate-400 mt-1 uppercase tracking-widest">بحث فوري عن الملاعب والخدمات باستخدام Flash Lite</p>
              </div>

              <div className="flex gap-2">
                {quickButtons.map(btn => (
                  <button 
                    key={btn.id}
                    onClick={() => searchLocations(btn.prompt)}
                    className="bg-slate-50 border-2 border-slate-900 p-4 rounded-2xl hover:bg-[#001F3F] hover:text-white transition-all flex flex-col items-center gap-2 group"
                  >
                    <btn.icon size={20} />
                    <span className="text-[10px] font-black">{btn.label}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="mt-8 flex gap-3">
              <input 
                type="text" 
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="أين يقع ملعب تشرين؟ (بحث فوري...)"
                className="flex-1 bg-slate-100 border-2 border-slate-900 rounded-2xl px-6 py-4 font-black outline-none focus:ring-4 focus:ring-blue-600/10"
              />
              <button 
                onClick={() => searchLocations('custom')}
                disabled={loading || !query}
                className="bg-[#001F3F] text-white px-8 rounded-2xl font-black flex items-center gap-2 hover:bg-black disabled:opacity-50"
              >
                {loading ? <Loader2 className="animate-spin" /> : <Zap size={20} />}
                بحث سريع
              </button>
            </div>
          </div>

          {response && (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4 duration-500">
              <div className="lg:col-span-2 bg-white p-8 rounded-[3rem] border-2 border-slate-900 shadow-sm">
                <h3 className="font-black text-lg mb-4 flex items-center gap-2 text-blue-900">
                  <Info size={20}/> المعلومات (استجابة فورية)
                </h3>
                <div className="prose prose-slate max-w-none text-right font-medium leading-relaxed">
                  {response.text.split('\n').map((line, i) => (
                    <p key={i} className="mb-2">{line}</p>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                <h3 className="font-black text-sm uppercase tracking-widest text-slate-400 mr-4">المواقع الجغرافية</h3>
                {response.links.length > 0 ? response.links.map((link, i) => (
                  <a 
                    key={i} 
                    href={link.uri} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="block bg-white p-6 rounded-2xl border-2 border-slate-900 hover:border-orange-600 hover:shadow-lg transition-all group"
                  >
                    <div className="flex justify-between items-center">
                      <div className="flex items-center gap-3">
                        <div className="p-2 bg-orange-50 text-orange-600 rounded-lg group-hover:bg-orange-600 group-hover:text-white transition-colors">
                          <MapPin size={20}/>
                        </div>
                        <span className="font-black text-sm">{link.title}</span>
                      </div>
                      <ExternalLink size={16} className="text-slate-300 group-hover:text-orange-600" />
                    </div>
                  </a>
                )) : (
                  <div className="bg-slate-100 p-8 rounded-2xl text-center border-2 border-dashed border-slate-300">
                    <p className="text-[10px] font-black text-slate-400 uppercase">لا توجد خرائط مباشرة</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 animate-in fade-in duration-500">
          {/* Sidebar: Player List */}
          <div className="lg:col-span-1 bg-white rounded-[2.5rem] border-2 border-slate-900 shadow-sm overflow-hidden flex flex-col h-[70vh]">
             <div className="bg-[#001F3F] p-5 text-white flex justify-between items-center">
                <h3 className="font-black text-sm uppercase tracking-wider flex items-center gap-2">
                   <Users size={18}/> حالة الفريق (LIVE)
                </h3>
                <Signal size={16} className="text-emerald-400 animate-pulse"/>
             </div>
             <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-2">
                {activePlayers.map(p => (
                   <button 
                     key={p.id} 
                     onClick={() => setSelectedPlayer(p)}
                     className={`w-full text-right p-4 rounded-2xl border-2 transition-all flex items-center justify-between group ${selectedPlayer?.id === p.id ? 'bg-orange-50 border-orange-600 shadow-md' : 'bg-slate-50 border-slate-200 hover:border-slate-900'}`}
                   >
                      <div className="flex items-center gap-3">
                         <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs ${p.lat ? 'bg-emerald-600 text-white animate-pulse' : 'bg-slate-200 text-slate-400'}`}>
                            #{p.number || '0'}
                         </div>
                         <div>
                            <p className="font-black text-xs text-slate-900">{p.name}</p>
                            <p className="text-[9px] font-black text-slate-400 uppercase">{p.lat ? 'متصل حالياً' : 'غير متصل'}</p>
                         </div>
                      </div>
                      <div className="flex gap-1">
                         <button 
                           onClick={(e) => { e.stopPropagation(); simulatePlayerMove(p.id); }}
                           className="p-1.5 bg-white border border-slate-300 rounded-lg text-slate-400 hover:text-emerald-600 hover:border-emerald-600 transition-all opacity-0 group-hover:opacity-100"
                           title="محاكاة تحرك اللاعب"
                         >
                            <RefreshCw size={14}/>
                         </button>
                         <ChevronLeft size={16} className={`text-slate-300 ${selectedPlayer?.id === p.id ? 'translate-x-0 text-orange-600' : 'translate-x-4 opacity-0 group-hover:translate-x-0 group-hover:opacity-100'} transition-all`}/>
                      </div>
                   </button>
                ))}
             </div>
          </div>

          {/* Main Content: Map Interface */}
          <div className="lg:col-span-3 space-y-4">
             <div className="bg-white p-4 rounded-[2.5rem] border-2 border-slate-900 shadow-sm flex justify-between items-center">
                <div className="flex items-center gap-3">
                   <div className="p-3 bg-orange-600 text-white rounded-2xl">
                      <Crosshair size={24}/>
                   </div>
                   <div>
                      <h3 className="font-black text-slate-900 text-lg uppercase tracking-tight">رادار التتبع اللحظي (Google Maps LIVE)</h3>
                      <p className="text-[10px] font-black text-slate-400 uppercase">تتبع مواقع اللاعبين أثناء التمارين والمباريات لضمان الالتزام الجغرافي</p>
                   </div>
                </div>
                {selectedPlayer?.lat && (
                   <div className="bg-emerald-50 border border-emerald-200 px-4 py-2 rounded-xl flex items-center gap-3">
                      <div className="w-2 h-2 bg-emerald-600 rounded-full animate-ping"></div>
                      <span className="text-[10px] font-black text-emerald-800 uppercase">دقة الإشارة: عالية (GPS)</span>
                   </div>
                )}
             </div>

             <div className="bg-slate-200 rounded-[3rem] border-4 border-slate-900 h-[60vh] overflow-hidden relative shadow-inner group">
                {selectedPlayer?.lat && selectedPlayer?.lng ? (
                   <iframe
                     title="Player Tracking Map"
                     width="100%"
                     height="100%"
                     frameBorder="0"
                     style={{ border: 0 }}
                     src={`https://www.google.com/maps/embed/v1/place?key=${process.env.API_KEY}&q=${selectedPlayer.lat},${selectedPlayer.lng}&zoom=18`}
                     allowFullScreen
                   ></iframe>
