import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { 
  MapPin, Search, Navigation, Hospital, Utensils, Trophy, 
  ExternalLink, Loader2, Info, Zap, Users, Radio, Crosshair, 
  Map as MapIcon, ChevronLeft, Signal, RefreshCw, Clock
} from 'lucide-react';
import { AppState, Person } from '../types';

interface LocationAssistantProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const LocationAssistant: React.FC<LocationAssistantProps> = ({ state, setState }) => {
  const [activeMode, setActiveMode] = useState<'search' | 'tracking'>('tracking');
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [response, setResponse] = useState<{ text: string, links: any[] } | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);

  // إحداثيات حمص الافتراضية
  const defaultCenter = { lat: 34.7324, lng: 36.7137 };

  const searchLocations = async (type: string) => {
    setLoading(true);
    setResponse(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let latLng = defaultCenter;

      try {
        const pos = await new Promise<GeolocationPosition>((res, rej) => 
          navigator.geolocation.getCurrentPosition(res, rej)
        );
        latLng = { lat: pos.coords.latitude, lng: pos.coords.longitude };
      } catch (e) {
        console.warn("Geolocation denied, using default coordinates.");
      }

      const prompt = `بناءً على موقعي الحالي، أريد معلومات دقيقة عن ${type === 'custom' ? query : type} في مدينة حمص أو المناطق المحيطة بها، مع التركيز على المرافق الرياضية المناسبة لنادي الكرامة.`;

      const result = await ai.models.generateContent({
        model: "gemini-flash-lite-latest",
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: { latitude: latLng.lat, longitude: latLng.lng }
            }
          }
        },
      });

      const text = result.text || "لم يتم العثور على تفاصيل محددة.";
      const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

      const links = chunks
        .filter((chunk: any) => chunk.maps)
        .map((chunk: any) => ({
          title: chunk.maps.title,
          uri: chunk.maps.uri
        }));

      setResponse({ text, links });
    } catch (error: any) {
      alert("حدث خطأ أثناء الاتصال بخدمة الخرائط: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const simulatePlayerMove = (playerId: string) => {
    // دالة للمحاكاة - تقوم بتحديث موقع لاعب عشوائياً بالقرب من حمص لغرض العرض اللحظي
    setState(prev => ({
      ...prev,
      people: prev.people.map(p => {
        if (p.id === playerId) {
          const newLat = 34.7324 + (Math.random() - 0.5) * 0.01;
          const newLng = 36.7137 + (Math.random() - 0.5) * 0.01;
          return { ...p, lat: newLat, lng: newLng, lastLocationUpdate: new Date().toISOString() };
        }
        return p;
      })
    }));
  };

  const activePlayers = state.people.filter(p => p.role === 'لاعب' && (state.globalCategoryFilter === 'الكل' || p.category === state.globalCategoryFilter));
  const trackingPlayers = activePlayers.filter(p => p.lat && p.lng);

  const quickButtons = [
