        people: ppl || [],
        sessions: sess || [],
        matches: mtch || [],
        attendance: filteredAttn,
        users: usrs || prev.users
      }));
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
      addLog('خطأ في جلب البيانات', error.message || 'فشل الوصول للسحاب.', 'error');
    } finally {
      setIsSyncing(false);
