import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Sparkles, Send, Bot, User, Loader2, BrainCircuit, Zap, X, Globe, ExternalLink, BarChart, TrendingUp } from 'lucide-react';
import { AppState } from '../types';

interface AIAssistantProps {
  state: AppState;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ state }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string, links?: {title: string, uri: string}[] }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [aiMode, setAiMode] = useState<'fast' | 'deep' | 'search' | 'tactical'>('fast');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleAsk = async (predefinedQuery?: string) => {
    const userQuery = predefinedQuery || input;
    if (!userQuery.trim() || loading) return;

    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setInput('');
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const restrictedCat = state.currentUser?.restrictedCategory;
      const filteredPeople = restrictedCat ? state.people.filter(p => p.category === restrictedCat) : state.people;
      const filteredMatches = restrictedCat ? state.matches.filter(m => m.category === restrictedCat) : state.matches;
      const filteredSessions = restrictedCat ? state.sessions.filter(s => s.category === restrictedCat) : state.sessions;
      const filteredAttendance = state.attendance.filter(a => filteredPeople.some(p => p.id === a.personId));

      // تحضير بيانات إحصائية للذكاء الاصطناعي
      const statsSummary = {
        totalPlayers: filteredPeople.filter(p => p.role === 'لاعب').length,
        avgAttendance: filteredAttendance.length > 0 ? (filteredAttendance.filter(a => a.status === 'حاضر').length / filteredAttendance.length * 100).toFixed(1) : 0,
        recentResults: filteredMatches.filter(m => m.isCompleted).slice(0, 5).map(m => `${m.ourScore}-${m.opponentScore} ضد ${m.opponent}`),
        topScorers: "سيتم استخراجها من الأحداث..."
      };

      const context = `
        أنت المحلل الذكي الرسمي لنادي الكرامة الرياضي السوري. 
        ${restrictedCat ? `- صلاحياتك محدودة بفئة: ${restrictedCat}` : `- صلاحياتك شاملة لكل الفئات: ${state.categories.join(', ')}`}
        بيانات النادي الداخلية حالياً: ${filteredPeople.length} عضو، ${filteredMatches.length} مباراة، ${filteredSessions.length} تمرين.
        إحصائيات سريعة: معدل الحضور العام ${statsSummary.avgAttendance}%، آخر النتائج: ${statsSummary.recentResults.join(', ')}.
        في حال طلب تحليل تكتيكي، استخدم هذه الأرقام لتقديم نصائح واقعية للمدربين.
      `;

      let responseText = "";
      let groundingLinks: {title: string, uri: string}[] = [];

      if (aiMode === 'search') {
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `${context}\nسؤال المستخدم: ${userQuery}`,
          config: {
            tools: [{ googleSearch: {} }]
          }
        });
        responseText = response.text || "عذراً، لم أجد نتائج بحث دقيقة.";
        const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
        groundingLinks = chunks.filter((c: any) => c.web).map((c: any) => ({ title: c.web.title, uri: c.web.uri }));

      } else if (aiMode === 'tactical') {
        const response = await ai.models.generateContent({
          model: 'gemini-3-pro-preview',
          contents: `${context}\nطلب المستخدم: تحليل تكتيكي معمق وتوصيات بناءً على البيانات أعلاه بخصوص: ${userQuery}`,
          config: {
            thinkingConfig: { thinkingBudget: 16384 }
          }
        });
        responseText = response.text || "عذراً، لم أستطع توليد التحليل التكتيكي.";
      } else {
        const isDeep = aiMode === 'deep';
        const response = await ai.models.generateContent({
          model: isDeep ? 'gemini-3-pro-preview' : 'gemini-flash-lite-latest',
          contents: `${context}\nسؤال المستخدم: ${userQuery}`,
          config: isDeep ? {
            thinkingConfig: { thinkingBudget: 32768 }
          } : undefined
        });
        responseText = response.text || "عذراً، لم أستطع تحليل الطلب.";
      }

      setMessages(prev => [...prev, { role: 'ai', text: responseText, links: groundingLinks }]);
    } catch (error: any) {
      setMessages(prev => [...prev, { role: 'ai', text: "حدث خطأ في الاتصال بـ Gemini: " + error.message }]);
    } finally {
      setLoading(false);
    }
  };

  const suggestions = [
    "حلل مستوى انضباط اللاعبين في التمارين الأخيرة",
    "اعطني توصيات تكتيكية بناءً على آخر 5 نتائج",
    "اقترح لي تمرين لرفع اللياقة",
    "من هم أكثر اللاعبين التزاماً هذا الشهر؟"
  ];

  return (
    <div className="flex flex-col h-[calc(100vh-180px)] space-y-4 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 shadow-sm flex flex-col md:flex-row items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-orange-500 to-orange-600 p-3 rounded-2xl shadow-lg">
            <Sparkles className="text-white" size={24} />
          </div>
          <div>
            <h2 className="text-xl font-black text-slate-900">المحلل الذكي المتكامل</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">تغطية داخلية (بيانات النادي) وعالمية (جوجل)</p>
          </div>
        </div>

        <div className="flex flex-wrap gap-2 bg-slate-100 p-1 rounded-2xl border-2 border-slate-200">
           <button onClick={() => setAiMode('fast')} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-black text-[10px] transition-all ${aiMode === 'fast' ? 'bg-[#001F3F] text-white shadow-md' : 'text-slate-500 hover:text-slate-900'}`}><Zap size={14} /> سريع</button>
           <button onClick={() => setAiMode('search')} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-black text-[10px] transition-all ${aiMode === 'search' ? 'bg-emerald-600 text-white shadow-md' : 'text-slate-500 hover:text-slate-900'}`}><Globe size={14} /> بحث مباشر</button>
           <button onClick={() => setAiMode('tactical')} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-black text-[10px] transition-all ${aiMode === 'tactical' ? 'bg-purple-600 text-white shadow-md' : 'text-slate-500 hover:text-slate-900'}`}><BarChart size={14} /> تحليل تكتيكي</button>
           <button onClick={() => setAiMode('deep')} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-black text-[10px] transition-all ${aiMode === 'deep' ? 'bg-orange-600 text-white shadow-md' : 'text-slate-500 hover:text-slate-900'}`}><BrainCircuit size={14} /> تفكير (Pro)</button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[3rem] border-2 border-slate-900 shadow-inner overflow-hidden flex flex-col relative">
        <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center space-y-6 opacity-40">
              <Bot size={80} className="text-slate-200" />
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3 w-full max-w-lg">
                {suggestions.map((s, i) => (
                  <button key={i} onClick={() => handleAsk(s)} className="p-3 bg-slate-50 border-2 border-dashed border-slate-300 rounded-xl text-[10px] font-black hover:border-orange-600 hover:text-orange-600 transition-all text-right">
                    {s}
                  </button>
                ))}
              </div>
            </div>
          )}

          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-start' : 'justify-end'} animate-in slide-in-from-bottom-2`}>
              <div className={`max-w-[85%] p-5 rounded-[2rem] flex flex-col gap-3 ${msg.role === 'user' ? 'bg-slate-100 border-2 border-slate-900 text-slate-900 rounded-tr-none' : 'bg-[#001F3F] text-white rounded-tl-none border-b-4 border-orange-600 shadow-xl'}`}>
                <div className="flex gap-4">
                  <div className={`shrink-0 w-8 h-8 rounded-full flex items-center justify-center ${msg.role === 'user' ? 'bg-slate-900 text-white' : 'bg-orange-600 text-white'}`}>
                    {msg.role === 'user' ? <User size={16}/> : <Bot size={16}/>}
                  </div>
                  <div className="text-sm font-medium leading-relaxed whitespace-pre-wrap flex-1">
                    {msg.text}
                  </div>
                </div>
                {msg.links && msg.links.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-white/10 space-y-2">
                    <p className="text-[9px] font-black text-orange-400 uppercase tracking-widest">المصادر المعتمدة:</p>
                    <div className="flex flex-wrap gap-2">
                      {msg.links.map((link, idx) => (
                        <a key={idx} href={link.uri} target="_blank" rel="noopener noreferrer" className="bg-white/10 hover:bg-white/20 px-3 py-1.5 rounded-lg text-[9px] font-black flex items-center gap-2 transition-all">
                          <ExternalLink size={10}/> {link.title}
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-end">
              <div className="bg-[#001F3F] text-white p-5 rounded-[2rem] rounded-tl-none flex items-center gap-3 shadow-lg">
                <Loader2 className="animate-spin" size={20} />
                <span className="text-xs font-black animate-pulse">
                  {aiMode === 'search' ? 'جاري البحث عبر جوجل...' : aiMode === 'tactical' ? 'جاري التحليل التكتيكي...' : 'جاري التحليل المعمق...'}
                </span>
              </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        <div className="p-6 bg-slate-50 border-t-2 border-slate-900 flex gap-3 items-center">
          <input 
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleAsk()}
            placeholder={aiMode === 'search' ? "ابحث عن أي معلومة رياضية عالمية..." : "اسأل المحلل الذكي..."}
            className="flex-1 bg-white border-2 border-slate-900 rounded-2xl px-6 py-4 font-black text-slate-900 outline-none focus:ring-4 focus:ring-orange-600/10 transition-all"
          />
          <button 
            onClick={() => handleAsk()}
            disabled={loading || !input.trim()}
            className={`p-4 rounded-2xl transition-all shadow-lg disabled:opacity-50 text-white ${aiMode === 'search' ? 'bg-emerald-600 hover:bg-emerald-700' : aiMode === 'tactical' ? 'bg-purple-600 hover:bg-purple-700' : (aiMode === 'deep' ? 'bg-orange-600 hover:bg-orange-700' : 'bg-[#001F3F] hover:bg-black')}`}
          >
            <Send size={24} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default AIAssistant;

import React, { useState, useMemo } from 'react';
import { Calendar as CalendarIcon, MapPin, Clock, Plus, Trash2, Edit, X, Printer, FileText, CheckCircle, ShieldCheck, Lock, AlertCircle, Map, ChevronRight, BarChart3, PieChart, Users, User, TrendingUp, CalendarDays, Gavel } from 'lucide-react';
import { AppState, TrainingSession, Category, Person, AttendanceRecord } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

export default function TrainingPlanner({ state, setState, defaultSelectedId, addLog }: TrainingPlannerProps) {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  // تحديث الصلاحيات: المدير وإداري الفئة يمكنهم الإدارة
  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري فئة';
  const canModifyConfig = isManager || isCatAdmin; 

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showPrintView, setShowPrintView] = useState(false);
  const [activeTab, setActiveTab] = useState<'agenda' | 'stats'>('agenda');
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);

  // States for Stats
  const [reportType, setReportType] = useState<'category' | 'player' | 'discipline'>('category');
  const [selectedCatForReport, setSelectedCatForReport] = useState<string>(restrictedCat || state.categories[0] || '');
  const [selectedPlayerId, setSelectedPlayerId] = useState<string>('');
  const [reportPeriod, setReportPeriod] = useState<{ month: string, year: string }>({
    month: (new Date().getMonth() + 1).toString().padStart(2, '0'),
    year: new Date().getFullYear().toString()
  });
  const [printData, setPrintData] = useState<any>(null);

  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'الرجال'),
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    pitch: ''
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.time) return;

    const today = new Date().toISOString().split('T')[0];
    if (formData.date < today) {
      alert("تنبيه أمني: لا يمكن جدولة تمرين في تاريخ قديم. يرجى اختيار تاريخ اليوم أو تاريخ مستقبلي.");
      return;
    }

    const finalCategory = restrictedCat || formData.category;

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData, category: finalCategory } as TrainingSession : s)
      }));
      addLog?.('تعديل موعد تمرين', `تم تحديث بيانات تمرين فئة ${finalCategory}`, 'info');
    } else {
      const newSession: TrainingSession = {
        id: generateUUID(),
        category: finalCategory as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        pitch: formData.pitch || 'غير محدد',
        objective: formData.objective || 'تمرين عام',
        isCompleted: false
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
      addLog?.('إضافة موعد تمرين', `تمت جدولة تمرين جديد لفئة ${newSession.category}`, 'info');
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const toggleSessionComplete = (id: string, currentStatus: boolean) => {
    const session = state.sessions.find(s => s.id === id);
    if (isCatAdmin && session?.category !== restrictedCat) {
      alert('لا تملك صلاحية تعديل تمارين خارج فئتك المخصصة.');
      return;
    }

    setState(prev => ({
      ...prev,
      sessions: prev.sessions.map(s => s.id === id ? { ...s, isCompleted: !currentStatus } : s)
    }));
    addLog?.('تحديث حالة تمرين', currentStatus ? 'تم إعادة فتح التمرين' : 'تم تأشير التمرين كمنتهي', 'info');
  };

  const filteredSessions = useMemo(() => {
    return (restrictedCat 
      ? state.sessions.filter(s => s.category === restrictedCat)
      : state.sessions.filter(s => (state.globalCategoryFilter === 'الكل' || s.category === state.globalCategoryFilter)))
      .sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [state.sessions, restrictedCat, state.globalCategoryFilter]);

  const isSessionLocked = (session: TrainingSession) => {
    const sessionTime = new Date(`${session.date}T${session.time}`);
    const now = new Date();
    const diffInMinutes = (now.getTime() - sessionTime.getTime()) / (1000 * 60);
    return diffInMinutes > 30;
  };

  const generateReport = () => {
    const period = `${reportPeriod.year}-${reportPeriod.month}`;

    if (reportType === 'category') {
      const catSessions = state.sessions.filter(s => s.category === selectedCatForReport && s.date.startsWith(period));
      const catPlayers = state.people.filter(p => p.role === 'لاعب' && p.category === selectedCatForReport);

      let totalPresence = 0;
      let totalLates = 0;
      let totalAbsence = 0;
      let totalExcused = 0;

      catSessions.forEach(s => {
        const records = state.attendance.filter(a => a.sessionId === s.id);
        totalPresence += records.filter(r => r.status === 'حاضر').length;
        totalLates += records.filter(r => r.status === 'متأخر').length;
        totalAbsence += records.filter(r => r.status === 'غائب').length;
        totalExcused += records.filter(r => r.status === 'غياب بعذر').length;
      });

      const totalPossible = catSessions.length * catPlayers.length;
      const attendanceRate = totalPossible > 0 ? Math.round((totalPresence / totalPossible) * 100) : 0;

      setPrintData({
        type: 'category',
        title: `تقرير أداء فئة: ${selectedCatForReport}`,
        period: `${reportPeriod.month} / ${reportPeriod.year}`,
        sessions: catSessions,
        stats: { totalSessions: catSessions.length, attendanceRate, totalPresence, totalLates, totalAbsence, totalExcused, playersCount: catPlayers.length }
      });
    } else if (reportType === 'player') {
      const player = state.people.find(p => p.id === selectedPlayerId);
      if (!player) return alert('يرجى اختيار اللاعب أولاً');

      const playerRecords = state.attendance.filter(a => a.personId === player.id && a.date.startsWith(period));
      const playerSessions = state.sessions.filter(s => s.category === player.category && s.date.startsWith(period));

      const present = playerRecords.filter(r => r.status === 'حاضر').length;
      const late = playerRecords.filter(r => r.status === 'متأخر').length;
      const absent = playerRecords.filter(r => r.status === 'غائب').length;
      const excused = playerRecords.filter(r => r.status === 'غياب بعذر').length;

      const score = playerSessions.length > 0 ? Math.round(((present + (late * 0.5)) / playerSessions.length) * 100) : 0;

      setPrintData({
        type: 'player',
        player,
        title: `تقرير التزام اللاعب: ${player.name}`,
        period: `${reportPeriod.month} / ${reportPeriod.year}`,
        stats: { present, late, absent, excused, total: playerSessions.length, score },
        records: playerRecords.map(r => {
          const s = state.sessions.find(ses => ses.id === r.sessionId);
          return { ...r, objective: s?.objective || 'تمرين عام' };
        })
      });
    } else if (reportType === 'discipline') {
      const catPlayers = state.people.filter(p => p.role === 'لاعب' && p.category === selectedCatForReport);
      const catSessions = state.sessions.filter(s => s.category === selectedCatForReport && s.date.startsWith(period));

      const disciplinaryStats = catPlayers.map(p => {
        const records = state.attendance.filter(a => a.personId === p.id && a.date.startsWith(period));
        return {
          name: p.name,
          number: p.number,
          lates: records.filter(r => r.status === 'متأخر').length,
          absences: records.filter(r => r.status === 'غائب').length,
          excused: records.filter(r => r.status === 'غياب بعذر').length,
          totalOffenses: records.filter(r => r.status !== 'حاضر').length
        };
      }).sort((a,b) => b.totalOffenses - a.totalOffenses);

      setPrintData({
        type: 'discipline',
        title: `كشف انضباط فئة: ${selectedCatForReport}`,
        period: `${reportPeriod.month} / ${reportPeriod.year}`,
        stats: disciplinaryStats
      });
    }
    setShowPrintView(true);
  };

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-4 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";

  if (showPrintView && printData) {
    return (
      <div className="fixed inset-0 bg-white z-[600] overflow-y-auto p-12 dir-rtl text-right">
        <div className="max-w-5xl mx-auto border-4 border-slate-900 p-12 print:border-2">
           <div className="no-print flex justify-between items-center mb-10 border-b pb-4">
              <button onClick={() => setShowPrintView(false)} className="flex items-center gap-2 font-black text-slate-500 hover:text-red-600 transition-all"><ChevronRight/> إغلاق المعاينة</button>
              <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-10 py-4 rounded-2xl font-black flex items-center gap-3 shadow-2xl"><Printer size={20}/> طباعة التقرير الفني PDF</button>
           </div>

           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-8 mb-10">
              <div className="flex items-center gap-4">
                 <ClubLogo size={100} />
                 <div>
                    <h2 className="text-3xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
