                    <div className="max-h-96 overflow-y-auto custom-scrollbar p-2 space-y-2">
                       {state.notifications.length === 0 ? <p className="py-8 text-center text-[10px] font-black text-slate-400 italic">لا يوجد إشعارات</p> : state.notifications.map(n => (
                         <div key={n.id} className="p-3 bg-slate-50 border border-slate-200 rounded-xl">
