              <div className={`flex items-center gap-2 px-4 py-2 rounded-2xl border transition-all duration-500 ${syncStatus === 'synced' ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : syncStatus === 'error' ? 'bg-red-50 border-red-200 text-red-700 animate-pulse' : 'bg-orange-50 border-orange-200 text-orange-700'}`}>
                 {syncStatus === 'synced' && <CloudCheck size={18} />}
                 {syncStatus === 'error' && <CloudOff size={18} />}
                 {syncStatus === 'syncing' && <Cloud size={18} className="animate-bounce" />}
                 <span className="text-[10px] font-black uppercase whitespace-nowrap hidden sm:inline">{syncStatus === 'synced' ? 'مزامنة كاملة' : syncStatus === 'error' ? 'خطأ بالربط' : 'جاري الرفع...'}</span>
              </div>
              <button onClick={() => fetchData(true)} className="p-2.5 rounded-xl bg-slate-100 text-slate-600 hover:bg-slate-200 transition-all shadow-sm">
