  // قفل مزامنة متطور: يمنع جلب البيانات إذا كانت هناك عملية رفع نشطة أو تمت مؤخراً
  const syncLockRef = useRef<{ isLocked: boolean; lastPush: number }>({ isLocked: false, lastPush: 0 });

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_cloud_v4');
    if (saved) {
      try { return JSON.parse(saved); } catch (e) { console.error(e); }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      attendance: [],
      users: [],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  useEffect(() => {
    if (state.currentUser?.restrictedCategory) {
      setState(prev => ({ ...prev, globalCategoryFilter: state.currentUser!.restrictedCategory! }));
    }
  }, [state.currentUser]);

  useEffect(() => {
    localStorage.setItem('alkarama_cloud_v4', JSON.stringify(state));
  }, [state]);

  const addLog = useCallback((message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: generateUUID(),
      message, details, type, timestamp: Date.now(), isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  }, []);

  const sanitize = (data: any[]) => {
    return data.map(item => {
      const cleanItem = JSON.parse(JSON.stringify(item));
      Object.keys(cleanItem).forEach(key => {
        if (cleanItem[key] === undefined) cleanItem[key] = null;
      });
      return cleanItem;
    });
  };

  const fetchData = useCallback(async (force = false) => {
    // التحقق من القفل: لا تجلب البيانات إذا كنا بصدد رفعها أو رفعناها منذ أقل من 3 ثوانٍ
    const now = Date.now();
    if (!state.currentUser || (!force && (syncLockRef.current.isLocked || (now - syncLockRef.current.lastPush < 3000)))) return;

    setIsSyncing(true);
    setSyncStatus('syncing');
    try {
      let pplQuery = supabase.from('people').select('*');
      let sessQuery = supabase.from('sessions').select('*');
      let mtchQuery = supabase.from('matches').select('*');
      let usrsQuery = supabase.from('users').select('*');

      if (state.currentUser.restrictedCategory) {
        pplQuery = pplQuery.eq('category', state.currentUser.restrictedCategory);
        sessQuery = sessQuery.eq('category', state.currentUser.restrictedCategory);
        mtchQuery = mtchQuery.eq('category', state.currentUser.restrictedCategory);
      }

      const [
        { data: cats },
        { data: ppl },
        { data: sess },
        { data: mtch },
        { data: attn },
        { data: usrs }
      ] = await Promise.all([
        supabase.from('categories').select('name'),
        pplQuery,
        sessQuery,
        mtchQuery,
        supabase.from('attendance').select('*'),
        usrsQuery,
      ]);

      const filteredAttn = attn ? attn.filter(a => (ppl || []).some(p => p.id === a.personId)) : [];

      setState(prev => ({
        ...prev,
        categories: (cats && cats.length > 0) ? cats.map(c => c.name) : prev.categories,
        people: ppl || [],
        sessions: sess || [],
        matches: mtch || [],
        attendance: filteredAttn,
        users: usrs || prev.users
      }));
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
      console.error("Fetch Error:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser]);

  useEffect(() => {
    if (!state.currentUser) return;

    const channels = ['people', 'sessions', 'matches', 'attendance', 'users'].map(table => 
      supabase
        .channel(`public:${table}`)
        .on('postgres_changes', { event: '*', schema: 'public', table: table }, () => {
          fetchData();
        })
        .subscribe()
    );

    return () => {
      channels.forEach(channel => supabase.removeChannel(channel));
    };
  }, [state.currentUser, fetchData]);

  const pushData = useCallback(async (updatedState: AppState) => {
    if (!updatedState.currentUser) return;

    syncLockRef.current.isLocked = true;
    setSyncStatus('syncing');
    try {
      // تنفيذ كل عمليات الرفع بالتوازي لضمان السرعة والاتساق
      await Promise.all([
        updatedState.people.length > 0 ? supabase.from('people').upsert(sanitize(updatedState.people), { onConflict: 'id' }) : Promise.resolve(),
        updatedState.sessions.length > 0 ? supabase.from('sessions').upsert(sanitize(updatedState.sessions), { onConflict: 'id' }) : Promise.resolve(),
        updatedState.matches.length > 0 ? supabase.from('matches').upsert(sanitize(updatedState.matches), { onConflict: 'id' }) : Promise.resolve(),
        updatedState.attendance.length > 0 ? supabase.from('attendance').upsert(sanitize(updatedState.attendance), { onConflict: 'id' }) : Promise.resolve(),
        updatedState.users.length > 0 ? supabase.from('users').upsert(sanitize(updatedState.users), { onConflict: 'id' }) : Promise.resolve(),
      ]);

      setSyncStatus('synced');
      syncLockRef.current.lastPush = Date.now();
    } catch (error: any) {
      setSyncStatus('error');
      addLog('فشل مزامنة البيانات', error.message, 'error');
    } finally {
      // إبقاء القفل مفعلاً لفترة بسيطة حتى بعد الانتهاء لضمان استقرار السحاب
      setTimeout(() => {
        syncLockRef.current.isLocked = false;
      }, 2500);
    }
  }, [addLog]);

  const updateStateAndSync = async (updater: (prev: AppState) => AppState) => {
    // تفعيل القفل فوراً قبل أي عملية تحديث حالة
    syncLockRef.current.isLocked = true;

    let nextState: AppState | null = null;
    setState(prev => {
      nextState = updater(prev);
      return nextState;
    });

    if (nextState) {
      await pushData(nextState);
    } else {
      syncLockRef.current.isLocked = false;
    }
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setActiveTab('dashboard');
    localStorage.removeItem('alkarama_cloud_v4');
  };

  const handleCloudLogin = async (usernameInput: string, passwordInput: string): Promise<AppUser | null> => {
    try {
      const { data, error } = await supabase.from('users').select('*').eq('username', usernameInput.trim()).single();
      if (error || !data) throw new Error("بيانات الدخول غير صحيحة.");
      if (data.password === passwordInput) {
        const loggedUser: AppUser = { id: data.id, username: data.username, role: data.role as any, restrictedCategory: data.restrictedCategory };
        setState(prev => ({ ...prev, currentUser: loggedUser }));
        return loggedUser;
      }
      return null;
    } catch (err: any) {
      return null;
    }
  };

  if (!state.currentUser) return <Login onLoginAttempt={handleCloudLogin} />;

  const navItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'إدارة الفريق', icon: Users },
    { id: 'attendance', label: 'نظام الحضور', icon: ClipboardCheck },
