import React, { useState, useRef, useEffect, useMemo } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Sparkles, Send, Bot, User, Loader2, BrainCircuit, Zap, X, Globe, ExternalLink, BarChart, TrendingUp, ShieldAlert, HeartPulse } from 'lucide-react';
import { AppState } from '../types';

interface AIAssistantProps {
  state: AppState;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ state }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string, links?: {title: string, uri: string}[] }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [aiMode, setAiMode] = useState<'fast' | 'deep' | 'search' | 'tactical'>('fast');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const clubDataAnalysis = useMemo(() => {
    const restrictedCat = state.currentUser?.restrictedCategory;
    const filteredPeople = restrictedCat ? state.people.filter(p => p.category === restrictedCat) : state.people;
    const filteredMatches = restrictedCat ? state.matches.filter(m => m.category === restrictedCat) : state.matches;

    // تحليل الإصابات والسجل الطبي
    const injurySummary = filteredPeople
      .filter(p => p.injuries || p.medicalHistory)
      .map(p => `${p.name}: ${p.injuries || 'لا يوجد إصابات حالية'} | التاريخ الطبي: ${p.medicalHistory || 'سليم'}`)
      .join('\n');

    // تحليل العقوبات والانضباط
    const disciplinarySummary = filteredPeople
      .filter(p => p.penalties)
      .map(p => `${p.name}: ${p.penalties}`)
      .join('\n');

    // الهدافين
    const goalMap: Record<string, number> = {};
    filteredMatches.forEach(m => {
      m.events.filter(e => e.type === 'goal').forEach(e => {
        goalMap[e.player] = (goalMap[e.player] || 0) + 1;
      });
    });
    const topScorers = Object.entries(goalMap)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([name, goals]) => `${name} (${goals} أهداف)`)
      .join(', ');

    return {
      restrictedCat,
      filteredPeopleCount: filteredPeople.length,
      filteredMatchesCount: filteredMatches.length,
      topScorers: topScorers || "لا يوجد أهداف مسجلة",
      injurySummary: injurySummary || "جميع اللاعبين جاهزون طبياً",
      disciplinarySummary: disciplinarySummary || "لا يوجد عقوبات مسجلة حالياً",
      recentResults: filteredMatches.filter(m => m.isCompleted).slice(0, 5).map(m => `${m.opponent} (${m.ourScore}-${m.opponentScore})`).join(' | ')
    };
  }, [state]);

  const handleAsk = async (predefinedQuery?: string) => {
    const userQuery = predefinedQuery || input;
    if (!userQuery.trim() || loading) return;

    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setInput('');
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const { restrictedCat, topScorers, injurySummary, disciplinarySummary, recentResults, filteredPeopleCount } = clubDataAnalysis;

      const systemInstruction = `
        أنت المحلل التقني والتكتيكي الأول لنادي الكرامة الرياضي.
        بناءً على البيانات التالية، قدم تحليلات دقيقة:
        - الفئة: ${restrictedCat || 'عام'}
        - عدد الكوادر: ${filteredPeopleCount}
        - أفضل الهدافين: ${topScorers}
        - تقرير الإصابات: ${injurySummary}
        - سجل العقوبات والانضباط: ${disciplinarySummary}
        - آخر النتائج: ${recentResults}

        عند تقديم التوصيات، ضع في اعتبارك الحالة الطبية للاعبين (الإصابات) وسجلهم الانضباطي (العقوبات).
        إذا سُئلت عن تشكيل أو خطة، اقترح استبعاد المصابين أو المعاقبين.
      `;

      let responseText = "";
      if (aiMode === 'search') {
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: userQuery,
          config: { 
            systemInstruction,
            tools: [{ googleSearch: {} }] 
          }
        });
        responseText = response.text || "";
      } else {
        const response = await ai.models.generateContent({
          model: aiMode === 'deep' ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview',
          contents: userQuery,
          config: { 
            systemInstruction,
            thinkingConfig: aiMode === 'deep' ? { thinkingBudget: 16384 } : undefined 
          }
        });
        responseText = response.text || "";
      }

      setMessages(prev => [...prev, { role: 'ai', text: responseText }]);
    } catch (error: any) {
      setMessages(prev => [...prev, { role: 'ai', text: "حدث خطأ: " + error.message }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-180px)] space-y-4">
      <div className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-orange-500 to-orange-600 p-3 rounded-2xl shadow-lg">
            <BrainCircuit className="text-white" size={24} />
          </div>
          <div>
            <h2 className="text-xl font-black text-slate-900">المحلل التكتيكي المتطور</h2>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">تحليل الأداء، الإصابات، والانضباط</p>
          </div>
        </div>

        <div className="flex gap-2 bg-slate-100 p-1 rounded-2xl">
           <button onClick={() => setAiMode('fast')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all ${aiMode === 'fast' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}>سريع</button>
           <button onClick={() => setAiMode('deep')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all ${aiMode === 'deep' ? 'bg-orange-600 text-white' : 'text-slate-500'}`}>تفكير عميق</button>
           <button onClick={() => setAiMode('search')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all ${aiMode === 'search' ? 'bg-emerald-600 text-white' : 'text-slate-500'}`}>بحث ويب</button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[3rem] border-2 border-slate-900 flex flex-col overflow-hidden relative shadow-inner">
        <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center opacity-30 space-y-4">
              <Bot size={64} />
              <p className="font-black text-sm">اسألني عن تحليل الإصابات أو توصيات التشكيل بناءً على الانضباط...</p>
            </div>
          )}
          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-start' : 'justify-end'}`}>
              <div className={`max-w-[85%] p-5 rounded-[2rem] text-sm leading-relaxed ${msg.role === 'user' ? 'bg-slate-100 border-2 border-slate-900 rounded-tr-none' : 'bg-[#001F3F] text-white border-b-4 border-orange-600 rounded-tl-none'}`}>
                {msg.text}
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-end">
              <div className="bg-slate-900 text-white p-4 rounded-2xl flex items-center gap-3">
                <Loader2 className="animate-spin" size={16} />
                <span className="text-xs font-black">جاري تحليل السجلات التاريخية...</span>
              </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        <div className="p-4 bg-slate-50 border-t-2 border-slate-900 flex gap-2">
          <input 
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleAsk()}
            placeholder="مثلاً: حلل تأثير الإصابات الحالية على مباراة القمة القادمة؟"
            className="flex-1 bg-white border-2 border-slate-900 rounded-2xl px-6 py-4 font-black outline-none focus:ring-4 focus:ring-orange-600/10"
          />
          <button onClick={() => handleAsk()} disabled={loading} className="bg-[#001F3F] text-white p-4 rounded-2xl shadow-lg hover:bg-black transition-all">
            <Send size={24} />
          </button>
        </div>
      </div>
    </div>
  );
};

