import React, { useState, useRef, useEffect, useMemo } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Sparkles, Send, Bot, User, Loader2, BrainCircuit, Zap, X, Globe, ExternalLink, BarChart, TrendingUp, ShieldAlert, HeartPulse, History, Gavel } from 'lucide-react';
import { AppState } from '../types';

interface AIAssistantProps {
  state: AppState;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ state }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [aiMode, setAiMode] = useState<'fast' | 'deep' | 'tactical'>('fast');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const clubAnalysis = useMemo(() => {
    const players = state.people.filter(p => p.role === 'لاعب');

    // تحليل الإصابات والتاريخ الطبي
    const medicalHistory = players
      .filter(p => p.injuries || p.medicalHistory)
      .map(p => `- ${p.name}: إصابات سابقة (${p.injuries || 'لا يوجد'})، ملاحظات طبية (${p.medicalHistory || 'سليم'})`)
      .join('\n');

    // تحليل الانضباط (الغيابات والعقوبات)
    const disciplinaryRecords = players.map(p => {
      const records = state.attendance.filter(a => a.personId === p.id);
      const absences = records.filter(r => r.status === 'غائب').length;
      const lates = records.filter(r => r.status === 'متأخر').length;
      return `- ${p.name}: غيابات (${absences})، تأخيرات (${lates})، عقوبات إدارية (${p.penalties || 'لا يوجد'})`;
    }).join('\n');

    // تحليل التوجهات الفنية (النتائج الأخيرة)
    const recentMatches = state.matches
      .filter(m => m.isCompleted)
      .slice(0, 5)
      .map(m => `- ضد ${m.opponent}: النتيجة (${m.ourScore}-${m.opponentScore})، نوع المباراة (${m.matchType})`)
      .join('\n');

    return { medicalHistory, disciplinaryRecords, recentMatches };
  }, [state]);

  const handleAsk = async () => {
    if (!input.trim() || loading) return;

    const userQuery = input;
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setInput('');
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const { medicalHistory, disciplinaryRecords, recentMatches } = clubAnalysis;

      const systemInstruction = `
        أنت المحلل التقني الأول لنادي الكرامة الرياضي. 
        لديك صلاحية الوصول لكامل السجل التاريخي:
        1. السجل الطبي والإصابات:
        ${medicalHistory}

        2. سجل الانضباط والالتزام:
        ${disciplinaryRecords}

        3. نتائج الفريق الأخيرة وتوجهات الأداء:
        ${recentMatches}

        مهمتك:
        - تقديم توصيات تكتيكية تأخذ بعين الاعتبار "جاهزية اللاعبين الطبية" و "مدى التزامهم الانضباطي".
        - إذا طلبت تشكيلة، استبعد اللاعبين المصابين أو غير المنضبطين.
        - قدم تحليلاً للنتائج الأخيرة واقترح حلولاً للمشاكل الفنية المتكررة.
        - استخدم لغة احترافية، تحليلية، ومشجعة.
      `;

      const response = await ai.models.generateContent({
        model: aiMode === 'deep' ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview',
        contents: userQuery,
        config: { 
          systemInstruction,
          thinkingConfig: aiMode === 'deep' ? { thinkingBudget: 16000 } : undefined 
        }
      });

      setMessages(prev => [...prev, { role: 'ai', text: response.text || "لم أستطع تحليل البيانات حالياً." }]);
    } catch (error: any) {
      setMessages(prev => [...prev, { role: 'ai', text: "حدث خطأ في الاتصال بالمحلل: " + error.message }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-180px)] space-y-4">
      <div className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-4">
          <div className="bg-[#001F3F] p-3 rounded-2xl">
            <BrainCircuit className="text-orange-400" size={24} />
          </div>
          <div>
            <h2 className="text-xl font-black text-slate-900 uppercase">المحلل التكتيكي الشامل</h2>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">تحليل الإصابات، الانضباط، وتوجهات الأداء</p>
          </div>
        </div>
        <div className="flex gap-2 bg-slate-100 p-1 rounded-2xl">
           <button onClick={() => setAiMode('fast')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all ${aiMode === 'fast' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}>تحليل سريع</button>
           <button onClick={() => setAiMode('deep')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all ${aiMode === 'deep' ? 'bg-orange-600 text-white' : 'text-slate-500'}`}>تفكير عميق</button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[3rem] border-2 border-slate-900 flex flex-col overflow-hidden relative shadow-inner">
        <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center opacity-30 space-y-4">
              <Bot size={64} />
              <p className="font-black text-sm text-center px-10">أنا هنا لتحليل حالة الفريق. اسألني عن الإصابات، أو أفضل تشكيل بناءً على الانضباط، أو تحليل النتائج الأخيرة.</p>
            </div>
          )}
          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-start' : 'justify-end'}`}>
              <div className={`max-w-[85%] p-5 rounded-[2rem] text-sm leading-relaxed ${msg.role === 'user' ? 'bg-slate-100 border-2 border-slate-900 rounded-tr-none' : 'bg-[#001F3F] text-white border-b-4 border-orange-600 rounded-tl-none'}`}>
                {msg.text}
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-end">
              <div className="bg-slate-900 text-white p-4 rounded-2xl flex items-center gap-3">
                <Loader2 className="animate-spin" size={16} />
                <span className="text-[10px] font-black animate-pulse">جاري فحص السجلات التاريخية والطبية...</span>
              </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        <div className="p-4 bg-slate-50 border-t-2 border-slate-900 flex gap-2">
          <input 
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleAsk()}
            placeholder="مثلاً: ما هو تأثير الإصابات الحالية على خياراتنا في الهجوم؟"
            className="flex-1 bg-white border-2 border-slate-900 rounded-2xl px-6 py-4 font-black outline-none focus:ring-4 focus:ring-orange-600/10"
          />
          <button onClick={handleAsk} disabled={loading} className="bg-[#001F3F] text-white p-4 rounded-2xl shadow-lg hover:bg-black transition-all">
            <Send size={24} />
          </button>
        </div>
      </div>
    </div>
  );
};

