                     <span className="text-xs font-black text-slate-900 leading-none">{state.currentUser?.username}</span>
                     <span className="text-[9px] font-black text-orange-600 uppercase tracking-tighter mt-1">{state.currentUser?.role}</span>
                  </div>
                  <div className="w-10 h-10 bg-[#001F3F] text-white border-2 border-[#001F3F] rounded-xl flex items-center justify-center font-black shadow-md">
                     {state.currentUser?.username?.charAt(0).toUpperCase()}
                  </div>
               </div>

               <button className="p-2 text-slate-400 hover:text-orange-600 transition-colors relative bg-white rounded-lg shadow-sm" onClick={() => setShowNotifications(!showNotifications)}>
                  <Bell size={20} />
