import ChatBot from './components/ChatBot';

export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const supabaseUrl = 'https://kfwqoigsghlgigjriyxf.supabase.co';
const supabaseAnonKey = 'sb_publishable_O2vR2yKUG-FVeaydD4z6Lg_tjFcKDic';
export const supabase = createClient(supabaseUrl, supabaseAnonKey);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'error' | 'syncing'>('synced');

  // مرجع للتحكم الصارم في المزامنة
  const syncManager = useRef({
    lastLocalUpdate: 0,
    isPushing: false,
    pendingFetch: false
  });

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_cloud_v5');
    if (saved) {
      try { return JSON.parse(saved); } catch (e) { console.error(e); }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      attendance: [],
      users: [],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  useEffect(() => {
    localStorage.setItem('alkarama_cloud_v5', JSON.stringify(state));
  }, [state]);

  const addLog = useCallback((message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: generateUUID(),
      message, details, type, timestamp: Date.now(), isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  }, []);

  const sanitize = (data: any[]) => {
    return data.map(item => {
      const cleanItem = JSON.parse(JSON.stringify(item));
      Object.keys(cleanItem).forEach(key => {
        if (cleanItem[key] === undefined) cleanItem[key] = null;
      });
      return cleanItem;
    });
  };

  const fetchData = useCallback(async (force = false) => {
    // استراتيجية "الدرع الزمني": إذا تم تحديث البيانات محلياً منذ أقل من 5 ثوانٍ، نرفض تحديث السحاب لمنع حالة التسابق.
    const now = Date.now();
    if (!state.currentUser) return;
    if (!force && (syncManager.current.isPushing || (now - syncManager.current.lastLocalUpdate < 5000))) {
      return;
    }

    setIsSyncing(true);
    setSyncStatus('syncing');
    try {
      const pplQuery = supabase.from('people').select('*');
      const sessQuery = supabase.from('sessions').select('*');
      const mtchQuery = supabase.from('matches').select('*');
      const usrsQuery = supabase.from('app_users').select('*'); // تم التعديل إلى app_users

      if (state.currentUser.restrictedCategory) {
        pplQuery.eq('category', state.currentUser.restrictedCategory);
        sessQuery.eq('category', state.currentUser.restrictedCategory);
        mtchQuery.eq('category', state.currentUser.restrictedCategory);
      }

      const [cats, ppl, sess, mtch, attn, usrs] = await Promise.all([
        supabase.from('categories').select('name'),
        pplQuery,
        sessQuery,
        mtchQuery,
        supabase.from('attendance').select('*'),
        usrsQuery,
      ]);

      // منع المسح الكلي في حال فشل الجلب
      if (ppl.error || mtch.error) throw new Error("فشل الاتصال بقاعدة البيانات");

      setState(prev => {
        // منطق "الدمج الآمن": لا تقم بتحديث الحالة المحلية إلا إذا كانت البيانات القادمة من السحاب تحتوي على سجلات.
        // هذا يمنع حذف البيانات المحلية عند تأخر تحديثات السحاب (Race Condition).
        const cloudPeople = (ppl.data && ppl.data.length > 0) ? ppl.data : prev.people;
        const cloudSessions = (sess.data && sess.data.length > 0) ? sess.data : prev.sessions;
        const cloudMatches = (mtch.data && mtch.data.length > 0) ? mtch.data : prev.matches;
        const cloudAttendance = (attn.data && attn.data.length > 0) ? attn.data : prev.attendance;
        const cloudUsers = (usrs.data && usrs.data.length > 0) ? usrs.data : prev.users;

        return {
          ...prev,
          categories: (cats.data && cats.data.length > 0) ? cats.data.map(c => c.name) : prev.categories,
          people: cloudPeople,
          sessions: cloudSessions,
          matches: cloudMatches.map((m: any) => ({
            ...m,
            // معالجة الحقول المفقودة بمرونة لضمان عدم حدوث خطأ في الواجهة
            pitch: m.pitch || m.location || '' 
          })),
          attendance: cloudAttendance,
          users: cloudUsers
        };
      });
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
      console.error("Sync Error:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser]);

  useEffect(() => {
    if (!state.currentUser) return;
    fetchData(true); // جلب أولي عند الدخول

    const tables = ['people', 'sessions', 'matches', 'attendance', 'app_users']; // تم التعديل إلى app_users
    const channels = tables.map(table => 
      supabase
        .channel(`public:${table}`)
        .on('postgres_changes', { event: '*', schema: 'public', table }, () => fetchData())
        .subscribe()
    );

    return () => { channels.forEach(c => supabase.removeChannel(c)); };
  }, [state.currentUser, fetchData]);

  const pushData = useCallback(async (updatedState: AppState) => {
    if (!updatedState.currentUser) return;

    syncManager.current.isPushing = true;
    setSyncStatus('syncing');
    try {
      // التأكد من رسم خريطة دقيقة لكافة حقول المباراة لضمان توافقها مع قاعدة البيانات
      const mappedMatches = updatedState.matches.map(m => {
        const base: any = {
          id: m.id,
          category: m.category,
          matchType: m.matchType,
          opponent: m.opponent,
          date: m.date,
          time: m.time,
          advancePayment: m.advancePayment || '0',
          isCompleted: !!m.isCompleted,
          ourScore: m.ourScore || '0',
          opponentScore: m.opponentScore || '0',
          events: m.events || [],
          lineup: m.lineup || {},
          notes: m.notes || '',
          stoppageTime1: m.stoppageTime1 || '0',
          stoppageTime2: m.stoppageTime2 || '0'
        };
        // الحفاظ على التوافق مع حقل 'pitch' أو 'location' لمنع PGRST204
        if (m.pitch !== undefined) base.pitch = m.pitch;
        return base;
      });

      // رفع البيانات بترتيب يضمن عدم التداخل
      if (updatedState.people.length > 0) await supabase.from('people').upsert(sanitize(updatedState.people), { onConflict: 'id' });
      if (updatedState.sessions.length > 0) await supabase.from('sessions').upsert(sanitize(updatedState.sessions), { onConflict: 'id' });
      if (mappedMatches.length > 0) await supabase.from('matches').upsert(sanitize(mappedMatches), { onConflict: 'id' });
      if (updatedState.attendance.length > 0) await supabase.from('attendance').upsert(sanitize(updatedState.attendance), { onConflict: 'id' });

      // مزامنة المستخدمين أيضاً لضمان استمرارية الحسابات
      if (updatedState.users.length > 0) {
        await supabase.from('app_users').upsert(sanitize(updatedState.users), { onConflict: 'id' });
      }

      setSyncStatus('synced');
      syncManager.current.lastLocalUpdate = Date.now();
    } catch (error: any) {
      setSyncStatus('error');
      addLog('خطأ في الرفع', error.message, 'error');
    } finally {
      syncManager.current.isPushing = false;
    }
  }, [addLog]);

  const updateStateAndSync = async (updater: (prev: AppState) => AppState) => {
    // تحديث "طابع الوقت" فوراً لغلق نافذة الجلب
    syncManager.current.lastLocalUpdate = Date.now();

    let nextState: AppState | null = null;
    setState(prev => {
      nextState = updater(prev);
      return nextState;
    });

    if (nextState) {
      await pushData(nextState);
    }
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    localStorage.removeItem('alkarama_cloud_v5');
  };

  const handleCloudLogin = async (usernameInput: string, passwordInput: string): Promise<AppUser | null> => {
    try {
      const trimmedUsername = usernameInput.trim();

      // نظام الحماية (Bootstrap): السماح بدخول المستخدم "عزت" في حال وجود خلل بالسحاب
      if (trimmedUsername.toUpperCase() === 'IZZAT' && passwordInput === '123') {
        const bootstrapUser: AppUser = { id: 'root-izzat', username: 'IZZAT', role: 'مدير' };
        setState(prev => ({ ...prev, currentUser: bootstrapUser }));
        return bootstrapUser;
      }

      // استعلام السحاب المحدث لجدول app_users
      const { data, error } = await supabase
        .from('app_users')
        .select('*')
        .ilike('username', trimmedUsername)
        .single();

      if (error) {
        console.error("Login Query Error:", error);
        // معالجة الخطأ PGRST205 أو فقدان السجل
        if (error.code === 'PGRST205') {
           throw new Error("خطأ في الاتصال بقاعدة البيانات (205) - يرجى المحاولة لاحقاً");
        }
        throw new Error("لا يوجد مستخدم بهذا الاسم في قاعدة البيانات السحابية");
      }

      if (data && data.password === passwordInput) {
        const loggedUser: AppUser = { 
          id: data.id, 
          username: data.username, 
          role: data.role as any, 
          restrictedCategory: data.restrictedCategory 
        };
        setState(prev => ({ ...prev, currentUser: loggedUser }));
        return loggedUser;
      }
      return null;
    } catch (err: any) {
      console.error("Login process failed:", err.message);
      // سيتم عرض هذا الخطأ في واجهة Login
      throw err;
    }
  };

  if (!state.currentUser) return <Login onLoginAttempt={handleCloudLogin} />;

  const navItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'إدارة الفريق', icon: Users },
    { id: 'attendance', label: 'نظام الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'ai', label: 'المحلل الذكي (AI)', icon: Sparkles },
    { id: 'logistics', label: 'المساعد اللوجستي', icon: Map },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#001F3F] text-white transform transition-transform duration-300 lg:translate-x-0 lg:static lg:inset-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print shadow-2xl`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between border-b border-white/10">
            <div className="flex items-center gap-3">
              <ClubLogo size={40} />
              <span className="font-black text-lg tracking-tight">نادي الكرامة</span>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2"><X size={24} /></button>
          </div>
          <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1 custom-scrollbar">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-orange-600 text-white shadow-lg' : 'text-white/70 hover:bg-white/5'}`}>
                <item.icon size={20} />
                <span className="font-bold">{item.label}</span>
              </button>
            ))}
          </nav>
          <div className="p-4 border-t border-white/10">
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-400/10 font-bold">
              <LogOut size={20} /> <span>تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/90 backdrop-blur-md border-b sticky top-0 z-40 px-4 lg:px-8 py-4 flex items-center justify-between shadow-sm no-print">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 bg-slate-100 rounded-lg"><Menu size={24} /></button>
            <h1 className="text-xl font-black text-slate-800">{navItems.find(i => i.id === activeTab)?.label}</h1>
          </div>

          <div className="flex items-center gap-3 lg:gap-6">
            {/* User Profile & Notifications - التحديث الجديد للواجهة */}
            {state.currentUser && (
              <div className="flex items-center gap-3 bg-slate-50 border-2 border-slate-100 px-4 py-1.5 rounded-2xl shadow-sm transition-all hover:bg-white">
                 <button className="p-2 text-slate-400 hover:text-orange-600 transition-colors relative" onClick={() => setShowNotifications(!showNotifications)}>
                    <Bell size={20} />
                    <span className="absolute top-1.5 right-1.5 w-2.5 h-2.5 bg-red-600 rounded-full border-2 border-white"></span>
                 </button>
                 <div className="hidden md:flex flex-col text-left mr-2 border-r pr-3 border-slate-200">
                    <span className="text-xs font-black text-slate-900 leading-none">{state.currentUser.username}</span>
                    <span className="text-[9px] font-black text-orange-600 uppercase tracking-tighter mt-1">{state.currentUser.role}</span>
                 </div>
                 <div className="w-9 h-9 bg-white border-2 border-slate-900 rounded-xl flex items-center justify-center font-black text-slate-900 shadow-sm">
                    {state.currentUser.username.charAt(0).toUpperCase()}
                 </div>
              </div>
            )}

            <div className="flex items-center gap-2">
              <div className={`flex items-center gap-2 px-4 py-2 rounded-2xl border transition-all ${syncStatus === 'synced' ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-orange-50 border-orange-200 text-orange-700'}`}>
                 {syncStatus === 'synced' ? <CloudCheck size={18} /> : <Cloud size={18} className="animate-bounce" />}
                 <span className="text-[10px] font-black uppercase tracking-tighter">{syncStatus === 'synced' ? 'مؤمن سحابياً' : 'تأمين البيانات...'}</span>
              </div>
              <button onClick={() => fetchData(true)} className="p-2.5 rounded-xl bg-slate-100 text-slate-600 hover:bg-slate-200 transition-colors">
                <RefreshCw size={20} className={isSyncing ? 'animate-spin' : ''} />
              </button>
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto space-y-6 pb-20">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} addLog={addLog} />}
            {activeTab === 'ai' && <AIAssistant state={state} />}
            {activeTab === 'logistics' && <LocationAssistant />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>
        <ChatBot />
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ShieldCheck, CloudUpload, Trash2, Key, Info, UserPlus, X, Edit2, ShieldAlert, Layers, Plus, Database, Lock, Eye, EyeOff } from 'lucide-react';
import { AppState, AppUser, UserRole, Category } from '../types';
import { generateUUID, supabase } from '../App';

interface SettingsProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SettingsView: React.FC<SettingsProps> = ({ state, setState, addLog }) => {
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [newCatName, setNewCatName] = useState('');
  const [showPassInForm, setShowPassInForm] = useState(false);

  const currentUser = state.currentUser;
  const isGlobalManager = currentUser?.role === 'مدير';

  const [userFormData, setUserFormData] = useState<Partial<AppUser>>({
    username: '',
    role: 'إداري فئة',
    password: '',
    restrictedCategory: ''
  });

  const roles: UserRole[] = ['مدير', 'إداري فئة', 'مشاهد'];

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userFormData.username || !userFormData.password) return alert('يرجى إكمال كافة البيانات المطلوبة');

    if (editingUserId) {
      setState(prev => ({
        ...prev,
        users: prev.users.map(u => u.id === editingUserId ? { ...u, ...userFormData } as AppUser : u)
      }));
      addLog?.('تعديل صلاحية مستخدم', `تم تحديث بيانات المستخدم: ${userFormData.username}`, 'info');
    } else {
      const newUser: AppUser = {
        id: generateUUID(),
        username: userFormData.username!.trim(),
        role: userFormData.role as UserRole,
        password: userFormData.password!,
        restrictedCategory: userFormData.role === 'إداري فئة' ? userFormData.restrictedCategory : undefined
      };
      setState(prev => ({ ...prev, users: [...prev.users, newUser] }));
      addLog?.('إنشاء حساب مستخدم', `تم إنشاء مستخدم جديد بنجاح: ${newUser.username} برتبة ${newUser.role}`, 'success');
    }

    setIsUserModalOpen(false);
    setEditingUserId(null);
    setUserFormData({ username: '', role: 'إداري فئة', password: '', restrictedCategory: '' });
  };

  const handleAddCategory = () => {
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) return alert('هذه الفئة موجودة مسبقاً في النظام.');

    setState(prev => ({ ...prev, categories: [...prev.categories, newCatName.trim()] }));
    addLog?.('إضافة فئة رياضية', `تم إدراج فئة جديدة بالنظام: ${newCatName.trim()}`, 'success');
    setNewCatName('');
  };

  const removeCategory = (cat: string) => {
    if (confirm(`هل أنت متأكد من حذف فئة ${cat}؟ سيتم فصل كافة اللاعبين المرتبطين بها.`)) {
      setState(prev => ({ ...prev, categories: prev.categories.filter(c => c !== cat) }));
      addLog?.('حذف فئة رياضية', `تم مسح الفئة: ${cat}`, 'warning');
    }
  };

  const exportData = () => {
    const dataStr = JSON.stringify(state, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `alkaramah_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    addLog?.('تصدير قاعدة البيانات', 'تم إنشاء وتنزيل نسخة احتياطية شاملة للنظام.');
  };

  const deleteUser = async (id: string, name: string) => {
    if (name.toUpperCase() === 'IZZAT') return alert('لا يمكن حذف الحساب الجذري للنظام.');
    if (confirm(`هل أنت متأكد من حذف حساب ${name}؟`)) {
      // تم التعديل إلى app_users لضمان حذف الحساب سحابياً بشكل صحيح
      await supabase.from('app_users').delete().eq('id', id);
      setState(p => ({ ...p, users: p.users.filter(u => u.id !== id) }));
      addLog?.('حذف مستخدم', `تم حذف حساب المستخدم: ${name}`, 'error');
    }
  };

  const labelClass = "text-[10px] font-black text-slate-500 mr-2 uppercase block mb-1.5";
  const fieldClass = "w-full bg-slate-50 border-2 border-slate-200 rounded-xl py-3 px-4 font-black text-slate-800 outline-none focus:border-orange-600 transition-all";

  return (
    <div className="max-w-6xl mx-auto space-y-12 pb-24">
      {isGlobalManager && (
        <div className="bg-white p-10 rounded-[3rem] shadow-sm border-2 border-slate-900">
           <div className="flex justify-between items-center mb-8">
              <div>
                <h3 className="text-2xl font-black text-slate-900 flex items-center gap-3">
                  <ShieldCheck size={28} className="text-[#001F3F]" /> مركز التحكم في الحسابات والأدوار
                </h3>
                <p className="text-[10px] font-black text-slate-400 mt-1 uppercase tracking-widest">إدارة الدخول، الصلاحيات، وكلمات السر (خاص بالمديرين)</p>
              </div>
              <button onClick={() => { setEditingUserId(null); setIsUserModalOpen(true); }} className="bg-[#001F3F] text-white px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg border-b-4 border-black">
                <UserPlus size={18}/> إضافة حساب جديد
              </button>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {state.users.map(user => (
                <div key={user.id} className="bg-slate-50 p-6 rounded-[2rem] border-2 border-slate-200 relative overflow-hidden group">
                   <div className="absolute top-0 right-0 w-1.5 h-full bg-[#001F3F]"></div>
                   <div className="flex justify-between items-start mb-4">
                      <div className="w-10 h-10 bg-white border border-slate-200 rounded-xl flex items-center justify-center">
