        ${performanceAndDiscipline}

        [سجل النتائج الأخيرة للفئة]:
        ${recentMatches}

        مهمتك الأساسية:
        - تقديم توصيات تكتيكية مبنية على "الأرقام الفعالة" (الأهداف والتمريرات) والالتزام.
        - اقتراح تشكيلة مثالية (تكتيكية) تأخذ بعين الاعتبار غياب اللاعبين غير المنضبطين أو المصابين.
        - تحليل نقاط الضعف في النتائج الأخيرة (مثلاً إذا كانت النتائج سلبية، اقترح حلولاً دفاعية أو هجومية).
        - ساعد المدرب في اتخاذ قرارات "موضوعية" بعيداً عن العواطف، بالاعتماد على إحصائيات الحضور والمشاركة.
        - كن حازماً في التوصيات الانضباطية.

        استخدم اللغة العربية الاحترافية الممزوجة بروح نادي الكرامة "النسور".
      `;

      const response = await ai.models.generateContent({
        model: aiMode === 'deep' ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview',
        contents: userQuery,
        config: { 
          systemInstruction,
          thinkingConfig: aiMode === 'deep' ? { thinkingBudget: 16000 } : undefined 
        }
      });

      setMessages(prev => [...prev, { role: 'ai', text: response.text || "لم أستطع تحليل البيانات حالياً." }]);
    } catch (error: any) {
      setMessages(prev => [...prev, { role: 'ai', text: "حدث خطأ في الاتصال بالمحلل: " + error.message }]);
    } finally {
      setLoading(false);
    }
  };

