                               <input type="number" className="w-full bg-slate-800 border-2 border-slate-700 rounded-xl py-3 px-4 text-white font-black text-center text-2xl" value={activeMatch.stoppageTime1 || '0'} onChange={e => setActiveMatch({...activeMatch, stoppageTime1: e.target.value})} />
                            </div>
                            <div className="bg-white/5 p-6 rounded-[2rem] border border-white/10">
                               <label className="text-[10px] font-black text-orange-400 block mb-3 uppercase tracking-widest flex items-center gap-2"><Clock size={14}/> الشوط الثاني (+)</label>
                               <input type="number" className="w-full bg-slate-800 border-2 border-slate-700 rounded-xl py-3 px-4 text-white font-black text-center text-2xl" value={activeMatch.stoppageTime2 || '0'} onChange={e => setActiveMatch({...activeMatch, stoppageTime2: e.target.value})} />
                            </div>
                         </div>
                      </section>

                      <section className="bg-white p-8 rounded-[4rem] border-4 border-slate-900 shadow-xl">
                         <div className="flex justify-between items-center mb-8 border-b-2 border-slate-100 pb-4">
                            <h3 className="font-black text-md text-[#001F3F] uppercase tracking-tighter flex items-center gap-2">
                               <Zap size={20} className="text-orange-600"/> أحداث المباراة (Match Events)
                            </h3>
                         </div>
                         <div className="grid grid-cols-2 gap-3 mb-8">
                            <button onClick={() => addEvent('goal')} className="bg-emerald-600 text-white py-3 rounded-2xl text-[10px] font-black shadow-md hover:bg-black transition-all border-b-4 border-emerald-900">⚽ هدف</button>
                            <button onClick={() => addEvent('assist')} className="bg-blue-600 text-white py-3 rounded-2xl text-[10px] font-black shadow-md hover:bg-black transition-all border-b-4 border-blue-900">👟 تمريرة</button>
                            <button onClick={() => addEvent('yellow')} className="bg-yellow-400 text-slate-900 py-3 rounded-2xl text-[10px] font-black shadow-md hover:bg-black transition-all border-b-4 border-yellow-600">🟨 إنذار</button>
                            <button onClick={() => addEvent('red')} className="bg-red-600 text-white py-3 rounded-2xl text-[10px] font-black shadow-md hover:bg-black transition-all border-b-4 border-red-900">🟥 طرد</button>
                         </div>
                         <div className="space-y-4 max-h-[500px] overflow-y-auto custom-scrollbar pr-2">
                            {activeMatch.events.map((ev, i) => (
                               <div key={ev.id} className="bg-slate-50 p-4 rounded-[1.5rem] border-2 border-slate-100 shadow-sm relative group animate-in slide-in-from-right-4 duration-300">
                                  <div className="flex items-center gap-3">
                                     <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg shadow-inner ${ev.type === 'goal' ? 'bg-emerald-100' : ev.type === 'yellow' ? 'bg-yellow-100' : ev.type === 'red' ? 'bg-red-100' : 'bg-blue-100'}`}>
                                       {ev.type === 'goal' ? '⚽' : ev.type === 'yellow' ? '🟨' : ev.type === 'red' ? '🟥' : '👟'}
                                     </div>
                                     <div className="flex-1">
                                        <select className="w-full text-[10px] font-black bg-white border-2 border-slate-200 p-2 rounded-lg outline-none focus:border-slate-900" value={ev.player} onChange={e => {
                                           const evs = [...activeMatch.events];
                                           evs[i].player = e.target.value;
                                           setActiveMatch({...activeMatch, events: evs});
                                        }}>
                                           <option value="">-- اللاعب --</option>
                                           {state.people.filter(p => p.category === activeMatch.category).map(p => <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>)}
                                        </select>
                                     </div>
                                     <div className="w-14">
                                        <input type="number" className="w-full text-[12px] font-black border-2 border-slate-200 p-2 rounded-lg text-center focus:border-slate-900" value={ev.minute} placeholder="د" onChange={e => {
                                           const evs = [...activeMatch.events];
                                           evs[i].minute = e.target.value;
                                           setActiveMatch({...activeMatch, events: evs});
                                        }} />
                                     </div>
                                  </div>
                                  <button onClick={() => removeEvent(ev.id)} className="absolute -top-2 -left-2 bg-red-100 text-red-600 p-1.5 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"><X size={12}/></button>
                               </div>
                            ))}
                            {activeMatch.events.length === 0 && (
                               <p className="text-center py-10 text-[10px] font-black text-slate-300 italic">لا توجد أحداث مسجلة</p>
                            )}
                         </div>
                      </section>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

