                      <option value="">-- اختر لاعب --</option>
                      {state.people.filter(p => p.role === 'لاعب' && (!restrictedCat || p.category === restrictedCat)).map(p => (
                         <option key={p.id} value={p.id}>{p.name} ({p.category})</option>
