              <h3 className="text-2xl font-black text-slate-900">استخراج تقارير البيانات البصرية (A4 Optimized)</h3>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
              <div className="space-y-4">
