                    </div>
                    {reportType === 'player' && (
                       <div className="space-y-2">
                          <label className={labelClass}>البحث عن الاسم</label>
                          <select value={selectedPlayerId} onChange={e => setSelectedPlayerId(e.target.value)} className={fieldClass}>
                             <option value="">-- اختر من القائمة --</option>
                             {state.people.filter(p => p.category === selectedCatForReport).map(p => (
                                <option key={p.id} value={p.id}>{p.name} ({p.role})</option>
                             ))}
                          </select>
                       </div>
                    )}
                 </div>

                 {(reportType === 'multi_player' || reportType === 'matches_custom') && (
                   <div className="space-y-4">
                      <label className={labelClass}>تحديد قائمة للاستخراج ({selectedPlayerIds.length})</label>
                      <div className="max-h-[250px] overflow-y-auto border-2 border-slate-900 rounded-xl p-4 space-y-2 bg-slate-50 custom-scrollbar">
                         {state.people.filter(p => p.role === 'لاعب' && p.category === selectedCatForReport).map(p => (
                            <button key={p.id} onClick={() => togglePlayerSelection(p.id)} className={`w-full flex items-center justify-between p-3 rounded-lg border-2 transition-all ${selectedPlayerIds.includes(p.id) ? 'bg-[#001F3F] text-white border-[#001F3F]' : 'bg-white text-slate-900 border-slate-200'}`}>
                               <div className="flex items-center gap-3">
                                  {selectedPlayerIds.includes(p.id) ? <CheckSquare size={16}/> : <Square size={16}/>}
                                  <span className="font-black text-xs">{p.name}</span>
                               </div>
                               <span className="text-[10px] font-black opacity-60">#{p.number}</span>
                            </button>
                         ))}
                      </div>
                   </div>
                 )}

                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                       <label className={labelClass}>من تاريخ</label>
                       <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className={fieldClass} />
                    </div>
                    <div className="space-y-2">
                       <label className={labelClass}>إلى تاريخ</label>
                       <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className={fieldClass} />
                    </div>
                 </div>
              </div>

              <div className="flex flex-col justify-end gap-4">
                 <div className="bg-slate-100 p-5 rounded-2xl border-2 border-slate-200 space-y-2">
                    <h4 className="font-black text-[10px] text-[#001F3F] uppercase flex items-center gap-2"><Info size={14}/> تعليمات التصدير</h4>
                    <p className="text-[9px] font-medium leading-relaxed text-slate-500">سيتم إنشاء تقرير احترافي بصيغة PDF يتضمن كافة البيانات الإحصائية والانضباطية المختارة في النطاق الزمني المحدد.</p>
                 </div>
                 <button onClick={generateReport} className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black text-md shadow-xl hover:bg-black transition-all border-b-4 border-black uppercase flex items-center justify-center gap-3">
                    <Printer size={20}/> استخراج ومعاينة PDF (A4)
                 </button>
              </div>
           </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[500] p-4 no-print">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl border-[6px] border-slate-900 overflow-hidden">
              <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center">
                 <h3 className="font-black text-slate-900 uppercase">جدولة نشاط مركزي جديد</h3>
                 <button onClick={() => setIsModalOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900"><X size={20}/></button>
              </div>
              <form onSubmit={handleSave} className="p-8 space-y-5">
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className={labelClass}>الفئة</label>
                       <select required disabled={!!restrictedCat} className={fieldClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>المكان</label>
                       <input type="text" className={fieldClass} value={formData.pitch || ''} onChange={e => setFormData({...formData, pitch: e.target.value})} placeholder="ملعب الكرامة.." />
                    </div>
                 </div>
                 <div className="space-y-1">
                    <label className={labelClass}>موضوع / هدف النشاط</label>
                    <input required type="text" className={fieldClass} value={formData.objective || ''} onChange={e => setFormData({...formData, objective: e.target.value})} placeholder="تمرين تكتيكي / نشاط خارجي.." />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className={labelClass}>التاريخ</label>
                       <input required type="date" className={fieldClass} value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>التوقيت</label>
                       <input required type="time" className={fieldClass} value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black shadow-xl hover:bg-black transition-all mt-4 uppercase">حفظ وتثبيت الحصة</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, ShieldAlert, History, Search, ShieldCheck, Lock, Unlock, Clock, Calendar as CalendarIcon, AlertCircle, Printer, ChevronRight, FileText, Users } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord, TrainingSession, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus | null; excuse?: string; time?: string; date?: string }>>({});
  const [showPrintView, setShowPrintView] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;
  const restrictedCat = currentUser.restrictedCategory;
  const isViewer = currentUser.role === 'مشاهد';
  const isCatAdmin = currentUser.role === 'إداري فئة';
  const isManager = currentUser.role === 'مدير';

  // تصفية الجلسات المتاحة للاختيار
  const sessions = state.sessions
    .filter(s => {
      if (restrictedCat) return s.category === restrictedCat;
      return (globalFilter === 'الكل' || s.category === globalFilter);
    })
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);

  // تحديث: جلب كافة أعضاء الفئة مع وضع الكادر أولاً ثم اللاعبين
  const categoryMembers = state.people
    .filter(p => (activeSession ? p.category === activeSession.category : true))
    .sort((a, b) => {
      const isAStaff = a.role !== 'لاعب';
      const isBStaff = b.role !== 'لاعب';
      if (isAStaff && !isBStaff) return -1;
      if (!isAStaff && isBStaff) return 1;
      return 0; // الحفاظ على الترتيب الحالي إذا كان كلاهما من نفس النوع
    });

  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  // فحص انتهاء الوقت التلقائي (30 دقيقة)
  const isTimeExpired = activeSession ? (() => {
    const sessionTime = new Date(`${activeSession.date}T${activeSession.time}`);
    const now = new Date();
    const diffInMinutes = (now.getTime() - sessionTime.getTime()) / (1000 * 60);
    return diffInMinutes > 30;
  })() : false;

  // حالة القفل: إما يدوي من المدير أو تلقائي بمرور الوقت
  const isLocked = activeSession?.isLocked || (isTimeExpired && !isManager);

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    if (isLocked || isViewer) return;

    const saved = savedRecords.find(r => r.personId === pid);
    const local = localRecords[pid];
    const currentStatus = local?.status !== undefined ? local.status : (saved?.status || null);

    if (isManager && currentStatus === status) {
      setLocalRecords(prev => ({ 
        ...prev, 
        [pid]: { ...prev[pid], status: null } 
      }));
      return;
    }

    if (isCatAdmin && currentStatus !== null) {
      alert('نظام الحماية: لا يمكنك تعديل حالة الحضور بعد رصدها للمرة الأولى.');
      return;
    }

    const now = new Date();
    const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');

    setLocalRecords(prev => ({ 
      ...prev, 
      [pid]: { ...prev[pid], status, time: timeStr } 
    }));
  };

  const handleSetExcuse = (pid: string, excuse: string) => {
    if (isLocked || isViewer) return;
    setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], excuse } }));
  };

  // إصلاح دالة "تثبيت الرصد النهائي" وحل مشكلة المزامنة والقفل
  const saveAttendance = async () => {
    if (!selectedSessionId || isSaving) return;
    if (isLocked && !isManager) {
      alert("عذراً، السجل مقفل حالياً.");
      return;
    }

    setIsSaving(true);
    try {
      const newRecords: AttendanceRecord[] = [];
      const now = new Date();
      const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');

      categoryMembers.forEach(p => {
        const local = localRecords[p.id];
        const saved = savedRecords.find(r => r.personId === p.id);

        let statusToSave: AttendanceStatus | null = null;
        let excuseToSave = "";

        if (local && local.status !== undefined) {
          statusToSave = local.status;
          excuseToSave = local.excuse || "";
        } else if (saved) {
          statusToSave = saved.status;
          excuseToSave = saved.excuse || "";
        }

        // الغياب التلقائي عند التثبيت إذا كان الوقت قد مضى (للمدير الخيار في تركها فارغة)
        if (isTimeExpired && statusToSave === null && !isManager) {
          statusToSave = 'غائب';
        }

        if (statusToSave !== null) {
          newRecords.push({
            id: saved?.id || generateUUID(),
            personId: p.id,
            sessionId: selectedSessionId,
            date: activeSession!.date,
            time: local?.time || saved?.time || timeStr,
            status: statusToSave as AttendanceStatus,
            excuse: excuseToSave,
            isLocked: true
          });
        }
      });

      // 1. تحديث الحالة السحابية أولاً للسجلات
      if (newRecords.length > 0) {
        const { error: attError } = await supabase.from('attendance').upsert(newRecords.map(r => ({
          ...r,
          fine: r.fine || null
        })), { onConflict: 'id' });
        if (attError) throw attError;
      }

      // 2. تحديث الحالة السحابية للجلسة (قفل الجلسة)
      const { error: sessError } = await supabase.from('sessions').update({ 
        isLocked: true, 
        isCompleted: true 
      }).eq('id', selectedSessionId);

      if (sessError) throw sessError;

      // 3. تحديث الحالة المحلية للمزامنة الفورية
      setState(prev => ({
        ...prev,
        attendance: [
          ...prev.attendance.filter(a => a.sessionId !== selectedSessionId),
          ...newRecords
        ],
        sessions: prev.sessions.map(s => s.id === selectedSessionId ? { ...s, isLocked: true, isCompleted: true } : s)
      }));

      addLog?.('تثبيت الحضور', `تم رصد حضور فئة ${activeSession?.category} وإغلاق السجل نهائياً`, 'success');
      setLocalRecords({});
      alert('تم تثبيت الرصد النهائي وقفل السجل في السحابة بنجاح.');
    } catch (err: any) {
      console.error("Save Error:", err);
      alert('خطأ في الاتصال بالسحابة أو تثبيت البيانات: ' + err.message);
    } finally {
      setIsSaving(false);
    }
  };

  const toggleLock = async () => {
    if (!isManager || !activeSession) return;
    const newLockStatus = !activeSession.isLocked;

    setState(p => ({
      ...p,
      sessions: p.sessions.map(s => s.id === selectedSessionId ? { ...s, isLocked: newLockStatus } : s)
    }));

    await supabase.from('sessions').update({ isLocked: newLockStatus }).eq('id', selectedSessionId);
    addLog?.('قفل السجل', `${newLockStatus ? 'تم قفل' : 'تم إلغاء قفل'} سجل الحضور يدوياً`, 'warning');
  };

  if (showPrintView && activeSession) {
    const reportRecords = categoryMembers.map(p => {
        const r = savedRecords.find(rec => rec.personId === p.id);
        return { member: p, record: r };
    });

    return (
      <div className="fixed inset-0 bg-white z-[500] overflow-y-auto p-4 sm:p-12 dir-rtl text-right print:p-0">
        <div className="max-w-[210mm] mx-auto border-4 border-slate-900 p-10 print:border-2 print:p-6 bg-white min-h-[297mm] shadow-none">
           <div className="no-print flex justify-between items-center mb-10 border-b pb-4">
              <button onClick={() => setShowPrintView(false)} className="flex items-center gap-2 font-black text-slate-500 hover:text-red-600 transition-colors"><ChevronRight/> العودة للرصد</button>
              <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black flex items-center gap-2 shadow-xl"><Printer size={18}/> تصدير PDF (A4)</button>
           </div>

           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-6 mb-8 print:border-b-2">
              <div className="flex items-center gap-4">
                 <ClubLogo size={80} />
                 <div>
                    <h2 className="text-2xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-sm font-black text-orange-600">مكتب كرة القدم المركزي</p>
                 </div>
              </div>
              <div className="text-left font-black">
                 <p className="text-xl uppercase tracking-tighter">كشف حضور وانضباط رسمي</p>
                 <p className="text-sm text-slate-500">{activeSession.objective}</p>
                 <p className="text-[10px] mt-1">الفئة: {activeSession.category} | التاريخ: {activeSession.date}</p>
              </div>
           </div>

           <table className="w-full text-right border-collapse border-2 border-slate-900">
              <thead>
                 <tr className="bg-slate-100 border-b-2 border-slate-900 text-[10px] font-black uppercase">
                    <th className="p-3 border-l border-slate-900 text-center w-12">ت</th>
                    <th className="p-3 border-l border-slate-900">الاسم الكامل</th>
                    <th className="p-3 border-l border-slate-900 text-center">الصفة</th>
                    <th className="p-3 border-l border-slate-900 text-center">الحالة</th>
                    <th className="p-3 border-l border-slate-900 text-center">الوقت</th>
                    <th className="p-3">الملاحظات / العذر</th>
                 </tr>
              </thead>
              <tbody>
                 {reportRecords.map((item, idx) => (
                    <tr key={item.member.id} className={`border-b border-slate-300 text-xs font-black ${item.member.role !== 'لاعب' ? 'bg-slate-50' : ''}`}>
                       <td className="p-3 border-l border-slate-300 text-center">{idx + 1}</td>
                       <td className="p-3 border-l border-slate-300">{item.member.name}</td>
                       <td className="p-3 border-l border-slate-300 text-center text-[10px] opacity-70">{item.member.role}</td>
                       <td className="p-3 border-l border-slate-300 text-center">
                          <span className={item.record?.status === 'حاضر' ? 'text-emerald-600' : item.record?.status === 'متأخر' ? 'text-orange-600' : 'text-red-600'}>
                             {item.record?.status || 'غائب'}
                          </span>
                       </td>
                       <td className="p-3 border-l border-slate-300 text-center">{item.record?.time || '--'}</td>
                       <td className="p-3 text-[10px] italic text-slate-500">{item.record?.excuse || '--'}</td>
                    </tr>
                 ))}
              </tbody>
           </table>

           <div className="mt-20 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">توقيع مدرب الفئة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">إداري الفئة المسؤول</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">مدير مكتب كرة القدم</p>
                 <p className="font-black text-xs text-blue-900">عزت عامر الشيخة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
           </div>

           <div className="mt-10 pt-4 border-t border-slate-200 text-center hidden print:block">
              <p className="text-[8px] font-black text-slate-400">وثيقة رسمية صادرة عن النظام الإلكتروني لنادي الكرامة الرياضي - مقاس A4</p>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row gap-6 items-end no-print relative overflow-hidden">
        <div className="absolute top-0 right-0 w-2 h-full bg-[#001F3F]"></div>
        <div className="flex-1 space-y-2 w-full">
           <label className="text-[10px] font-black text-slate-900 mr-2 uppercase tracking-widest flex items-center gap-2">
             <ClipboardCheck size={14} className="text-blue-900"/> اختيار الجلسة التدريبية أو النشاط
           </label>
           <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); }}
            className="w-full bg-slate-100 border-2 border-slate-900 rounded-xl p-4 font-black text-xl text-slate-900 outline-none focus:border-orange-600 transition-all">
             <option value="">-- اختر التمرين من القائمة لفتح الرصد --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} | {s.objective} ({s.category})</option>)}
           </select>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          {isManager && selectedSessionId && (
            <button onClick={toggleLock} className={`flex-1 md:flex-none px-6 py-5 rounded-2xl font-black text-lg shadow-sm border-2 ${activeSession?.isLocked ? 'bg-red-50 text-red-600 border-red-600' : 'bg-emerald-50 text-emerald-700 border-emerald-600'}`}>
              {activeSession?.isLocked ? <Lock size={20} className="inline ml-2"/> : <Unlock size={20} className="inline ml-2"/>}
              {activeSession?.isLocked ? 'فتح السجل' : 'قفل السجل'}
            </button>
          )}
          <button onClick={() => setShowPrintView(true)} disabled={!selectedSessionId} className="flex-1 md:flex-none bg-white text-slate-900 border-2 border-slate-900 px-6 py-5 rounded-2xl font-black text-lg disabled:opacity-30 hover:bg-slate-50 transition-all">
            <Printer size={20} className="inline ml-2" /> طباعة A4
          </button>
          {!isViewer && (
            <button onClick={saveAttendance} disabled={!selectedSessionId || (isLocked && !isManager) || isSaving} className="flex-1 md:flex-[1.5] bg-[#001F3F] text-white px-8 py-5 rounded-2xl font-black text-lg shadow-xl disabled:opacity-30 border-b-4 border-black hover:bg-black transition-all">
              {isSaving ? <History className="animate-spin inline ml-2"/> : <Save size={20} className="inline ml-2" />}
              تثبيت الرصد النهائي
            </button>
          )}
        </div>
      </div>

      {isLocked && (
        <div className="bg-red-50 p-6 rounded-[2.5rem] border-4 border-red-900 flex items-center gap-4 shadow-lg animate-in slide-in-from-top duration-500">
           <div className="p-4 bg-red-900 text-white rounded-2xl"><Lock size={32}/></div>
           <div>
              <h3 className="text-xl font-black text-red-900 uppercase">السجل محمي ومقفل إدارياً</h3>
              <p className="text-xs font-black text-red-700 mt-1 uppercase">
                {activeSession?.isLocked ? 'تم اعتماد النتائج النهائية ونسخها للسحابة. لا يمكن التعديل حالياً.' : 'مضى وقت طويل على النشاط، يتطلب التعديل صلاحية "مدير النظام".'}
              </p>
           </div>
        </div>
      )}

      {activeSession && (
        <div className={`bg-white rounded-[2.5rem] shadow-sm border-2 border-slate-900 overflow-hidden relative ${isLocked && !isManager ? 'opacity-70 pointer-events-none grayscale-[0.3]' : ''}`}>
          <div className="p-6 border-b-2 border-slate-900 bg-slate-100 flex justify-between items-center">
             <div className="flex items-center gap-4">
               <div className="w-14 h-14 bg-white border-2 border-slate-900 rounded-xl flex items-center justify-center font-black text-2xl text-[#001F3F] shadow-md uppercase">K</div>
               <div>
                 <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">{activeSession.objective}</h3>
                 <p className="text-[10px] font-black text-[#001F3F] uppercase tracking-widest">{activeSession.category} • {activeSession.date}</p>
               </div>
             </div>
             <div className="flex items-center gap-2 bg-blue-50 text-blue-700 px-4 py-2 rounded-xl border border-blue-200">
                <Users size={18}/>
                <span className="text-[10px] font-black uppercase tracking-tighter">إجمالي الكادر واللاعبين: {categoryMembers.length}</span>
             </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-right min-w-[900px]">
              <thead className="bg-slate-200 border-b-2 border-slate-900">
                <tr>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest">الاسم / الدور (الكادر أولاً)</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest text-center">الرصد الانضباطي</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest text-center">التوقيت</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest">توضيح إداري / عذر</th>
                </tr>
              </thead>
              <tbody className="divide-y-2 divide-slate-200">
                {categoryMembers.map(p => {
                  const saved = savedRecords.find(r => r.personId === p.id);
                  const local = localRecords[p.id];

                  let currentStatus: AttendanceStatus | null = null;
                  let currentTime = "--:--";
                  let currentExcuse = "";

                  if (local !== undefined) {
                    currentStatus = local.status;
                    currentTime = local.time || "--:--";
                    currentExcuse = local.excuse || "";
                  } else if (saved) {
                    currentStatus = saved.status;
                    currentTime = saved.time || "--:--";
                    currentExcuse = saved.excuse || "";
                  }

                  const isMarked = (saved && saved.status) || (local && local.status);
                  const isDisabledForUser = !isManager && isMarked;
                  const isStaff = p.role !== 'لاعب';

                  return (
                    <tr key={p.id} className={`hover:bg-blue-50/30 transition-all ${isStaff ? 'bg-slate-50/80 border-r-8 border-[#001F3F]' : ''}`}>
                      <td className="px-6 py-5 border-l-2 border-slate-100">
                        <div className="flex items-center gap-3">
                          <div className={`w-10 h-10 rounded-lg flex items-center justify-center font-black text-md border-2 border-slate-900 ${currentStatus ? (isStaff ? 'bg-orange-600 text-white' : 'bg-[#001F3F] text-white') : 'bg-white'}`}>
                            {p.role === 'لاعب' ? (p.number || '??') : p.role.charAt(0)}
                          </div>
                          <div>
                             <span className="font-black text-[15px] text-slate-900 block">{p.name}</span>
                             <span className={`text-[9px] font-black uppercase ${isStaff ? 'text-orange-600' : 'text-slate-400'}`}>
                                {p.role} {isStaff ? ' (كادر)' : ''}
                             </span>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-5">
                        <div className="flex justify-center gap-2">
                          {['حاضر', 'متأخر', 'غائب', 'غياب بعذر'].map(st => (
                            <button key={st} disabled={(isLocked && !isManager) || isDisabledForUser || isViewer} onClick={() => handleSetStatus(p.id, st as AttendanceStatus)}
                              className={`px-4 py-2 rounded-lg text-[9px] font-black border-2 transition-all ${currentStatus === st ? `bg-slate-900 text-white border-slate-900 shadow-lg scale-105` : 'bg-white text-slate-900 border-slate-300 hover:border-slate-900'} disabled:opacity-50`}>
                              {st}
                            </button>
                          ))}
                        </div>
                      </td>
                      <td className="px-6 py-5 text-center">
                        <span className="font-black text-[10px] text-slate-900 bg-white px-3 py-1 rounded-lg border border-slate-200 shadow-sm">{currentTime}</span>
                      </td>
                      <td className="px-6 py-5">
                        <input disabled={(isLocked && !isManager) || isDisabledForUser || isViewer} type="text" value={currentExcuse} onChange={e => handleSetExcuse(p.id, e.target.value)}
                          className="bg-white border-2 border-slate-200 rounded-lg px-4 py-2 text-[10px] font-black w-full outline-none focus:border-[#001F3F] placeholder:text-slate-300" 
                          placeholder="اكتب التبرير هنا..."
                        />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTracker;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
export type UserRole = 'مدير' | 'إداري فئة' | 'مشاهد';
export type MatchType = 'دوري' | 'كأس' | 'ودية' | 'بطولة ودية' | 'مباراة دولية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface Person {
  id: string;
  name: string;
  fatherName: string;
  motherName: string;
  birthDate: string;
  birthPlace: string;
  khana: string;
  nationalId: string;
  federalNumber: string;
  internationalId: string;
  address: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  contractStart?: string;
  contractEnd?: string;
  contractValue?: string;
  medicalHistory?: string;
  injuries?: string;
  penalties?: string;
  notes?: string;
  coachingCertificate?: string;
  academicDegree?: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  excuse?: string;
  fine?: string;
  isLocked?: boolean;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  pitch?: string;
  objective: string;
  isCompleted?: boolean;
  isLocked?: boolean;
}

export interface MatchEvent {
  id: string;
  type: 'goal' | 'assist' | 'yellow' | 'red' | 'injury' | 'substitution';
  player: string; 
  minute: string;
  note?: string;
}

export interface Match {
  id: string;
  category: Category;
  matchType: MatchType;
  opponent: string;
  pitch?: string;
  date: string;
  time: string;
  advancePayment: string;
  isCompleted: boolean;
  ourScore: string;
  opponentScore: string;
  stoppageTime?: string; // للحفاظ على التوافق القديم
  stoppageTime1?: string; // وقت ضائع شوط أول
  stoppageTime2?: string; // وقت ضائع شوط ثاني
  events: MatchEvent[];
  lineup: {
    starters: { playerId: string; name: string; number: string; minutesPlayed?: string }[];
    subs: { 
      playerId: string; 
      name: string; 
      number: string; 
      minutesPlayed?: string;
      substitutionMinute?: string;
      replacedPlayerId?: string;
    }[];
    reserves?: { playerId: string; name: string; number: string }[];
    staff: { role: string; name: string }[];
    captain: string;
  };
  notes?: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  categories: Category[];
  currentUser: AppUser | null;
  notifications: AppNotification[];
  globalCategoryFilter: Category | 'الكل';
}

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';
  const isCatAdmin = currentUser?.role === 'إداري فئة';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة'
  });

  useEffect(() => {
    if (isAddOpen) {
      setFormData(prev => ({
        ...prev,
        category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter)
      }));
    }
  }, [isAddOpen, state.globalCategoryFilter, state.categories, restrictedCat]);

  useEffect(() => {
    if (activeMatch && !isViewer) {
      const newLineup = { ...activeMatch.lineup };
      let hasChanged = false;
      const st1 = parseInt(activeMatch.stoppageTime1 || '0') || 0;
      const st2 = parseInt(activeMatch.stoppageTime2 || '0') || 0;

      newLineup.subs.forEach((s) => {
        if (s.substitutionMinute && s.replacedPlayerId) {
          const minute = parseInt(s.substitutionMinute) || 0;
          let subMins = 0;
          if (minute <= 45) {
            subMins = (45 - minute) + st1 + 45 + st2;
          } else {
            subMins = (90 - minute) + st2;
          }
          if (s.minutesPlayed !== subMins.toString()) {
            s.minutesPlayed = subMins.toString();
            hasChanged = true;
          }

          const starterIdx = newLineup.starters.findIndex(st => st.playerId === s.replacedPlayerId);
          if (starterIdx !== -1) {
            let stMins = 0;
            if (minute <= 45) {
              stMins = minute;
            } else {
              stMins = 45 + st1 + (minute - 45);
            }
            if (newLineup.starters[starterIdx].minutesPlayed !== stMins.toString()) {
              newLineup.starters[starterIdx].minutesPlayed = stMins.toString();
              hasChanged = true;
            }
          }
        }
      });

      if (hasChanged) {
        setActiveMatch(prev => prev ? { ...prev, lineup: newLineup } : null);
      }
    }
  }, [activeMatch?.stoppageTime1, activeMatch?.stoppageTime2]);

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isViewer) return;

    const finalCategory = restrictedCat || formData.category;
    if (!formData.opponent || !formData.date || !formData.time || !finalCategory) return;

    const newMatch: Match = {
      id: generateUUID(),
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time,
      category: finalCategory,
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: { 
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '90' })), 
        subs: [], 
        reserves: [],
        staff: [], 
        captain: '' 
      },
      notes: ''
    };

    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ${newMatch.matchType} ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
  };

  const updateActiveMatchLineup = (index: number, playerId: string, isStarter: boolean) => {
    if (!activeMatch || isViewer) return;
    const person = state.people.find(p => p.id === playerId);
    if (!person) {
      const newLineup = { ...activeMatch.lineup };
      if (isStarter) {
        newLineup.starters[index] = { ...newLineup.starters[index], playerId: '', name: '', number: '' };
      }
      setActiveMatch({ ...activeMatch, lineup: newLineup });
      return;
    }

    const newLineup = { ...activeMatch.lineup };
    if (isStarter) {
      newLineup.starters[index] = { ...newLineup.starters[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const toggleCaptain = (playerId: string) => {
    if (!activeMatch || !playerId || isViewer) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.captain = newLineup.captain === playerId ? '' : playerId;
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateMinutes = (index: number, minutes: string, isStarter: boolean) => {
    if (!activeMatch || isViewer) return;
    const newLineup = { ...activeMatch.lineup };
    if (isStarter) {
      newLineup.starters[index].minutesPlayed = minutes;
    } else {
      newLineup.subs[index].minutesPlayed = minutes;
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const handleSubstitutionCalculation = (subIndex: number, replacedPlayerId: string, subMinute: string) => {
    if (!activeMatch || isViewer) return;
    const newLineup = { ...activeMatch.lineup };
    const minute = parseInt(subMinute) || 0;
    const st1 = parseInt(activeMatch.stoppageTime1 || '0') || 0;
    const st2 = parseInt(activeMatch.stoppageTime2 || '0') || 0;

    const starterIdx = newLineup.starters.findIndex(s => s.playerId === replacedPlayerId);
    if (starterIdx !== -1) {
      if (minute <= 45) {
        newLineup.starters[starterIdx].minutesPlayed = minute.toString();
      } else {
        const starterMins = 45 + st1 + (minute - 45);
        newLineup.starters[starterIdx].minutesPlayed = starterMins.toString();
      }
    }

    let subMins = 0;
    if (minute <= 45) {
      subMins = (45 - minute) + st1 + 45 + st2;
    } else {
      subMins = (90 - minute) + st2;
    }

    newLineup.subs[subIndex].replacedPlayerId = replacedPlayerId;
    newLineup.subs[subIndex].substitutionMinute = subMinute;
    newLineup.subs[subIndex].minutesPlayed = subMins.toString();

    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addSub = () => {
    if (!activeMatch || isViewer) return;
    setActiveMatch({
      ...activeMatch,
      lineup: {
        ...activeMatch.lineup,
        subs: [...activeMatch.lineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0', substitutionMinute: '', replacedPlayerId: '' }]
      }
    });
  };

  const updateSub = (index: number, playerId: string) => {
    if (!activeMatch || isViewer) return;
    const person = state.people.find(p => p.id === playerId);
    if (!person) return;

    const newSubs = [...activeMatch.lineup.subs];
    newSubs[index] = { ...newSubs[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const removeSub = (index: number) => {
    if (!activeMatch || isViewer) return;
    const newSubs = activeMatch.lineup.subs.filter((_, i) => i !== index);
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  // وظائف قائمة الاحتياط الجديدة
  const addReserve = () => {
    if (!activeMatch || isViewer) return;
    const currentReserves = activeMatch.lineup.reserves || [];
    setActiveMatch({
      ...activeMatch,
      lineup: {
        ...activeMatch.lineup,
        reserves: [...currentReserves, { playerId: '', name: '', number: '' }]
      }
    });
  };

  const updateReserve = (index: number, playerId: string) => {
    if (!activeMatch || isViewer) return;
    const person = state.people.find(p => p.id === playerId);
    if (!person) return;

    const newReserves = [...(activeMatch.lineup.reserves || [])];
    newReserves[index] = { playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, reserves: newReserves } });
  };

  const removeReserve = (index: number) => {
    if (!activeMatch || isViewer) return;
    const newReserves = (activeMatch.lineup.reserves || []).filter((_, i) => i !== index);
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, reserves: newReserves } });
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch || isViewer) return;
    const newEvent: MatchEvent = {
      id: generateUUID(),
      type,
      player: '',
      minute: '',
      note: ''
    };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const removeEvent = (eventId: string) => {
    if (!activeMatch || isViewer) return;
    setActiveMatch({
      ...activeMatch,
      events: activeMatch.events.filter(e => e.id !== eventId)
    });
  };

  const saveMatchDetails = () => {
    if (!activeMatch || isViewer) return;
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, isCompleted: true } : m)
    }));
    addLog?.('تحديث المباراة', `تم حفظ تفاصيل مباراة ${activeMatch.opponent}`, 'info');
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [
      ...activeMatch!.lineup.starters.map(s => s.playerId),
      ...activeMatch!.lineup.subs.map(s => s.playerId),
      ...(activeMatch!.lineup.reserves || []).map(r => r.playerId)
    ].filter(id => id && id !== currentId);

    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const fieldClass = "w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-[#001F3F] mr-2 uppercase block mb-1.5";

  if (showPrintView) {
    return (
      <div className="fixed inset-0 bg-white z-[500] overflow-y-auto p-12 text-right dir-rtl">
        <div className="max-w-5xl mx-auto border-4 border-slate-900 p-12 print:border-2">
           <div className="no-print flex justify-between items-center mb-10 border-b pb-4">
              <button onClick={() => setShowPrintView(false)} className="flex items-center gap-2 font-black text-slate-500"><ChevronRight/> العودة للأجندة</button>
              <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black flex items-center gap-2 shadow-xl"><Printer size={18}/> طباعة PDF</button>
           </div>
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-8 mb-10">
              <div className="flex items-center gap-4">
                 <ClubLogo size={90} />
                 <div>
                    <h2 className="text-3xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-md font-black text-orange-600 uppercase">مكتب كرة القدم المركزي</p>
                 </div>
              </div>
           </div>
           <table className="w-full text-right border-collapse">
              <thead>
                 <tr className="bg-slate-100 border-y-2 border-slate-900 text-xs font-black">
                    <th className="p-4 border-l">التاريخ</th>
                    <th className="p-4 border-l">المنافس</th>
                    <th className="p-4 border-l text-center">النتيجة</th>
                    <th className="p-4">الملعب</th>
                 </tr>
              </thead>
              <tbody>
                 {filteredMatches.map(m => (
                    <tr key={m.id} className="border-b border-slate-200 text-sm font-black">
                       <td className="p-4 border-l">{m.date} - {m.time}</td>
                       <td className="p-4 border-l">{m.opponent}</td>
                       <td className="p-4 border-l text-center">{m.isCompleted ? `${m.ourScore} - ${m.opponentScore}` : 'لم تلعب'}</td>
                       <td className="p-4">{m.pitch}</td>
                    </tr>
                 ))}
              </tbody>
           </table>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div>
           <h2 className="text-xl font-black text-slate-900 flex items-center gap-3">
             <Trophy size={24} className="text-orange-600" /> إدارة أجندة المباريات المركزية
           </h2>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowPrintView(true)} className="bg-white text-slate-900 border-2 border-slate-900 px-6 py-3 rounded-xl font-black text-sm">طباعة الأجندة</button>
          {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black text-sm">جدولة مواجهة</button>}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative border-b-8 transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-6">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400">{m.date} - {m.category}</span>
             </div>
             <div className="text-center mb-6">
                <p className="text-3xl font-black">{m.ourScore} - {m.opponentScore}</p>
                <p className="text-sm font-black mt-2">{m.opponent}</p>
                <p className="text-[10px] font-black text-slate-400 mt-2 flex items-center justify-center gap-1"><MapPin size={10}/> {m.pitch}</p>
             </div>
             <div className="flex flex-col gap-2">
                <button onClick={() => setActiveMatch(m)} className="w-full bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs">التشكيل والتقرير</button>
                {!isViewer && (isManager || restrictedCat === m.category) && (
                  <button onClick={async () => { if(confirm('حذف المباراة؟')) { await supabase.from('matches').delete().eq('id', m.id); setState(p => ({...p, matches: p.matches.filter(x => x.id !== m.id)})); } }} className="w-full py-2 bg-red-50 text-red-600 rounded-xl font-black text-[10px] border border-red-200">حذف المباراة</button>
                )}
             </div>
          </div>
        ))}
      </div>

      {isAddOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[300] p-4 no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg border-[6px] border-slate-900">
