                    <button onClick={() => setReportType('discipline')} className={`w-full py-3 px-4 rounded-xl font-black text-right text-[10px] transition-all flex items-center gap-2 ${reportType === 'discipline' ? 'bg-red-600 text-white shadow-md' : 'text-slate-500 hover:bg-white'}`}>
