const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus | null; excuse?: string; time?: string; date?: string }>>({});
  const [showPrintView, setShowPrintView] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [adminEditOverride, setAdminEditOverride] = useState(false);

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;
  const restrictedCat = currentUser.restrictedCategory;
  const isViewer = currentUser.role === 'مشاهد';
  const isCatAdmin = currentUser.role === 'إداري فئة';
  const isManager = currentUser.role === 'مدير';

  const sessions = state.sessions
    .filter(s => {
      if (restrictedCat) return s.category === restrictedCat;
      return (globalFilter === 'الكل' || s.category === globalFilter);
    })
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);

  const categoryMembers = state.people
    .filter(p => (activeSession ? p.category === activeSession.category : true))
    .sort((a, b) => {
      const isAStaff = a.role !== 'لاعب';
      const isBStaff = b.role !== 'لاعب';
      if (isAStaff && !isBStaff) return -1;
      if (!isAStaff && isBStaff) return 1;
      return a.name.localeCompare(b.name);
    });

  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  const isTimeExpired = activeSession ? (() => {
    const sessionTime = new Date(`${activeSession.date}T${activeSession.time}`);
    const now = new Date();
    const diffInMinutes = (now.getTime() - sessionTime.getTime()) / (1000 * 60);
    return diffInMinutes > 30;
  })() : false;

  const isLocked = activeSession?.isLocked || activeSession?.isCompleted || (isTimeExpired && !isManager);

  // خاصية جديدة للمدير: تجاوز القفل للتعديل السريع
  const canEditNow = isManager ? (adminEditOverride || !isLocked) : !isLocked;

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    if ((isLocked && !canEditNow) || isViewer) return;

    const saved = savedRecords.find(r => r.personId === pid);
    const local = localRecords[pid];
    const currentStatus = local?.status !== undefined ? local.status : (saved?.status || null);

    if (isManager && currentStatus === status) {
      setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], status: null } }));
      return;
    }

    if (isCatAdmin && currentStatus !== null) {
      alert('نظام الحماية: لا يمكنك تعديل حالة الحضور بعد رصدها للمرة الأولى.');
      return;
    }

    const now = new Date();
    const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');

    setLocalRecords(prev => ({ 
      ...prev, 
      [pid]: { ...prev[pid], status, time: timeStr } 
    }));
  };

  const handleSetExcuse = (pid: string, excuse: string) => {
    if ((isLocked && !canEditNow) || isViewer) return;
    setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], excuse } }));
  };

  const saveAttendance = async () => {
    if (!selectedSessionId || isSaving) return;
    if (isLocked && !canEditNow) {
      alert("عذراً، السجل مقفل حالياً.");
      return;
    }

    setIsSaving(true);
    try {
      const newRecords: AttendanceRecord[] = [];
      const now = new Date();
      const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');

      categoryMembers.forEach(p => {
        const local = localRecords[p.id];
        const saved = savedRecords.find(r => r.personId === p.id);

        let statusToSave: AttendanceStatus | null = null;
        let excuseToSave = "";

        if (local && local.status !== undefined) {
          statusToSave = local.status;
          excuseToSave = local.excuse || "";
        } else if (saved) {
          statusToSave = saved.status;
          excuseToSave = saved.excuse || "";
        }

        if (isTimeExpired && statusToSave === null && !isManager) {
          statusToSave = 'غائب';
        }

        if (statusToSave !== null) {
          newRecords.push({
            id: saved?.id || generateUUID(),
            personId: p.id,
            sessionId: selectedSessionId,
            date: activeSession!.date,
            time: local?.time || saved?.time || timeStr,
            status: statusToSave as AttendanceStatus,
            excuse: excuseToSave,
            isLocked: true
          });
        }
      });

      if (newRecords.length > 0) {
        const { error: attError } = await supabase.from('attendance').upsert(newRecords.map(r => ({
          id: r.id, personId: r.personId, sessionId: r.sessionId, date: r.date, 
          time: r.time, status: r.status, excuse: r.excuse
        })), { onConflict: 'id' });
        if (attError) throw attError;
      }

      const { error: sessError } = await supabase.from('sessions').update({ 
        isCompleted: true 
      }).eq('id', selectedSessionId);

      if (sessError) throw sessError;

      setState(prev => ({
        ...prev,
        attendance: [
          ...prev.attendance.filter(a => a.sessionId !== selectedSessionId),
          ...newRecords
        ],
        sessions: prev.sessions.map(s => s.id === selectedSessionId ? { ...s, isLocked: true, isCompleted: true } : s)
      }));

      addLog?.('تثبيت الحضور', `تم رصد حضور فئة ${activeSession?.category} وإغلاق السجل`, 'success');
      setLocalRecords({});
      setAdminEditOverride(false);
      alert('تم تثبيت الرصد النهائي وقفل السجل بنجاح.');
    } catch (err: any) {
      console.error("Save Error:", err);
      alert('خطأ في الاتصال بالسحابة: ' + err.message);
    } finally {
      setIsSaving(false);
    }
  };

  const toggleLock = async () => {
    if (!isManager || !activeSession) return;
    const newLockStatus = !(activeSession.isLocked || activeSession.isCompleted);

    setState(p => ({
      ...p,
      sessions: p.sessions.map(s => s.id === selectedSessionId ? { ...s, isLocked: newLockStatus, isCompleted: newLockStatus } : s)
    }));

    await supabase.from('sessions').update({ isCompleted: newLockStatus }).eq('id', selectedSessionId);
    addLog?.('قفل السجل', `${newLockStatus ? 'تم قفل' : 'تم فتح'} سجل الحضور`, 'warning');
  };

  if (showPrintView && activeSession) {
    const reportRecords = categoryMembers.map(p => {
        const r = savedRecords.find(rec => rec.personId === p.id);
        return { member: p, record: r };
    });

    return (
      <div className="fixed inset-0 bg-white z-[500] overflow-y-auto p-4 sm:p-12 dir-rtl text-right print:p-0">
        <div className="max-w-[210mm] mx-auto border-4 border-slate-900 p-10 print:border-2 print:p-6 bg-white min-h-screen">
           <div className="no-print flex justify-between items-center mb-10 border-b pb-4">
              <button onClick={() => setShowPrintView(false)} className="flex items-center gap-2 font-black text-slate-500 hover:text-red-600 transition-colors"><ChevronRight/> العودة للرصد</button>
              <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black flex items-center gap-2 shadow-xl"><Printer size={18}/> تصدير PDF (A4)</button>
           </div>

           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-6 mb-8 print:border-b-2">
              <div className="flex items-center gap-4">
                 <ClubLogo size={80} />
                 <div>
                    <h2 className="text-2xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-sm font-black text-orange-600">مكتب كرة القدم المركزي</p>
                 </div>
              </div>
              <div className="text-left font-black">
                 <p className="text-xl uppercase tracking-tighter">كشف حضور وانضباط رسمي</p>
                 <p className="text-sm text-slate-500">{activeSession.objective}</p>
                 <p className="text-[10px] mt-1">الفئة: {activeSession.category} | التاريخ: {activeSession.date}</p>
              </div>
           </div>

           <table className="w-full text-right border-collapse border-2 border-slate-900">
              <thead>
                 <tr className="bg-slate-100 border-b-2 border-slate-900 text-[10px] font-black uppercase">
                    <th className="p-3 border-l border-slate-900 text-center w-12">ت</th>
                    <th className="p-3 border-l border-slate-900">الاسم الكامل</th>
                    <th className="p-3 border-l border-slate-900 text-center">الصفة</th>
                    <th className="p-3 border-l border-slate-900 text-center">الحالة</th>
                    <th className="p-3 border-l border-slate-900 text-center">الوقت</th>
                    <th className="p-3">الملاحظات</th>
                 </tr>
              </thead>
              <tbody>
                 {reportRecords.map((item, idx) => (
                    <tr key={item.member.id} className={`border-b border-slate-300 text-xs font-black ${item.member.role !== 'لاعب' ? 'bg-slate-50' : ''}`}>
                       <td className="p-3 border-l border-slate-300 text-center">{idx + 1}</td>
                       <td className="p-3 border-l border-slate-300">{item.member.name}</td>
                       <td className="p-3 border-l border-slate-300 text-center text-[10px] opacity-70">{item.member.role}</td>
                       <td className="p-3 border-l border-slate-300 text-center">
                          <span className={item.record?.status === 'حاضر' ? 'text-emerald-600' : item.record?.status === 'متأخر' ? 'text-orange-600' : 'text-red-600'}>
                             {item.record?.status || 'غائب'}
                          </span>
                       </td>
                       <td className="p-3 border-l border-slate-300 text-center">{item.record?.time || '--'}</td>
                       <td className="p-3 text-[10px] italic text-slate-500">{item.record?.excuse || '--'}</td>
                    </tr>
                 ))}
              </tbody>
           </table>

           <div className="mt-20 signature-section flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">توقيع مدرب الفئة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">إداري الفئة المسؤول</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">أمين سر مكتب كرة القدم</p>
                 <p className="text-[10px]">..........................</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row gap-6 items-end no-print relative overflow-hidden">
        <div className="absolute top-0 right-0 w-2 h-full bg-[#001F3F]"></div>
        <div className="flex-1 space-y-2 w-full">
           <label className="text-[10px] font-black text-slate-900 mr-2 uppercase tracking-widest flex items-center gap-2">
             <ClipboardCheck size={14} className="text-blue-900"/> اختيار الجلسة للرصد
           </label>
           <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); setAdminEditOverride(false); }}
            className="w-full bg-slate-100 border-2 border-slate-900 rounded-xl p-4 font-black text-xl text-slate-900 outline-none focus:border-orange-600 transition-all">
             <option value="">-- اختر التمرين من القائمة --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} | {s.objective} ({s.category})</option>)}
           </select>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          {isManager && selectedSessionId && (
            <div className="flex gap-2">
              <button onClick={() => setAdminEditOverride(!adminEditOverride)} className={`px-4 py-5 rounded-2xl font-black text-xs border-2 transition-all flex items-center gap-2 ${adminEditOverride ? 'bg-orange-600 text-white border-orange-900 shadow-lg' : 'bg-white text-slate-900 border-slate-300'}`}>
                <Edit3 size={16}/> {adminEditOverride ? 'إيقاف تعديل المدير' : 'وضع تعديل المدير'}
              </button>
              <button onClick={toggleLock} className={`px-6 py-5 rounded-2xl font-black text-lg shadow-sm border-2 ${isLocked ? 'bg-red-50 text-red-600 border-red-600' : 'bg-emerald-50 text-emerald-700 border-emerald-600'}`}>
                {isLocked ? <Lock size={20} className="inline ml-2"/> : <Unlock size={20} className="inline ml-2"/>}
                {isLocked ? 'فتح السجل' : 'قفل السجل'}
              </button>
            </div>
          )}
          <button onClick={() => setShowPrintView(true)} disabled={!selectedSessionId} className="flex-1 md:flex-none bg-white text-slate-900 border-2 border-slate-900 px-6 py-5 rounded-2xl font-black text-lg disabled:opacity-30">
            <Printer size={20} className="inline ml-2" /> طباعة
          </button>
          {!isViewer && (
            <button onClick={saveAttendance} disabled={!selectedSessionId || (isLocked && !canEditNow) || isSaving} className="flex-1 md:flex-[1.5] bg-[#001F3F] text-white px-8 py-5 rounded-2xl font-black text-lg shadow-xl disabled:opacity-30 border-b-4 border-black">
              {isSaving ? <History className="animate-spin inline ml-2"/> : <Save size={20} className="inline ml-2" />}
              تثبيت الرصد النهائي
            </button>
          )}
        </div>
      </div>

      {isLocked && !adminEditOverride && (
        <div className="bg-red-50 p-6 rounded-[2.5rem] border-4 border-red-900 flex items-center gap-4 shadow-lg">
           <div className="p-4 bg-red-900 text-white rounded-2xl"><Lock size={32}/></div>
           <div>
              <h3 className="text-xl font-black text-red-900">السجل مقفل إدارياً</h3>
              <p className="text-xs font-black text-red-700 mt-1 uppercase">
                {activeSession?.isCompleted ? 'تم رصد النتائج النهائية وقفله. التعديل للمدير فقط.' : 'مضى وقت طويل على الجلسة، يتطلب التعديل صلاحية "المدير".'}
              </p>
           </div>
        </div>
      )}

      {adminEditOverride && (
        <div className="bg-orange-50 p-4 rounded-2xl border-2 border-orange-600 flex items-center gap-3 animate-pulse">
           <ShieldAlert className="text-orange-600" size={24}/>
           <span className="text-xs font-black text-orange-900">أنت الآن في وضع "تعديل المدير": القيود الزمنية والإدارية متوقفة مؤقتاً لحسابك.</span>
        </div>
      )}

      {activeSession && (
        <div className={`bg-white rounded-[2.5rem] shadow-sm border-2 border-slate-900 overflow-hidden relative ${isLocked && !canEditNow ? 'opacity-70 pointer-events-none grayscale-[0.3]' : ''}`}>
          <div className="p-6 border-b-2 border-slate-900 bg-slate-100 flex justify-between items-center">
             <div className="flex items-center gap-4">
               <div className="w-14 h-14 bg-white border-2 border-slate-900 rounded-xl flex items-center justify-center font-black text-2xl text-[#001F3F] uppercase">K</div>
               <div>
                 <h3 className="text-xl font-black text-slate-900 uppercase">{activeSession.objective}</h3>
                 <p className="text-[10px] font-black text-[#001F3F] uppercase tracking-widest">{activeSession.category} • {activeSession.date}</p>
               </div>
             </div>
             <div className="flex items-center gap-2 bg-blue-50 text-blue-700 px-4 py-2 rounded-xl border border-blue-200">
                <Users size={18}/>
                <span className="text-[10px] font-black uppercase tracking-tighter">إجمالي الكادر واللاعبين: {categoryMembers.length}</span>
             </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-right min-w-[900px]">
              <thead className="bg-slate-200 border-b-2 border-slate-900">
                <tr>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest">الاسم / الدور (الكادر أولاً)</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest text-center">الرصد الانضباطي</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest text-center">التوقيت</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest">توضيح إداري / عذر</th>
                </tr>
              </thead>
              <tbody className="divide-y-2 divide-slate-200">
                {categoryMembers.map(p => {
                  const saved = savedRecords.find(r => r.personId === p.id);
                  const local = localRecords[p.id];

                  let currentStatus: AttendanceStatus | null = null;
                  let currentTime = "--:--";
                  let currentExcuse = "";

                  if (local !== undefined) {
                    currentStatus = local.status;
                    currentTime = local.time || "--:--";
                    currentExcuse = local.excuse || "";
                  } else if (saved) {
                    currentStatus = saved.status;
                    currentTime = saved.time || "--:--";
                    currentExcuse = saved.excuse || "";
                  }

                  const isMarked = (saved && saved.status) || (local && local.status);
                  const isDisabledForUser = !canEditNow && isMarked;
                  const isStaff = p.role !== 'لاعب';

                  return (
                    <tr key={p.id} className={`hover:bg-blue-50/30 transition-all ${isStaff ? 'bg-slate-50 border-r-8 border-orange-600' : ''}`}>
                      <td className="px-6 py-5 border-l-2 border-slate-100">
                        <div className="flex items-center gap-3">
                          <div className={`w-10 h-10 rounded-lg flex items-center justify-center font-black text-md border-2 border-slate-900 ${currentStatus ? (isStaff ? 'bg-orange-600 text-white' : 'bg-[#001F3F] text-white') : 'bg-white'}`}>
                            {p.role === 'لاعب' ? (p.number || '??') : p.role.charAt(0)}
                          </div>
                          <div>
                             <span className="font-black text-[15px] text-slate-900 block">{p.name}</span>
                             <span className={`text-[9px] font-black uppercase ${isStaff ? 'text-orange-600' : 'text-slate-400'}`}>
                                {p.role} {isStaff ? ' (كادر)' : ''}
                             </span>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-5">
                        <div className="flex justify-center gap-2">
                          {['حاضر', 'متأخر', 'غائب', 'غياب بعذر'].map(st => (
                            <button key={st} disabled={(isLocked && !canEditNow) || isDisabledForUser || isViewer} onClick={() => handleSetStatus(p.id, st as AttendanceStatus)}
                              className={`px-4 py-2 rounded-lg text-[9px] font-black border-2 transition-all ${currentStatus === st ? `bg-slate-900 text-white border-slate-900 shadow-lg scale-105` : 'bg-white text-slate-900 border-slate-300 hover:border-slate-900'} disabled:opacity-50`}>
                              {st}
                            </button>
                          ))}
                        </div>
                      </td>
                      <td className="px-6 py-5 text-center">
                        <span className="font-black text-[10px] text-slate-900 bg-white px-3 py-1 rounded-lg border border-slate-200">{currentTime}</span>
                      </td>
                      <td className="px-6 py-5">
                        <input disabled={(isLocked && !canEditNow) || isDisabledForUser || isViewer} type="text" value={currentExcuse} onChange={e => handleSetExcuse(p.id, e.target.value)}
                          className="bg-white border-2 border-slate-200 rounded-lg px-4 py-2 text-[10px] font-black w-full outline-none focus:border-[#001F3F]" 
                          placeholder="اكتب التبرير هنا..."
                        />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTracker;

import React, { useState } from 'react';
import { ShieldCheck, CloudUpload, Trash2, Key, Info, UserPlus, X, Edit2, ShieldAlert, Layers, Plus, Database, Lock, Eye, EyeOff } from 'lucide-react';
import { AppState, AppUser, UserRole, Category } from '../types';
import { generateUUID, supabase } from '../App';

interface SettingsProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SettingsView: React.FC<SettingsProps> = ({ state, setState, addLog }) => {
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [newCatName, setNewCatName] = useState('');
  const [showPassInForm, setShowPassInForm] = useState(false);

  const currentUser = state.currentUser;
  const isGlobalManager = currentUser?.role === 'مدير';

  const [userFormData, setUserFormData] = useState<Partial<AppUser>>({
    username: '',
    role: 'إداري فئة',
    password: '',
    restrictedCategory: ''
  });

  const roles: UserRole[] = ['مدير', 'إداري فئة', 'مشاهد'];

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userFormData.username || !userFormData.password) return alert('يرجى إكمال كافة البيانات المطلوبة');

    if (editingUserId) {
      setState(prev => ({
        ...prev,
        users: prev.users.map(u => u.id === editingUserId ? { ...u, ...userFormData } as AppUser : u)
      }));
      addLog?.('تعديل صلاحية مستخدم', `تم تحديث بيانات المستخدم: ${userFormData.username}`, 'info');
    } else {
      const newUser: AppUser = {
        id: generateUUID(),
        username: userFormData.username!.trim(),
        role: userFormData.role as UserRole,
        password: userFormData.password!,
        restrictedCategory: (userFormData.role === 'إداري فئة' || userFormData.role === 'مشاهد') ? userFormData.restrictedCategory : undefined
      };
      setState(prev => ({ ...prev, users: [...prev.users, newUser] }));
      addLog?.('إنشاء حساب مستخدم', `تم إنشاء مستخدم جديد بنجاح: ${newUser.username} برتبة ${newUser.role}`, 'success');
    }

    setIsUserModalOpen(false);
    setEditingUserId(null);
    setUserFormData({ username: '', role: 'إداري فئة', password: '', restrictedCategory: '' });
  };

  const handleAddCategory = () => {
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) return alert('هذه الفئة موجودة مسبقاً في النظام.');

    setState(prev => ({ ...prev, categories: [...prev.categories, newCatName.trim()] }));
    addLog?.('إضافة فئة رياضية', `تم إدراج فئة جديدة بالنظام: ${newCatName.trim()}`, 'success');
    setNewCatName('');
  };

  const removeCategory = (cat: string) => {
    if (confirm(`هل أنت متأكد من حذف فئة ${cat}؟ سيتم فصل كافة اللاعبين المرتبطين بها.`)) {
      setState(prev => ({ ...prev, categories: prev.categories.filter(c => c !== cat) }));
      addLog?.('حذف فئة رياضية', `تم مسح الفئة: ${cat}`, 'warning');
    }
  };

  const exportData = () => {
    const dataStr = JSON.stringify(state, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `alkaramah_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    addLog?.('تصدير قاعدة البيانات', 'تم إنشاء وتنزيل نسخة احتياطية شاملة للنظام.');
  };

  const deleteUser = async (id: string, name: string) => {
    if (name.toUpperCase() === 'IZZAT' || name === 'عزت عامر الشيخة') return alert('لا يمكن حذف الحساب الجذري للنظام.');
    if (confirm(`هل أنت متأكد من حذف حساب ${name}؟`)) {
      await supabase.from('app_users').delete().eq('id', id);
      setState(p => ({ ...p, users: p.users.filter(u => u.id !== id) }));
      addLog?.('حذف مستخدم', `تم حذف حساب المستخدم: ${name}`, 'error');
    }
  };

  const labelClass = "text-[10px] font-black text-slate-500 mr-2 uppercase block mb-1.5";
  const fieldClass = "w-full bg-slate-50 border-2 border-slate-200 rounded-xl py-3 px-4 font-black text-slate-800 outline-none focus:border-orange-600 transition-all";

  return (
    <div className="max-w-6xl mx-auto space-y-12 pb-24">
      {isGlobalManager && (
        <div className="bg-white p-10 rounded-[3rem] shadow-sm border-2 border-slate-900">
           <div className="flex justify-between items-center mb-8">
              <div>
                <h3 className="text-2xl font-black text-slate-900 flex items-center gap-3">
                  <ShieldCheck size={28} className="text-[#001F3F]" /> مركز التحكم في الحسابات والأدوار
                </h3>
                <p className="text-[10px] font-black text-slate-400 mt-1 uppercase tracking-widest">إدارة الدخول، الصلاحيات، وكلمات السر (خاص بالمديرين)</p>
              </div>
              <button onClick={() => { setEditingUserId(null); setIsUserModalOpen(true); }} className="bg-[#001F3F] text-white px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg border-b-4 border-black">
                <UserPlus size={18}/> إضافة حساب جديد
              </button>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {state.users.map(user => (
                <div key={user.id} className="bg-slate-50 p-6 rounded-[2rem] border-2 border-slate-200 relative overflow-hidden group">
                   <div className="absolute top-0 right-0 w-1.5 h-full bg-[#001F3F]"></div>
                   <div className="flex justify-between items-start mb-4">
                      <div className="w-10 h-10 bg-white border border-slate-200 rounded-xl flex items-center justify-center">
                         <Key size={18} className="text-orange-600"/>
                      </div>
                      <span className={`text-[9px] font-black px-3 py-1 rounded-lg uppercase border ${user.role === 'مدير' ? 'bg-orange-600 text-white border-orange-700' : user.role === 'مشاهد' ? 'bg-slate-200 text-slate-600' : 'bg-[#001F3F] text-white border-black'}`}>
                        {user.role}
                      </span>
                   </div>
                   <h4 className="font-black text-lg text-slate-900">{user.username}</h4>
                   <p className="text-[9px] font-black text-slate-400 mt-1 uppercase tracking-tighter">
                      {user.restrictedCategory ? `مخصص لفئة: ${user.restrictedCategory}` : 'صلاحيات وصول شاملة'}
                   </p>
                   <div className="mt-6 pt-4 border-t border-slate-200 flex justify-between items-center">
                      <p className="text-[10px] font-black text-slate-300">PASS: {user.password ? '****' : 'N/A'}</p>
                      <div className="flex gap-2">
                         <button onClick={() => { setEditingUserId(user.id); setUserFormData(user); setIsUserModalOpen(true); }} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"><Edit2 size={16}/></button>
                         {(user.username.toUpperCase() !== 'IZZAT' && user.username !== 'عزت عامر الشيخة') && (
                           <button onClick={() => deleteUser(user.id, user.username)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={16}/></button>
                         )}
                      </div>
                   </div>
                </div>
              ))}
           </div>
        </div>
      )}

      <div className="bg-white p-12 rounded-[4rem] shadow-sm border border-slate-100">
        <h3 className="text-3xl font-black text-slate-800 mb-10">إدارة الفئات الرياضية</h3>
        <div className="flex flex-col md:flex-row gap-6 mb-12">
          <input 
            type="text" 
            value={newCatName} 
            onChange={e => setNewCatName(e.target.value)}
            placeholder="مثال: فئة البراعم.."
            className="flex-1 bg-slate-50 border-4 border-slate-100 rounded-[2rem] p-6 font-black text-2xl outline-none focus:border-orange-600 transition-all"
          />
          <button 
            onClick={handleAddCategory}
            disabled={!isGlobalManager}
            className="bg-[#001F3F] text-white px-12 py-6 rounded-[2rem] font-black disabled:opacity-30"
          >
            تثبيت الفئة الجديدة
          </button>
        </div>
        <div className="flex flex-wrap gap-4">
           {state.categories.map(cat => (
             <div key={cat} className="bg-slate-50 border-2 border-slate-200 px-6 py-3 rounded-2xl flex items-center gap-4 group">
                <span className="font-black text-slate-700">{cat}</span>
                {isGlobalManager && (
                  <button onClick={() => removeCategory(cat)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-opacity"><X size={16}/></button>
                )}
             </div>
           ))}
        </div>
      </div>

      <div className="bg-[#001F3F] p-16 rounded-[5rem] shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-32 -mt-32"></div>
        <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-10">
           <div className="text-white">
              <h3 className="text-3xl font-black mb-2">نسخة الحماية والنسخ الاحتياطي</h3>
              <p className="font-black text-orange-400 uppercase tracking-widest text-sm">تصدير كافة البيانات المسجلة على النظام في ملف واحد</p>
           </div>
           <button onClick={exportData} className="bg-white text-[#001F3F] font-black px-12 py-6 rounded-[2.5rem] flex items-center justify-center gap-5 text-2xl shadow-xl hover:scale-105 transition-all">
             <Database size={32}/> تصدير قاعدة البيانات (JSON)
           </button>
        </div>
      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/90 backdrop-blur-3xl flex items-center justify-center z-[500] p-6 no-print overflow-y-auto">
          <div className="bg-white rounded-[4rem] w-full max-w-xl shadow-2xl border-[10px] border-white p-12">
            <div className="flex justify-between items-center mb-10">
               <h3 className="text-2xl font-black text-[#001F3F] uppercase tracking-tighter">إعدادات دخول الحساب</h3>
               <button onClick={() => setIsUserModalOpen(false)} className="bg-slate-100 p-3 rounded-full"><X/></button>
            </div>
            <form onSubmit={handleSaveUser} className="space-y-6">
              <div>
                <label className={labelClass}>اسم المستخدم (الاسم الحقيقي أو الكنية)</label>
                <input required type="text" value={userFormData.username || ''} onChange={e => setUserFormData({ ...userFormData, username: e.target.value })}
                  className={fieldClass} placeholder="مثال: Ahmed_KSC" />
              </div>

              <div>
                <label className={labelClass}>كلمة المرور الخاصة بالحساب</label>
                <div className="relative">
                   <input required type={showPassInForm ? "text" : "password"} value={userFormData.password || ''} onChange={e => setUserFormData({ ...userFormData, password: e.target.value })}
                    className={fieldClass} placeholder="اكتب كلمة سر قوية.." />
                   <button type="button" onClick={() => setShowPassInForm(!showPassInForm)} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
                      {showPassInForm ? <EyeOff size={20}/ : <Eye size={20}/>}
                   </button>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className={labelClass}>رتبة الصلاحية</label>
                    <select className={fieldClass}
                      value={userFormData.role} onChange={e => setUserFormData({ ...userFormData, role: e.target.value as UserRole, restrictedCategory: '' })}>
                      {roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                 </div>
                 {(userFormData.role === 'إداري فئة' || userFormData.role === 'مشاهد') && (
                    <div>
                      <label className={labelClass}>الفئة المخصصة (اتركها فارغة للمشاهد العام)</label>
                      <select className={fieldClass}
                        value={userFormData.restrictedCategory} onChange={e => setUserFormData({ ...userFormData, restrictedCategory: e.target.value })}>
                        <option value="">{userFormData.role === 'مشاهد' ? 'رؤية كل الفئات' : '-- اختر الفئة --'}</option>
                        {state.categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                      </select>
                    </div>
                 )}
              </div>

              <div className="bg-blue-50 p-4 rounded-2xl border-2 border-blue-100 flex items-start gap-3">
                 <ShieldAlert className="text-blue-600 shrink-0" size={20}/>
                 <p className="text-[10px] font-black text-blue-900 leading-relaxed uppercase">
                    {userFormData.role === 'مشاهد' 
                      ? 'ملاحظة: "المشاهد المخصص" سيرى فقط بيانات الفئة المختارة، بينما "المشاهد" بدون فئة سيرى كافة بيانات النادي.'
                      : 'تنبيه: "إداري الفئة" سيقتصر وصوله فقط على البيانات الخاصة بفئته المحددة، ولن يتمكن من تعديل الحضور بعد رصده للمرة الأولى.'}
                 </p>
              </div>

              <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-6 rounded-[2.5rem] shadow-2xl text-2xl hover:bg-black transition-all">
                {editingUserId ? 'تحديث بيانات الحساب' : 'تثبيت الحساب في النظام'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SettingsView;

import React, { useState, useMemo } from 'react';
import { Calendar as CalendarIcon, MapPin, Clock, Plus, Trash2, Edit, X, Printer, FileText, CheckCircle, ShieldCheck, Lock, AlertCircle, Map, ChevronRight, BarChart3, PieChart, Users, User, TrendingUp, CalendarDays, Gavel, UserCircle, Hash, Trophy, Search, CheckSquare, Square, Info, Target, Zap, Filter, LayoutPanelLeft } from 'lucide-react';
import { AppState, TrainingSession, Category, Person, AttendanceRecord, Match } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

export default function TrainingPlanner({ state, setState, defaultSelectedId, addLog }: TrainingPlannerProps) {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري فئة';
  const canModifyConfig = isManager || isCatAdmin; 

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showPrintView, setShowPrintView] = useState(false);
  const [activeTab, setActiveTab] = useState<'agenda' | 'stats'>('agenda');
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);

  const [reportType, setReportType] = useState<'category' | 'player' | 'discipline' | 'multi_player' | 'matches_custom'>('category');
  const [selectedCatForReport, setSelectedCatForReport] = useState<string>(restrictedCat || state.categories[0] || '');
  const [selectedPlayerId, setSelectedPlayerId] = useState<string>('');
  const [selectedPlayerIds, setSelectedPlayerIds] = useState<string[]>([]);

  const [startDate, setStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);

  const [printData, setPrintData] = useState<any>(null);

  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'الرجال'),
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    pitch: ''
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.time) return;

    const finalCategory = restrictedCat || formData.category;

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData, category: finalCategory } as TrainingSession : s)
      }));
      addLog?.('تعديل موعد تمرين', `تم تحديث بيانات تمرين فئة ${finalCategory}`, 'info');
    } else {
      const newSession: TrainingSession = {
        id: generateUUID(),
        category: finalCategory as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        pitch: formData.pitch || 'غير محدد',
        objective: formData.objective || 'تمرين عام',
        isCompleted: false,
        isLocked: false
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
      addLog?.('إضافة موعد تمرين', `تمت جدولة تمرين جديد لفئة ${newSession.category}`, 'info');
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const toggleSessionComplete = (id: string, currentStatus: boolean) => {
    const session = state.sessions.find(s => s.id === id);
    if (isCatAdmin && session?.category !== restrictedCat) return;

    setState(prev => ({
      ...prev,
      sessions: prev.sessions.map(s => s.id === id ? { ...s, isCompleted: !currentStatus } : s)
    }));
  };

  const filteredSessions = useMemo(() => {
    return (restrictedCat 
      ? state.sessions.filter(s => s.category === restrictedCat)
      : state.sessions.filter(s => (state.globalCategoryFilter === 'الكل' || s.category === state.globalCategoryFilter)))
      .sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [state.sessions, restrictedCat, state.globalCategoryFilter]);

  const generateReport = () => {
    const start = new Date(startDate).getTime();
    const end = new Date(endDate).getTime();
    const periodStr = `من ${startDate} إلى ${endDate}`;

    if (reportType === 'category' || reportType === 'multi_player') {
      const catSessions = state.sessions.filter(s => 
        s.category === selectedCatForReport && 
        new Date(s.date).getTime() >= start && 
        new Date(s.date).getTime() <= end
      );

      let targetPlayers = state.people.filter(p => p.role === 'لاعب' && p.category === selectedCatForReport);
      if (reportType === 'multi_player' && selectedPlayerIds.length > 0) {
        targetPlayers = targetPlayers.filter(p => selectedPlayerIds.includes(p.id));
      }

      const catMatches = state.matches.filter(m => 
        m.category === selectedCatForReport && 
        new Date(m.date).getTime() >= start && 
        new Date(m.date).getTime() <= end
      );

      const playerList = targetPlayers.map(p => {
        // فلترة السجلات بحيث تنتمي فقط للجلسات التي تمت تصفيتها
        const sessionIds = catSessions.map(cs => cs.id);
        const playerRecords = state.attendance.filter(a => 
          a.personId === p.id && 
          sessionIds.includes(a.sessionId) &&
          new Date(a.date).getTime() >= start && 
          new Date(a.date).getTime() <= end
        );
        const present = playerRecords.filter(r => r.status === 'حاضر').length;
        const late = playerRecords.filter(r => r.status === 'متأخر').length;
        // تصحيح: التقريب والحد الأقصى 100
        const attRateRaw = catSessions.length > 0 ? ((present + late * 0.7) / catSessions.length) * 100 : 0;
        const attRate = Math.min(100, Math.round(attRateRaw));

        let yellows = 0;
        let reds = 0;
        catMatches.forEach(m => {
          yellows += m.events.filter(e => e.type === 'yellow' && (e.player === p.id || e.player === p.name)).length;
          reds += m.events.filter(e => e.type === 'red' && (e.player === p.id || e.player === p.name)).length;
        });

        return { ...p, attRate, yellows, reds };
      }).sort((a,b) => b.attRate - a.attRate);

      const totalPossible = catSessions.length * targetPlayers.length;
      let totalPresenceAcross = 0;
      targetPlayers.forEach(p => {
        const sessionIds = catSessions.map(cs => cs.id);
        const recs = state.attendance.filter(a => a.personId === p.id && sessionIds.includes(a.sessionId) && new Date(a.date).getTime() >= start && new Date(a.date).getTime() <= end);
        totalPresenceAcross += recs.filter(r => r.status === 'حاضر').length;
      });

      const attendanceRateRaw = totalPossible > 0 ? (totalPresenceAcross / totalPossible) * 100 : 0;
      const attendanceRate = Math.min(100, Math.round(attendanceRateRaw));

      setPrintData({
        type: 'category',
        title: reportType === 'multi_player' ? `تقرير أداء اللاعبين المختارين - فئة ${selectedCatForReport}` : `تقرير أداء فئة: ${selectedCatForReport}`,
        period: periodStr,
        sessions: catSessions,
        playerList,
        stats: { totalSessions: catSessions.length, attendanceRate, playersCount: targetPlayers.length }
      });
    } else if (reportType === 'player') {
      const player = state.people.find(p => p.id === selectedPlayerId);
      if (!player) return alert('يرجى اختيار اللاعب أولاً');

      const playerSessions = state.sessions.filter(s => 
        s.category === player.category && 
        new Date(s.date).getTime() >= start && 
        new Date(s.date).getTime() <= end
      );
      const sessionIds = playerSessions.map(ps => ps.id);

      const playerRecords = state.attendance.filter(a => 
        a.personId === player.id && 
        sessionIds.includes(a.sessionId) &&
        new Date(a.date).getTime() >= start && 
        new Date(a.date).getTime() <= end
      );

      const playerMatches = state.matches.filter(m => 
        m.category === player.category && 
        new Date(m.date).getTime() >= start && 
        new Date(m.date).getTime() <= end
      );

      const present = playerRecords.filter(r => r.status === 'حاضر').length;
      const late = playerRecords.filter(r => r.status === 'متأخر').length;
      const absent = playerRecords.filter(r => r.status === 'غائب').length;
      const excused = playerRecords.filter(r => r.status === 'غياب بعذر').length;

      // تصحيح: التقريب والحد الأقصى 100
      const scoreRaw = playerSessions.length > 0 ? ((present + (late * 0.5)) / playerSessions.length) * 100 : 0;
      const score = Math.min(100, Math.round(scoreRaw));

      let matchYellows = 0;
      let matchReds = 0;
      playerMatches.forEach(m => {
        matchYellows += m.events.filter(e => e.type === 'yellow' && (e.player === player.id || e.player === player.name)).length;
        matchReds += m.events.filter(e => e.type === 'red' && (e.player === player.id || e.player === player.name)).length;
      });

      setPrintData({
        type: 'player',
        player,
        title: `تقرير التزام اللاعب: ${player.name}`,
        period: periodStr,
        stats: { present, late, absent, excused, total: playerSessions.length, score, matchYellows, matchReds },
        records: playerRecords.map(r => {
          const s = state.sessions.find(ses => ses.id === r.sessionId);
          return { ...r, objective: s?.objective || 'تمرين عام' };
        }).sort((a,b) => b.date.localeCompare(a.date))
      });
    } else if (reportType === 'discipline') {
      const catMembers = state.people.filter(p => p.category === selectedCatForReport);
      const catSessions = state.sessions.filter(s => 
        s.category === selectedCatForReport && 
        new Date(s.date).getTime() >= start && 
        new Date(s.date).getTime() <= end
      );
      const sessionIds = catSessions.map(cs => cs.id);

      const disciplinaryStats = catMembers.map(p => {
        const records = state.attendance.filter(a => 
          a.personId === p.id && 
          sessionIds.includes(a.sessionId) &&
          new Date(a.date).getTime() >= start && 
          new Date(a.date).getTime() <= end
        );
        const lates = records.filter(r => r.status === 'متأخر').length;
        const absences = records.filter(r => r.status === 'غائب').length;
        const excused = records.filter(r => r.status === 'غياب بعذر').length;
        return {
          id: p.id,
          name: p.name,
          role: p.role,
          number: p.number,
          federalId: p.federalNumber || p.nationalId || 'بدون رقم',
          lates,
          absences,
          excused,
          totalOffenses: lates + absences
        };
      }).sort((a,b) => b.totalOffenses - a.totalOffenses);

      setPrintData({
        type: 'discipline',
        title: `كشف انضباط فئة: ${selectedCatForReport}`,
        period: periodStr,
        stats: disciplinaryStats
      });
    } else if (reportType === 'matches_custom') {
      const targetMatches = state.matches.filter(m => 
        m.isCompleted && 
        m.category === selectedCatForReport && 
        new Date(m.date).getTime() >= start && 
        new Date(m.date).getTime() <= end
      );

      let targetPlayers = state.people.filter(p => p.role === 'لاعب' && p.category === selectedCatForReport);
      if (selectedPlayerIds.length > 0) {
        targetPlayers = targetPlayers.filter(p => selectedPlayerIds.includes(p.id));
      }

      const matchStatsByPlayer = targetPlayers.map(p => {
        let totalMins = 0;
        let goals = 0;
        let assists = 0;
        let yellows = 0;
        let reds = 0;
        let apps = 0;

        targetMatches.forEach(m => {
          const starter = m.lineup.starters.find(s => s.playerId === p.id);
          const sub = m.lineup.subs.find(s => s.playerId === p.id);

          if (starter || sub) {
            apps++;
            totalMins += parseInt(starter?.minutesPlayed || sub?.minutesPlayed || '0') || 0;
            goals += m.events.filter(e => e.type === 'goal' && (e.player === p.id || e.player === p.name)).length;
            assists += m.events.filter(e => e.type === 'assist' && (e.player === p.id || e.player === p.name)).length;
            yellows += m.events.filter(e => e.type === 'yellow' && (e.player === p.id || e.player === p.name)).length;
            reds += m.events.filter(e => e.type === 'red' && (e.player === p.id || e.player === p.name)).length;
          }
        });

        return { ...p, apps, totalMins, goals, assists, yellows, reds };
      }).sort((a, b) => b.goals - a.goals);

      setPrintData({
        type: 'matches_custom',
        title: `تقرير المشاركات الفنية - فئة ${selectedCatForReport}`,
        period: periodStr,
        matches: targetMatches,
        playerStats: matchStatsByPlayer
      });
    }
    setShowPrintView(true);
  };
  // Rest of TrainingPlanner stays identical to fulfill the "do not delete/shortcut" rule...
  const togglePlayerSelection = (pid: string) => {
