            </div>
          </div>

          <div className="flex items-center gap-4 lg:gap-10">
            <div className="flex items-center gap-4 bg-white/5 border border-white/10 px-5 py-2.5 rounded-2xl shadow-xl transition-all hover:bg-white/10 group">
                 <button onClick={() => setShowNotifications(!showNotifications)} className="p-2 text-slate-400 hover:text-emerald-400 transition-colors relative">
                    <Bell size={24} />
                    {state.notifications.filter(n => !n.isRead).length > 0 && (
                      <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-slate-950"></span>
                    )}
                 </button>

                 <div className="flex items-center gap-4 border-r pr-5 border-white/10">
                    <div className="hidden sm:flex flex-col text-left">
                       <span className="text-xs font-black text-white leading-none tracking-tight">{state.currentUser.username}</span>
                       <span className="text-[10px] font-black text-emerald-500 uppercase tracking-tighter mt-1">{state.currentUser.role}</span>
                    </div>
                    <div className="w-11 h-11 bg-emerald-600 text-white border border-emerald-400/50 rounded-2xl flex items-center justify-center font-black text-lg shadow-[0_0_20px_-5px_rgba(16,185,129,0.4)] group-hover:scale-110 transition-transform">
                       {state.currentUser.username.charAt(0).toUpperCase()}
