                 </div>
              </div>

            <div className="flex items-center gap-3">
              <div className={`hidden md:flex items-center gap-3 px-5 py-3 rounded-2xl border transition-all ${syncStatus === 'synced' ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' : 'bg-orange-500/10 border-orange-500/20 text-orange-400 animate-pulse'}`}>
                 {syncStatus === 'synced' ? <CloudCheck size={20} /> : <Cloud size={20} className="animate-bounce" />}
                 <span className="text-[11px] font-black uppercase tracking-tighter">{syncStatus === 'synced' ? 'Cloud Secure' : 'Syncing...'}</span>
              </div>
              <button onClick={() => fetchData(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/10 text-slate-400 hover:text-white hover:bg-emerald-600 transition-all shadow-xl">
