export default SquadManagement;

import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, ShieldAlert, History, Search, ShieldCheck, Lock, Unlock, Clock, Calendar as CalendarIcon, AlertCircle, Printer, ChevronRight, FileText, Users, Edit3, Shield as ShieldIcon } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord, TrainingSession, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus | null; excuse?: string; time?: string; date?: string }>>({});
  const [showPrintView, setShowPrintView] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [adminEditOverride, setAdminEditOverride] = useState(false);

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;
  const restrictedCat = currentUser.restrictedCategory;
  const isViewer = currentUser.role === 'مشاهد';
  const isCatAdmin = currentUser.role === 'إداري فئة';
  const isManager = currentUser.role === 'مدير';

  const sessions = state.sessions
    .filter(s => {
      if (restrictedCat) return s.category === restrictedCat;
      return (globalFilter === 'الكل' || s.category === globalFilter);
    })
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);

  const categoryMembers = state.people
    .filter(p => (activeSession ? p.category === activeSession.category : true))
    .sort((a, b) => {
      const isAStaff = a.role !== 'لاعب';
      const isBStaff = b.role !== 'لاعب';
      if (isAStaff && !isBStaff) return -1;
      if (!isAStaff && isBStaff) return 1;
      return a.name.localeCompare(b.name);
    });

  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  const isTimeExpired = activeSession ? (() => {
    const sessionTime = new Date(`${activeSession.date}T${activeSession.time}`);
    const now = new Date();
    const diffInMinutes = (now.getTime() - sessionTime.getTime()) / (1000 * 60);
    return diffInMinutes > 30;
  })() : false;

  const isLocked = activeSession?.isLocked || activeSession?.isCompleted || (isTimeExpired && !isManager);
  const canEditNow = isManager ? (adminEditOverride || !isLocked) : !isLocked;

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    if ((isLocked && !canEditNow) || isViewer) return;
    const saved = savedRecords.find(r => r.personId === pid);
    const local = localRecords[pid];
    const currentStatus = local?.status !== undefined ? local.status : (saved?.status || null);

    if (isManager && currentStatus === status) {
      setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], status: null } }));
      return;
    }
    if (isCatAdmin && currentStatus !== null) {
      alert('نظام الحماية: لا يمكنك تعديل حالة الحضور بعد رصدها للمرة الأولى.');
      return;
    }
    const now = new Date();
    const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
    setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], status, time: timeStr } }));
  };

  const handleSetExcuse = (pid: string, excuse: string) => {
    if ((isLocked && !canEditNow) || isViewer) return;
    setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], excuse } }));
  };

  const saveAttendance = async () => {
    if (!selectedSessionId || isSaving) return;
    if (isLocked && !canEditNow) { alert("عذراً، السجل مقفل حالياً."); return; }
    setIsSaving(true);
    try {
      const newRecords: AttendanceRecord[] = [];
      const now = new Date();
      const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
      categoryMembers.forEach(p => {
        const local = localRecords[p.id];
        const saved = savedRecords.find(r => r.personId === p.id);
        let statusToSave: AttendanceStatus | null = null;
        let excuseToSave = "";
        if (local && local.status !== undefined) { statusToSave = local.status; excuseToSave = local.excuse || ""; }
        else if (saved) { statusToSave = saved.status; excuseToSave = saved.excuse || ""; }
        if (isTimeExpired && statusToSave === null && !isManager) { statusToSave = 'غائب'; }
        if (statusToSave !== null) {
          newRecords.push({
            id: saved?.id || generateUUID(), personId: p.id, sessionId: selectedSessionId, date: activeSession!.date,
            time: local?.time || saved?.time || timeStr, status: statusToSave as AttendanceStatus, excuse: excuseToSave, isLocked: true
          });
        }
      });
      if (newRecords.length > 0) {
        const { error: attError } = await supabase.from('attendance').upsert(newRecords.map(r => ({
          id: r.id, personId: r.personId, sessionId: r.sessionId, date: r.date, time: r.time, status: r.status, excuse: r.excuse
        })), { onConflict: 'id' });
        if (attError) throw attError;
      }
      const { error: sessError } = await supabase.from('sessions').update({ isCompleted: true }).eq('id', selectedSessionId);
      if (sessError) throw sessError;
      setState(prev => ({
        ...prev,
        attendance: [...prev.attendance.filter(a => a.sessionId !== selectedSessionId), ...newRecords],
        sessions: prev.sessions.map(s => s.id === selectedSessionId ? { ...s, isLocked: true, isCompleted: true } : s)
      }));
      addLog?.('تثبيت الحضور', `تم رصد حضور فئة ${activeSession?.category}`, 'success');
      setLocalRecords({});
      setAdminEditOverride(false);
      alert('تم تثبيت الرصد النهائي بنجاح.');
    } catch (err: any) { alert('خطأ في الاتصال بالسحابة: ' + err.message); } finally { setIsSaving(false); }
  };

  const toggleLock = async () => {
    if (!isManager || !activeSession) return;
    const newLockStatus = !(activeSession.isLocked || activeSession.isCompleted);
    setState(p => ({ ...p, sessions: p.sessions.map(s => s.id === selectedSessionId ? { ...s, isLocked: newLockStatus, isCompleted: newLockStatus } : s) }));
    await supabase.from('sessions').update({ isCompleted: newLockStatus }).eq('id', selectedSessionId);
    addLog?.('قفل السجل', `${newLockStatus ? 'تم قفل' : 'تم فتح'} سجل الحضور`, 'warning');
  };

  if (showPrintView && activeSession) {
    const reportRecords = categoryMembers.map(p => {
        const r = savedRecords.find(rec => rec.personId === p.id);
        return { member: p, record: r };
    });
    return (
      <div className="fixed inset-0 bg-white z-[500] overflow-y-auto p-12 text-right dir-rtl">
        <div className="max-w-[210mm] mx-auto border-4 border-slate-900 p-12 bg-white min-h-screen text-slate-900">
           <div className="no-print flex justify-between items-center mb-10 border-b pb-4">
              <button onClick={() => setShowPrintView(false)} className="flex items-center gap-2 font-black text-slate-500"><ChevronRight/> العودة</button>
              <button onClick={() => window.print()} className="bg-slate-900 text-white px-8 py-3 rounded-xl font-black flex items-center gap-2 shadow-xl"><Printer size={18}/> تصدير PDF</button>
           </div>
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-8 mb-10">
              <div className="flex items-center gap-4">
                 <ClubLogo size={80} />
                 <div>
                    <h2 className="text-3xl font-black">نادي الكرامة الرياضي</h2>
                    <p className="text-md font-bold text-emerald-600 uppercase mt-1 tracking-widest">كشف حضور وانضباط - نسخة رسمية</p>
                 </div>
              </div>
           </div>
           <div className="bg-slate-50 p-6 rounded-2xl mb-10 border-2 border-slate-900 flex justify-between items-center font-black">
              <div><p className="text-xs text-slate-500 uppercase">موضوع الجلسة</p><p className="text-xl mt-1">{activeSession.objective}</p></div>
              <div className="text-left"><p className="text-xs text-slate-500 uppercase tracking-widest">{activeSession.category}</p><p className="text-xl mt-1">{activeSession.date}</p></div>
           </div>
           <table className="w-full text-right border-collapse border-2 border-slate-900">
              <thead><tr className="bg-slate-100 border-b-2 border-slate-900 font-black text-xs uppercase"><th className="p-4 border-l border-slate-900 text-center w-12">ت</th><th className="p-4 border-l border-slate-900">الاسم الكامل</th><th className="p-4 border-l border-slate-900 text-center">الصفة</th><th className="p-4 border-l border-slate-900 text-center">الحالة</th><th className="p-4 border-l border-slate-900 text-center">الوقت</th><th className="p-4">الملاحظات</th></tr></thead>
              <tbody>
                 {reportRecords.map((item, idx) => (
                    <tr key={item.member.id} className={`border-b border-slate-300 text-sm font-black ${item.member.role !== 'لاعب' ? 'bg-slate-50' : ''}`}>
                       <td className="p-4 border-l border-slate-300 text-center">{idx + 1}</td>
                       <td className="p-4 border-l border-slate-300">{item.member.name}</td>
                       <td className="p-4 border-l border-slate-300 text-center text-xs">{item.member.role}</td>
                       <td className="p-4 border-l border-slate-300 text-center"><span className={item.record?.status === 'حاضر' ? 'text-emerald-600' : 'text-red-600'}>{item.record?.status || 'غائب'}</span></td>
                       <td className="p-4 border-l border-slate-300 text-center font-mono">{item.record?.time || '--'}</td>
                       <td className="p-4 text-xs italic">{item.record?.excuse || '--'}</td>
                    </tr>
                 ))}
