import React, { useState, useMemo } from 'react';
import { BarChart3, Users, Search, Filter, Trophy, Target, AlertTriangle, TrendingUp, ChevronLeft, Zap, PieChart as PieChartIcon } from 'lucide-react';
import { AppState, Person } from '../types';

interface StatsViewProps {
  state: AppState;
  onOpenReport: (player: Person) => void;
}

const StatsView: React.FC<StatsViewProps> = ({ state, onOpenReport }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const globalFilter = state.globalCategoryFilter;
  const restrictedCat = state.currentUser?.restrictedCategory;

  const playerStats = useMemo(() => {
    return state.people
      .filter(p => p.role === 'لاعب' && 
        (restrictedCat ? p.category === restrictedCat : (globalFilter === 'الكل' || p.category === globalFilter)) &&
        (p.name.includes(searchTerm))
      )
      .map(player => {
        const completedMatches = state.matches.filter(m => m.isCompleted);
        const playerMatches = completedMatches.filter(m => 
          m.lineup.starters.some(s => s.playerId === player.id) || 
          m.lineup.subs.some(s => s.playerId === player.id)
        );

        let goals = 0;
        let assists = 0;
        let yellows = 0;
        let reds = 0;

        playerMatches.forEach(m => {
          goals += m.events.filter(e => e.type === 'goal' && (e.player === player.name || e.player === player.id)).length;
          assists += m.events.filter(e => e.type === 'assist' && (e.player === player.name || e.player === player.id)).length;
          yellows += m.events.filter(e => e.type === 'yellow' && (e.player === player.name || e.player === player.id)).length;
          reds += m.events.filter(e => e.type === 'red' && (e.player === player.name || e.player === player.id)).length;
        });

        const playerSessions = state.sessions.filter(s => s.category === player.category);
        const sessionIds = playerSessions.map(ps => ps.id);
        const records = state.attendance.filter(a => a.personId === player.id && sessionIds.includes(a.sessionId));

        const present = records.filter(r => r.status === 'حاضر').length;
        const late = records.filter(r => r.status === 'متأخر').length;

        const attendanceRateRaw = playerSessions.length > 0 ? ((present + late * 0.7) / playerSessions.length) * 100 : 0;
        const attendanceRate = Math.min(100, Math.round(attendanceRateRaw));

        return {
          player,
          matchesPlayed: playerMatches.length,
          goals,
          assists,
          yellows,
          reds,
          attendanceRate
        };
      })
      .sort((a, b) => b.goals - a.goals);
  }, [state.people, state.matches, state.attendance, state.sessions, globalFilter, restrictedCat, searchTerm]);

  return (
    <div className="space-y-10 animate-in fade-in duration-700">
      {/* Header Stat Board */}
      <div className="bg-slate-900/50 p-12 rounded-[4rem] border border-white/5 text-white shadow-2xl flex flex-col md:flex-row justify-between items-center gap-10 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/10 blur-[100px] -mr-32 -mt-32"></div>
        <div className="flex items-center gap-8 relative z-10">
           <div className="bg-emerald-600 p-6 rounded-[2.5rem] shadow-2xl glow-emerald ring-4 ring-emerald-500/20">
             <BarChart3 size={48} />
           </div>
           <div>
             <h2 className="text-4xl font-black uppercase tracking-tighter">مركز تحليلات النخبة</h2>
             <p className="text-[11px] font-bold text-emerald-500 uppercase tracking-[0.4em] mt-2">Performance Intelligence System</p>
           </div>
        </div>
        <div className="grid grid-cols-2 gap-6 w-full md:w-auto relative z-10">
           <div className="bg-white/5 p-8 rounded-[2.5rem] border border-white/10 text-center shadow-xl backdrop-blur-md">
             <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">إجمالي المسجلين</p>
             <p className="text-4xl font-black text-white tracking-tighter">{playerStats.length}</p>
           </div>
           <div className="bg-white/5 p-8 rounded-[2.5rem] border border-white/10 text-center shadow-xl backdrop-blur-md">
             <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-2">إجمالي الأهداف</p>
             <p className="text-4xl font-black text-emerald-400 tracking-tighter">{playerStats.reduce((a, b) => a + b.goals, 0)}</p>
           </div>
        </div>
      </div>

      <div className="relative group">
        <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-emerald-500 transition-colors" size={24} />
        <input 
          type="text" 
          placeholder="ابحث عن لاعب لتحليل أرقامه الفنية..." 
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
          className="w-full bg-slate-950 border border-white/10 rounded-[2.5rem] py-6 pr-16 pl-8 font-black outline-none focus:border-emerald-500 focus:ring-8 focus:ring-emerald-500/5 transition-all text-xl text-white shadow-2xl"
        />
      </div>

      <div className="glass-panel rounded-[4rem] shadow-2xl overflow-hidden border-white/5">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[1200px]">
            <thead className="bg-slate-950/50 border-b border-white/5">
              <tr>
                <th className="px-10 py-8 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">اللاعب / القطاع</th>
                <th className="px-8 py-8 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">مباريات</th>
                <th className="px-8 py-8 text-[11px] font-black text-emerald-500 uppercase tracking-[0.2em] text-center">أهداف</th>
                <th className="px-8 py-8 text-[11px] font-black text-blue-400 uppercase tracking-[0.2em] text-center">تمريرات</th>
                <th className="px-8 py-8 text-[11px] font-black text-amber-500 uppercase tracking-[0.2em] text-center">إنذارات</th>
                <th className="px-8 py-8 text-[11px] font-black text-red-500 uppercase tracking-[0.2em] text-center">طرد</th>
                <th className="px-8 py-8 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">معدل الانضباط</th>
                <th className="px-10 py-8"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {playerStats.map(({ player, matchesPlayed, goals, assists, yellows, reds, attendanceRate }) => (
                <tr key={player.id} className="hover:bg-white/[0.03] transition-all group cursor-pointer">
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-6">
                      <div className="w-14 h-14 rounded-2xl bg-slate-900 text-white flex items-center justify-center font-black text-xl border border-white/10 shadow-2xl group-hover:bg-emerald-600 transition-colors">
                        {player.number || '??'}
                      </div>
                      <div>
                        <p className="font-black text-xl text-white group-hover:text-emerald-400 transition-colors tracking-tight">{player.name}</p>
                        <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mt-1">{player.category}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6 text-center font-black text-white text-lg">{matchesPlayed}</td>
                  <td className="px-8 py-6 text-center">
                    <span className={`px-4 py-2 rounded-xl font-black text-sm ${goals > 0 ? 'bg-emerald-500 text-slate-950 glow-emerald' : 'bg-white/5 text-slate-600 border border-white/5'}`}>
                      {goals}
                    </span>
                  </td>
                  <td className="px-8 py-6 text-center">
                    <span className={`px-4 py-2 rounded-xl font-black text-sm ${assists > 0 ? 'bg-blue-500 text-white glow-blue' : 'bg-white/5 text-slate-600 border border-white/5'}`}>
                      {assists}
                    </span>
                  </td>
                  <td className="px-8 py-6 text-center font-black text-amber-500">{yellows}</td>
                  <td className="px-8 py-6 text-center font-black text-red-500">{reds}</td>
                  <td className="px-8 py-6">
                    <div className="flex flex-col items-center gap-2">
                      <div className="w-32 bg-slate-950 h-2 rounded-full overflow-hidden border border-white/10 p-0.5">
                         <div 
                          className={`h-full rounded-full transition-all duration-1000 ${attendanceRate > 80 ? 'bg-emerald-500 glow-emerald' : attendanceRate > 50 ? 'bg-amber-500' : 'bg-red-500'}`} 
                          style={{ width: `${attendanceRate}%` }}
                         />
                      </div>
                      <span className="text-[10px] font-black text-slate-400 tracking-widest">%{attendanceRate}</span>
                    </div>
                  </td>
                  <td className="px-10 py-6 text-left">
                    <button 
                      onClick={() => onOpenReport(player)}
                      className="bg-white/5 border border-white/10 text-white px-6 py-3 rounded-2xl font-black text-[11px] hover:bg-emerald-600 transition-all uppercase tracking-widest flex items-center gap-3 group/btn"
                    >
                      تحليل كامل <ChevronLeft size={16} className="group-hover/btn:-translate-x-1 transition-transform" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {playerStats.length === 0 && (
          <div className="py-32 text-center bg-slate-950/20">
             <TrendingUp className="mx-auto text-slate-800 mb-6" size={80} />
             <p className="text-slate-600 font-black italic text-lg uppercase tracking-widest">لا يوجد بيانات إحصائية متاحة حالياً للقطاع المحدد</p>
          </div>
        )}
      </div>
    </div>
  );
};

