              type="text" 
              placeholder="ابحث عن بطل في فريقك..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
              className={`${fieldClass} pr-16 h-16 text-xl shadow-inner`} 
            />
          </div>

          <div className="flex flex-wrap items-center gap-4 w-full lg:w-auto">
            {!restrictedCat && (
              <select 
