              >
                <option value="الكل">جميع الفئات</option>
                {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            )}

            {!isViewer && (
              <button 
                onClick={() => { setEditingId(null); setIsModalOpen(true); }} 
                className="bg-[#FF6B00] text-white px-10 h-16 rounded-[1.5rem] font-black text-sm flex items-center gap-4 hover:bg-black transition-all shadow-2xl glow-orange"
              >
                <UserPlus size={24} /> تسجيل عضو
              </button>
            )}
          </div>
      </div>

      {/* Tabs */}
      <div className="flex p-1.5 bg-[#001F3F] border border-white/10 rounded-[2rem] w-fit mx-auto md:mx-0 shadow-inner">
          <button 
            onClick={() => setActiveSubTab('players')}
            className={`flex items-center gap-3 px-10 py-4 rounded-[1.5rem] font-black text-sm transition-all duration-300 ${activeSubTab === 'players' ? 'bg-[#FF6B00] text-white shadow-lg' : 'text-white/50 hover:text-white'}`}
          >
            قائمة اللاعبين
          </button>
          <button 
            onClick={() => setActiveSubTab('staff')}
            className={`flex items-center gap-3 px-10 py-4 rounded-[1.5rem] font-black text-sm transition-all duration-300 ${activeSubTab === 'staff' ? 'bg-[#FF6B00] text-white shadow-lg' : 'text-white/50 hover:text-white'}`}
          >
            الكوادر الفنية
          </button>
      </div>

      {/* Player Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {displayList.map(person => (
          <div key={person.id} className="glass-card p-8 rounded-[3rem] relative group overflow-hidden border-[#FF6B00]/20">
