                 {person.name.charAt(0).toUpperCase()}
               </div>
               <div className="flex flex-col items-end gap-2">
                  <span className={`text-[10px] font-black px-4 py-1.5 rounded-xl uppercase tracking-widest shadow-lg ${person.role === 'لاعب' ? 'bg-[#FF6B00] text-white' : 'bg-white text-[#001F3F]'}`}>
                    {person.role}
                  </span>
                  <span className="text-[10px] font-black text-white/50 uppercase">{person.category}</span>
               </div>
             </div>

             <div className="space-y-4 relative z-10">
               <h4 className="font-black text-2xl text-white tracking-tight group-hover:text-[#FF6B00] transition-colors">{person.name}</h4>
               <div className="flex flex-wrap gap-3 text-[11px] font-black text-white/60 uppercase">
                 <span className="flex items-center gap-2 bg-white/5 px-3 py-1.5 rounded-xl border border-white/5"><MapPin size={14} className="text-[#FF6B00]" /> {person.birthPlace}</span>
                 <span className="flex items-center gap-2 bg-white/5 px-3 py-1.5 rounded-xl border border-white/5"><Calendar size={14} className="text-[#FF6B00]" /> {calculateAge(person.birthDate)} سنة</span>
