                   </div>
                   <button onClick={() => onOpenReport?.(person)} className="text-[#FF6B00] text-[11px] font-black hover:underline uppercase tracking-widest">عرض التقرير</button>
                </div>
                {!isViewer && (
                  <div className="flex gap-2">
                    <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-3 bg-white/5 text-white/60 hover:bg-[#FF6B00] hover:text-white rounded-2xl transition-all shadow-xl"><Plus size={18}/></button>
                    <button onClick={async () => { if(confirm(`حذف ${person.name}؟`)) { await supabase.from('people').delete().eq('id', person.id); setState(p => ({...p, people: p.people.filter(x => x.id !== person.id)})); } }} className="p-3 bg-red-500/10 text-red-500 hover:bg-red-600 hover:text-white rounded-2xl transition-all"><Trash2 size={18}/></button>
                  </div>
                )}
             </div>
          </div>
        ))}
      </div>

      {/* Modal - Club Theme */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-[#001226]/95 backdrop-blur-2xl flex items-center justify-center z-[500] p-6 no-print overflow-y-auto">
           <div className="glass-panel rounded-[3rem] w-full max-w-4xl shadow-[0_0_100px_rgba(255,107,0,0.2)] border-[#FF6B00]/40 overflow-hidden animate-in zoom-in-95">
              <div className="p-8 bg-[#001F3F] border-b border-[#FF6B00]/30 flex justify-between items-center">
