interface PlayerReportProps {
  state: AppState;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [hoveredData, setHoveredData] = useState<any | null>(null);

  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';

  const matchStats = useMemo(() => {
    if (isStaff) return { played: 0, goals: 0, assists: 0, yellows: 0, reds: 0, minutes: 0, list: [] };
    let totalMinutes = 0;
    const statsList = state.matches.filter(m => m.isCompleted).sort((a, b) => a.date.localeCompare(b.date)).map(m => {
      const starter = m.lineup.starters.find(s => s.playerId === player.id);
      const sub = m.lineup.subs.find(s => s.playerId === player.id);
      let mins = starter ? parseInt(starter.minutesPlayed || '90') : (sub ? parseInt(sub.minutesPlayed || '0') : 0);
      totalMinutes += mins;
      const goals = m.events.filter(e => e.type === 'goal' && (e.player === player.name || e.player === player.id)).length;
      const assists = m.events.filter(e => e.type === 'assist' && (e.player === player.name || e.player === player.id)).length;
      return { id: m.id, opponent: m.opponent, date: m.date, mins, goals, assists, played: !!(starter || sub) };
    }).filter(s => s.played);
    return { played: statsList.length, goals: statsList.reduce((a, b) => a + b.goals, 0), assists: statsList.reduce((a, b) => a + b.assists, 0), minutes: totalMinutes, list: statsList };
  }, [state.matches, player, isStaff]);

  const attendanceData = useMemo(() => {
    const sessions = state.sessions.filter(s => s.category === player.category);
    const sessionIds = sessions.map(s => s.id);
    const records = state.attendance.filter(a => a.personId === player.id && sessionIds.includes(a.sessionId));
    const present = records.filter(r => r.status === 'حاضر').length;
    const late = records.filter(r => r.status === 'متأخر').length;
    const rate = sessions.length > 0 ? Math.min(100, Math.round(((present + late * 0.7) / sessions.length) * 100)) : 0;
    return { rate, present, late };
  }, [state.attendance, state.sessions, player]);

  const performanceTrend = useMemo(() => {
    if (isStaff) return [];
    return matchStats.list.map((m) => {
      const sessionsUntilMatch = state.sessions.filter(s => s.category === player.category && s.date <= m.date);
      const attRecords = state.attendance.filter(a => a.personId === player.id && sessionsUntilMatch.map(s => s.id).includes(a.sessionId));
      const rollingRate = sessionsUntilMatch.length > 0 ? Math.min(100, Math.round(((attRecords.filter(r => r.status === 'حاضر').length + attRecords.filter(r => r.status === 'متأخر').length * 0.7) / sessionsUntilMatch.length) * 100)) : 0;
      return { ...m, rollingRate };
    }).slice(-12);
  }, [matchStats.list, state.sessions, state.attendance, player, isStaff]);

  return (
    <div className="space-y-10 animate-in fade-in duration-500 pb-24 text-right" dir="rtl">
      <div className="flex flex-col md:flex-row justify-between items-center no-print gap-6">
        <button onClick={onBack} className="flex items-center gap-3 text-white/60 hover:text-[#FF6B00] font-black transition-all bg-white/5 px-6 py-3 rounded-2xl border border-white/10">
          <ChevronRight size={22} /> العودة للفريق
        </button>
        <div className="flex gap-4">
           <button onClick={() => window.print()} className="bg-white text-[#001F3F] px-8 py-4 rounded-2xl font-black text-sm flex items-center gap-3 shadow-2xl hover:bg-[#FF6B00] hover:text-white transition-all border-b-4 border-black/20">
             <Printer size={20} /> طباعة الملف الرسمي
           </button>
        </div>
      </div>

      {/* Header Profile */}
      <div className="glass-panel rounded-[4rem] shadow-2xl border-[#FF6B00]/40 overflow-hidden relative">
