    e.preventDefault();
    if (!username.trim() || !password) {
      setError('يرجى إدخال اسم المستخدم وكلمة المرور.');
      return;
    }
    setLoading(true);
    setError('');
    try {
      const user = await onLoginAttempt(username, password);
      if (user) {
        setLoginSuccess(true);
      } else {
        setError('خطأ في التحقق من البيانات.');
        setLoading(false);
      }
    } catch (err: any) {
      setError(err.message || 'فشل تسجيل الدخول.');
      setLoading(false);
    }
  };

  if (loginSuccess) {
    return (
      <div className="min-h-screen bg-[#001F3F] flex flex-col items-center justify-center p-6 text-white text-right" dir="rtl">
        <div className="bg-white p-12 rounded-[4rem] shadow-[0_0_100px_rgba(255,107,0,0.5)] border-8 border-[#FF6B00] animate-in zoom-in duration-700">
