        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#001226] flex flex-col items-center justify-center p-6 text-right" dir="rtl">
      <div className="max-w-md w-full glass-panel rounded-[4rem] shadow-[0_32px_64px_-12px_rgba(0,0,0,0.8)] overflow-hidden border-[#FF6B00]/40 relative z-10 animate-in fade-in duration-1000">
        <div className="bg-[#001F3F] p-12 flex flex-col items-center text-center border-b-8 border-[#FF6B00]">
          <div className="bg-white p-6 rounded-[3rem] shadow-2xl mb-8 ring-8 ring-white/10">
            <ClubLogo size={120} />
          </div>
          <h2 className="text-white font-black text-2xl tracking-tight leading-snug uppercase">نادي الكرامة الرياضي</h2>
          <p className="text-[#FF6B00] font-black mt-4 text-sm uppercase tracking-[0.3em]">مكتب كرة القدم المركزي</p>
