            {error && <div className="bg-red-500 text-white p-4 rounded-2xl text-[12px] font-black text-center border-2 border-white shadow-xl animate-bounce">{error}</div>}

            <div className="space-y-3">
              <label className="text-[11px] font-black text-[#FF6B00] mr-2 uppercase flex items-center gap-2">اسم المستخدم</label>
              <input 
                type="text" 
                value={username} 
                onChange={e => setUsername(e.target.value)}
                disabled={loading}
                className="w-full bg-[#001226] border-2 border-white/10 rounded-3xl py-5 px-8 outline-none focus:border-[#FF6B00] font-black text-white transition-all text-xl" 
              />
            </div>

            <div className="space-y-3">
              <label className="text-[11px] font-black text-[#FF6B00] mr-2 uppercase flex items-center gap-2">كلمة المرور</label>
              <div className="relative">
                <input 
                  type={showPass ? "text" : "password"} 
