import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, ShieldAlert, History, Search, ShieldCheck, Lock, Unlock, Clock, Calendar as CalendarIcon, AlertCircle, Printer, ChevronRight, FileText, Users, Edit3, Shield as ShieldIcon } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord, TrainingSession, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus | null; excuse?: string; time?: string; date?: string }>>({});
  const [showPrintView, setShowPrintView] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [adminEditOverride, setAdminEditOverride] = useState(false);

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;
  const restrictedCat = currentUser.restrictedCategory;
  const isViewer = currentUser.role === 'مشاهد';
  const isManager = currentUser.role === 'مدير';

  const sessions = state.sessions
    .filter(s => {
      if (restrictedCat) return s.category === restrictedCat;
      return (globalFilter === 'الكل' || s.category === globalFilter);
    })
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);
  const categoryMembers = state.people
    .filter(p => (activeSession ? p.category === activeSession.category : true))
    .sort((a, b) => (a.role !== 'لاعب' ? -1 : 1));

  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  const isLocked = activeSession?.isCompleted;
  const canEditNow = isManager ? (adminEditOverride || !isLocked) : !isLocked;

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    if ((isLocked && !canEditNow) || isViewer) return;
    const now = new Date();
    const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
    setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], status, time: timeStr } }));
  };

  const saveAttendance = async () => {
    if (!selectedSessionId || isSaving) return;
    setIsSaving(true);
    try {
      const newRecords: AttendanceRecord[] = [];
      const timeStr = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
      categoryMembers.forEach(p => {
        const local = localRecords[p.id];
        const saved = savedRecords.find(r => r.personId === p.id);
        const statusToSave = local?.status || saved?.status || null;
        if (statusToSave) {
          newRecords.push({
            id: saved?.id || generateUUID(), personId: p.id, sessionId: selectedSessionId, date: activeSession!.date,
            time: local?.time || saved?.time || timeStr, status: statusToSave as AttendanceStatus, excuse: local?.excuse || saved?.excuse || "", isLocked: true
          });
        }
      });

      const { error: attError } = await supabase.from('attendance').upsert(newRecords.map(r => ({ 
        id: r.id, 
        personId: r.personId, 
        sessionId: r.sessionId, 
        date: r.date, 
        time: r.time, 
        status: r.status, 
        excuse: r.excuse 
      })));

      if (attError) throw attError;

      const { error: sessError } = await supabase.from('sessions').update({ 
        isCompleted: true 
      }).eq('id', selectedSessionId);

      if (sessError) throw sessError;

      setState(prev => ({
        ...prev,
        attendance: [...prev.attendance.filter(a => a.sessionId !== selectedSessionId), ...newRecords],
        sessions: prev.sessions.map(s => s.id === selectedSessionId ? { ...s, isCompleted: true } : s)
      }));

      setLocalRecords({});
      addLog?.('تثبيت الحضور', `تم اعتماد كشف حضور فئة ${activeSession?.category}`, 'success');
      alert('تم الرصد النهائي بنجاح.');
    } catch (err: any) { 
      console.error("Attendance Save Fail:", err);
      alert('خطأ في الحفظ: ' + err.message); 
    } finally { 
      setIsSaving(false); 
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="glass-panel p-10 rounded-[3.5rem] shadow-2xl relative overflow-hidden flex flex-col lg:flex-row gap-8 items-end no-print border-[#FF6B00]/40">
        <div className="absolute top-0 right-0 w-2 h-full bg-[#FF6B00]"></div>
        <div className="flex-1 space-y-3 w-full">
           <label className="text-[11px] font-black text-white/60 mr-2 uppercase tracking-widest flex items-center gap-3">
             <div className="w-2 h-2 bg-[#FF6B00] rounded-full animate-pulse"></div> اختيار الحصة للرصد الفوري
           </label>
           <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); }}
            className="w-full bg-[#001226] border-2 border-white/10 rounded-3xl p-6 font-black text-2xl text-white outline-none focus:border-[#FF6B00] transition-all shadow-2xl appearance-none cursor-pointer">
             <option value="">-- اختر التمرين من الأجندة --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} | {s.objective} ({s.category})</option>)}
           </select>
        </div>
        <div className="flex flex-wrap gap-4 w-full md:w-auto">
          {isManager && selectedSessionId && (
            <button onClick={() => setAdminEditOverride(!adminEditOverride)} className={`px-6 py-5 rounded-2xl font-black text-xs border transition-all ${adminEditOverride ? 'bg-[#FF6B00] text-white border-white' : 'bg-white/5 text-white/40 border-white/10'}`}>
              {adminEditOverride ? 'إيقاف تعديل المدير' : 'تفعيل تعديل المدير'}
            </button>
          )}
          {!isViewer && (
            <button onClick={saveAttendance} disabled={!selectedSessionId || (isLocked && !canEditNow) || isSaving} className="bg-[#FF6B00] text-white px-10 py-5 rounded-3xl font-black text-lg shadow-2xl hover:bg-black transition-all disabled:opacity-20 glow-orange flex items-center gap-4 uppercase tracking-widest">
              {isSaving ? <History className="animate-spin" size={24}/> : <Save size={24} />}
              تثبيت الرصد النهائي
            </button>
          )}
        </div>
      </div>

      {isLocked && !adminEditOverride && (
        <div className="bg-red-500/10 p-6 rounded-[2.5rem] border-2 border-red-500/30 flex items-center gap-4 shadow-lg animate-in slide-in-from-top-4">
           <Lock className="text-red-500" size={24}/>
           <p className="text-sm font-black text-red-200">هذا السجل مقفل إدارياً بعد الاعتماد النهائي. التعديل مسموح للمدير فقط.</p>
        </div>
      )}

      {activeSession && (
        <div className={`glass-panel rounded-[3.5rem] shadow-2xl overflow-hidden relative border-white/10 ${isLocked && !canEditNow ? 'opacity-50 pointer-events-none' : ''}`}>
          <div className="p-10 border-b border-white/5 bg-white/5 flex justify-between items-center">
             <div className="flex items-center gap-6">
               <div className="w-20 h-20 bg-white border-4 border-[#FF6B00] rounded-[2rem] flex items-center justify-center font-black text-4xl text-[#001F3F] shadow-2xl">
                  {activeSession.category.charAt(0)}
               </div>
               <div>
                 <h3 className="text-3xl font-black text-white leading-none uppercase">{activeSession.objective}</h3>
                 <p className="text-[10px] font-bold text-[#FF6B00] uppercase tracking-[0.4em] mt-3">{activeSession.category} • {activeSession.date}</p>
               </div>
             </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-right min-w-[1000px]">
              <thead className="bg-[#001226] text-white/50 border-b border-white/10">
                <tr>
                  <th className="px-10 py-8 text-[11px] font-black uppercase tracking-widest">الاسم والصفة</th>
                  <th className="px-10 py-8 text-[11px] font-black uppercase tracking-widest text-center">حالة الرصد</th>
                  <th className="px-10 py-8 text-[11px] font-black uppercase tracking-widest text-center">الوقت</th>
                  <th className="px-10 py-8 text-[11px] font-black uppercase tracking-widest">ملاحظات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {categoryMembers.map(p => {
                  const saved = savedRecords.find(r => r.personId === p.id);
                  const local = localRecords[p.id];
                  const currentStatus = local?.status || saved?.status || null;
                  const currentTime = local?.time || saved?.time || "--:--";

                  return (
                    <tr key={p.id} className="transition-all hover:bg-white/[0.03]">
                      <td className="px-10 py-6">
                        <div className="flex items-center gap-5">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-sm border-2 transition-all ${currentStatus ? 'bg-[#FF6B00] text-white border-white' : 'bg-white/5 text-white/20 border-white/10'}`}>
                            {p.number || p.role.charAt(0)}
                          </div>
                          <div>
                             <span className="font-black text-xl text-white block tracking-tight">{p.name}</span>
                             <span className="text-[10px] font-black uppercase text-[#FF6B00]">{p.role}</span>
                          </div>
                        </div>
                      </td>
                      <td className="px-10 py-6 text-center">
                        <div className="flex justify-center gap-2">
                          {['حاضر', 'متأخر', 'غائب', 'غياب بعذر'].map(st => (
                            <button key={st} onClick={() => handleSetStatus(p.id, st as AttendanceStatus)}
                              className={`px-4 py-2.5 rounded-xl text-[9px] font-black border-2 transition-all ${currentStatus === st ? 'bg-white text-[#001F3F] border-[#FF6B00] scale-110 shadow-xl' : 'bg-white/5 text-white/40 border-white/5 hover:border-[#FF6B00]'}`}>
                              {st}
                            </button>
                          ))}
                        </div>
                      </td>
                      <td className="px-10 py-6 text-center">
                        <span className="font-black text-sm text-[#FF6B00] bg-white/5 px-4 py-2 rounded-xl border border-[#FF6B00]/30">{currentTime}</span>
                      </td>
                      <td className="px-10 py-6">
                        <input type="text" value={local?.excuse || saved?.excuse || ""} onChange={e => setLocalRecords(prev => ({ ...prev, [p.id]: { ...prev[p.id], excuse: e.target.value } }))}
                          className="bg-[#001226] border-2 border-white/10 rounded-xl px-5 py-3 text-[11px] font-bold w-full outline-none focus:border-[#FF6B00] text-white placeholder:text-white/10" 
                          placeholder="تبرير إداري..."
                        />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

