           </div>
        </div>

        {!restrictedCat && (
          <div className="flex items-center gap-4 bg-white/5 p-2 rounded-2xl border border-white/10">
            <span className="text-[10px] font-black text-white/60 mr-2 uppercase">تصفية العرض:</span>
            <select 
              value={globalFilter}
              onChange={e => setState(p => ({ ...p, globalCategoryFilter: e.target.value as any }))}
              className="bg-[#FF6B00] border-2 border-white rounded-xl py-2 px-6 font-black text-[12px] text-white outline-none cursor-pointer hover:bg-black transition-all"
            >
              <option value="الكل">جميع الفئات</option>
              {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
        )}
      </div>

      {/* 2. Key Performance Indicators (Stats Cards) */}
