        {stats.map((s, i) => (
          <div key={i} className="group relative" style={{ color: s.textColor }}>
             <div className="absolute inset-0 translate-x-2 translate-y-2 bg-[#001F3F] rounded-[2.5rem] -z-10 border border-white/10"></div>
