                <div className="p-5 rounded-3xl mb-4 border-2 border-current shadow-lg">
                   <s.icon size={32} />
                </div>
                <h3 className="text-[11px] font-black uppercase tracking-widest opacity-80">{s.label}</h3>
                <p className="text-5xl font-black mt-2 tracking-tight">{s.value}</p>
             </div>
