          <div className="solid-panel p-10">
             <div className="flex justify-between items-center mb-8 pb-4 border-b-4 border-slate-100">
               <h3 className="text-2xl font-black text-[#001F3F] flex items-center gap-4">
                 <Calendar size={28} className="text-orange-600" /> الحصص التدريبية والأنشطة
               </h3>
               <span className="bg-blue-100 text-blue-700 text-[10px] font-black px-4 py-1.5 rounded-full uppercase border-2 border-blue-700">أجندة</span>
