                    <div className="flex items-center gap-4 text-[10px] font-black text-slate-600 mt-2">
                       <span className="flex items-center gap-1"><MapPin size={12}/> {s.pitch || 'ملعب الكرامة'}</span>
                       <span className="flex items-center gap-1"><Clock size={12}/> {s.time}</span>
                    </div>
                 </button>
               )) : (
                 <div className="col-span-full py-12 text-center opacity-30 italic font-black text-sm">لا توجد تمارين قادمة في السجل</div>
               )}
             </div>
          </div>
        </div>

      </div>
    </div>
  );
};

