import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, ShieldAlert, History, Search, ShieldCheck, Lock, Unlock, Clock, Calendar as CalendarIcon, AlertCircle, Printer, ChevronRight, FileText, Users, Edit3, Shield as ShieldIcon } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord, TrainingSession, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus | null; excuse?: string; time?: string; date?: string }>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [adminEditOverride, setAdminEditOverride] = useState(false);

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;
  const restrictedCat = currentUser.restrictedCategory;
  const isViewer = currentUser.role === 'مشاهد';
  const isManager = currentUser.role === 'مدير';

  const sessions = state.sessions
    .filter(s => {
      if (restrictedCat) return s.category === restrictedCat;
      return (globalFilter === 'الكل' || s.category === globalFilter);
    })
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);
  const categoryMembers = state.people
    .filter(p => (activeSession ? p.category === activeSession.category : true))
    .sort((a, b) => (a.role !== 'لاعب' ? -1 : 1));

  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  const isLocked = activeSession?.isCompleted;
  const canEditNow = isManager ? (adminEditOverride || !isLocked) : !isLocked;

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    if ((isLocked && !canEditNow) || isViewer) return;
    const now = new Date();
    const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
    setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], status, time: timeStr } }));
  };

  const saveAttendance = async () => {
    if (!selectedSessionId || isSaving) return;
    setIsSaving(true);
    try {
      const newRecords: AttendanceRecord[] = [];
      const timeStr = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
      categoryMembers.forEach(p => {
        const local = localRecords[p.id];
        const saved = savedRecords.find(r => r.personId === p.id);
        const statusToSave = local?.status || saved?.status || null;
        if (statusToSave) {
          newRecords.push({
            id: saved?.id || generateUUID(), personId: p.id, sessionId: selectedSessionId, date: activeSession!.date,
            time: local?.time || saved?.time || timeStr, status: statusToSave as AttendanceStatus, excuse: local?.excuse || saved?.excuse || "", isLocked: true
          });
        }
      });

      const { error: attError } = await supabase.from('attendance').upsert(newRecords.map(r => ({ 
        id: r.id, personId: r.personId, sessionId: r.sessionId, date: r.date, time: r.time, status: r.status, excuse: r.excuse 
      })));

      if (attError) throw attError;

      await supabase.from('sessions').update({ isCompleted: true }).eq('id', selectedSessionId);

      setState(prev => ({
        ...prev,
        attendance: [...prev.attendance.filter(a => a.sessionId !== selectedSessionId), ...newRecords],
        sessions: prev.sessions.map(s => s.id === selectedSessionId ? { ...s, isCompleted: true } : s)
      }));

      setLocalRecords({});
      addLog?.('تثبيت الحضور', `اعتماد كشف حضور: ${activeSession?.category}`, 'success');
      alert('تم الاعتماد النهائي.');
    } catch (err: any) { 
      alert('خطأ: ' + err.message); 
    } finally { 
      setIsSaving(false); 
    }
  };

  return (
    <div className="space-y-4 md:space-y-8 animate-in fade-in duration-500 px-2 md:px-0 pb-20">
      {/* Session Selection - Compact for Mobile */}
      <div className="solid-panel p-4 md:p-10 relative overflow-hidden flex flex-col gap-4 md:gap-8 no-print !border-[#FF6B00] !shadow-none">
        <div className="flex-1 space-y-2">
           <label className="text-[10px] font-black text-[#001F3F] mr-2 uppercase tracking-widest flex items-center gap-2">
             <div className="w-1.5 h-1.5 bg-[#FF6B00] rounded-full"></div> رصد حضور الحصة
           </label>
           <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); }}
            className="w-full bg-slate-50 border-2 md:border-4 border-[#001F3F] rounded-2xl p-4 md:p-6 font-black text-sm md:text-2xl text-[#001F3F] outline-none">
             <option value="">-- اختر التمرين من القائمة --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} | {s.objective} ({s.category})</option>)}
           </select>
        </div>
        <div className="flex flex-col md:flex-row gap-3 w-full">
          {!isViewer && (
            <button onClick={saveAttendance} disabled={!selectedSessionId || (isLocked && !canEditNow) || isSaving} className="w-full md:w-auto bg-[#001F3F] text-white px-8 py-4 rounded-xl font-black text-sm md:text-lg flex items-center justify-center gap-3 border-b-4 border-black">
              {isSaving ? <History className="animate-spin" size={20}/> : <Save size={20} />}
              اعتماد الرصد النهائي
            </button>
          )}
          {isManager && selectedSessionId && (
            <button onClick={() => setAdminEditOverride(!adminEditOverride)} className={`w-full md:w-auto px-4 py-3 rounded-xl font-black text-[10px] border-2 transition-all ${adminEditOverride ? 'bg-[#FF6B00] text-white border-black' : 'bg-slate-100 text-[#001F3F] border-[#001F3F]'}`}>
              {adminEditOverride ? 'إلغاء وضع التعديل' : 'تعديل السجل المقفل'}
            </button>
          )}
        </div>
      </div>

      {activeSession && (
        <div className={`solid-panel overflow-hidden relative !shadow-none ${isLocked && !canEditNow ? 'opacity-60 grayscale' : ''}`}>
          <div className="p-4 md:p-8 border-b-2 border-slate-100 bg-slate-50 flex flex-col md:flex-row justify-between items-center gap-3">
             <div className="flex items-center gap-4 w-full md:w-auto">
               <div className="w-12 h-12 md:w-16 md:h-16 bg-[#001F3F] border-2 border-[#FF6B00] rounded-xl flex items-center justify-center font-black text-xl md:text-3xl text-white uppercase">
                  {activeSession.category.charAt(0)}
               </div>
               <div>
                 <h3 className="text-sm md:text-xl font-black text-[#001F3F] leading-tight">{activeSession.objective}</h3>
                 <p className="text-[8px] md:text-[10px] font-bold text-[#FF6B00] uppercase tracking-widest mt-1">{activeSession.category} • {activeSession.date}</p>
               </div>
             </div>
             {isLocked && <span className="bg-red-600 text-white px-4 py-1.5 rounded-full text-[9px] font-black flex items-center gap-2 uppercase"><Lock size={12}/> سجل مقفل</span>}
          </div>

          <div className="overflow-x-auto -mx-2 md:mx-0">
            <table className="w-full text-right min-w-[750px] md:min-w-[900px]">
              <thead className="bg-[#001F3F] text-white border-b-2 border-slate-900">
                <tr>
                  <th className="px-4 md:px-8 py-4 text-[9px] md:text-[10px] font-black uppercase tracking-widest">الاسم</th>
                  <th className="px-4 md:px-8 py-4 text-[9px] md:text-[10px] font-black uppercase tracking-widest text-center">حالة الحضور</th>
                  <th className="px-4 md:px-8 py-4 text-[9px] md:text-[10px] font-black uppercase tracking-widest">توضيح / عذر</th>
                </tr>
              </thead>
              <tbody className="divide-y-2 divide-slate-100">
                {categoryMembers.map(p => {
                  const saved = savedRecords.find(r => r.personId === p.id);
                  const local = localRecords[p.id];
                  const currentStatus = local?.status || saved?.status || null;

                  return (
                    <tr key={p.id} className="transition-all hover:bg-slate-50">
                      <td className="px-4 md:px-8 py-4">
                        <div className="flex items-center gap-3">
                          <div className={`w-8 h-8 md:w-10 md:h-10 rounded-lg flex items-center justify-center font-black text-[10px] border-2 ${currentStatus ? 'bg-[#FF6B00] text-white border-[#001F3F]' : 'bg-slate-100 text-slate-300 border-slate-200'}`}>
                            {p.number || '0'}
                          </div>
                          <span className="font-black text-xs md:text-sm text-[#001F3F]">{p.name}</span>
                        </div>
                      </td>
                      <td className="px-4 md:px-8 py-4 text-center">
                        <div className="flex justify-center gap-1 md:gap-2">
                          {['حاضر', 'متأخر', 'غائب', 'غياب بعذر'].map(st => (
                            <button key={st} onClick={() => handleSetStatus(p.id, st as AttendanceStatus)}
                              className={`px-2.5 md:px-4 py-1.5 md:py-2.5 rounded-lg text-[8px] md:text-[9px] font-black border-2 transition-all active:scale-90 ${currentStatus === st ? 'bg-[#FF6B00] text-white border-[#001F3F] shadow-md' : 'bg-slate-100 text-slate-400 border-slate-200'}`}>
                              {st}
                            </button>
                          ))}
                        </div>
                      </td>
                      <td className="px-4 md:px-8 py-4">
                        <input type="text" value={local?.excuse || saved?.excuse || ""} onChange={e => setLocalRecords(prev => ({ ...prev, [p.id]: { ...prev[p.id], excuse: e.target.value } }))}
                          className="bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-[10px] font-bold w-full outline-none focus:border-[#FF6B00]" 
                          placeholder="سجل عذراً..."
                        />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTracker;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
export type UserRole = 'مدير' | 'إداري فئة' | 'مشاهد';
export type MatchType = 'دوري' | 'كأس' | 'ودية' | 'بطولة ودية' | 'مباراة دولية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface PlayerEvaluation {
  id: string;
  playerId: string;
  date: string;
  physical: number; // 1-10
  tactical: number;
  technical: number;
  mental: number;
  speed: number;
  coachNote?: string;
}

export interface Person {
  id: string;
  name: string;
  fatherName: string;
  motherName: string;
  birthDate: string;
  birthPlace: string;
  khana: string;
  nationalId: string;
  federalNumber: string;
  internationalId: string;
  address: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  contractStart?: string;
  contractEnd?: string;
  contractValue?: string;
  medicalHistory?: string;
  injuries?: string;
  penalties?: string;
  notes?: string;
  coachingCertificate?: string;
  academicDegree?: string;
  evaluations?: PlayerEvaluation[];
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  excuse?: string;
  fine?: string;
  isLocked?: boolean;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  pitch?: string;
  objective: string;
  isCompleted?: boolean;
  isLocked?: boolean;
}

export interface MatchEvent {
  id: string;
  type: 'goal' | 'assist' | 'yellow' | 'red' | 'injury' | 'substitution';
  player: string; 
  minute: string;
  note?: string;
}

export interface Match {
  id: string;
  category: Category;
  matchType: MatchType;
  opponent: string;
  pitch?: string;
  date: string;
  time: string;
  advancePayment: string;
  isCompleted: boolean;
  ourScore: string;
  opponentScore: string;
  stoppageTime?: string; 
  stoppageTime1?: string; 
  stoppageTime2?: string; 
  events: MatchEvent[];
  lineup: {
    starters: { playerId: string; name: string; number: string; minutesPlayed?: string }[];
    subs: { 
      playerId: string; 
      name: string; 
      number: string; 
      minutesPlayed?: string;
      substitutionMinute?: string;
      replacedPlayerId?: string;
    }[];
    reserves?: { playerId: string; name: string; number: string }[];
    staff: { role: string; name: string }[];
    captain: string;
  };
  notes?: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  categories: Category[];
  currentUser: AppUser | null;
  notifications: AppNotification[];
  globalCategoryFilter: Category | 'الكل';
}

import React, { useMemo, useState } from 'react';
import { 
  ChevronRight, Printer, Target, AlertTriangle, Clock, Calendar, 
  TrendingUp, Users, Shield, MapPin, Activity, Globe, Trophy, 
  CheckCircle, Award, GraduationCap, Home, StickyNote, CreditCard, BarChart3, PieChart,
  Hash, ClipboardList, User, Timer, FileText, Briefcase, Sparkles, Loader2, X, BrainCircuit,
  HeartPulse, ShieldAlert, Gavel, Smartphone, CalendarDays, Wallet, Zap, ShieldCheck,
  Medal, Swords, Star
} from 'lucide-react';
import { AppState, Person, Match, AttendanceRecord } from '../types';
import ClubLogo from './ClubLogo';
import { GoogleGenAI } from "@google/genai";

interface PlayerReportProps {
  state: AppState;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';

  // فصل إحصائيات المباريات: رسمية vs ودية
  const matchStats = useMemo(() => {
    if (isStaff) return { officialMins: 0, friendlyMins: 0, goals: 0, assists: 0, list: [] };

    let officialMins = 0;
    let friendlyMins = 0;

    const statsList = state.matches
      .filter(m => m.isCompleted)
      .sort((a, b) => a.date.localeCompare(b.date))
      .map(m => {
        const starter = m.lineup.starters.find(s => s.playerId === player.id);
        const sub = m.lineup.subs.find(s => s.playerId === player.id);

        let mins = 0;
        if (starter) {
          mins = parseInt(starter.minutesPlayed || '90') || 0;
        } else if (sub) {
          mins = parseInt(sub.minutesPlayed || '0') || 0;
        }

        const isOfficial = ['دوري', 'كأس', 'مباراة دولية'].includes(m.matchType);
        if (isOfficial) officialMins += mins;
        else friendlyMins += mins;

        const goals = m.events.filter(e => e.type === 'goal' && (e.player === player.name || e.player === player.id)).length;
        const assists = m.events.filter(e => e.type === 'assist' && (e.player === player.name || e.player === player.id)).length;

        return { 
          opponent: m.opponent, 
          date: m.date, 
          type: m.matchType,
          isOfficial,
          mins, 
          goals, 
          assists,
          played: !!(starter || sub) 
        };
      })
      .filter(s => s.played);

    return {
      officialMins,
      friendlyMins,
      goals: statsList.reduce((a, b) => a + b.goals, 0),
      assists: statsList.reduce((a, b) => a + b.assists, 0),
      list: statsList
    };
  }, [state.matches, player, isStaff]);

  // تصحيح معادلة الحضور لضمان عدم تجاوز 100% عبر الفلترة الفريدة
  const attendanceData = useMemo(() => {
    const sessions = state.sessions.filter(s => s.category === player.category);
    const sessionIds = sessions.map(s => s.id);

    // استخدام Map لضمان عدم احتساب سجلين لنفس الحصة للاعب واحد
    const allRecords = state.attendance.filter(a => a.personId === player.id && sessionIds.includes(a.sessionId));
    const uniqueRecords = Array.from(new Map(allRecords.map(r => [r.sessionId, r])).values());

    const present = uniqueRecords.filter(r => r.status === 'حاضر').length;
    const late = uniqueRecords.filter(r => r.status === 'متأخر').length;
    const excused = uniqueRecords.filter(r => r.status === 'غياب بعذر').length;

    const totalSessions = sessions.length || 1;
    const weightedAttendance = present + excused + (late * 0.7);
    const rate = Math.min(100, Math.round((weightedAttendance / totalSessions) * 100));

    return { rate, total: sessions.length, present, late, excused };
  }, [state.attendance, state.sessions, player]);

  // ميزة الرادار التكتيكي الجديدة (محاكاة لبيانات تجريبية أو من التقييمات)
  const radarData = useMemo(() => {
    // القيم افتراضية حتى يتم إدخال التقييمات رسمياً
    return [
      { label: 'بدني', val: 8.5 },
      { label: 'تكتيك', val: 7.2 },
      { label: 'تقني', val: 9.0 },
      { label: 'ذهني', val: 6.5 },
      { label: 'سرعة', val: 8.8 }
    ];
  }, []);

  const handleGenerateAiAnalysis = async () => {
    setLoadingAi(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `أنت محلل تقني لنادي الكرامة السوري. حلل بيانات اللاعب ${player.name}: دقائق رسمية(${matchStats.officialMins}), ودية(${matchStats.friendlyMins}), أهداف(${matchStats.goals}), التزام(${attendanceData.rate}%). قدم تقريراً مختصراً واحترافياً.`;
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });
      setAiAnalysis(response.text || "فشل توليد التحليل.");
    } catch (error: any) {
      setAiAnalysis("خطأ في الاتصال.");
    } finally {
      setLoadingAi(false);
    }
  };

  return (
    <div className="space-y-4 md:space-y-8 animate-in fade-in duration-500 pb-24 px-2 md:px-0 text-right" dir="rtl">
      {/* Back & Print */}
      <div className="flex flex-row justify-between items-center no-print gap-2">
        <button onClick={onBack} className="flex items-center gap-2 text-[#001F3F] font-black bg-white border-2 border-[#001F3F] px-4 py-2.5 rounded-xl text-xs md:text-sm shadow-md active:scale-95 transition-all">
          <ChevronRight size={18} /> رجوع
        </button>
        <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-4 py-2.5 rounded-xl font-black text-xs md:text-sm flex items-center gap-2 shadow-lg border-b-4 border-black active:border-b-0 active:translate-y-1 transition-all">
          <Printer size={18} /> طباعة الملف
        </button>
      </div>

      {/* Profile Header - Mobile Optimized */}
      <div className="solid-panel overflow-hidden relative !shadow-none md:!shadow-[8px_8px_0px_0px_#001F3F]">
        <div className="bg-[#001F3F] h-24 md:h-32 relative">
          <div className="absolute -bottom-10 right-6 md:right-12 flex items-end gap-4 md:gap-6">
            <div className="w-24 h-24 md:w-40 md:h-40 bg-white rounded-2xl md:rounded-[2.5rem] border-4 md:border-8 border-white flex items-center justify-center font-black text-4xl md:text-6xl text-[#001F3F] uppercase shadow-lg">
               {player.name.charAt(0)}
            </div>
            <div className="mb-2">
              <h1 className="text-xl md:text-3xl font-black text-white drop-shadow-md">{player.name}</h1>
              <div className="flex gap-2 mt-1">
                 <span className="bg-orange-600 text-white text-[8px] md:text-[10px] font-black px-2 md:px-4 py-1 rounded-lg border border-white uppercase">{player.role}</span>
                 <span className="bg-blue-600 text-white text-[8px] md:text-[10px] font-black px-2 md:px-4 py-1 rounded-lg border border-white uppercase">{player.category}</span>
              </div>
            </div>
          </div>
        </div>
        <div className="h-12 md:h-20"></div>

        <div className="px-4 md:px-12 pb-8 grid grid-cols-2 md:grid-cols-5 gap-3 md:gap-6">
           <div className="bg-slate-50 p-3 md:p-4 rounded-xl border-2 border-slate-100 flex flex-col items-center">
             <Medal className="text-[#001F3F] mb-1" size={18}/>
             <span className="text-[8px] md:text-[10px] font-black text-slate-400 uppercase">دقائق رسمية</span>
             <p className="text-lg md:text-2xl font-black text-[#001F3F]">{matchStats.officialMins}</p>
           </div>
           <div className="bg-slate-50 p-3 md:p-4 rounded-xl border-2 border-slate-100 flex flex-col items-center">
             <Swords className="text-orange-600 mb-1" size={18}/>
             <span className="text-[8px] md:text-[10px] font-black text-slate-400 uppercase">دقائق ودية</span>
             <p className="text-lg md:text-2xl font-black text-[#001F3F]">{matchStats.friendlyMins}</p>
           </div>
           <div className="bg-slate-50 p-3 md:p-4 rounded-xl border-2 border-slate-100 flex flex-col items-center">
             <Trophy className="text-blue-600 mb-1" size={18}/>
             <span className="text-[8px] md:text-[10px] font-black text-slate-400 uppercase">الأهداف</span>
             <p className="text-lg md:text-2xl font-black text-[#001F3F]">{matchStats.goals}</p>
           </div>
           <div className="bg-slate-50 p-3 md:p-4 rounded-xl border-2 border-slate-100 flex flex-col items-center">
             <Zap className="text-blue-400 mb-1" size={18}/>
             <span className="text-[8px] md:text-[10px] font-black text-slate-400 uppercase">أسيست</span>
             <p className="text-lg md:text-2xl font-black text-[#001F3F]">{matchStats.assists}</p>
           </div>
           <div className="bg-slate-50 p-3 md:p-4 rounded-xl border-2 border-slate-100 flex flex-col items-center col-span-2 md:col-span-1">
             <TrendingUp className="text-emerald-500 mb-1" size={18}/>
             <span className="text-[8px] md:text-[10px] font-black text-slate-400 uppercase">نسبة الالتزام</span>
             <p className="text-lg md:text-2xl font-black text-emerald-600">%{attendanceData.rate}</p>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 md:gap-8">
        <div className="lg:col-span-2 space-y-6 md:space-y-8">

          {/* Radar Chart Section - New Visual Feature */}
          <div className="bg-white p-6 md:p-10 rounded-3xl border-4 border-[#001F3F] shadow-sm flex flex-col md:flex-row items-center gap-10">
             <div className="w-full md:w-1/2">
                <h3 className="text-md md:text-lg font-black flex items-center gap-2 mb-6">
                   <Target className="text-orange-600" size={20}/> البصمة الفنية (Radar Chart)
                </h3>
                <div className="relative w-full aspect-square max-w-[250px] mx-auto">
                   <svg viewBox="0 0 100 100" className="w-full h-full">
                      {/* Polygon background */}
                      <circle cx="50" cy="50" r="45" fill="none" stroke="#e2e8f0" strokeWidth="0.5" />
                      <circle cx="50" cy="50" r="30" fill="none" stroke="#e2e8f0" strokeWidth="0.5" />
                      <circle cx="50" cy="50" r="15" fill="none" stroke="#e2e8f0" strokeWidth="0.5" />

                      {/* Web lines */}
                      {[0, 72, 144, 216, 288].map(angle => (
                        <line 
                          key={angle}
                          x1="50" y1="50" 
                          x2={50 + 45 * Math.cos(angle * Math.PI / 180)} 
                          y2={50 + 45 * Math.sin(angle * Math.PI / 180)} 
                          stroke="#e2e8f0" strokeWidth="0.5"
                        />
                      ))}

                      {/* Radar Shape */}
                      <polygon 
                        points={radarData.map((d, i) => {
                          const angle = i * 72;
                          const r = d.val * 4.5;
                          const x = 50 + r * Math.cos(angle * Math.PI / 180);
                          const y = 50 + r * Math.sin(angle * Math.PI / 180);
                          return `${x},${y}`;
                        }).join(' ')}
                        fill="rgba(255, 107, 0, 0.4)"
                        stroke="#FF6B00"
                        strokeWidth="2"
                      />
                   </svg>
                   {radarData.map((d, i) => {
                      const angle = i * 72;
                      const x = 50 + 48 * Math.cos(angle * Math.PI / 180);
                      const y = 50 + 48 * Math.sin(angle * Math.PI / 180);
                      return (
                        <div key={i} className="absolute font-black text-[8px] uppercase text-[#001F3F]" style={{ left: `${x}%`, top: `${y}%`, transform: 'translate(-50%, -50%)' }}>
                          {d.label}
                        </div>
                      );
                   })}
                </div>
             </div>
             <div className="w-full md:w-1/2 space-y-4">
                <div className="bg-slate-50 p-4 rounded-2xl border-2 border-slate-100">
                   <h4 className="text-[10px] font-black text-slate-400 mb-2 uppercase">تقييم المدرب الحالي</h4>
                   <div className="flex gap-1 text-orange-400">
                      {[1,2,3,4].map(s => <Star key={s} size={16} fill="currentColor"/>)}
                      <Star size={16} />
                   </div>
                   <p className="text-[10px] font-bold text-slate-600 mt-2 italic">"لاعب ذو إمكانيات بدنية عالية، يحتاج لتطوير الوعي التكتيكي في الكرات الثابتة."</p>
                </div>
                <button className="w-full bg-[#001F3F] text-white py-3 rounded-xl font-black text-[10px] uppercase shadow-md active:bg-black transition-all">إضافة تقييم شهري</button>
             </div>
          </div>

          <div className="bg-white p-6 md:p-8 rounded-3xl border-2 border-slate-900 shadow-sm">
             <div className="flex justify-between items-center mb-6">
                <h3 className="text-md md:text-lg font-black flex items-center gap-2">
                   <BrainCircuit className="text-blue-900" size={20}/> التحليل الرقمي الذكي (AI)
                </h3>
                <button onClick={handleGenerateAiAnalysis} disabled={loadingAi} className="bg-orange-600 text-white px-4 py-2 rounded-lg font-black text-[10px] flex items-center gap-2 active:scale-90 transition-all">
                   {loadingAi ? <Loader2 className="animate-spin" size={14}/> : <Sparkles size={14}/>} تحديث التحليل
                </button>
             </div>
             {aiAnalysis ? (
               <p className="text-xs md:text-sm font-bold text-slate-700 leading-relaxed bg-blue-50 p-4 rounded-2xl border-r-4 border-blue-900">{aiAnalysis}</p>
             ) : (
               <div className="text-center py-6 text-slate-400 text-[10px] font-black italic">اضغط لتوليد التقرير التكتيكي...</div>
             )}
          </div>

          <div className="bg-white p-4 md:p-8 rounded-3xl border-2 border-slate-900 shadow-sm overflow-hidden">
             <h3 className="text-md md:text-lg font-black text-slate-900 mb-6 flex items-center gap-2">
               <ClipboardList className="text-[#001F3F]" size={20}/> سجل المشاركات الميدانية
             </h3>
             <div className="overflow-x-auto -mx-4 md:mx-0">
               <table className="w-full text-right border-collapse min-w-[500px]">
                 <thead>
                    <tr className="bg-slate-50 border-y-2 border-slate-900 text-[9px] md:text-[10px] font-black uppercase">
                       <th className="p-3 border-l">المنافس / النوع</th>
                       <th className="p-3 border-l text-center">الدقائق</th>
                       <th className="p-3 border-l text-center">أهداف</th>
                       <th className="p-3 text-center">أسيست</th>
                    </tr>
                 </thead>
                 <tbody>
                    {matchStats.list.length > 0 ? matchStats.list.map((m, i) => (
                      <tr key={i} className="border-b border-slate-100 text-[10px] md:text-xs font-black hover:bg-slate-50">
                         <td className="p-3 border-l">
                            <div className="flex flex-col">
                               <span>{m.opponent}</span>
                               <span className={`text-[8px] font-black px-1.5 py-0.5 rounded w-fit mt-1 ${m.isOfficial ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>{m.type}</span>
                            </div>
                         </td>
                         <td className="p-3 border-l text-center font-bold text-[#001F3F]">{m.mins} د</td>
                         <td className="p-3 border-l text-center text-emerald-600">{m.goals || '-'}</td>
                         <td className="p-3 text-center text-blue-600">{m.assists || '-'}</td>
                      </tr>
                    )) : (
                      <tr><td colSpan={4} className="p-10 text-center text-slate-300 font-black">لا توجد سجلات حالياً</td></tr>
                    )}
                 </tbody>
               </table>
             </div>
          </div>
        </div>

        {/* Sidebar Info */}
        <div className="space-y-6">
          <div className="bg-[#001F3F] p-6 md:p-8 rounded-3xl border-4 border-slate-900 text-white shadow-xl">
             <div className="flex items-center gap-2 mb-6 border-b border-white/10 pb-4">
                <ShieldCheck className="text-orange-400" size={20}/>
                <h3 className="text-sm font-black uppercase">البيانات الإدارية</h3>
             </div>
             <div className="space-y-4 text-[10px] md:text-xs">
                <div className="flex justify-between border-b border-white/5 pb-2">
                   <span className="text-slate-400 font-black">رقم القيد:</span>
                   <span className="font-black">{player.khana || '--'}</span>
                </div>
                <div className="flex justify-between border-b border-white/5 pb-2">
                   <span className="text-slate-400 font-black">الرقم الوطني:</span>
                   <span className="font-black text-orange-400">{player.nationalId || '--'}</span>
                </div>
                <div className="flex justify-between border-b border-white/5 pb-2">
                   <span className="text-slate-400 font-black">المواليد:</span>
                   <span className="font-black">{player.birthDate}</span>
                </div>
                <div className="flex flex-col bg-white/5 p-3 rounded-xl mt-4">
                   <span className="text-[9px] text-orange-400 font-black uppercase mb-1">توزيع الحضور الموثق</span>
                   <div className="grid grid-cols-3 gap-2 text-center mt-2">
                      <div className="bg-white/5 p-2 rounded-lg"><p className="opacity-50 text-[8px]">حاضر</p><p className="text-emerald-400 font-black">{attendanceData.present}</p></div>
                      <div className="bg-white/5 p-2 rounded-lg"><p className="opacity-50 text-[8px]">متأخر</p><p className="text-yellow-400 font-black">{attendanceData.late}</p></div>
                      <div className="bg-white/5 p-2 rounded-lg"><p className="opacity-50 text-[8px]">بعذر</p><p className="text-blue-400 font-black">{attendanceData.excused}</p></div>
                   </div>
                </div>
             </div>
          </div>

          <div className="bg-white p-6 md:p-8 rounded-3xl border-2 border-slate-900 shadow-sm">
             <h4 className="text-xs font-black text-red-600 mb-4 flex items-center gap-2">
                <HeartPulse size={16}/> سجل الإصابات
             </h4>
             <p className="text-[10px] font-bold text-slate-600 italic bg-red-50 p-3 rounded-xl border border-red-100">
                {player.injuries || "لا يوجد سجل إصابات سابق لهذا اللاعب."}
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PlayerReport;

import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, History, Lock, Clock, Calendar as CalendarIcon, Printer, ChevronRight, FileText, Users, Edit3, Shield as ShieldIcon } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord, TrainingSession, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus | null; excuse?: string; time?: string; date?: string }>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [adminEditOverride, setAdminEditOverride] = useState(false);

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;
  const restrictedCat = currentUser.restrictedCategory;
  const isViewer = currentUser.role === 'مشاهد';
  const isManager = currentUser.role === 'مدير';

  const sessions = state.sessions
    .filter(s => {
      if (restrictedCat) return s.category === restrictedCat;
      return (globalFilter === 'الكل' || s.category === globalFilter);
    })
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);
  const categoryMembers = state.people
    .filter(p => (activeSession ? p.category === activeSession.category : true))
    .sort((a, b) => (a.role !== 'لاعب' ? -1 : 1));

  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  const isLocked = activeSession?.isCompleted;
  const canEditNow = isManager ? (adminEditOverride || !isLocked) : !isLocked;

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    if ((isLocked && !canEditNow) || isViewer) return;
    const now = new Date();
    const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
    setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], status, time: timeStr } }));
  };

  const saveAttendance = async () => {
    if (!selectedSessionId || isSaving) return;
    setIsSaving(true);
    try {
      const newRecords: AttendanceRecord[] = [];
      const timeStr = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });

      categoryMembers.forEach(p => {
        const local = localRecords[p.id];
        const saved = savedRecords.find(r => r.personId === p.id);
        const statusToSave = local?.status || saved?.status || null;
        if (statusToSave) {
          newRecords.push({
            id: saved?.id || generateUUID(), 
            personId: p.id, 
            sessionId: selectedSessionId, 
            date: activeSession!.date,
            time: local?.time || saved?.time || timeStr, 
            status: statusToSave as AttendanceStatus, 
            excuse: local?.excuse || saved?.excuse || "", 
            isLocked: true
          });
        }
      });

      const { error: attError } = await supabase.from('attendance').upsert(newRecords.map(r => ({ 
        id: r.id, personId: r.personId, sessionId: r.sessionId, date: r.date, time: r.time, status: r.status, excuse: r.excuse 
      })));

      if (attError) throw attError;

      await supabase.from('sessions').update({ isCompleted: true }).eq('id', selectedSessionId);

      setState(prev => ({
        ...prev,
        attendance: [...prev.attendance.filter(a => a.sessionId !== selectedSessionId), ...newRecords],
        sessions: prev.sessions.map(s => s.id === selectedSessionId ? { ...s, isCompleted: true } : s)
      }));

      setLocalRecords({});
      addLog?.('تثبيت الحضور', `اعتماد كشف حضور: ${activeSession?.category}`, 'success');
      alert('تم الاعتماد النهائي بنجاح.');
    } catch (err: any) { 
      alert('خطأ: ' + err.message); 
    } finally { 
      setIsSaving(false); 
    }
  };

  return (
    <div className="space-y-4 md:space-y-8 animate-in fade-in duration-500 px-2 md:px-0 pb-20">
      <div className="solid-panel p-4 md:p-10 relative overflow-hidden flex flex-col gap-4 md:gap-8 no-print !border-[#FF6B00] !shadow-none">
        <div className="flex-1 space-y-2">
           <label className="text-[10px] font-black text-[#001F3F] mr-2 uppercase tracking-widest flex items-center gap-2">
             <div className="w-1.5 h-1.5 bg-[#FF6B00] rounded-full"></div> رصد حضور الحصة الفوري
           </label>
           <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); }}
            className="w-full bg-slate-50 border-2 md:border-4 border-[#001F3F] rounded-2xl p-4 md:p-6 font-black text-sm md:text-2xl text-[#001F3F] outline-none">
             <option value="">-- اختر التمرين من القائمة --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} | {s.objective} ({s.category})</option>)}
           </select>
        </div>
        <div className="flex flex-col md:flex-row gap-3 w-full">
          {!isViewer && (
            <button onClick={saveAttendance} disabled={!selectedSessionId || (isLocked && !canEditNow) || isSaving} className="w-full md:w-auto bg-[#001F3F] text-white px-8 py-5 rounded-xl font-black text-sm md:text-lg flex items-center justify-center gap-3 border-b-8 border-black active:translate-y-1 active:border-b-0 transition-all">
              {isSaving ? <History className="animate-spin" size={20}/> : <Save size={20} />}
              اعتماد الرصد النهائي
            </button>
          )}
          {isManager && selectedSessionId && (
            <button onClick={() => setAdminEditOverride(!adminEditOverride)} className={`w-full md:w-auto px-4 py-3 rounded-xl font-black text-[10px] border-2 transition-all ${adminEditOverride ? 'bg-[#FF6B00] text-white border-black' : 'bg-slate-100 text-[#001F3F] border-[#001F3F]'}`}>
              {adminEditOverride ? 'إيقاف وضع التعديل' : 'تفعيل تعديل السجل المقفل'}
            </button>
          )}
        </div>
      </div>

      {activeSession && (
        <div className={`solid-panel overflow-hidden relative !shadow-none ${isLocked && !canEditNow ? 'opacity-60 grayscale' : ''}`}>
          <div className="p-4 md:p-8 border-b-2 border-slate-100 bg-slate-50 flex flex-col md:flex-row justify-between items-center gap-3">
             <div className="flex items-center gap-4 w-full md:w-auto">
               <div className="w-12 h-12 md:w-16 md:h-16 bg-[#001F3F] border-2 border-[#FF6B00] rounded-xl flex items-center justify-center font-black text-xl md:text-3xl text-white uppercase">
                  {activeSession.category.charAt(0)}
               </div>
               <div>
                 <h3 className="text-sm md:text-xl font-black text-[#001F3F] leading-tight">{activeSession.objective}</h3>
                 <p className="text-[8px] md:text-[10px] font-bold text-[#FF6B00] uppercase tracking-widest mt-1">{activeSession.category} • {activeSession.date}</p>
               </div>
             </div>
             {isLocked && <span className="bg-red-600 text-white px-4 py-1.5 rounded-full text-[9px] font-black flex items-center gap-2 uppercase"><Lock size={12}/> سجل مقفل إدارياً</span>}
          </div>

          <div className="overflow-x-auto -mx-2 md:mx-0">
            <table className="w-full text-right min-w-[750px] md:min-w-[900px]">
              <thead className="bg-[#001F3F] text-white border-b-4 border-slate-900">
                <tr>
                  <th className="px-4 md:px-8 py-4 text-[9px] md:text-[10px] font-black uppercase tracking-widest">الاسم والصفة</th>
                  <th className="px-4 md:px-8 py-4 text-[9px] md:text-[10px] font-black uppercase tracking-widest text-center">حالة الحضور</th>
                  <th className="px-4 md:px-8 py-4 text-[9px] md:text-[10px] font-black uppercase tracking-widest text-center">التوقيت</th>
                  <th className="px-4 md:px-8 py-4 text-[9px] md:text-[10px] font-black uppercase tracking-widest">ملاحظات / عذر</th>
                </tr>
              </thead>
              <tbody className="divide-y-2 divide-slate-100">
                {categoryMembers.map(p => {
                  const saved = savedRecords.find(r => r.personId === p.id);
                  const local = localRecords[p.id];
                  const currentStatus = local?.status || saved?.status || null;
                  const currentTime = local?.time || saved?.time || "--:--";

                  return (
                    <tr key={p.id} className="transition-all hover:bg-slate-50">
                      <td className="px-4 md:px-8 py-4">
                        <div className="flex items-center gap-3">
                          <div className={`w-8 h-8 md:w-10 md:h-10 rounded-lg flex items-center justify-center font-black text-[10px] border-2 transition-all ${currentStatus ? 'bg-[#FF6B00] text-white border-[#001F3F]' : 'bg-slate-100 text-slate-300 border-slate-200'}`}>
                            {p.number || '0'}
                          </div>
                          <div className="flex flex-col">
                             <span className="font-black text-xs md:text-sm text-[#001F3F]">{p.name}</span>
                             <span className="text-[8px] font-black text-[#FF6B00] uppercase">{p.role}</span>
                          </div>
                        </div>
                      </td>
                      <td className="px-4 md:px-8 py-4 text-center">
                        <div className="flex justify-center gap-1 md:gap-2">
                          <button onClick={() => handleSetStatus(p.id, 'حاضر')} className={`px-2 md:px-3 py-2 rounded-lg text-[8px] md:text-[9px] font-black border-2 transition-all active:scale-90 ${currentStatus === 'حاضر' ? 'bg-emerald-500 text-white border-emerald-700 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>حاضر</button>
                          <button onClick={() => handleSetStatus(p.id, 'متأخر')} className={`px-2 md:px-3 py-2 rounded-lg text-[8px] md:text-[9px] font-black border-2 transition-all active:scale-90 ${currentStatus === 'متأخر' ? 'bg-yellow-500 text-white border-yellow-700 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>متأخر</button>
                          <button onClick={() => handleSetStatus(p.id, 'غائب')} className={`px-2 md:px-3 py-2 rounded-lg text-[8px] md:text-[9px] font-black border-2 transition-all active:scale-90 ${currentStatus === 'غائب' ? 'bg-red-500 text-white border-red-700 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>غائب</button>
                          <button onClick={() => handleSetStatus(p.id, 'غياب بعذر')} className={`px-2 md:px-3 py-2 rounded-lg text-[8px] md:text-[9px] font-black border-2 transition-all active:scale-90 ${currentStatus === 'غياب بعذر' ? 'bg-blue-600 text-white border-blue-800 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>بعذر</button>
                        </div>
                      </td>
                      <td className="px-4 md:px-8 py-4 text-center">
                         <span className="text-[10px] font-black bg-slate-100 px-2 py-1 rounded border border-slate-200 text-[#001F3F]">{currentTime}</span>
                      </td>
                      <td className="px-4 md:px-8 py-4">
                        <input type="text" value={local?.excuse || saved?.excuse || ""} onChange={e => setLocalRecords(prev => ({ ...prev, [p.id]: { ...prev[p.id], excuse: e.target.value } }))}
                          className="bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-[10px] font-bold w-full outline-none focus:border-[#FF6B00]" 
                          placeholder="سجل عذراً أو ملاحظة..."
                        />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

