             <h3 className="text-md md:text-lg font-black text-[#001F3F] mb-6 flex items-center gap-2">
                <Info className="text-blue-700" size={20}/> تفاصيل الهوية والبيانات العائلية
             </h3>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="space-y-1">
                   <p className="text-[10px] font-black text-slate-400 uppercase">اسم الأب</p>
                   <p className="font-bold text-sm text-slate-900">{player.fatherName || '--'}</p>
                </div>
                <div className="space-y-1">
                   <p className="text-[10px] font-black text-slate-400 uppercase">اسم الأم</p>
                   <p className="font-bold text-sm text-slate-900">{player.motherName || '--'}</p>
                </div>
                <div className="space-y-1">
                   <p className="text-[10px] font-black text-slate-400 uppercase">مكان الولادة</p>
                   <p className="font-bold text-sm text-slate-900">{player.birthPlace || '--'}</p>
                </div>
                <div className="space-y-1">
                   <p className="text-[10px] font-black text-slate-400 uppercase">الرقم الاتحادي</p>
                   <p className="font-bold text-sm text-slate-900">{player.federalNumber || '--'}</p>
                </div>
                <div className="space-y-1">
                   <p className="text-[10px] font-black text-slate-400 uppercase">الرقم الدولي</p>
                   <p className="font-bold text-sm text-slate-900">{player.internationalId || '--'}</p>
                </div>
                <div className="space-y-1">
                   <p className="text-[10px] font-black text-slate-400 uppercase">تاريخ الانضمام للنادي</p>
