               {player.name.charAt(0)}
            </div>
            <div className="mb-2">
              <h1 className="text-xl md:text-3xl font-black text-white drop-shadow-md">{player.name}</h1>
              <div className="flex gap-2 mt-1">
                 <span className="bg-orange-600 text-white text-[8px] md:text-[10px] font-black px-2 md:px-4 py-1 rounded-lg border border-white uppercase">{player.role}</span>
                 <span className="bg-blue-600 text-white text-[8px] md:text-[10px] font-black px-2 md:px-4 py-1 rounded-lg border border-white uppercase">{player.category}</span>
              </div>
            </div>
          </div>
        </div>
        <div className="h-12 md:h-20"></div>

        <div className="px-4 md:px-12 pb-8 grid grid-cols-2 md:grid-cols-5 gap-3 md:gap-6">
           <div className="bg-slate-50 p-3 md:p-4 rounded-xl border-2 border-slate-100 flex flex-col items-center">
             <Medal className="text-[#001F3F] mb-1" size={18}/>
             <span className="text-[8px] md:text-[10px] font-black text-slate-400 uppercase">دقائق رسمية</span>
             <p className="text-lg md:text-2xl font-black text-[#001F3F]">{matchStats.officialMins}</p>
