        opponentScore: m.opponentScore || '0'
      }));

      // تنفيذ عمليات الحفظ بالتسلسل لضمان عدم حدوث تداخل
      await Promise.all([
        updatedState.people.length > 0 && supabase.from('people').upsert(sanitize(updatedState.people), { onConflict: 'id' }),
        updatedState.sessions.length > 0 && supabase.from('sessions').upsert(sanitize(updatedState.sessions), { onConflict: 'id' }),
        mappedMatches.length > 0 && supabase.from('matches').upsert(sanitize(mappedMatches), { onConflict: 'id' }),
        updatedState.attendance.length > 0 && supabase.from('attendance').upsert(sanitize(updatedState.attendance), { onConflict: 'id' }),
        updatedState.users.length > 0 && supabase.from('app_users').upsert(sanitize(updatedState.users), { onConflict: 'id' }),
        updatedState.warehouse.length > 0 && supabase.from('warehouse').upsert(sanitize(updatedState.warehouse), { onConflict: 'id' })
      ]);

      setSyncStatus('synced');
      syncManager.current.lastLocalUpdate = Date.now();
    } catch (error: any) {
      setSyncStatus('error');
      addLog('خطأ في الرفع السحابي', error.message, 'error');
    } finally {
      syncManager.current.isPushing = false;
    }
  }, [addLog]);

  const updateStateAndSync = async (updater: (prev: AppState) => AppState) => {
    syncManager.current.lastLocalUpdate = Date.now();
    let nextState: AppState | null = null;
    setState(prev => {
      nextState = updater(prev);
      return nextState;
    });
    if (nextState) {
      await pushData(nextState);
    }
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
