      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 md:gap-8">
        {/* Quick Actions & Logistics */}
        <div className="lg:col-span-4 space-y-6">
           <div className="bg-[#FF6B00] p-6 rounded-3xl border-4 border-[#001F3F] text-white shadow-xl">
              <h3 className="text-md font-black mb-4 flex items-center gap-2">
                 <Activity size={20}/> الوصول السريع للتقارير
