              <div className="grid grid-cols-1 gap-2">
                 <button className="w-full bg-[#001F3F] p-4 rounded-xl flex items-center justify-between font-black text-xs hover:bg-black transition-all">
                    <span>تحليل الجاهزية الفنية</span>
                    <TrendingUp size={18} className="text-orange-400" />
                 </button>
                 <button className="w-full bg-[#001F3F] p-4 rounded-xl flex items-center justify-between font-black text-xs hover:bg-black transition-all">
                    <span>تتبع المستودع المركزي</span>
                    <Search size={18} className="text-orange-400" />
