               ))}
               {upcomingMatches.length === 0 && <div className="py-12 text-center text-xs font-black text-slate-300 italic border-2 border-dashed border-slate-200 rounded-3xl">لا توجد مباريات مستقبلية حالياً</div>}
             </div>
          </div>

          <div className="solid-panel p-6 md:p-10 !shadow-none md:!shadow-[8px_8px_0px_0px_#001F3F]">
