        const safeUsers = (usrs.data && usrs.data.length > 0) ? usrs.data : (prev.users.length > 0 ? prev.users : []);

        return {
          ...prev,
          categories: (cats.data && cats.data.length > 0) ? cats.data.map(c => c.name) : prev.categories,
          people: safePeople,
          sessions: safeSessions.map((s: any) => ({ ...s, isLocked: !!s.isCompleted })),
          matches: safeMatches.map((m: any) => ({ ...m, pitch: m.pitch || m.location || '' })),
          warehouse: safeWarehouse,
          attendance: safeAttendance,
          users: safeUsers
        };
      });
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
      console.error("Fetch Error:", error);
    } finally {
      setIsSyncing(false);
      syncManager.current.isInitialLoad = false;
