import React, { useState, useMemo, useEffect } from 'react';
import { Users, Calendar, Trophy, Clock, MapPin, AlertCircle, ChevronLeft, ShieldAlert, Filter, Printer, FileText, ClipboardCheck, Zap, Activity, TrendingUp, Search, X, BellRing, AlertTriangle, Timer } from 'lucide-react';
import { AppState, Person, Match, TrainingSession } from '../types';

interface DashboardProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onMatchClick: (id: string) => void;
  onSessionClick: (id: string) => void;
  onPlayerClick?: (player: Person) => void;
}

const CountdownCard: React.FC<{ 
  title: string; 
  subtitle: string; 
  targetDate: string; 
  targetTime: string; 
  type: 'match' | 'training';
  onClick: () => void;
}> = ({ title, subtitle, targetDate, targetTime, type, onClick }) => {
  const [timeLeft, setTimeLeft] = useState<{ days: number, hours: number, minutes: number, seconds: number, isLive: boolean } | null>(null);

  useEffect(() => {
    const calculate = () => {
      const target = new Date(`${targetDate}T${targetTime}`);
      const now = new Date();
      const diff = target.getTime() - now.getTime();

      // نشاط مباشر إذا كان الوقت الحالي بعد البدء بمدة لا تزيد عن ساعتين للمباريات وساعة للتدريب
      const durationLimit = type === 'match' ? 2 * 60 * 60 * 1000 : 1.5 * 60 * 60 * 1000;
      const isLive = diff <= 0 && Math.abs(diff) < durationLimit;

      if (diff <= 0 && !isLive) {
        setTimeLeft(null);
        return;
      }

      const d = Math.floor(diff / (1000 * 60 * 60 * 24));
      const h = Math.floor((diff / (1000 * 60 * 60)) % 24);
      const m = Math.floor((diff / (1000 * 60)) % 60);
      const s = Math.floor((diff / 1000) % 60);

      setTimeLeft({ days: d, hours: h, minutes: m, seconds: s, isLive });
    };

    calculate();
    const timer = setInterval(calculate, 1000);
    return () => clearInterval(timer);
  }, [targetDate, targetTime, type]);

  if (!timeLeft && !timeLeft?.isLive) return null;

  return (
    <button 
      onClick={onClick}
      className={`relative w-full overflow-hidden p-6 rounded-[2.5rem] border-4 transition-all duration-500 hover:scale-[1.02] active:scale-95 group shadow-2xl ${
        timeLeft.isLive 
        ? 'bg-red-950 border-red-600 animate-pulse' 
        : 'bg-[#001F3F] border-[#FF6B00]'
      }`}
    >
      <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-125 transition-transform">
        {type === 'match' ? <Trophy size={120} /> : <Calendar size={120} />}
      </div>

      <div className="relative z-10 flex flex-col items-start text-right">
        <div className="flex items-center gap-3 mb-2">
           {timeLeft.isLive ? (
             <div className="flex items-center gap-2 bg-red-600 text-white px-4 py-1 rounded-full text-[10px] font-black animate-bounce shadow-lg">
                <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>
                بث مباشر الآن
             </div>
           ) : (
             <div className="bg-[#FF6B00] text-white px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg">
                {type === 'match' ? 'المواجهة القادمة' : 'الحصة التدريبية'}
             </div>
           )}
           <span className="text-[10px] font-bold text-white/40 uppercase tracking-tighter">{targetDate} @ {targetTime}</span>
        </div>

        <h3 className="text-2xl md:text-3xl font-black text-white mb-1 drop-shadow-md">{title}</h3>
        <p className="text-xs font-bold text-[#FF6B00] mb-6 uppercase tracking-widest opacity-80">{subtitle}</p>

        {timeLeft.isLive ? (
          <div className="flex flex-col items-start gap-1">
             <p className="text-white font-black text-lg">النشاط جارٍ حالياً...</p>
             <p className="text-red-400 text-[10px] font-bold">انتقل للتفاصيل للمتابعة الإدارية</p>
          </div>
        ) : (
          <div className="flex gap-4 items-center">
            <div className="flex flex-col items-center">
              <span className="text-2xl md:text-4xl font-black text-white font-mono glow-text">{String(timeLeft.days).padStart(2, '0')}</span>
              <span className="text-[8px] font-black text-white/40 uppercase">يوم</span>
            </div>
            <span className="text-2xl font-black text-[#FF6B00] mb-4">:</span>
            <div className="flex flex-col items-center">
              <span className="text-2xl md:text-4xl font-black text-white font-mono glow-text">{String(timeLeft.hours).padStart(2, '0')}</span>
              <span className="text-[8px] font-black text-white/40 uppercase">ساعة</span>
            </div>
            <span className="text-2xl font-black text-[#FF6B00] mb-4">:</span>
            <div className="flex flex-col items-center">
              <span className="text-2xl md:text-4xl font-black text-white font-mono glow-text">{String(timeLeft.minutes).padStart(2, '0')}</span>
              <span className="text-[8px] font-black text-white/40 uppercase">دقيقة</span>
            </div>
          </div>
        )}
      </div>
    </button>
  );
};

