  const sanitize = (data: any[]) => {
    return data.map(item => {
      const cleanItem = JSON.parse(JSON.stringify(item));
      Object.keys(cleanItem).forEach(key => {
        if (cleanItem[key] === undefined) cleanItem[key] = null;
      });
      return cleanItem;
    });
  };

  const fetchData = useCallback(async () => {
    if (!state.currentUser || syncManager.current.isPushing) return;

    setIsSyncing(true);
    setSyncStatus('syncing');
    try {
      const pplQuery = supabase.from('people').select('*');
      const sessQuery = supabase.from('sessions').select('*');
      const mtchQuery = supabase.from('matches').select('*');
      const usrsQuery = supabase.from('app_users').select('*');
      const wrhsQuery = supabase.from('warehouse').select('*');
      const attnQuery = supabase.from('attendance').select('*');

      if (state.currentUser.restrictedCategory) {
        pplQuery.eq('category', state.currentUser.restrictedCategory);
        sessQuery.eq('category', state.currentUser.restrictedCategory);
        mtchQuery.eq('category', state.currentUser.restrictedCategory);
        wrhsQuery.or(`category.eq.${state.currentUser.restrictedCategory},category.eq.المخزن العام`);
      }

      const [cats, ppl, sess, mtch, attn, usrs, wrhs] = await Promise.all([
        supabase.from('categories').select('name'),
        pplQuery,
        sessQuery,
        mtchQuery,
        attnQuery,
        usrsQuery,
        wrhsQuery
      ]);

      if (ppl.error || mtch.error || sess.error) throw new Error("Connection Error");

      // CRITICAL: Safe Merge Logic - Only update local state if fetched data is valid and not empty when local has data
      setState(prev => {
        const safeData = (fetched: any[] | null, local: any[]) => {
          if (fetched === null) return local;
          if (fetched.length === 0 && local.length > 0) {
             console.warn("Supabase returned empty set while local has data. Preserving local state.");
             return local;
          }
          return fetched;
        };

        const updatedPeople = safeData(ppl.data, prev.people);
        const updatedMatches = safeData(mtch.data, prev.matches);
        const updatedSessions = safeData(sess.data, prev.sessions);
        const updatedAttendance = safeData(attn.data, prev.attendance);
