          warehouse: updatedWarehouse,
          attendance: updatedAttendance,
          users: updatedUsers
        };
      });
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
      console.error("Fetch Error:", error);
    } finally {
      setIsSyncing(false);
      syncManager.current.isInitialLoad = false;
    }
