  onClick: () => void;
}> = ({ title, subtitle, targetDate, targetTime, type, onClick }) => {
  const [timeLeft, setTimeLeft] = useState<{ days: number, hours: number, minutes: number, seconds: number, isLive: boolean } | null>(null);

  useEffect(() => {
    const calculate = () => {
      const target = new Date(`${targetDate}T${targetTime}`);
      const now = new Date();
      const diff = target.getTime() - now.getTime();

      // Activity is live if current time is after start but within a reasonable duration (2h for match, 1.5h for session)
      const liveDuration = type === 'match' ? 120 * 60 * 1000 : 90 * 60 * 1000;
      const isLive = diff <= 0 && Math.abs(diff) < liveDuration;

      if (diff <= 0 && !isLive) {
        setTimeLeft(null); // Activity has ended
        return;
      }

      const d = Math.floor(diff / (1000 * 60 * 60 * 24));
      const h = Math.floor((diff / (1000 * 60 * 60)) % 24);
      const m = Math.floor((diff / (1000 * 60)) % 60);
      const s = Math.floor((diff / 1000) % 60);

      setTimeLeft({ days: d, hours: h, minutes: m, seconds: s, isLive });
    };

    calculate();
    const interval = setInterval(calculate, 1000);
    return () => clearInterval(interval);
  }, [targetDate, targetTime, type]);

  if (!timeLeft) return null;

  return (
    <button 
      onClick={onClick}
      className={`relative w-full overflow-hidden p-6 md:p-8 rounded-[2.5rem] border-4 transition-all duration-500 hover:scale-[1.02] active:scale-95 group shadow-2xl ${
        timeLeft.isLive 
        ? 'bg-red-950 border-red-600 animate-pulse' 
        : 'bg-[#001F3F] border-[#FF6B00]'
      }`}
    >
      {/* Background Icon Decoration */}
      <div className="absolute -top-4 -left-4 p-8 opacity-10 group-hover:rotate-12 transition-transform duration-700">
        {type === 'match' ? <Trophy size={160} /> : <Calendar size={160} />}
      </div>

      <div className="relative z-10 flex flex-col items-start text-right">
        <div className="flex items-center gap-3 mb-4 w-full">
           {timeLeft.isLive ? (
             <div className="flex items-center gap-2 bg-red-600 text-white px-5 py-2 rounded-full text-[10px] md:text-[12px] font-black uppercase shadow-[0_0_20px_rgba(220,38,38,0.5)]">
                <div className="w-2.5 h-2.5 bg-white rounded-full animate-ping"></div>
                بث مباشر الآن (LIVE)
             </div>
           ) : (
             <div className="bg-[#FF6B00] text-white px-5 py-2 rounded-full text-[10px] md:text-[12px] font-black uppercase tracking-widest shadow-lg">
                {type === 'match' ? 'المواجهة القادمة' : 'الحصة التدريبية القادمة'}
             </div>
           )}
           <div className="flex-1"></div>
           <span className="text-[10px] md:text-[12px] font-bold text-white/40 uppercase tracking-tighter tabular-nums">{targetDate} @ {targetTime}</span>
        </div>

        <h3 className="text-2xl md:text-4xl font-black text-white mb-2 drop-shadow-xl tracking-tight leading-tight">{title}</h3>
        <p className="text-xs md:text-sm font-bold text-[#FF6B00] mb-8 uppercase tracking-[0.2em] opacity-80">{subtitle}</p>

        {timeLeft.isLive ? (
          <div className="flex flex-col items-start gap-2 py-4">
             <p className="text-white font-black text-xl md:text-2xl animate-pulse">النشاط جارٍ في هذه اللحظات</p>
             <div className="flex items-center gap-2 text-red-400 text-[10px] md:text-[12px] font-bold uppercase">
                <Activity size={16} /> انتقل للتحكم الفوري والمتابعة
             </div>
          </div>
        ) : (
          <div className="flex gap-4 md:gap-8 items-end">
            <div className="flex flex-col items-center">
              <span className="text-3xl md:text-5xl font-black text-white font-mono tabular-nums drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]">{String(timeLeft.days).padStart(2, '0')}</span>
              <span className="text-[8px] md:text-[10px] font-black text-white/40 uppercase tracking-widest mt-1">يوم</span>
            </div>
            <span className="text-3xl md:text-5xl font-black text-[#FF6B00] mb-5 animate-pulse">:</span>
            <div className="flex flex-col items-center">
              <span className="text-3xl md:text-5xl font-black text-white font-mono tabular-nums drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]">{String(timeLeft.hours).padStart(2, '0')}</span>
              <span className="text-[8px] md:text-[10px] font-black text-white/40 uppercase tracking-widest mt-1">ساعة</span>
            </div>
            <span className="text-3xl md:text-5xl font-black text-[#FF6B00] mb-5 animate-pulse">:</span>
            <div className="flex flex-col items-center">
              <span className="text-3xl md:text-5xl font-black text-white font-mono tabular-nums drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]">{String(timeLeft.minutes).padStart(2, '0')}</span>
              <span className="text-[8px] md:text-[10px] font-black text-white/40 uppercase tracking-widest mt-1">دقيقة</span>
            </div>
          </div>
        )}
      </div>

      {/* Visual Scanline Effect */}
      <div className="absolute inset-0 bg-gradient-to-b from-transparent via-white/[0.02] to-transparent h-[2px] w-full top-0 animate-[scanline_4s_linear_infinite] pointer-events-none"></div>
    </button>
  );
};

