      const target = new Date(`${m.date}T${m.time}`);
      // Show if it's in the future OR currently live (within 2h window)
      return target.getTime() + (120 * 60 * 1000) > now.getTime();
    })
    .sort((a, b) => a.date.localeCompare(b.date) || a.time.localeCompare(b.time));

