import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Star, Sparkles, Heart, Loader2
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person, PlayerEvaluation } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);

  // حالة تقييم اللاعب الفردي في المباراة
  const [evalPlayer, setEvalPlayer] = useState<Person | null>(null);
  const [evalData, setEvalData] = useState({ stars: 3, effort: 70, discipline: 70, impact: 70, note: '' });
  const [isSavingEval, setIsSavingEval] = useState(false);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة'
  });

  useEffect(() => {
    if (isAddOpen) {
      setFormData(prev => ({
        ...prev,
        category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter)
      }));
    }
  }, [isAddOpen, state.globalCategoryFilter, state.categories, restrictedCat]);

  useEffect(() => {
    if (activeMatch && !isViewer) {
      const newLineup = { ...activeMatch.lineup };
      let hasChanged = false;
      const st1 = parseInt(activeMatch.stoppageTime1 || '0') || 0;
      const st2 = parseInt(activeMatch.stoppageTime2 || '0') || 0;

      newLineup.subs.forEach((s) => {
        if (s.substitutionMinute && s.replacedPlayerId) {
          const minute = parseInt(s.substitutionMinute) || 0;
          let subMins = 0;
          if (minute <= 45) {
            subMins = (45 - minute) + st1 + 45 + st2;
          } else {
            subMins = (90 - minute) + st2;
          }
          if (s.minutesPlayed !== subMins.toString()) {
            s.minutesPlayed = subMins.toString();
            hasChanged = true;
          }

          const starterIdx = newLineup.starters.findIndex(st => st.playerId === s.replacedPlayerId);
          if (starterIdx !== -1) {
            let stMins = 0;
            if (minute <= 45) {
              stMins = minute;
            } else {
              stMins = 45 + st1 + (minute - 45);
            }
            if (newLineup.starters[starterIdx].minutesPlayed !== stMins.toString()) {
              newLineup.starters[starterIdx].minutesPlayed = stMins.toString();
              hasChanged = true;
            }
          }
        }
      });

      if (hasChanged) {
        setActiveMatch(prev => prev ? { ...prev, lineup: newLineup } : null);
      }
    }
  }, [activeMatch?.stoppageTime1, activeMatch?.stoppageTime2]);

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === globalFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isViewer) return;
    const finalCategory = restrictedCat || formData.category;
    if (!formData.opponent || !formData.date || !formData.time || !finalCategory) return;
    const newMatch: Match = {
      id: generateUUID(),
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time,
      category: finalCategory,
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: { starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '90' })), subs: [], staff: [], captain: '' },
      notes: ''
    };
    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    setIsAddOpen(false);
  };

  const openEvalModal = (playerId: string) => {
    const person = state.people.find(p => p.id === playerId);
    if (!person) return;

    // محاولة إيجاد تقييم موجود مسبقاً لهذه المباراة
    const existing = state.evaluations.find(e => e.playerId === playerId && e.matchId === activeMatch?.id);
    if (existing) {
       setEvalData({ stars: existing.stars, effort: existing.effort || 70, discipline: existing.discipline || 70, impact: existing.impact || 70, note: existing.coachNote || '' });
    } else {
       setEvalData({ stars: 3, effort: 70, discipline: 70, impact: 70, note: '' });
    }
    setEvalPlayer(person);
  };

  const handleSavePlayerEval = async () => {
    if (!evalPlayer || !activeMatch) return;
    setIsSavingEval(true);
    try {
      const newEval: PlayerEvaluation = {
        id: state.evaluations.find(e => e.playerId === evalPlayer.id && e.matchId === activeMatch.id)?.id || generateUUID(),
        playerId: evalPlayer.id,
        matchId: activeMatch.id,
        date: activeMatch.date,
        physical: evalData.effort, // استخدام الجهد كبديل للبدني في تقييم المباراة
        tactical: 70, // قيم افتراضية لعدم توفرها في تقييم المباراة السريع
        technical: 70,
        mental: 70,
        speed: 70,
        stars: evalData.stars,
        effort: evalData.effort,
        discipline: evalData.discipline,
        impact: evalData.impact,
        coachNote: evalData.note
      };

      const { error } = await supabase.from('player_evaluations').upsert(newEval);
      if (error) throw error;

      setState(prev => ({
        ...prev,
        evaluations: [...prev.evaluations.filter(e => e.id !== newEval.id), newEval]
      }));

      addLog?.('تقييم لاعب', `تم تقييم أداء ${evalPlayer.name} في مباراة ${activeMatch.opponent}`, 'success');
      setEvalPlayer(null);
    } catch (err: any) {
      alert("خطأ: " + err.message);
    } finally {
      setIsSavingEval(false);
    }
  };

  const updateActiveMatchLineup = (index: number, playerId: string, isStarter: boolean) => {
    if (!activeMatch || isViewer) return;
    const person = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (!person) {
      if (isStarter) newLineup.starters[index] = { ...newLineup.starters[index], playerId: '', name: '', number: '' };
    } else {
      if (isStarter) newLineup.starters[index] = { ...newLineup.starters[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const saveMatchDetails = () => {
    if (!activeMatch || isViewer) return;
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, isCompleted: true } : m)
    }));
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [...activeMatch!.lineup.starters.map(s => s.playerId), ...activeMatch!.lineup.subs.map(s => s.playerId)].filter(id => id && id !== currentId);
    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const fieldClass = "w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-[#001F3F] mr-2 uppercase block mb-1.5";

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div><h2 className="text-xl font-black text-slate-900 flex items-center gap-3"><Trophy size={24} className="text-orange-600" /> إدارة أجندة المباريات المركزية</h2></div>
        <div className="flex gap-3">
          <button onClick={() => setShowPrintView(true)} className="bg-white text-slate-900 border-2 border-slate-900 px-6 py-3 rounded-xl font-black text-sm">طباعة الأجندة</button>
          {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black text-sm">جدولة مواجهة</button>}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative border-b-8 transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-6"><span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span><span className="text-[10px] font-black text-slate-900">{m.date} - {m.category}</span></div>
             <div className="text-center mb-6"><p className="text-3xl font-black text-slate-900">{m.ourScore} - {m.opponentScore}</p><p className="font-black text-sm text-slate-700 mt-2">{m.opponent}</p></div>
             <div className="flex flex-col gap-2"><button onClick={() => setActiveMatch(m)} className="w-full bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs">التشكيل والتقرير</button></div>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/98 backdrop-blur-2xl z-[400] overflow-y-auto no-print">
           <div className="max-w-7xl mx-auto p-4 lg:p-12 min-h-screen text-right" dir="rtl">
              <div className="bg-white rounded-[4rem] border-[10px] border-slate-900 p-8 lg:p-12 shadow-2xl relative">
                <header className="relative flex flex-col md:flex-row justify-between items-center mb-12 border-b-8 border-slate-900 pb-10 gap-6">
                   <div className="flex items-center gap-6"><div className="bg-[#001F3F] text-white w-24 h-24 rounded-[2rem] flex items-center justify-center font-black text-4xl border-4 border-slate-900 shadow-2xl animate-pulse">K</div><div><h2 className="text-4xl font-black text-slate-900 tracking-tighter">الكرامة <span className="text-orange-600">×</span> {activeMatch.opponent}</h2></div></div>
                   <div className="flex gap-4">
                      <button onClick={saveMatchDetails} className="bg-emerald-600 text-white px-10 py-5 rounded-[2rem] font-black text-lg border-b-8 border-emerald-900"><span className="flex items-center gap-3"><Save size={24}/> حفظ التقرير الفني</span></button>
                      <button onClick={() => setActiveMatch(null)} className="bg-white text-slate-900 px-8 py-5 rounded-[2rem] font-black text-lg border-4 border-slate-900 shadow-xl"><X size={24}/></button>
                   </div>
                </header>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                   <div className="lg:col-span-8 space-y-12">
                      <section>
                         <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter mb-8 border-r-4 border-orange-600 pr-4">التشكيلة الأساسية</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="bg-white p-6 rounded-[2.5rem] border-4 border-slate-900 shadow-xl flex flex-col relative group">
                                  <div className="flex justify-between items-start mb-4">
                                     <div className="w-14 h-14 bg-slate-900 text-white rounded-[1.5rem] flex items-center justify-center font-black text-2xl border-2 border-white">{s.number || (idx + 1)}</div>
                                     {s.playerId && (
                                       <button onClick={() => openEvalModal(s.playerId)} className="p-3 bg-orange-100 text-orange-600 rounded-[1.2rem] border-2 border-orange-200 hover:bg-orange-600 hover:text-white transition-all">
                                          <Star size={20} />
                                       </button>
                                     )}
                                  </div>
                                  <select className="w-full bg-slate-50 border-2 border-slate-400 rounded-xl p-3 font-black text-sm" value={s.playerId} onChange={e => updateActiveMatchLineup(idx, e.target.value, true)}>
                                     <option value="">-- اختر لاعب --</option>
                                     {getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>)}
                                  </select>
                               </div>
                            ))}
                         </div>
                      </section>

                      <section>
                         <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter mb-8 border-r-4 border-blue-900 pr-4">البدلاء</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {activeMatch.lineup.subs.map((s, idx) => (
                               <div key={idx} className="bg-slate-50 p-6 rounded-[2.5rem] border-4 border-slate-300 flex flex-col space-y-4">
                                  <div className="flex justify-between items-center">
                                     <span className="text-[11px] font-black text-blue-900 uppercase">البديل #{idx+1}</span>
                                     {s.playerId && <button onClick={() => openEvalModal(s.playerId)} className="p-2 bg-orange-100 text-orange-600 rounded-lg"><Star size={16}/></button>}
                                  </div>
                                  <select className="w-full bg-white border-2 border-slate-400 rounded-xl p-2.5 font-black text-xs" value={s.playerId} onChange={e => {
                                     const newSubs = [...activeMatch.lineup.subs];
                                     const p = state.people.find(x => x.id === e.target.value);
                                     newSubs[idx] = { ...newSubs[idx], playerId: p?.id || '', name: p?.name || '', number: p?.number?.toString() || '' };
                                     setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
                                  }}>
                                     <option value="">-- اختر لاعب --</option>
                                     {getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>)}
                                  </select>
                               </div>
                            ))}
                            <button onClick={() => setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: [...activeMatch.lineup.subs, {playerId: '', name: '', number: ''}]}})} className="border-4 border-dashed border-slate-200 p-8 rounded-[2.5rem] font-black text-slate-300 hover:border-blue-900 hover:text-blue-900 transition-all">+ إضافة بديل</button>
                         </div>
                      </section>
                   </div>

                   {/* الشريط الجانبي - النتائج والأحداث */}
                   <div className="lg:col-span-4 space-y-10">
                      <section className="bg-slate-900 text-white p-10 rounded-[4rem] border-8 border-orange-600 shadow-2xl text-center">
                         <h3 className="text-xl font-black text-orange-400 mb-10 uppercase tracking-widest">مركز النتائج</h3>
                         <div className="flex justify-center items-center gap-6">
                            <input type="number" className="w-24 h-24 bg-white text-slate-900 rounded-[2.5rem] text-center font-black text-5xl border-8 border-orange-600" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                            <span className="text-6xl font-black text-orange-600">:</span>
                            <input type="number" className="w-24 h-24 bg-white text-slate-900 rounded-[2.5rem] text-center font-black text-5xl border-8 border-slate-300" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                         </div>
                      </section>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}

      {/* نافذة تقييم لاعب المباراة */}
      {evalPlayer && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-2xl z-[600] flex items-center justify-center p-4">
           <div className="bg-white rounded-[3rem] w-full max-w-xl border-[8px] border-white shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
              <div className="bg-[#001F3F] p-8 flex justify-between items-center border-b-8 border-orange-600">
                 <div className="flex items-center gap-4">
                    <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center font-black text-3xl text-[#001F3F] uppercase border-4 border-orange-600">
                       {evalPlayer.name.charAt(0)}
                    </div>
                    <div>
                       <h4 className="text-white font-black text-xl">تقييم الأداء: {evalPlayer.name}</h4>
                       <p className="text-orange-400 font-bold text-xs uppercase tracking-widest">مباراة ضد: {activeMatch?.opponent}</p>
                    </div>
                 </div>
                 <button onClick={() => setEvalPlayer(null)} className="text-white hover:rotate-90 transition-all"><X size={32}/></button>
              </div>

              <div className="p-8 space-y-10 overflow-y-auto custom-scrollbar">
                 {/* نجوم التقييم */}
                 <div className="text-center space-y-4">
                    <p className="text-[10px] font-black text-[#001F3F] uppercase tracking-[0.3em]">التقييم العام للنجوم</p>
                    <div className="flex justify-center gap-3">
                       {[1,2,3,4,5].map(s => (
                         <button key={s} onClick={() => setEvalData({...evalData, stars: s})} className="transition-all hover:scale-125 active:scale-90">
                            <Star size={40} fill={s <= evalData.stars ? "#FFB800" : "none"} className={s <= evalData.stars ? "text-[#FFB800]" : "text-slate-200"} />
                         </button>
                       ))}
                    </div>
                 </div>

                 {/* السلايدرات الفنية للمباراة */}
                 <div className="space-y-8">
                    {[
                      { label: 'الجهد البدني (Effort)', key: 'effort', color: 'accent-orange-600' },
                      { label: 'الانضباط التكتيكي (Discipline)', key: 'discipline', color: 'accent-blue-900' },
                      { label: 'التأثير الفني (Impact)', key: 'impact', color: 'accent-emerald-600' }
                    ].map(item => (
                       <div key={item.key} className="space-y-3">
                          <div className="flex justify-between items-center">
                             <span className="text-xs font-black text-[#001F3F]">{item.label}</span>
                             <span className="bg-slate-100 px-3 py-1 rounded-lg text-xs font-black text-[#001F3F] border border-slate-200">{evalData[item.key as keyof typeof evalData]}%</span>
                          </div>
                          <input 
                            type="range" min="0" max="100" step="1"
                            value={evalData[item.key as keyof typeof evalData]}
                            onChange={(e) => setEvalData({...evalData, [item.key]: parseInt(e.target.value)})}
                            className={`w-full h-3 bg-slate-100 rounded-lg appearance-none cursor-pointer ${item.color}`}
                          />
                       </div>
                    ))}
                 </div>

                 {/* تعليق المباراة */}
                 <div className="space-y-3">
                    <label className="text-[10px] font-black text-[#001F3F] uppercase block tracking-widest mr-2">ملاحظات المدرب على الأداء</label>
                    <textarea 
                      value={evalData.note}
                      onChange={(e) => setEvalData({...evalData, note: e.target.value})}
                      className="w-full h-32 bg-slate-50 border-2 border-slate-900 rounded-[2rem] p-6 font-bold text-sm text-[#001F3F] outline-none focus:border-orange-600 transition-all resize-none shadow-inner"
                      placeholder="صف أداء اللاعب، تحركاته، الأخطاء المرتكبة..."
                    ></textarea>
                 </div>
              </div>

              <div className="p-8 border-t-2 border-slate-100">
                 <button 
                  onClick={handleSavePlayerEval}
                  disabled={isSavingEval}
                  className="w-full bg-[#001F3F] text-white py-6 rounded-[2.5rem] font-black text-xl flex items-center justify-center gap-4 hover:bg-black transition-all border-b-8 border-black active:translate-y-2 active:border-b-0"
                 >
                    {isSavingEval ? <Loader2 className="animate-spin"/> : <Sparkles size={24} className="text-orange-400"/>}
                    تثبيت تقييم المباراة
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Star, Sparkles, Heart, Loader2
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person, PlayerEvaluation } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);

  // حالة تقييم اللاعب الفردي في المباراة
  const [evalPlayer, setEvalPlayer] = useState<Person | null>(null);
  const [evalData, setEvalData] = useState({ stars: 3, effort: 70, discipline: 70, impact: 70, note: '' });
  const [isSavingEval, setIsSavingEval] = useState(false);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';
  // Define globalFilter variable from state to fix ReferenceError
  const globalFilter = state.globalCategoryFilter;

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة'
  });

  useEffect(() => {
    if (isAddOpen) {
      setFormData(prev => ({
        ...prev,
        category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter)
      }));
    }
  }, [isAddOpen, state.globalCategoryFilter, state.categories, restrictedCat]);

  useEffect(() => {
    if (activeMatch && !isViewer) {
      const newLineup = { ...activeMatch.lineup };
      let hasChanged = false;
      const st1 = parseInt(activeMatch.stoppageTime1 || '0') || 0;
      const st2 = parseInt(activeMatch.stoppageTime2 || '0') || 0;

      newLineup.subs.forEach((s) => {
        if (s.substitutionMinute && s.replacedPlayerId) {
          const minute = parseInt(s.substitutionMinute) || 0;
          let subMins = 0;
          if (minute <= 45) {
            subMins = (45 - minute) + st1 + 45 + st2;
          } else {
            subMins = (90 - minute) + st2;
          }
          if (s.minutesPlayed !== subMins.toString()) {
            s.minutesPlayed = subMins.toString();
            hasChanged = true;
          }

          const starterIdx = newLineup.starters.findIndex(st => st.playerId === s.replacedPlayerId);
          if (starterIdx !== -1) {
            let stMins = 0;
            if (minute <= 45) {
              stMins = minute;
            } else {
              stMins = 45 + st1 + (minute - 45);
            }
            if (newLineup.starters[starterIdx].minutesPlayed !== stMins.toString()) {
              newLineup.starters[starterIdx].minutesPlayed = stMins.toString();
              hasChanged = true;
            }
          }
        }
      });

      if (hasChanged) {
        setActiveMatch(prev => prev ? { ...prev, lineup: newLineup } : null);
      }
    }
  }, [activeMatch?.stoppageTime1, activeMatch?.stoppageTime2]);

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      // Fixed: Using the globalFilter variable defined above
      return (state.globalCategoryFilter === 'الكل' || m.category === globalFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat, globalFilter]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isViewer) return;
    const finalCategory = restrictedCat || formData.category;
    if (!formData.opponent || !formData.date || !formData.time || !finalCategory) return;
    const newMatch: Match = {
      id: generateUUID(),
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time,
      category: finalCategory,
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: { starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '90' })), subs: [], staff: [], captain: '' },
      notes: ''
    };
    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    setIsAddOpen(false);
  };

  const openEvalModal = (playerId: string) => {
    const person = state.people.find(p => p.id === playerId);
    if (!person) return;

    // محاولة إيجاد تقييم موجود مسبقاً لهذه المباراة
    const existing = state.evaluations.find(e => e.playerId === playerId && e.matchId === activeMatch?.id);
    if (existing) {
       setEvalData({ stars: existing.stars, effort: existing.effort || 70, discipline: existing.discipline || 70, impact: existing.impact || 70, note: existing.coachNote || '' });
    } else {
       setEvalData({ stars: 3, effort: 70, discipline: 70, impact: 70, note: '' });
    }
    setEvalPlayer(person);
  };

  const handleSavePlayerEval = async () => {
    if (!evalPlayer || !activeMatch) return;
    setIsSavingEval(true);
    try {
      const newEval: PlayerEvaluation = {
        id: state.evaluations.find(e => e.playerId === evalPlayer.id && e.matchId === activeMatch.id)?.id || generateUUID(),
        playerId: evalPlayer.id,
        matchId: activeMatch.id,
        date: activeMatch.date,
        physical: evalData.effort, // استخدام الجهد كبديل للبدني في تقييم المباراة
        tactical: 70, // قيم افتراضية لعدم توفرها في تقييم المباراة السريع
        technical: 70,
        mental: 70,
        speed: 70,
        stars: evalData.stars,
        effort: evalData.effort,
        discipline: evalData.discipline,
        impact: evalData.impact,
        coachNote: evalData.note
      };

      const { error } = await supabase.from('player_evaluations').upsert(newEval);
      if (error) throw error;

      setState(prev => ({
        ...prev,
        evaluations: [...prev.evaluations.filter(e => e.id !== newEval.id), newEval]
      }));

      addLog?.('تقييم لاعب', `تم تقييم أداء ${evalPlayer.name} في مباراة ${activeMatch.opponent}`, 'success');
      setEvalPlayer(null);
    } catch (err: any) {
      alert("خطأ: " + err.message);
    } finally {
      setIsSavingEval(false);
    }
  };

  const updateActiveMatchLineup = (index: number, playerId: string, isStarter: boolean) => {
    if (!activeMatch || isViewer) return;
    const person = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (!person) {
      if (isStarter) newLineup.starters[index] = { ...newLineup.starters[index], playerId: '', name: '', number: '' };
    } else {
      if (isStarter) newLineup.starters[index] = { ...newLineup.starters[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const saveMatchDetails = () => {
    if (!activeMatch || isViewer) return;
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, isCompleted: true } : m)
    }));
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [...activeMatch!.lineup.starters.map(s => s.playerId), ...activeMatch!.lineup.subs.map(s => s.playerId)].filter(id => id && id !== currentId);
    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const fieldClass = "w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-[#001F3F] mr-2 uppercase block mb-1.5";

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div><h2 className="text-xl font-black text-slate-900 flex items-center gap-3"><Trophy size={24} className="text-orange-600" /> إدارة أجندة المباريات المركزية</h2></div>
        <div className="flex gap-3">
          <button onClick={() => setShowPrintView(true)} className="bg-white text-slate-900 border-2 border-slate-900 px-6 py-3 rounded-xl font-black text-sm">طباعة الأجندة</button>
          {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black text-sm">جدولة مواجهة</button>}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative border-b-8 transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-6"><span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span><span className="text-[10px] font-black text-slate-900">{m.date} - {m.category}</span></div>
             <div className="text-center mb-6"><p className="text-3xl font-black text-slate-900">{m.ourScore} - {m.opponentScore}</p><p className="font-black text-sm text-slate-700 mt-2">{m.opponent}</p></div>
             <div className="flex flex-col gap-2"><button onClick={() => setActiveMatch(m)} className="w-full bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs">التشكيل والتقرير</button></div>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/98 backdrop-blur-2xl z-[400] overflow-y-auto no-print">
           <div className="max-w-7xl mx-auto p-4 lg:p-12 min-h-screen text-right" dir="rtl">
              <div className="bg-white rounded-[4rem] border-[10px] border-slate-900 p-8 lg:p-12 shadow-2xl relative">
                <header className="relative flex flex-col md:flex-row justify-between items-center mb-12 border-b-8 border-slate-900 pb-10 gap-6">
                   <div className="flex items-center gap-6"><div className="bg-[#001F3F] text-white w-24 h-24 rounded-[2rem] flex items-center justify-center font-black text-4xl border-4 border-slate-900 shadow-2xl animate-pulse">K</div><div><h2 className="text-4xl font-black text-slate-900 tracking-tighter">الكرامة <span className="text-orange-600">×</span> {activeMatch.opponent}</h2></div></div>
                   <div className="flex gap-4">
                      <button onClick={saveMatchDetails} className="bg-emerald-600 text-white px-10 py-5 rounded-[2rem] font-black text-lg border-b-8 border-emerald-900"><span className="flex items-center gap-3"><Save size={24}/> حفظ التقرير الفني</span></button>
                      <button onClick={() => setActiveMatch(null)} className="bg-white text-slate-900 px-8 py-5 rounded-[2rem] font-black text-lg border-4 border-slate-900 shadow-xl"><X size={24}/></button>
                   </div>
                </header>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                   <div className="lg:col-span-8 space-y-12">
                      <section>
                         <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter mb-8 border-r-4 border-orange-600 pr-4">التشكيلة الأساسية</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="bg-white p-6 rounded-[2.5rem] border-4 border-slate-900 shadow-xl flex flex-col relative group">
                                  <div className="flex justify-between items-start mb-4">
                                     <div className="w-14 h-14 bg-slate-900 text-white rounded-[1.5rem] flex items-center justify-center font-black text-2xl border-2 border-white">{s.number || (idx + 1)}</div>
                                     {s.playerId && (
                                       <button onClick={() => openEvalModal(s.playerId)} className="p-3 bg-orange-100 text-orange-600 rounded-[1.2rem] border-2 border-orange-200 hover:bg-orange-600 hover:text-white transition-all">
                                          <Star size={20} />
                                       </button>
                                     )}
                                  </div>
                                  <select className="w-full bg-slate-50 border-2 border-slate-400 rounded-xl p-3 font-black text-sm" value={s.playerId} onChange={e => updateActiveMatchLineup(idx, e.target.value, true)}>
                                     <option value="">-- اختر لاعب --</option>
                                     {getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>)}
                                  </select>
                               </div>
                            ))}
                         </div>
                      </section>

                      <section>
                         <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter mb-8 border-r-4 border-blue-900 pr-4">البدلاء</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {activeMatch.lineup.subs.map((s, idx) => (
                               <div key={idx} className="bg-slate-50 p-6 rounded-[2.5rem] border-4 border-slate-300 flex flex-col space-y-4">
                                  <div className="flex justify-between items-center">
                                     <span className="text-[11px] font-black text-blue-900 uppercase">البديل #{idx+1}</span>
                                     {s.playerId && <button onClick={() => openEvalModal(s.playerId)} className="p-2 bg-orange-100 text-orange-600 rounded-lg"><Star size={16}/></button>}
                                  </div>
                                  <select className="w-full bg-white border-2 border-slate-400 rounded-xl p-2.5 font-black text-xs" value={s.playerId} onChange={e => {
                                     const newSubs = [...activeMatch.lineup.subs];
                                     const p = state.people.find(x => x.id === e.target.value);
                                     newSubs[idx] = { ...newSubs[idx], playerId: p?.id || '', name: p?.name || '', number: p?.number?.toString() || '' };
                                     setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
                                  }}>
                                     <option value="">-- اختر لاعب --</option>
                                     {getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>)}
                                  </select>
                               </div>
                            ))}
                            <button onClick={() => setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: [...activeMatch.lineup.subs, {playerId: '', name: '', number: ''}]}})} className="border-4 border-dashed border-slate-200 p-8 rounded-[2.5rem] font-black text-slate-300 hover:border-blue-900 hover:text-blue-900 transition-all">+ إضافة بديل</button>
                         </div>
                      </section>
                   </div>

                   {/* الشريط الجانبي - النتائج والأحداث */}
                   <div className="lg:col-span-4 space-y-10">
                      <section className="bg-slate-900 text-white p-10 rounded-[4rem] border-8 border-orange-600 shadow-2xl text-center">
                         <h3 className="text-xl font-black text-orange-400 mb-10 uppercase tracking-widest">مركز النتائج</h3>
                         <div className="flex justify-center items-center gap-6">
                            <input type="number" className="w-24 h-24 bg-white text-slate-900 rounded-[2.5rem] text-center font-black text-5xl border-8 border-orange-600" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                            <span className="text-6xl font-black text-orange-600">:</span>
                            <input type="number" className="w-24 h-24 bg-white text-slate-900 rounded-[2.5rem] text-center font-black text-5xl border-8 border-slate-300" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                         </div>
                      </section>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}

      {/* نافذة تقييم لاعب المباراة */}
      {evalPlayer && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-2xl z-[600] flex items-center justify-center p-4">
           <div className="bg-white rounded-[3rem] w-full max-w-xl border-[8px] border-white shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
              <div className="bg-[#001F3F] p-8 flex justify-between items-center border-b-8 border-orange-600">
                 <div className="flex items-center gap-4">
                    <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center font-black text-3xl text-[#001F3F] uppercase border-4 border-orange-600">
                       {evalPlayer.name.charAt(0)}
                    </div>
                    <div>
                       <h4 className="text-white font-black text-xl">تقييم الأداء: {evalPlayer.name}</h4>
                       <p className="text-orange-400 font-bold text-xs uppercase tracking-widest">مباراة ضد: {activeMatch?.opponent}</p>
                    </div>
                 </div>
                 <button onClick={() => setEvalPlayer(null)} className="text-white hover:rotate-90 transition-all"><X size={32}/></button>
              </div>

              <div className="p-8 space-y-10 overflow-y-auto custom-scrollbar">
                 {/* نجوم التقييم */}
                 <div className="text-center space-y-4">
                    <p className="text-[10px] font-black text-[#001F3F] uppercase tracking-[0.3em]">التقييم العام للنجوم</p>
                    <div className="flex justify-center gap-3">
                       {[1,2,3,4,5].map(s => (
                         <button key={s} onClick={() => setEvalData({...evalData, stars: s})} className="transition-all hover:scale-125 active:scale-90">
                            <Star size={40} fill={s <= evalData.stars ? "#FFB800" : "none"} className={s <= evalData.stars ? "text-[#FFB800]" : "text-slate-200"} />
                         </button>
                       ))}
                    </div>
                 </div>

                 {/* السلايدرات الفنية للمباراة */}
                 <div className="space-y-8">
                    {[
                      { label: 'الجهد البدني (Effort)', key: 'effort', color: 'accent-orange-600' },
                      { label: 'الانضباط التكتيكي (Discipline)', key: 'discipline', color: 'accent-blue-900' },
                      { label: 'التأثير الفني (Impact)', key: 'impact', color: 'accent-emerald-600' }
                    ].map(item => (
                       <div key={item.key} className="space-y-3">
                          <div className="flex justify-between items-center">
                             <span className="text-xs font-black text-[#001F3F]">{item.label}</span>
                             <span className="bg-slate-100 px-3 py-1 rounded-lg text-xs font-black text-[#001F3F] border border-slate-200">{evalData[item.key as keyof typeof evalData]}%</span>
                          </div>
                          <input 
                            type="range" min="0" max="100" step="1"
                            value={evalData[item.key as keyof typeof evalData]}
                            onChange={(e) => setEvalData({...evalData, [item.key]: parseInt(e.target.value)})}
                            className={`w-full h-3 bg-slate-100 rounded-lg appearance-none cursor-pointer ${item.color}`}
                          />
                       </div>
                    ))}
                 </div>

                 {/* تعليق المباراة */}
                 <div className="space-y-3">
                    <label className="text-[10px] font-black text-[#001F3F] uppercase block tracking-widest mr-2">ملاحظات المدرب على الأداء</label>
                    <textarea 
                      value={evalData.note}
                      onChange={(e) => setEvalData({...evalData, note: e.target.value})}
                      className="w-full h-32 bg-slate-50 border-2 border-slate-900 rounded-[2rem] p-6 font-bold text-sm text-[#001F3F] outline-none focus:border-orange-600 transition-all resize-none shadow-inner"
                      placeholder="صف أداء اللاعب، تحركاته، الأخطاء المرتكبة..."
                    ></textarea>
                 </div>
              </div>

              <div className="p-8 border-t-2 border-slate-100">
                 <button 
                  onClick={handleSavePlayerEval}
                  disabled={isSavingEval}
                  className="w-full bg-[#001F3F] text-white py-6 rounded-[2.5rem] font-black text-xl flex items-center justify-center gap-4 hover:bg-black transition-all border-b-8 border-black active:translate-y-2 active:border-b-0"
                 >
                    {isSavingEval ? <Loader2 className="animate-spin"/> : <Sparkles size={24} className="text-orange-400"/>}
                    تثبيت تقييم المباراة
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
