  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onMatchClick: (id: string) => void;
  onSessionClick: (id: string) => void;
  onPlayerClick?: (player: Person) => void;
}

const LiveCountdownCard: React.FC<{ 
  activity: Match | TrainingSession;
  type: 'match' | 'training';
  onClick: () => void;
  onEdit?: () => void;
}> = ({ activity, type, onClick, onEdit }) => {
  const [timeLeft, setTimeLeft] = useState<{ days: number, hours: number, minutes: number, seconds: number, isLive: boolean } | null>(null);

  useEffect(() => {
    const calculate = () => {
      const target = new Date(`${activity.date}T${activity.time}`);
      const now = new Date();
      const diff = target.getTime() - now.getTime();

      const liveDuration = type === 'match' ? 120 * 60 * 1000 : 90 * 60 * 1000;
      const isLive = diff <= 0 && Math.abs(diff) < liveDuration;

      if (diff <= 0 && !isLive) {
        setTimeLeft(null); 
        return;
      }

      const d = Math.floor(diff / (1000 * 60 * 60 * 24));
      const h = Math.floor((diff / (1000 * 60 * 60)) % 24);
      const m = Math.floor((diff / (1000 * 60)) % 60);
      const s = Math.floor((diff / 1000) % 60);

      setTimeLeft({ days: d, hours: h, minutes: m, seconds: s, isLive });
    };

    calculate();
    const interval = setInterval(calculate, 1000);
    return () => clearInterval(interval);
  }, [activity.date, activity.time, type]);

  if (!timeLeft) return null;

  const title = type === 'match' ? `نادي الكرامة × ${(activity as Match).opponent}` : (activity as TrainingSession).objective;
  const subtitle = type === 'match' ? `${(activity as Match).matchType} | فئة: ${activity.category}` : `حصة تدريبية لفئة: ${activity.category}`;

  return (
    <div 
      className={`relative w-full overflow-hidden p-6 md:p-8 rounded-[2.5rem] border-4 transition-all duration-500 shadow-2xl ${
        timeLeft.isLive 
        ? 'bg-red-950 border-red-600 animate-pulse' 
        : 'bg-[#001F3F] border-[#FF6B00]'
      }`}
    >
      <div className="absolute -top-4 -left-4 p-8 opacity-10 pointer-events-none">
        {type === 'match' ? <Trophy size={160} /> : <Calendar size={160} />}
      </div>

      <div className="relative z-10 flex flex-col items-start text-right h-full">
        <div className="flex items-center gap-3 mb-4 w-full">
           {timeLeft.isLive ? (
             <div className="flex items-center gap-2 bg-red-600 text-white px-5 py-2 rounded-full text-[10px] md:text-[12px] font-black uppercase shadow-[0_0_20px_rgba(220,38,38,0.5)]">
                <div className="w-2.5 h-2.5 bg-white rounded-full animate-ping"></div>
                بث مباشر الآن (LIVE)
             </div>
           ) : (
             <div className="bg-[#FF6B00] text-white px-5 py-2 rounded-full text-[10px] md:text-[12px] font-black uppercase tracking-widest shadow-lg">
                {type === 'match' ? 'المواجهة القادمة' : 'الحصة التدريبية القادمة'}
             </div>
           )}
           <div className="flex-1"></div>
           <span className="text-[10px] md:text-[12px] font-bold text-white/40 uppercase tracking-tighter tabular-nums">{activity.date} @ {activity.time}</span>
        </div>

        <h3 className="text-2xl md:text-3xl font-black text-white mb-2 drop-shadow-xl tracking-tight leading-tight">{title}</h3>
        <p className="text-xs md:text-sm font-bold text-[#FF6B00] mb-8 uppercase tracking-[0.2em] opacity-80">{subtitle}</p>

        <div className="mt-auto w-full flex flex-col md:flex-row items-end justify-between gap-6">
          {timeLeft.isLive ? (
            <div className="flex flex-col items-start gap-2 py-4">
               <p className="text-white font-black text-xl md:text-2xl animate-pulse">النشاط جارٍ الآن</p>
            </div>
          ) : (
            <div className="flex gap-4 md:gap-8 items-end">
              <div className="flex flex-col items-center">
                <span className="text-3xl md:text-4xl font-black text-white font-mono tabular-nums">{String(timeLeft.days).padStart(2, '0')}</span>
                <span className="text-[8px] md:text-[10px] font-black text-white/40 uppercase tracking-widest mt-1">يوم</span>
              </div>
              <span className="text-3xl md:text-4xl font-black text-[#FF6B00] mb-4">:</span>
              <div className="flex flex-col items-center">
                <span className="text-3xl md:text-4xl font-black text-white font-mono tabular-nums">{String(timeLeft.hours).padStart(2, '0')}</span>
                <span className="text-[8px] md:text-[10px] font-black text-white/40 uppercase tracking-widest mt-1">ساعة</span>
              </div>
              <span className="text-3xl md:text-4xl font-black text-[#FF6B00] mb-4">:</span>
              <div className="flex flex-col items-center">
                <span className="text-3xl md:text-4xl font-black text-white font-mono tabular-nums">{String(timeLeft.minutes).padStart(2, '0')}</span>
                <span className="text-[8px] md:text-[10px] font-black text-white/40 uppercase tracking-widest mt-1">دقيقة</span>
              </div>
            </div>
          )}

          <div className="flex gap-2 w-full md:w-auto">
             {type === 'match' && onEdit && (
               <button 
                onClick={(e) => { e.stopPropagation(); onEdit(); }}
                className="flex-1 md:flex-none bg-white text-[#001F3F] px-6 py-3 rounded-2xl font-black text-xs flex items-center justify-center gap-2 hover:bg-orange-50 transition-all border-b-4 border-slate-300"
               >
                 <Edit size={16}/> تعديل سريع
               </button>
             )}
             <button 
              onClick={onClick}
              className="flex-1 md:flex-none bg-[#FF6B00] text-white px-6 py-3 rounded-2xl font-black text-xs flex items-center justify-center gap-2 hover:bg-black transition-all border-b-4 border-black/30"
             >
               فتح التفاصيل
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

