const LiveCountdownCard: React.FC<{ 
  activity: Match | TrainingSession;
  type: 'match' | 'training';
  onClick: () => void;
  onEdit?: () => void;
}> = ({ activity, type, onClick, onEdit }) => {
  const [timeLeft, setTimeLeft] = useState<{ days: number, hours: number, minutes: number, seconds: number, isLive: boolean } | null>(null);

  useEffect(() => {
    const calculate = () => {
      const target = new Date(`${activity.date}T${activity.time}`);
      const now = new Date();
      const diff = target.getTime() - now.getTime();

      const liveDuration = type === 'match' ? 120 * 60 * 1000 : 90 * 60 * 1000;
      const isLive = diff <= 0 && Math.abs(diff) < liveDuration;

      if (diff <= 0 && !isLive) {
        setTimeLeft(null); 
        return;
      }

      const d = Math.floor(diff / (1000 * 60 * 60 * 24));
      const h = Math.floor((diff / (1000 * 60 * 60)) % 24);
      const m = Math.floor((diff / (1000 * 60)) % 60);
      const s = Math.floor((diff / 1000) % 60);

      setTimeLeft({ days: d, hours: h, minutes: m, seconds: s, isLive });
    };

    calculate();
    const interval = setInterval(calculate, 1000);
    return () => clearInterval(interval);
  }, [activity.date, activity.time, type]);

  if (!timeLeft) return null;

  const title = type === 'match' ? `الكرامة × ${(activity as Match).opponent}` : (activity as TrainingSession).objective;
  const subtitle = type === 'match' ? `${(activity as Match).matchType} | فئة: ${activity.category}` : `حصة تدريبية | فئة: ${activity.category}`;

  return (
    <div 
      className={`relative w-full overflow-hidden p-6 md:p-8 rounded-[2.5rem] border-4 transition-all duration-500 shadow-2xl ${
        timeLeft.isLive 
        ? 'bg-red-950 border-red-600 animate-pulse' 
        : 'bg-[#001F3F] border-[#FF6B00]'
      }`}
    >
      <div className="absolute -top-4 -left-4 p-8 opacity-10 pointer-events-none group-hover:rotate-12 transition-transform duration-700">
        {type === 'match' ? <Trophy size={140} /> : <Calendar size={140} />}
      </div>

      <div className="relative z-10 flex flex-col items-start text-right">
        <div className="flex items-center gap-3 mb-4 w-full">
           {timeLeft.isLive ? (
             <div className="flex items-center gap-2 bg-red-600 text-white px-4 py-1.5 rounded-full text-[10px] font-black uppercase shadow-lg">
                <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>
                بث مباشر (LIVE)
             </div>
           ) : (
             <div className="bg-[#FF6B00] text-white px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest shadow-md">
                {type === 'match' ? 'مواجهة منتظرة' : 'تمرين مبرمج'}
             </div>
           )}
           <div className="flex-1"></div>
           <span className="text-[10px] font-bold text-white/50 uppercase tracking-tighter tabular-nums">{activity.date} | {activity.time}</span>
        </div>

        <h3 className="text-xl md:text-2xl font-black text-white mb-2 drop-shadow-lg tracking-tight line-clamp-1">{title}</h3>
        <p className="text-[10px] font-bold text-[#FF6B00] mb-8 uppercase tracking-[0.2em] opacity-80">{subtitle}</p>

        <div className="flex flex-wrap items-end justify-between w-full gap-4">
           {timeLeft.isLive ? (
             <div className="flex flex-col items-start gap-1 py-2">
                <p className="text-white font-black text-lg animate-pulse">النشاط جارٍ الآن</p>
                <div className="flex items-center gap-2 text-red-400 text-[10px] font-bold">
                   <Activity size={14} /> انتقل للرصد المباشر
                </div>
             </div>
           ) : (
             <div className="flex gap-4 items-end">
                <div className="flex flex-col items-center">
                  <span className="text-2xl md:text-3xl font-black text-white tabular-nums">{String(timeLeft.days).padStart(2, '0')}</span>
                  <span className="text-[8px] font-black text-white/40 uppercase">يوم</span>
                </div>
                <span className="text-xl font-black text-[#FF6B00] mb-3">:</span>
                <div className="flex flex-col items-center">
                  <span className="text-2xl md:text-3xl font-black text-white tabular-nums">{String(timeLeft.hours).padStart(2, '0')}</span>
                  <span className="text-[8px] font-black text-white/40 uppercase">ساعة</span>
                </div>
                <span className="text-xl font-black text-[#FF6B00] mb-3">:</span>
                <div className="flex flex-col items-center">
                  <span className="text-2xl md:text-3xl font-black text-white tabular-nums">{String(timeLeft.minutes).padStart(2, '0')}</span>
                  <span className="text-[8px] font-black text-white/40 uppercase">دقيقة</span>
                </div>
             </div>
           )}

           <div className="flex gap-2">
              {type === 'match' && onEdit && (
                <button 
                  onClick={(e) => { e.stopPropagation(); onEdit(); }}
                  className="bg-white/10 hover:bg-white/20 text-white p-3 rounded-2xl transition-all border border-white/10 shadow-lg group/btn"
                >
                   <Edit size={18} className="group-hover/btn:text-[#FF6B00] transition-colors" />
