                onClick={onClick}
                className="bg-[#FF6B00] text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase shadow-lg border-b-4 border-black/30 hover:bg-black transition-all"
              >
                فتح التفاصيل
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

