import React, { useState, useMemo, useEffect } from 'react';
import { Users, Calendar, Trophy, Clock, MapPin, AlertCircle, ChevronLeft, ShieldAlert, Filter, Printer, FileText, ClipboardCheck, Zap, Activity, TrendingUp, Search, X, BellRing, AlertTriangle, Timer, Edit, Save, Loader2 } from 'lucide-react';
import { AppState, Person, Match, TrainingSession } from '../types';

interface DashboardProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onMatchClick: (id: string) => void;
  onSessionClick: (id: string) => void;
  onPlayerClick?: (player: Person) => void;
}

const LiveCountdownCard: React.FC<{ 
  activity: Match | TrainingSession; 
  type: 'match' | 'session'; 
  onAction: () => void;
  onEdit?: () => void;
}> = ({ activity, type, onAction, onEdit }) => {
  const [timeLeft, setTimeLeft] = useState<{ d: number, h: number, m: number, s: number } | null>(null);

  useEffect(() => {
    const timer = setInterval(() => {
      const target = new Date(`${activity.date}T${activity.time}`);
      const now = new Date();
      const diff = target.getTime() - now.getTime();

      if (diff <= 0) {
        setTimeLeft(null);
        clearInterval(timer);
      } else {
        setTimeLeft({
          d: Math.floor(diff / (1000 * 60 * 60 * 24)),
          h: Math.floor((diff / (1000 * 60 * 60)) % 24),
          m: Math.floor((diff / (1000 * 60)) % 60),
          s: Math.floor((diff / 1000) % 60)
        });
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [activity.date, activity.time]);

  const isMatch = type === 'match';
  const title = isMatch ? `الكرامة × ${(activity as Match).opponent}` : (activity as TrainingSession).objective;

  return (
    <div className="solid-panel p-6 relative overflow-hidden group transition-all hover:scale-[1.02] hover:border-orange-600 border-b-8">
       <div className="flex justify-between items-start mb-4">
          <div className={`p-3 rounded-2xl ${isMatch ? 'bg-orange-600' : 'bg-[#001F3F]'} text-white shadow-lg`}>
             {isMatch ? <Trophy size={24}/> : <Calendar size={24}/>}
          </div>
          <div className="text-left">
             <span className="text-[10px] font-black text-slate-400 uppercase tracking-tighter tabular-nums">{activity.date} @ {activity.time}</span>
          </div>
       </div>

       <h3 className="text-xl font-black text-[#001F3F] mb-1 line-clamp-1">{title}</h3>
       <p className="text-[10px] font-bold text-orange-600 uppercase tracking-widest mb-6">{activity.category}</p>

       <div className="bg-slate-50 p-4 rounded-2xl border-2 border-slate-100 flex justify-between items-center mb-6">
          {timeLeft ? (
            <div className="flex gap-4 items-center">
               <div className="flex flex-col items-center">
                  <span className="text-xl font-black text-[#001F3F] tabular-nums">{timeLeft.d}</span>
                  <span className="text-[7px] font-black uppercase text-slate-400">يوم</span>
               </div>
               <span className="font-black text-slate-200">:</span>
               <div className="flex flex-col items-center">
                  <span className="text-xl font-black text-[#001F3F] tabular-nums">{String(timeLeft.h).padStart(2, '0')}</span>
                  <span className="text-[7px] font-black uppercase text-slate-400">ساعة</span>
               </div>
               <span className="font-black text-slate-200">:</span>
               <div className="flex flex-col items-center">
                  <span className="text-xl font-black text-[#001F3F] tabular-nums">{String(timeLeft.m).padStart(2, '0')}</span>
                  <span className="text-[7px] font-black uppercase text-slate-400">دقيقة</span>
               </div>
            </div>
          ) : (
            <span className="text-xs font-black text-emerald-600 animate-pulse flex items-center gap-2">
               <div className="w-2 h-2 bg-emerald-500 rounded-full"></div> النشاط جارٍ الآن
            </span>
          )}
          <Timer size={20} className="text-slate-200" />
       </div>

       <div className="flex gap-2">
          {isMatch && (
            <button onClick={onEdit} className="flex-1 bg-white border-2 border-[#001F3F] text-[#001F3F] py-3 rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-2 hover:bg-slate-50">
               <Edit size={14}/> تعديل
            </button>
          )}
          <button onClick={onAction} className={`flex-[2] ${isMatch ? 'bg-orange-600' : 'bg-[#001F3F]'} text-white py-3 rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-2 shadow-md hover:bg-black transition-all border-b-4 border-black/20`}>
             {isMatch ? 'عرض التقرير' : 'رصد الحضور'}
          </button>
       </div>
    </div>
  );
};

const Dashboard: React.FC<DashboardProps> = ({ state, setState, onMatchClick, onSessionClick, onPlayerClick }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [quickEditMatch, setQuickEditMatch] = useState<Match | null>(null);
  const [isSavingEdit, setIsSavingEdit] = useState(false);

  const now = new Date();
  const todayStr = now.toLocaleDateString('en-CA');
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowStr = tomorrow.toLocaleDateString('en-CA');

  const globalFilter = state.globalCategoryFilter;

  const allActivities = useMemo(() => {
    const upcomingMatches = state.matches
      .filter(m => !m.isCompleted && (globalFilter === 'الكل' || m.category === globalFilter))
      .map(m => ({ ...m, activityType: 'match' as const }));

    const upcomingSessions = state.sessions
      .filter(s => !s.isCompleted && (globalFilter === 'الكل' || s.category === globalFilter))
      .map(s => ({ ...s, activityType: 'session' as const }));

    return [...upcomingMatches, ...upcomingSessions].sort((a, b) => {
      const dateA = new Date(`${a.date}T${a.time}`).getTime();
      const dateB = new Date(`${b.date}T${b.time}`).getTime();
      return dateA - dateB;
    });
  }, [state.matches, state.sessions, globalFilter]);

  const handleQuickSaveMatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!quickEditMatch) return;
    setIsSavingEdit(true);
    try {
      setState(prev => ({
        ...prev,
        matches: prev.matches.map(m => m.id === quickEditMatch.id ? quickEditMatch : m)
      }));
      setQuickEditMatch(null);
    } finally {
      setIsSavingEdit(false);
    }
  };

  const hasMatchTomorrow = state.matches.some(m => m.date === tomorrowStr && !m.isCompleted && (globalFilter === 'الكل' || m.category === globalFilter));
  const hasSessionTomorrow = state.sessions.some(s => s.date === tomorrowStr && !s.isCompleted && (globalFilter === 'الكل' || s.category === globalFilter));

  const searchResults = searchTerm.length > 1 
    ? state.people.filter(p => p.name.includes(searchTerm) || p.number?.toString() === searchTerm).slice(0, 5)
    : [];

  const stats = [
    { label: 'الكوادر المسجلة', value: state.people.filter(p => globalFilter === 'الكل' || p.category === globalFilter).length, icon: Users, color: '#001F3F', textColor: '#FF6B00' },
    { label: 'الأنشطة المجدولة', value: allActivities.length, icon: Trophy, color: '#FF6B00', textColor: '#FFFFFF' },
    { label: 'المخزون العام', value: state.warehouse.length, icon: Package, color: '#FFFFFF', textColor: '#001F3F' },
  ];

  return (
    <div className="space-y-6 md:space-y-10 animate-in fade-in duration-700 px-2 md:px-0">

      {/* 1. Global Quick Search */}
      <div className="relative z-[60] no-print max-w-4xl mx-auto w-full">
         <div className="solid-panel !rounded-[2.5rem] p-1 flex items-center border-4 border-[#001F3F] overflow-hidden shadow-2xl transition-all focus-within:scale-[1.01] focus-within:border-[#FF6B00]">
            <div className="p-5"><Search size={28} className="text-[#001F3F]" /></div>
            <input 
              type="text" 
              placeholder="البحث السريع عن ملف لاعب أو إداري..." 
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="flex-1 bg-transparent py-5 font-black text-xl outline-none text-[#001F3F] placeholder:text-slate-300"
            />
            {searchTerm && <button onClick={() => setSearchTerm('')} className="p-5 text-slate-400 hover:text-red-500"><X size={24}/></button>}
         </div>
         {searchResults.length > 0 && (
           <div className="absolute top-full left-0 right-0 mt-3 bg-white border-4 border-[#001F3F] rounded-[2.5rem] shadow-2xl overflow-hidden animate-in slide-in-from-top-4 duration-300 z-[100]">
              {searchResults.map(p => (
                <button 
                  key={p.id} 
                  onClick={() => { onPlayerClick?.(p); setSearchTerm(''); }}
                  className="w-full p-5 flex items-center justify-between border-b-2 border-slate-50 hover:bg-slate-50 text-right transition-colors"
                >
                  <div className="flex items-center gap-5">
                    <div className="w-12 h-12 bg-[#001F3F] text-white rounded-2xl flex items-center justify-center font-black text-lg border-2 border-[#FF6B00]">#{p.number || '0'}</div>
                    <div className="text-right">
                      <p className="font-black text-lg text-[#001F3F]">{p.name}</p>
                      <p className="text-[10px] font-black text-[#FF6B00] uppercase tracking-widest">{p.role} | {p.category}</p>
                    </div>
                  </div>
                  <ChevronLeft size={24} className="text-slate-200"/>
                </button>
              ))}
           </div>
         )}
      </div>

      {/* 2. Professional Activity Feed */}
      <div className="space-y-6">
         <div className="flex items-center justify-between border-r-8 border-orange-600 pr-4">
            <div>
               <h2 className="text-2xl font-black text-white tracking-tighter">الجدول الزمني للأنشطة</h2>
               <p className="text-[10px] font-bold text-orange-400 uppercase tracking-widest">متابعة فورية للمباريات والتدريبات</p>
            </div>
            <span className="bg-white/5 border border-white/10 text-white px-4 py-1.5 rounded-xl text-[10px] font-black">إجمالي: {allActivities.length}</span>
         </div>

         <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4 gap-6">
            {allActivities.map(activity => (
              <LiveCountdownCard 
                key={activity.id} 
                activity={activity} 
                type={activity.activityType}
                onAction={() => activity.activityType === 'match' ? onMatchClick(activity.id) : onSessionClick(activity.id)}
                onEdit={activity.activityType === 'match' ? () => setQuickEditMatch(activity as Match) : undefined}
              />
            ))}
            {allActivities.length === 0 && (
              <div className="col-span-full py-20 text-center bg-[#001F3F]/30 border-4 border-dashed border-white/5 rounded-[3rem] opacity-30 grayscale">
                 <Activity size={80} className="mx-auto mb-4 text-white" />
                 <p className="font-black text-2xl text-white">لا توجد أنشطة مجدولة حالياً</p>
              </div>
            )}
         </div>
      </div>

      {/* 3. Stats KPIs */}
      <div className="grid grid-cols-3 gap-4 md:gap-8">
        {stats.map((s, i) => (
          <div key={i} className="group relative" style={{ color: s.textColor }}>
             <div className="p-6 md:p-12 rounded-[2.5rem] md:rounded-[3.5rem] border-4 border-[#001F3F] flex flex-col items-center shadow-xl transition-all hover:-translate-y-2 active:scale-95" style={{ backgroundColor: s.color }}>
                <div className="p-3 md:p-6 rounded-2xl md:rounded-[2.5rem] mb-2 md:mb-6 border-4 border-current">
                   <s.icon size={24} className="md:w-[48px] md:h-[48px]" />
                </div>
                <h3 className="text-[8px] md:text-[14px] font-black uppercase tracking-[0.3em] opacity-80 mb-2">{s.label}</h3>
                <p className="text-2xl md:text-7xl font-black tabular-nums">{s.value}</p>
             </div>
          </div>
        ))}
      </div>

      {/* Direct Quick Edit Match Modal */}
      {quickEditMatch && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-2xl z-[500] flex items-center justify-center p-4">
           <div className="bg-white rounded-[3rem] w-full max-w-xl border-[8px] border-white shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="bg-[#001F3F] p-8 flex justify-between items-center border-b-8 border-orange-600">
                 <div className="flex items-center gap-4">
                    <Trophy className="text-orange-600" size={32} />
                    <h4 className="text-white font-black text-xl">تعديل سريع: {quickEditMatch.opponent}</h4>
                 </div>
                 <button onClick={() => setQuickEditMatch(null)} className="text-white hover:rotate-90 transition-all"><X size={32}/></button>
              </div>

              <form onSubmit={handleQuickSaveMatch} className="p-8 space-y-6 text-right" dir="rtl">
                 <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                       <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mr-2">نتيجة الكرامة</label>
                       <input type="number" value={quickEditMatch.ourScore} onChange={e => setQuickEditMatch({...quickEditMatch, ourScore: e.target.value})} className="w-full bg-slate-50 border-4 border-[#001F3F] rounded-[1.5rem] p-5 text-center text-3xl font-black text-[#001F3F]" />
                    </div>
                    <div className="space-y-2">
                       <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mr-2">نتيجة الخصم</label>
                       <input type="number" value={quickEditMatch.opponentScore} onChange={e => setQuickEditMatch({...quickEditMatch, opponentScore: e.target.value})} className="w-full bg-slate-50 border-4 border-slate-300 rounded-[1.5rem] p-5 text-center text-3xl font-black text-slate-600" />
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mr-2">الملعب / الموقع</label>
                    <div className="relative">
                       <MapPin className="absolute right-4 top-1/2 -translate-y-1/2 text-orange-600" size={20} />
                       <input type="text" value={quickEditMatch.pitch} onChange={e => setQuickEditMatch({...quickEditMatch, pitch: e.target.value})} className="w-full bg-slate-50 border-2 border-slate-200 rounded-2xl py-4 pr-12 pl-4 font-black" />
                    </div>
                 </div>

                 <button 
                  type="submit" 
                  disabled={isSavingEdit}
                  className="w-full bg-[#001F3F] text-white py-6 rounded-[2.5rem] font-black text-xl flex items-center justify-center gap-4 hover:bg-black transition-all border-b-8 border-black active:translate-y-2 active:border-b-0"
                 >
                    {isSavingEdit ? <Loader2 className="animate-spin"/> : <Save size={24} className="text-orange-600"/>}
                    تثبيت التعديلات الفورية
                 </button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

