const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack, updateStateAndSync }) => {
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // حالة البصمة الفنية التفاعلية
  const [liveMetrics, setLiveMetrics] = useState({
    speed: 70, physical: 70, tactical: 70, technical: 70, mental: 70, stars: 3, coachNote: ''
  });

  useEffect(() => {
    if (player) {
      const latestEval = [...(state.evaluations || [])]
        .filter(e => e.playerId === player.id && !e.matchId)
        .sort((a, b) => b.date.localeCompare(a.date))[0];

      if (latestEval) {
        setLiveMetrics({
          speed: latestEval.speed || 70,
          physical: latestEval.physical || 70,
          tactical: latestEval.tactical || 70,
          technical: latestEval.technical || 70,
          mental: latestEval.mental || 70,
          stars: latestEval.stars || 3,
          coachNote: latestEval.coachNote || ''
        });
      }
    }
  }, [player, state.evaluations]);

  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';

  const matchStats = useMemo(() => {
    if (isStaff) return { officialMins: 0, friendlyMins: 0, goals: 0, assists: 0, list: [] };
    let officialMins = 0;
    let friendlyMins = 0;
    const statsList = state.matches
      .filter(m => m.isCompleted)
      .sort((a, b) => a.date.localeCompare(b.date))
      .map(m => {
        const starter = m.lineup.starters.find(s => s.playerId === player.id);
        const sub = m.lineup.subs.find(s => s.playerId === player.id);
        let mins = starter ? parseInt(starter.minutesPlayed || '90') : (sub ? parseInt(sub.minutesPlayed || '0') : 0);
        const isOfficial = ['دوري', 'كأس', 'مباراة دولية'].includes(m.matchType);
        if (isOfficial) officialMins += mins; else friendlyMins += mins;
        const goals = m.events.filter(e => e.type === 'goal' && (e.player === player.name || e.player === player.id)).length;
        const assists = m.events.filter(e => e.type === 'assist' && (e.player === player.name || e.player === player.id)).length;
        return { opponent: m.opponent, date: m.date, type: m.matchType, isOfficial, mins, goals, assists, played: !!(starter || sub) };
      })
      .filter(s => s.played);
    return { officialMins, friendlyMins, goals: statsList.reduce((a, b) => a + b.goals, 0), assists: statsList.reduce((a, b) => a + b.assists, 0), list: statsList };
  }, [state.matches, player, isStaff]);

  const attendanceData = useMemo(() => {
    const sessions = state.sessions.filter(s => s.category === player.category);
    const sessionIds = sessions.map(s => s.id);
    const allRecords = state.attendance.filter(a => a.personId === player.id && sessionIds.includes(a.sessionId));
    const uniqueRecords = Array.from(new Map(allRecords.map(r => [r.sessionId, r])).values()) as AttendanceRecord[];
    const present = uniqueRecords.filter(r => r.status === 'حاضر').length;
    const late = uniqueRecords.filter(r => r.status === 'متأخر').length;
    const excused = uniqueRecords.filter(r => r.status === 'غياب بعذر').length;
    const totalSessions = sessions.length || 1;
    const weightedAttendance = present + excused + (late * 0.7);
    return { rate: Math.min(100, Math.round((weightedAttendance / totalSessions) * 100)), total: sessions.length, present, late, excused };
  }, [state.attendance, state.sessions, player]);

  const radarPoints = useMemo(() => [
    { label: 'سرعة', key: 'speed', val: liveMetrics.speed },
    { label: 'بدني', key: 'physical', val: liveMetrics.physical },
    { label: 'تكتيك', key: 'tactical', val: liveMetrics.tactical },
    { label: 'تقني', key: 'technical', val: liveMetrics.technical },
    { label: 'ذهني', key: 'mental', val: liveMetrics.mental }
  ], [liveMetrics]);

  const readinessScore = Math.round((liveMetrics.speed + liveMetrics.physical + liveMetrics.tactical + liveMetrics.technical + liveMetrics.mental) / 5);

  const handleSaveEvaluation = async () => {
    if (state.currentUser?.role === 'مشاهد' || !updateStateAndSync) return;
    setIsSaving(true);
    try {
      const newEval: PlayerEvaluation = {
        id: generateUUID(),
        playerId: player.id,
        date: new Date().toISOString().split('T')[0],
        speed: liveMetrics.speed,
        physical: liveMetrics.physical,
        tactical: liveMetrics.tactical,
        technical: liveMetrics.technical,
        mental: liveMetrics.mental,
        stars: liveMetrics.stars,
        coachNote: liveMetrics.coachNote
      };
      updateStateAndSync(prev => ({ ...prev, evaluations: [newEval, ...prev.evaluations] }));
      alert("تم حفظ البصمة الفنية بنجاح.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleGenerateAiAnalysis = async () => {
    setLoadingAi(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `أنت محلل تقني لنادي الكرامة السوري. حلل بيانات اللاعب ${player.name}: دقائق رسمية(${matchStats.officialMins}), ودية(${matchStats.friendlyMins}), أهداف(${matchStats.goals}), التزام(${attendanceData.rate}%). قدم تقريراً مختصراً واحترافياً.`;
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
      setAiAnalysis(response.text || "فشل توليد التحليل.");
    } catch (error: any) { setAiAnalysis("خطأ في الاتصال."); } finally { setLoadingAi(false); }
  };

  const labelStyle = "text-[11px] font-black text-slate-900 uppercase tracking-wider mb-1 block";
  const valueStyle = "text-sm font-bold text-[#001F3F] bg-white p-2.5 rounded-xl border border-slate-200 shadow-sm";

  return (
    <div className="space-y-6 md:space-y-10 animate-in fade-in duration-500 pb-24 px-2 md:px-0 text-right font-['Tajawal']" dir="rtl">
      <div className="flex flex-row justify-between items-center no-print gap-3">
        <button onClick={onBack} className="flex items-center gap-2 text-[#001F3F] font-black bg-white border-2 border-[#001F3F] px-6 py-3 rounded-2xl text-sm shadow-md active:scale-95 transition-all">
          <ChevronRight size={20} /> رجوع للمديرية
        </button>
        <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-2xl font-black text-sm flex items-center gap-2 shadow-xl border-b-4 border-black hover:bg-black transition-all">
          <Printer size={20} /> تصدير التقرير الشامل
        </button>
      </div>

      <div className="solid-panel overflow-hidden relative !shadow-none md:!shadow-[10px_10px_0px_0px_#001F3F] border-4 border-[#001F3F]">
        <div className="bg-[#001F3F] h-28 md:h-40 relative">
          <div className="absolute -bottom-14 right-8 md:right-16 flex items-end gap-6 md:gap-10">
            <div className="w-28 h-28 md:w-48 md:h-48 bg-white rounded-3xl md:rounded-[3rem] border-[6px] md:border-[10px] border-white flex items-center justify-center font-black text-5xl md:text-8xl text-[#001F3F] uppercase shadow-2xl relative z-10">
               {player.name.charAt(0)}
               <div className="absolute -top-4 -left-4 bg-orange-600 text-white w-12 h-12 rounded-full flex items-center justify-center text-xl border-4 border-white">
                  #{player.number || '0'}
               </div>
            </div>
            <div className="mb-4">
              <h1 className="text-2xl md:text-5xl font-black text-white drop-shadow-lg tracking-tight">{player.name}</h1>
              <div className="flex gap-3 mt-2">
                 <span className="bg-orange-600 text-white text-[10px] md:text-[12px] font-black px-4 md:px-6 py-1.5 rounded-xl border-2 border-white uppercase shadow-lg">{player.role}</span>
                 <span className="bg-blue-600 text-white text-[10px] md:text-[12px] font-black px-4 md:px-6 py-1.5 rounded-xl border-2 border-white uppercase shadow-lg">{player.category}</span>
              </div>
            </div>
          </div>
        </div>
        <div className="h-16 md:h-24"></div>
        <div className="px-6 md:px-16 pb-10 grid grid-cols-2 md:grid-cols-5 gap-4 md:gap-8">
           <div className="bg-slate-50 p-4 md:p-6 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <Medal className="text-[#001F3F] mb-2" size={24}/>
             <span className="text-[10px] md:text-[11px] font-black text-slate-900 uppercase">دقائق رسمية</span>
             <p className="text-xl md:text-3xl font-black text-[#001F3F]">{matchStats.officialMins}</p>
           </div>
           <div className="bg-slate-50 p-4 md:p-6 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <Swords className="text-orange-600 mb-2" size={24}/>
             <span className="text-[10px] md:text-[11px] font-black text-slate-900 uppercase">دقائق ودية</span>
             <p className="text-xl md:text-3xl font-black text-[#001F3F]">{matchStats.friendlyMins}</p>
           </div>
           <div className="bg-slate-50 p-4 md:p-6 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <Trophy className="text-blue-600 mb-2" size={24}/>
             <span className="text-[10px] md:text-[11px] font-black text-slate-900 uppercase">الأهداف</span>
             <p className="text-xl md:text-3xl font-black text-[#001F3F]">{matchStats.goals}</p>
           </div>
           <div className="bg-slate-50 p-4 md:p-6 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <Zap className="text-orange-500 mb-2" size={24}/>
             <span className="text-[10px] md:text-[11px] font-black text-slate-900 uppercase">تمريرات حاسمة</span>
             <p className="text-xl md:text-3xl font-black text-[#001F3F]">{matchStats.assists}</p>
           </div>
           <div className="bg-slate-50 p-4 md:p-6 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center col-span-2 md:col-span-1 shadow-sm">
             <TrendingUp className="text-emerald-600 mb-2" size={24}/>
             <span className="text-[10px] md:text-[11px] font-black text-slate-900 uppercase">الالتزام العام</span>
             <p className="text-xl md:text-3xl font-black text-emerald-700">%{attendanceData.rate}</p>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 md:gap-10">
        <div className="lg:col-span-2 space-y-8 md:space-y-10">

          {/* البصمة الفنية التفاعلية (Radar) */}
          <div className="bg-white p-8 md:p-10 rounded-[2.5rem] border-4 border-[#001F3F] shadow-lg">
             <div className="flex justify-between items-center mb-8">
                <h3 className="text-lg md:text-2xl font-black flex items-center gap-3 text-[#001F3F]">
                   <Target className="text-orange-600" size={28}/> البصمة الفنية الحية (Technical Fingerprint)
                </h3>
                <button onClick={handleSaveEvaluation} disabled={isSaving} className="bg-[#001F3F] text-white px-6 py-2 rounded-xl font-black text-xs flex items-center gap-2 hover:bg-black transition-all shadow-md">
                   {isSaving ? <Loader2 className="animate-spin" size={14}/> : <Save size={14}/>} حفظ البصمة الشهرية
                </button>
             </div>

             <div className="flex flex-col md:flex-row items-center gap-12">
                {/* Radar Chart SVG */}
                <div className="w-full md:w-1/2 relative flex justify-center py-6">
                   <div className="relative w-full aspect-square max-w-[300px]">
                      <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-xl">
                         <circle cx="50" cy="50" r="45" fill="none" stroke="#e2e8f0" strokeWidth="0.5" />
                         <circle cx="50" cy="50" r="33.75" fill="none" stroke="#e2e8f0" strokeWidth="0.5" />
                         <circle cx="50" cy="50" r="22.5" fill="none" stroke="#e2e8f0" strokeWidth="0.5" />
                         <circle cx="50" cy="50" r="11.25" fill="none" stroke="#e2e8f0" strokeWidth="0.5" />
                         {[0, 72, 144, 216, 288].map(angle => {
                           const rad = (angle - 90) * Math.PI / 180;
                           return <line key={angle} x1="50" y1="50" x2={50 + 45 * Math.cos(rad)} y2={50 + 45 * Math.sin(rad)} stroke="#cbd5e1" strokeWidth="0.5" />;
                         })}
                         <polygon 
                           points={radarPoints.map((p, i) => {
                             const angle = (i * 72) - 90;
                             const r = (p.val / 100) * 45;
                             const x = 50 + r * Math.cos(angle * Math.PI / 180);
                             const y = 50 + r * Math.sin(angle * Math.PI / 180);
                             return `${x},${y}`;
                           }).join(' ')}
                           fill="rgba(255, 107, 0, 0.4)"
                           stroke="#FF6B00"
                           strokeWidth="3"
                           className="transition-all duration-500"
                         />
                      </svg>
                      {radarPoints.map((p, i) => {
                         const angle = (i * 72) - 90;
                         const x = 50 + 55 * Math.cos(angle * Math.PI / 180);
                         const y = 50 + 55 * Math.sin(angle * Math.PI / 180);
                         return (
                           <div key={i} className="absolute font-black text-[10px] uppercase text-[#001F3F] bg-white/90 px-2 py-0.5 rounded-lg border border-slate-100 shadow-sm" style={{ left: `${x}%`, top: `${y}%`, transform: 'translate(-50%, -50%)' }}>
                             {p.label}
                           </div>
                         );
                      })}
                   </div>
                </div>

                {/* Sliders Control */}
                <div className="w-full md:w-1/2 space-y-6">
                   {radarPoints.map(p => (
                     <div key={p.key} className="space-y-2">
                        <div className="flex justify-between items-center">
                           <span className="text-[11px] font-black text-[#001F3F] uppercase tracking-widest">{p.label}</span>
                           <span className="text-xs font-black text-orange-600">{p.val}%</span>
                        </div>
                        <input 
                          type="range" min="1" max="100" 
                          value={p.val}
                          onChange={e => setLiveMetrics({...liveMetrics, [p.key]: parseInt(e.target.value)})}
                          className="w-full h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-orange-600" 
                        />
                     </div>
                   ))}
                </div>
             </div>

             {/* Readiness State Progress Bar */}
             <div className="mt-12 bg-[#001F3F] p-8 rounded-[2.5rem] relative overflow-hidden shadow-2xl border-b-[10px] border-black">
                <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-16 -mt-16"></div>
                <div className="flex justify-between items-end mb-4 relative z-10">
                   <div>
                      <p className="text-orange-400 font-black text-[10px] uppercase tracking-[0.2em] mb-1">الحالة الجاهزية العامة (Fitness & Readiness)</p>
                      <h4 className="text-white font-black text-2xl tracking-tighter">مؤشر الجاهزية الميدانية</h4>
                   </div>
                   <span className="text-white font-black text-4xl">{readinessScore}%</span>
                </div>
                <div className="h-6 w-full bg-white/10 rounded-full p-1 border border-white/20 relative z-10">
                   <div 
                    className="h-full bg-orange-500 rounded-full transition-all duration-1000 shadow-[0_0_15px_rgba(255,107,0,0.5)]" 
                    style={{ width: `${readinessScore}%` }}
                   ></div>
                </div>
             </div>
          </div>

          {/* Coach Evaluation Box */}
          <div className="bg-white p-8 md:p-10 rounded-[2.5rem] border-4 border-[#001F3F] shadow-md grid grid-cols-1 md:grid-cols-3 gap-8">
             <div className="md:col-span-1 border-l-2 border-slate-100 pl-4">
                <h4 className="text-sm font-black text-[#001F3F] mb-6 flex items-center gap-2">
                   <Award size={20} className="text-orange-600"/> تقييم المدرب العام
                </h4>
                <div className="flex gap-2 text-slate-200 mb-8">
                   {[1,2,3,4,5].map(s => (
                     <button key={s} onClick={() => setLiveMetrics({...liveMetrics, stars: s})} className="transition-all hover:scale-110 active:scale-90">
                        <Star size={32} fill={s <= liveMetrics.stars ? "#FFB800" : "none"} className={s <= liveMetrics.stars ? "text-[#FFB800]" : "text-slate-200"} />
                     </button>
                   ))}
                </div>
                <div className="p-4 bg-orange-50 rounded-2xl border border-orange-100">
                   <p className="text-[10px] font-black text-orange-600 mb-1 uppercase">توصية النظام:</p>
                   <p className="text-[11px] font-bold text-[#001F3F]">
                      {readinessScore > 80 ? "اللاعب جاهز تماماً للمشاركة كأساسي." : readinessScore > 50 ? "اللاعب بحاجة لمزيد من العمل البدني لرفع الجاهزية." : "يرجى مراجعة التقارير الطبية، الجاهزية منخفضة."}
                   </p>
                </div>
             </div>
             <div className="md:col-span-2">
                <label className={labelStyle}>ملاحظات التقييم الفني الكيفي (Qualitative Feedback)</label>
                <textarea 
                  value={liveMetrics.coachNote}
                  onChange={e => setLiveMetrics({...liveMetrics, coachNote: e.target.value})}
                  className="w-full h-44 bg-slate-50 border-2 border-slate-900 rounded-[2rem] p-6 font-bold text-sm text-[#001F3F] outline-none focus:border-orange-600 transition-all resize-none shadow-inner"
                  placeholder="اكتب تعليقك الفني الشامل هنا (نقاط القوة، الضعف، الاحتياجات التدريبية)..."
                ></textarea>
             </div>
          </div>

          <div className="bg-white p-8 md:p-10 rounded-[2.5rem] border-2 border-[#001F3F] shadow-md">
             <h3 className="text-lg md:text-2xl font-black text-[#001F3F] mb-8 flex items-center gap-3 border-r-4 border-orange-600 pr-4">
                <Fingerprint className="text-blue-700" size={28}/> البيانات الثبوتية والعائلية الكاملة
             </h3>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div><label className={labelStyle}>اسم الأب</label><div className={valueStyle}>{player.fatherName || 'غير مسجل'}</div></div>
                <div><label className={labelStyle}>اسم الأم</label><div className={valueStyle}>{player.motherName || 'غير مسجل'}</div></div>
                <div><label className={labelStyle}>مكان وتاريخ الولادة</label><div className={valueStyle}>{player.birthPlace || 'دمشق'} / {player.birthDate}</div></div>
                <div><label className={labelStyle}>القيد (الخانة)</label><div className={valueStyle}>{player.khana || 'غير متوفر'}</div></div>
                <div><label className={labelStyle}>الرقم الوطني</label><div className={valueStyle}>{player.nationalId || '--- --- ---'}</div></div>
                <div><label className={labelStyle}>الرقم الاتحادي</label><div className={valueStyle}>{player.federalNumber || 'لم يصدر بعد'}</div></div>
                <div><label className={labelStyle}>الرقم الدولي (ID)</label><div className={valueStyle}>{player.internationalId || 'غير متوفر'}</div></div>
                <div><label className={labelStyle}>تاريخ الانضمام للنادي</label><div className={valueStyle}>{player.joinDate || '2024/01/01'}</div></div>
                <div><label className={labelStyle}>رقم الهاتف</label><div className={valueStyle} dir="ltr">{player.phone || '09-- --- ---'}</div></div>
             </div>
          </div>

          <div className="bg-white p-6 md:p-10 rounded-[2.5rem] border-2 border-[#001F3F] shadow-sm overflow-hidden">
             <h3 className="text-lg md:text-2xl font-black text-slate-900 mb-8 flex items-center gap-3">
               <ClipboardList className="text-[#001F3F]" size={28}/> سجل الأداء الميداني والمباريات
             </h3>
             <div className="overflow-x-auto -mx-6 md:mx-0">
               <table className="w-full text-right border-collapse min-w-[600px]">
                 <thead>
                    <tr className="bg-slate-100 border-y-2 border-[#001F3F] text-[11px] font-black uppercase text-slate-900">
                       <th className="p-4 border-l">المنافس / النوع</th>
                       <th className="p-4 border-l text-center">الدقائق</th>
                       <th className="p-4 border-l text-center">أهداف</th>
                       <th className="p-4 text-center">أسيست</th>
                    </tr>
                 </thead>
                 <tbody>
                    {matchStats.list.length > 0 ? matchStats.list.map((m, i) => (
                      <tr key={i} className="border-b border-slate-200 text-[12px] md:text-sm font-black hover:bg-slate-50 transition-colors">
                         <td className="p-4 border-l">
                            <div className="flex flex-col">
                               <span className="text-[#001F3F]">{m.opponent}</span>
                               <span className={`text-[9px] font-black px-2 py-0.5 rounded w-fit mt-1.5 border ${m.isOfficial ? 'bg-blue-100 text-blue-700 border-blue-300' : 'bg-orange-100 text-orange-700 border-orange-300'}`}>{m.type}</span>
                            </div>
                         </td>
                         <td className="p-4 border-l text-center font-bold text-[#001F3F]">{m.mins} دقيقة</td>
                         <td className="p-4 border-l text-center text-emerald-700">{m.goals || '-'}</td>
                         <td className="p-4 text-center text-blue-700">{m.assists || '-'}</td>
                      </tr>
                    )) : (
                      <tr><td colSpan={4} className="p-16 text-center text-slate-300 font-black italic">لا توجد سجلات مشاركة فنية حالياً</td></tr>
                    )}
                 </tbody>
               </table>
             </div>
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-[#001F3F] p-8 md:p-10 rounded-[3rem] border-4 border-black text-white shadow-2xl relative overflow-hidden">
             <div className="absolute top-0 right-0 w-32 h-32 bg-orange-600/10 rounded-full -mr-16 -mt-16"></div>
             <div className="flex items-center gap-3 mb-8 border-b border-white/10 pb-4">
                <ShieldCheck className="text-orange-500" size={24}/>
                <h3 className="text-sm md:text-lg font-black uppercase tracking-tighter">الحالة المالية والتعاقدية</h3>
             </div>
             <div className="space-y-6">
                <div className="flex justify-between items-center border-b border-white/5 pb-2">
                   <span className="text-slate-400 font-black text-xs">الرقم الوطني:</span>
                   <span className="font-black text-sm">{player.nationalId || '--- --- ---'}</span>
                </div>
                <div className="flex justify-between items-center border-b border-white/5 pb-2">
                   <span className="text-slate-400 font-black text-xs">تاريخ الميلاد:</span>
                   <span className="font-black text-sm">{player.birthDate}</span>
                </div>
                <div className="bg-white/5 p-6 rounded-3xl border border-white/10 mt-8 space-y-4">
                   <p className="text-orange-500 font-black text-[10px] uppercase tracking-widest flex items-center gap-2 mb-4">
                      <CreditCard size={16}/> وضع التعاقد المالي
                   </p>
                   <div className="flex justify-between text-xs">
                      <span className="text-slate-400">بداية العقد:</span>
                      <span className="font-bold">{player.contractStart || 'غير محدد'}</span>
                   </div>
