// مكون فرعي للعداد التنازلي الحي
const ActivityCountdown: React.FC<{ date: string; time: string }> = ({ date, time }) => {
  const [timeLeft, setTimeLeft] = useState<{ d: number; h: number; m: number; s: number } | null>(null);

  useEffect(() => {
    const calculateTime = () => {
      const target = new Date(`${date}T${time}`);
      const now = new Date();
      const diff = target.getTime() - now.getTime();

      if (diff <= 0) {
        setTimeLeft(null);
        return;
      }

      setTimeLeft({
        d: Math.floor(diff / (1000 * 60 * 60 * 24)),
        h: Math.floor((diff / (1000 * 60 * 60)) % 24),
        m: Math.floor((diff / (1000 * 60)) % 60),
        s: Math.floor((diff / 1000) % 60)
      });
    };

    calculateTime();
    const timer = setInterval(calculateTime, 1000);
    return () => clearInterval(timer);
  }, [date, time]);

  if (!timeLeft) {
    return <span className="text-emerald-500 font-black animate-pulse flex items-center gap-1"><Zap size={14}/> النشاط جارٍ الآن</span>;
  }

  return (
    <div className="flex gap-2 items-center text-[#001F3F]">
      <div className="flex flex-col items-center">
        <span className="text-sm font-black tabular-nums">{timeLeft.d}</span>
        <span className="text-[7px] font-bold opacity-50">يوم</span>
      </div>
      <span className="font-bold opacity-20">:</span>
      <div className="flex flex-col items-center">
        <span className="text-sm font-black tabular-nums">{String(timeLeft.h).padStart(2, '0')}</span>
        <span className="text-[7px] font-bold opacity-50">ساعة</span>
      </div>
      <span className="font-bold opacity-20">:</span>
      <div className="flex flex-col items-center">
        <span className="text-sm font-black tabular-nums">{String(timeLeft.m).padStart(2, '0')}</span>
        <span className="text-[7px] font-bold opacity-50">دقيقة</span>
      </div>
      <span className="font-bold opacity-20">:</span>
      <div className="flex flex-col items-center">
        <span className="text-sm font-black tabular-nums text-orange-600">{String(timeLeft.s).padStart(2, '0')}</span>
        <span className="text-[7px] font-bold opacity-50">ثانية</span>
      </div>
    </div>
  );
};

