  const [searchTerm, setSearchTerm] = useState('');
  const [localCategoryFilter, setLocalCategoryFilter] = useState<string>('الكل');

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: restrictedCat || state.categories[0] || '',
    joinDate: new Date().toISOString().split('T')[0]
  });

  const handleSaveEval = () => {
    if (!evalPersonId || evalStars === 0) return;

    const newEval: PlayerEvaluation = {
      id: generateUUID(),
      playerId: evalPersonId,
      date: new Date().toISOString().split('T')[0],
      stars: evalStars,
      coachNote: evalNote,
      evalType: 'monthly',
      physical: 0, tactical: 0, technical: 0, mental: 0, speed: 0
    };

    setState(prev => ({
      ...prev,
      evaluations: [...prev.evaluations, newEval]
    }));

    setIsEvalModalOpen(false);
    setEvalPersonId(null);
    setEvalStars(0);
    setEvalNote('');
    addLog?.('تقييم شهري', 'تم تسجيل تقييم شهري جديد بنجاح', 'success');
  };

  const baseFiltered = state.people.filter(p => {
    const matchCat = restrictedCat ? p.category === restrictedCat : (localCategoryFilter === 'الكل' ? true : p.category === localCategoryFilter);
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchCat && matchSearch;
  });

  return (
    <div className="space-y-4 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 no-print flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="flex-1 relative w-full">
           <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-900" size={18} />
           <input type="text" placeholder="البحث بالاسم..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 pr-12 pl-4 font-black" />
        </div>
        {!isViewer && (
          <button onClick={() => setIsModalOpen(true)} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black text-sm border-b-4 border-black">إضافة عضو</button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {baseFiltered.map(person => (
          <div key={person.id} className="bg-white p-5 rounded-[2rem] shadow-sm border-2 border-slate-900 relative group transition-all hover:border-orange-600 border-b-8">
             <div className="flex justify-between items-start mb-4">
                <div className="w-12 h-12 bg-slate-100 rounded-xl flex items-center justify-center font-black">{person.name.charAt(0)}</div>
                <span className="bg-orange-600 text-white text-[10px] font-black px-3 py-1 rounded-lg uppercase">{person.role}</span>
             </div>
             <h4 className="font-black text-lg text-slate-900">{person.name}</h4>
             <div className="mt-6 pt-4 border-t border-slate-100 flex justify-between items-center">
                <button onClick={() => onOpenReport?.(person)} className="text-blue-900 text-xs font-black underline">الملف الفني</button>
                {!isViewer && (
                  <button 
                    onClick={() => { setEvalPersonId(person.id); setIsEvalModalOpen(true); }}
                    className="bg-orange-50 text-orange-600 px-4 py-2 rounded-xl text-[10px] font-black border border-orange-200 hover:bg-orange-600 hover:text-white transition-all"
                  >
                    تقييم شهري
                  </button>
                )}
             </div>
          </div>
        ))}
      </div>

      {isEvalModalOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/90 backdrop-blur-md flex items-center justify-center z-[500] p-4">
           <div className="bg-white rounded-[2.5rem] w-full max-w-md border-[6px] border-slate-900 shadow-2xl p-8">
              <h3 className="text-xl font-black text-[#001F3F] mb-6 border-r-4 border-orange-600 pr-4">التقييم الشهري والتميز</h3>
              <div className="space-y-6 text-right" dir="rtl">
                 <div className="flex justify-center gap-2 mb-8">
                    {[1, 2, 3, 4, 5].map(s => (
                       <button key={s} onClick={() => setEvalStars(s)}>
                          <Star size={32} className={s <= evalStars ? 'text-orange-500 fill-orange-500' : 'text-slate-200'} />
                       </button>
                    ))}
                 </div>
                 <textarea 
                   placeholder="اكتب ملاحظة التقييم هنا..." 
                   className="w-full bg-slate-50 border-2 border-slate-200 rounded-2xl p-4 font-black text-sm h-32 resize-none"
                   value={evalNote}
                   onChange={e => setEvalNote(e.target.value)}
                 />
                 <div className="flex gap-2 pt-4">
                    <button onClick={() => setIsEvalModalOpen(false)} className="flex-1 bg-slate-100 text-slate-900 py-3 rounded-xl font-black">إلغاء</button>
                    <button onClick={handleSaveEval} className="flex-[2] bg-orange-600 text-white py-3 rounded-xl font-black shadow-lg border-b-4 border-orange-900">تثبيت التقييم</button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default SquadManagement;

import React, { useMemo } from 'react';
import { 
  ChevronRight, Printer, Target, AlertTriangle, Clock, Calendar, 
  TrendingUp, Users, Shield, MapPin, Activity, Globe, Trophy, 
  CheckCircle, Award, GraduationCap, Home, StickyNote, CreditCard, BarChart3, PieChart,
  Hash, ClipboardList, User, Timer, FileText, Briefcase, Sparkles, Loader2, X, BrainCircuit,
  HeartPulse, ShieldAlert, Gavel, Smartphone, CalendarDays, Wallet, Zap, ShieldCheck,
  Medal, Swords, Star, UserPlus, Info, Phone, Fingerprint
} from 'lucide-react';
import { AppState, Person, Match, AttendanceRecord, PlayerEvaluation } from '../types';
