export type MatchType = 'دوري' | 'كأس' | 'ودية' | 'بطولة ودية' | 'مباراة دولية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface PlayerEvaluation {
  id: string;
  playerId: string;
  matchId?: string; // إذا كان فارغاً فهو تقييم شهري
  date: string;
  stars: number; // 1-5
  physical: number; // 1-10
  tactical: number;
  technical: number;
  mental: number;
  speed: number;
  coachNote?: string;
  evalType: 'match' | 'monthly';
