export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const supabaseUrl = 'https://kfwqoigsghlgigjriyxf.supabase.co';
const supabaseAnonKey = 'sb_publishable_O2vR2yKUG-FVeaydD4z6Lg_tjFcKDic';
export const supabase = createClient(supabaseUrl, supabaseAnonKey);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'error' | 'syncing'>('synced');

  // نظام منع تداخل البيانات (Sync Lock Engine)
  const syncManager = useRef({
    isPushing: false,
    lastPushTime: 0,
    isInitialLoad: true
  });

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_cloud_v5');
    if (saved) {
      try { return JSON.parse(saved); } catch (e) { console.error(e); }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      warehouse: [],
      attendance: [],
      evaluations: [],
      users: [],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  useEffect(() => {
    localStorage.setItem('alkarama_cloud_v5', JSON.stringify(state));
  }, [state]);

  const addLog = useCallback((message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: generateUUID(),
      message, details, type, timestamp: Date.now(), isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  }, []);

  const sanitize = (data: any[]) => {
    return data.map(item => {
      const cleanItem = JSON.parse(JSON.stringify(item));
      Object.keys(cleanItem).forEach(key => {
        if (cleanItem[key] === undefined) cleanItem[key] = null;
      });
      return cleanItem;
    });
  };

  const fetchData = useCallback(async () => {
    // منع الجلب إذا كان هناك عملية رفع جارية لتجنب مسح البيانات المحلية الجديدة
    if (!state.currentUser || syncManager.current.isPushing) return;

    setIsSyncing(true);
    setSyncStatus('syncing');
    try {
      const pplQuery = supabase.from('people').select('*');
      const sessQuery = supabase.from('sessions').select('*');
      const mtchQuery = supabase.from('matches').select('*');
      const usrsQuery = supabase.from('app_users').select('*');
      const wrhsQuery = supabase.from('warehouse').select('*');
      const attnQuery = supabase.from('attendance').select('*');
      const evalQuery = supabase.from('player_evaluations').select('*');

      if (state.currentUser.restrictedCategory) {
        pplQuery.eq('category', state.currentUser.restrictedCategory);
        sessQuery.eq('category', state.currentUser.restrictedCategory);
        mtchQuery.eq('category', state.currentUser.restrictedCategory);
        wrhsQuery.or(`category.eq.${state.currentUser.restrictedCategory},category.eq.المخزن العام`);
      }

      const [cats, ppl, sess, mtch, attn, usrs, wrhs, evals] = await Promise.all([
        supabase.from('categories').select('name'),
        pplQuery,
        sessQuery,
        mtchQuery,
        attnQuery,
        usrsQuery,
        wrhsQuery,
        evalQuery
      ]);

      if (ppl.error || mtch.error) throw new Error("Connection Error");

      setState(prev => ({
        ...prev,
        categories: (cats.data && cats.data.length > 0) ? cats.data.map(c => c.name) : prev.categories,
        people: ppl.data || prev.people,
        sessions: (sess.data || prev.sessions).map((s: any) => ({ ...s, isLocked: !!s.isCompleted })),
        matches: (mtch.data || prev.matches).map((m: any) => ({ ...m, pitch: m.pitch || m.location || '' })),
        warehouse: wrhs.data || prev.warehouse,
        attendance: attn.data || prev.attendance,
        users: usrs.data || prev.users,
        evaluations: evals.data || prev.evaluations || []
      }));
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
      console.error("Fetch Error:", error);
    } finally {
      setIsSyncing(false);
      syncManager.current.isInitialLoad = false;
    }
  }, [state.currentUser]);

  const pushData = async (updatedState: AppState) => {
    if (!updatedState.currentUser) return;

    syncManager.current.isPushing = true;
    setSyncStatus('syncing');
    try {
      const mappedMatches = updatedState.matches.map(m => ({
        ...m,
        advancePayment: m.advancePayment || '0',
        ourScore: m.ourScore || '0',
        opponentScore: m.opponentScore || '0'
      }));

      // تحديث الجداول بشكل متسلسل ومضمون لضمان عدم حدوث تعارض
      const tasks = [];
      if (updatedState.people.length > 0) tasks.push(supabase.from('people').upsert(sanitize(updatedState.people), { onConflict: 'id' }));
      if (updatedState.sessions.length > 0) tasks.push(supabase.from('sessions').upsert(sanitize(updatedState.sessions), { onConflict: 'id' }));
      if (mappedMatches.length > 0) tasks.push(supabase.from('matches').upsert(sanitize(mappedMatches), { onConflict: 'id' }));
      if (updatedState.attendance.length > 0) tasks.push(supabase.from('attendance').upsert(sanitize(updatedState.attendance), { onConflict: 'id' }));
      if (updatedState.users.length > 0) tasks.push(supabase.from('app_users').upsert(sanitize(updatedState.users), { onConflict: 'id' }));
      if (updatedState.warehouse.length > 0) tasks.push(supabase.from('warehouse').upsert(sanitize(updatedState.warehouse), { onConflict: 'id' }));
      if (updatedState.evaluations.length > 0) tasks.push(supabase.from('player_evaluations').upsert(sanitize(updatedState.evaluations), { onConflict: 'id' }));

      await Promise.all(tasks);

      setSyncStatus('synced');
      syncManager.current.lastPushTime = Date.now();
    } catch (error: any) {
      setSyncStatus('error');
      addLog('خطأ مزامنة', error.message, 'error');
    } finally {
      // نترك القفل مفعلاً لمجرد ثوانٍ بسيطة للسماح للسحاب بالاستقرار
      setTimeout(() => {
        syncManager.current.isPushing = false;
      }, 2500);
    }
  };

  const updateStateAndSync = (updater: (prev: AppState) => AppState) => {
    setState(prev => {
      const next = updater(prev);
      pushData(next);
      return next;
    });
  };

  useEffect(() => {
    if (!state.currentUser) return;
    fetchData();

    // الاستماع الفوري للتغييرات في السحاب (Realtime)
    const channel = supabase.channel('cloud-sync-channel')
      .on('postgres_changes', { event: '*', schema: 'public' }, () => {
        const timeSinceLastPush = Date.now() - syncManager.current.lastPushTime;
        // لا نقوم بالجلب إذا كنا نحن من قمنا بالإرسال مؤخراً (لمنع مسح البيانات الجديدة)
        if (!syncManager.current.isPushing && timeSinceLastPush > 3000) {
          fetchData();
        }
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [state.currentUser, fetchData]);

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    localStorage.removeItem('alkarama_cloud_v5');
  };

  const handleCloudLogin = async (usernameInput: string, passwordInput: string): Promise<AppUser | null> => {
    try {
      const trimmedUser = usernameInput.trim();
      const trimmedPass = passwordInput.trim();
      if ((trimmedUser.toUpperCase() === 'IZZAT' || trimmedUser === 'عزت') && trimmedPass === '123') {
        const bootstrapUser: AppUser = { id: 'root-izzat', username: 'عزت عامر الشيخة', role: 'مدير' };
        setState(prev => ({ ...prev, currentUser: bootstrapUser }));
        return bootstrapUser;
      }
      const { data, error } = await supabase.from('app_users').select('*').ilike('username', trimmedUser).maybeSingle(); 
      if (error) throw new Error("Technical Error");
      if (!data) throw new Error("User not found");
      if (data.password === trimmedPass) {
        const loggedUser: AppUser = { id: data.id, username: data.username, role: data.role as any, restrictedCategory: data.restrictedCategory };
        setState(prev => ({ ...prev, currentUser: loggedUser }));
        return loggedUser;
      } else { throw new Error("Invalid Password"); }
    } catch (err: any) { throw err; }
  };

  if (!state.currentUser) return <Login onLoginAttempt={handleCloudLogin} />;

  const navItems = [
    { id: 'dashboard', label: 'الرئيسية', icon: LayoutDashboard },
    { id: 'squad', label: 'الفريق', icon: Users },
    { id: 'attendance', label: 'الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'warehouse', label: 'المستودع', icon: Package },
    { id: 'stats', label: 'الإحصائيات', icon: BarChart3 },
    { id: 'archive', label: 'الأرشيف', icon: Archive },
    { id: 'ai', label: 'الذكاء الفني', icon: Sparkles },
    { id: 'logistics', label: 'اللوجستيك', icon: Map },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  return (
    <div className="min-h-screen bg-[#000F21] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 transition-all duration-500 lg:translate-x-0 lg:static lg:p-4 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print`}>
        <div className="h-full bg-[#001F3F] rounded-[2rem] flex flex-col border-2 border-[#FF6B00]">
          <div className="p-8 flex items-center justify-between border-b border-white/5">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-white rounded-2xl">
                 <ClubLogo size={45} />
              </div>
              <div className="flex flex-col text-white">
                <span className="font-black text-lg leading-tight">نادي الكرامة</span>
                <span className="text-[10px] font-bold text-[#FF6B00] uppercase tracking-tighter">مكتب كرة القدم</span>
              </div>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2 text-white hover:text-[#FF6B00]"><X size={24} /></button>
          </div>

          <nav className="flex-1 overflow-y-auto py-6 px-4 space-y-2 custom-scrollbar">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all duration-300 group ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg scale-[1.02]' : 'text-white/60 hover:text-white hover:bg-white/5'}`}>
                <item.icon size={22} className={`${activeTab === item.id ? 'text-white' : 'group-hover:text-[#FF6B00]'} transition-colors`} />
                <span className="font-bold text-sm">{item.label}</span>
              </button>
            ))}
          </nav>

          <div className="p-6 border-t border-white/5">
            <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-red-400 hover:bg-red-500/10 font-bold transition-all">
              <LogOut size={22} /> <span className="text-sm">تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-[#001F3F] z-40 px-6 lg:px-12 py-5 flex items-center justify-between no-print border-b border-[#FF6B00]">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-3 bg-white/5 rounded-2xl text-white shadow-lg"><Menu size={24} /></button>
            <div>
               <h1 className="text-2xl font-black text-white tracking-tight">{navItems.find(i => i.id === activeTab)?.label}</h1>
               <p className="text-[10px] font-bold text-[#FF6B00] uppercase tracking-widest mt-0.5">Football Intelligence OS</p>
            </div>
          </div>

          <div className="flex items-center gap-4 lg:gap-8">
            <div className="flex items-center gap-4 bg-black/20 border border-white/10 px-5 py-2 rounded-2xl">
                 <button onClick={() => setShowNotifications(!showNotifications)} className="p-2 text-white/60 hover:text-[#FF6B00] relative">
                    <Bell size={24} />
                    {state.notifications.filter(n => !n.isRead).length > 0 && (
                      <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-[#FF6B00] rounded-full border-2 border-[#001F3F]"></span>
                    )}
                 </button>
                 <div className="flex items-center gap-4 border-r pr-5 border-white/10">
                    <div className="hidden sm:flex flex-col text-left">
                       <span className="text-xs font-black text-white leading-none">{state.currentUser.username}</span>
                       <span className="text-[10px] font-black text-[#FF6B00] uppercase mt-1">{state.currentUser.role}</span>
                    </div>
                    <div className="w-10 h-10 bg-[#FF6B00] text-white border border-white/20 rounded-2xl flex items-center justify-center font-black text-lg">
                       {state.currentUser.username.charAt(0).toUpperCase()}
                    </div>
                 </div>
              </div>
            <div className="flex items-center gap-3">
              <div className={`hidden md:flex items-center gap-3 px-5 py-3 rounded-2xl border transition-all ${syncStatus === 'synced' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-orange-500/10 border-[#FF6B00]/30 text-[#FF6B00]'}`}>
                 {syncStatus === 'synced' ? <CloudCheck size={18} /> : <Cloud size={18} />}
                 <span className="text-[10px] font-black uppercase tracking-tighter">{syncStatus === 'synced' ? 'مؤمن سحابياً' : 'جاري المزامنة...'}</span>
              </div>
              <button onClick={() => fetchData()} className="p-3.5 rounded-2xl bg-white/5 border border-white/10 text-white/60 hover:text-white hover:bg-[#FF6B00] transition-all">
                <RefreshCw size={20} className={isSyncing ? 'animate-spin' : ''} />
              </button>
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-6 lg:p-12 custom-scrollbar bg-[#000F21]">
          <div className="max-w-[1400px] mx-auto pb-24">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={updateStateAndSync} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} addLog={addLog} />}
            {activeTab === 'warehouse' && <WarehouseManagement state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'archive' && <ArchiveView state={state} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'stats' && <StatsView state={state} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} />}
            {activeTab === 'ai' && <AIAssistant state={state} />}
            {activeTab === 'logistics' && <LocationAssistant />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <nav className="lg:hidden fixed bottom-0 inset-x-0 bg-[#001F3F] border-t border-[#FF6B00]/30 p-3 flex justify-around items-center z-[100] rounded-t-[2rem]">
           {navItems.slice(0, 5).map(item => (
             <button key={item.id} onClick={() => setActiveTab(item.id)} className={`p-4 rounded-2xl transition-all ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg' : 'text-white/40'}`}>
                <item.icon size={24} />
             </button>
           ))}
        </nav>
        <ChatBot />
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Star, Heart
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person, PlayerEvaluation } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة'
  });

  useEffect(() => {
    if (defaultSelectedId) {
      const match = state.matches.find(m => m.id === defaultSelectedId);
      if (match) setActiveMatch(match);
    }
  }, [defaultSelectedId, state.matches]);

  const handleRating = (playerId: string, stars: number) => {
    if (!activeMatch || isViewer) return;

    const evalId = generateUUID();
    const newEval: PlayerEvaluation = {
      id: evalId,
      playerId,
      matchId: activeMatch.id,
      date: activeMatch.date,
      stars,
      physical: 7, // افتراضي للتقرير السريع
      tactical: 7,
      technical: 7,
      mental: 7,
      speed: 7,
      evalType: 'match'
    };

    setState(prev => ({
      ...prev,
      evaluations: [
        ...prev.evaluations.filter(e => !(e.playerId === playerId && e.matchId === activeMatch.id)),
        newEval
      ]
    }));
  };

  const getPlayerRating = (playerId: string) => {
    return state.evaluations.find(e => e.playerId === playerId && e.matchId === activeMatch?.id)?.stars || 0;
  };

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const updateActiveMatchLineup = (index: number, playerId: string, isStarter: boolean) => {
    if (!activeMatch || isViewer) return;
    const person = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (!person) {
      if (isStarter) newLineup.starters[index] = { ...newLineup.starters[index], playerId: '', name: '', number: '' };
    } else {
      if (isStarter) newLineup.starters[index] = { ...newLineup.starters[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const saveMatchDetails = () => {
    if (!activeMatch || isViewer) return;
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, isCompleted: true } : m)
    }));
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [...activeMatch!.lineup.starters.map(s => s.playerId), ...activeMatch!.lineup.subs.map(s => s.playerId)].filter(id => id && id !== currentId);
    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const StarRating: React.FC<{ playerId: string }> = ({ playerId }) => {
    const currentRating = getPlayerRating(playerId);
    return (
      <div className="flex gap-1">
        {[1, 2, 3, 4, 5].map(star => (
          <button 
            key={star} 
            onClick={() => handleRating(playerId, star)}
            className="transition-all hover:scale-125"
          >
            <Star 
              size={16} 
              className={star <= currentRating ? 'text-orange-500 fill-orange-500' : 'text-slate-300'} 
            />
          </button>
        ))}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div><h2 className="text-xl font-black text-slate-900 flex items-center gap-3"><Trophy size={24} className="text-orange-600" /> إدارة أجندة المباريات المركزية</h2></div>
        <div className="flex gap-3">
          <button onClick={() => setShowPrintView(true)} className="bg-white text-slate-900 border-2 border-slate-900 px-6 py-3 rounded-xl font-black text-sm">طباعة الأجندة</button>
          {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black text-sm">جدولة مواجهة</button>}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative border-b-8 transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-6"><span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span><span className="text-[10px] font-black text-slate-900">{m.date} - {m.category}</span></div>
             <div className="text-center mb-6"><p className="text-3xl font-black text-slate-900">{m.ourScore} - {m.opponentScore}</p><p className="font-black text-sm text-slate-700 mt-2">{m.opponent}</p></div>
             <div className="flex flex-col gap-2"><button onClick={() => setActiveMatch(m)} className="w-full bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs">التشكيل والتقرير</button></div>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/98 backdrop-blur-2xl z-[400] overflow-y-auto no-print">
           <div className="max-w-7xl mx-auto p-4 lg:p-12 min-h-screen text-right" dir="rtl">
              <div className="bg-white rounded-[4rem] border-[10px] border-slate-900 p-8 lg:p-12 shadow-2xl relative">
                <header className="relative flex flex-col md:flex-row justify-between items-center mb-12 border-b-8 border-slate-900 pb-10 gap-6">
                   <div className="flex items-center gap-6"><div className="bg-[#001F3F] text-white w-24 h-24 rounded-[2rem] flex items-center justify-center font-black text-4xl border-4 border-slate-900 shadow-2xl animate-pulse">K</div><div><h2 className="text-4xl font-black text-slate-900 tracking-tighter">الكرامة <span className="text-orange-600">×</span> {activeMatch.opponent}</h2></div></div>
                   <div className="flex gap-4">
                      <button onClick={saveMatchDetails} className="bg-emerald-600 text-white px-10 py-5 rounded-[2rem] font-black text-lg border-b-8 border-emerald-900"><span className="flex items-center gap-3"><Save size={24}/> حفظ التقرير الفني</span></button>
                      <button onClick={() => setActiveMatch(null)} className="bg-white text-slate-900 px-8 py-5 rounded-[2rem] font-black text-lg border-4 border-slate-900 shadow-xl"><X size={24}/></button>
                   </div>
                </header>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                   <div className="lg:col-span-12 space-y-12">
                      <section>
                         <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter mb-8 border-r-4 border-orange-600 pr-4">التشكيلة والتقييم</h3>
                         <div className="overflow-x-auto">
                            <table className="w-full text-right border-collapse">
                               <thead className="bg-[#001F3F] text-white">
                                  <tr>
                                     <th className="p-4 rounded-tr-2xl">الاسم</th>
                                     <th className="p-4 text-center">الرقم</th>
                                     <th className="p-4 text-center">الدقائق</th>
                                     <th className="p-4 rounded-tl-2xl text-center">التقييم (النجوم)</th>
                                  </tr>
                               </thead>
                               <tbody>
                                  {activeMatch.lineup.starters.map((s, idx) => (
                                     <tr key={idx} className="border-b border-slate-100 hover:bg-slate-50">
                                        <td className="p-4">
                                           <select className="w-full bg-transparent font-black text-xs" value={s.playerId} onChange={e => updateActiveMatchLineup(idx, e.target.value, true)}>
                                              <option value="">-- اختر لاعب --</option>
                                              {getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                           </select>
                                        </td>
                                        <td className="p-4 text-center font-black">{s.number || '--'}</td>
                                        <td className="p-4 text-center">
                                           <input type="number" className="w-16 bg-slate-50 border rounded p-1 text-center font-black" value={s.minutesPlayed || '90'} />
                                        </td>
                                        <td className="p-4 flex justify-center">
                                           {s.playerId && <StarRating playerId={s.playerId} />}
                                        </td>
                                     </tr>
                                  ))}
                               </tbody>
                            </table>
                         </div>
                      </section>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState } from 'react';
