interface PlayerReportProps {
  state: AppState;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';

  const playerEvals = state.evaluations.filter(e => e.playerId === player.id);

  const avgStars = useMemo(() => {
    const matchEvals = playerEvals.filter(e => e.evalType === 'match');
    if (matchEvals.length === 0) return 0;
    const total = matchEvals.reduce((acc, curr) => acc + curr.stars, 0);
    return (total / matchEvals.length).toFixed(1);
  }, [playerEvals]);

  const latestMonthlyEval = useMemo(() => {
    return [...playerEvals]
      .filter(e => e.evalType === 'monthly')
      .sort((a, b) => b.date.localeCompare(a.date))[0];
  }, [playerEvals]);

  const matchStats = useMemo(() => {
    if (isStaff) return { officialMins: 0, friendlyMins: 0, goals: 0, assists: 0, list: [] };
    const statsList = state.matches
      .filter(m => m.isCompleted)
      .map(m => {
        const starter = m.lineup.starters.find(s => s.playerId === player.id);
        const sub = m.lineup.subs.find(s => s.playerId === player.id);
        const played = !!(starter || sub);
        const goals = m.events.filter(e => e.type === 'goal' && (e.player === player.id || e.player === player.name)).length;
        const rating = state.evaluations.find(e => e.playerId === player.id && e.matchId === m.id)?.stars || 0;
        return played ? { opponent: m.opponent, date: m.date, goals, rating } : null;
      }).filter(x => x !== null);
    return { list: statsList };
  }, [state.matches, state.evaluations, player]);

  return (
    <div className="space-y-6 md:space-y-10 animate-in fade-in duration-500 pb-24 px-2 md:px-0 text-right font-['Tajawal']" dir="rtl">
      <div className="flex justify-between items-center no-print">
        <button onClick={onBack} className="bg-white border-2 border-[#001F3F] px-6 py-2 rounded-xl font-black text-sm shadow-md">رجوع</button>
        <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-xl border-b-4 border-black">
          <Printer size={20} /> طباعة التقرير
        </button>
      </div>

      <div className="solid-panel overflow-hidden border-4 border-[#001F3F]">
        <div className="bg-[#001F3F] h-32 relative">
           <div className="absolute -bottom-12 right-8 flex items-end gap-6">
              <div className="w-32 h-32 bg-white rounded-3xl border-8 border-white flex items-center justify-center font-black text-6xl text-[#001F3F] shadow-2xl">
                 {player.name.charAt(0)}
              </div>
              <div className="mb-4">
                 <h1 className="text-3xl font-black text-white">{player.name}</h1>
                 <p className="text-orange-400 font-bold text-sm uppercase">{player.role} | {player.category}</p>
              </div>
           </div>
        </div>
        <div className="h-16"></div>
        <div className="px-8 pb-10 grid grid-cols-1 md:grid-cols-4 gap-4">
           <div className="bg-slate-50 p-6 rounded-2xl border-2 border-[#001F3F] text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase mb-2">متوسط نجوم المباريات</p>
              <div className="flex justify-center gap-1 mb-2">
                 {[1,2,3,4,5].map(s => <Star key={s} size={14} className={s <= Math.round(Number(avgStars)) ? 'text-orange-500 fill-orange-500' : 'text-slate-200'}/>)}
              </div>
              <p className="text-3xl font-black text-[#001F3F]">{avgStars}</p>
           </div>
           <div className="bg-slate-50 p-6 rounded-2xl border-2 border-[#001F3F] md:col-span-3 text-right">
              <p className="text-[10px] font-black text-orange-600 uppercase mb-3 border-r-4 border-orange-600 pr-2">آخر تقييم شهري للمديرية</p>
              {latestMonthlyEval ? (
                <div className="space-y-2">
                   <div className="flex gap-1">
                      {[1,2,3,4,5].map(s => <Star key={s} size={14} className={s <= latestMonthlyEval.stars ? 'text-orange-500 fill-orange-500' : 'text-slate-200'}/>)}
                      <span className="text-[9px] text-slate-400 mr-2">بتاريخ: {latestMonthlyEval.date}</span>
                   </div>
                   <p className="text-sm font-bold text-[#001F3F] italic leading-relaxed">"{latestMonthlyEval.coachNote || 'لا توجد ملاحظات مكتوبة'}"</p>
                </div>
              ) : <p className="text-xs font-black text-slate-300">لم يتم رصد تقييم شهري لهذا الملف حتى الآن.</p>}
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
         <div className="bg-white p-8 rounded-[2.5rem] border-2 border-[#001F3F] shadow-sm">
            <h3 className="text-xl font-black text-[#001F3F] mb-6 flex items-center gap-3">
               <Fingerprint size={24} className="text-orange-600"/> البيانات الثبوتية والاتصال
            </h3>
            <div className="space-y-4">
               <div className="flex justify-between border-b pb-2"><span className="text-slate-500 text-xs font-black">الاسم الكامل:</span><span className="font-bold text-sm">{player.name}</span></div>
               <div className="flex justify-between border-b pb-2"><span className="text-slate-500 text-xs font-black">الرقم الوطني:</span><span className="font-bold text-sm">{player.nationalId || '--'}</span></div>
               <div className="flex justify-between border-b pb-2"><span className="text-slate-500 text-xs font-black">رقم الهاتف:</span><span className="font-bold text-sm" dir="ltr">{player.phone || '--'}</span></div>
               <div className="flex justify-between border-b pb-2"><span className="text-slate-500 text-xs font-black">العنوان:</span><span className="font-bold text-sm">{player.address || '--'}</span></div>
            </div>
         </div>

         <div className="bg-white p-8 rounded-[2.5rem] border-2 border-[#001F3F] shadow-sm">
            <h3 className="text-xl font-black text-[#001F3F] mb-6 flex items-center gap-3">
               <Trophy size={24} className="text-blue-900"/> سجل المباريات والنجوم
            </h3>
            <div className="space-y-3">
               {matchStats.list.length > 0 ? matchStats.list.map((m: any, i) => (
                 <div key={i} className="flex justify-between items-center bg-slate-50 p-4 rounded-xl border border-slate-200">
                    <div>
                       <p className="font-black text-xs text-[#001F3F]">{m.opponent}</p>
                       <p className="text-[9px] text-slate-400">{m.date}</p>
                    </div>
                    <div className="flex items-center gap-3">
                       {m.goals > 0 && <span className="bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded font-black text-[9px]">{m.goals}⚽</span>}
                       <div className="flex gap-0.5">
                          {[1,2,3,4,5].map(s => <Star key={s} size={10} className={s <= m.rating ? 'text-orange-500 fill-orange-500' : 'text-slate-200'}/>)}
                       </div>
                    </div>
                 </div>
               )) : <p className="text-center py-10 text-slate-300 font-black italic text-xs">لا يوجد سجل مشاركات فنية مؤرشفة.</p>}
            </div>
         </div>
      </div>
    </div>
  );
};

