import React, { useMemo, useState } from 'react';
import { 
  ChevronRight, Printer, Target, AlertTriangle, Clock, Calendar, 
  TrendingUp, Users, Shield, MapPin, Activity, Globe, Trophy, 
  CheckCircle, Award, GraduationCap, Home, StickyNote, CreditCard, BarChart3, PieChart,
  Hash, ClipboardList, User, Timer, FileText, Briefcase, Sparkles, Loader2, X, BrainCircuit,
  HeartPulse, ShieldAlert, Gavel, Smartphone, CalendarDays, Wallet, Zap, ShieldCheck,
  Medal, Swords, Star, UserPlus, Info, Phone, Fingerprint
} from 'lucide-react';
import { AppState, Person, Match, AttendanceRecord, PlayerEvaluation } from '../types';
import ClubLogo from './ClubLogo';
import { GoogleGenAI } from "@google/genai";

interface PlayerReportProps {
  state: AppState;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';

  const playerEvals = useMemo(() => {
    return state.evaluations.filter(e => e.playerId === player.id);
  }, [state.evaluations, player]);

  const avgMatchStars = useMemo(() => {
    const matchEvals = playerEvals.filter(e => e.evalType === 'match');
    if (matchEvals.length === 0) return 0;
    const total = matchEvals.reduce((acc, curr) => acc + curr.stars, 0);
    return (total / matchEvals.length).toFixed(1);
  }, [playerEvals]);

  const latestMonthlyEval = useMemo(() => {
    return [...playerEvals]
      .filter(e => e.evalType === 'monthly')
      .sort((a, b) => b.date.localeCompare(a.date))[0];
  }, [playerEvals]);

  // إحصائيات المشاركة
  const matchStats = useMemo(() => {
    if (isStaff) return { officialMins: 0, friendlyMins: 0, goals: 0, assists: 0, list: [] };

    let officialMins = 0;
    let friendlyMins = 0;

    const statsList = state.matches
      .filter(m => m.isCompleted)
      .sort((a, b) => a.date.localeCompare(b.date))
      .map(m => {
        const starter = m.lineup.starters.find(s => s.playerId === player.id);
        const sub = m.lineup.subs.find(s => s.playerId === player.id);

        let mins = 0;
        if (starter) mins = parseInt(starter.minutesPlayed || '90') || 0;
        else if (sub) mins = parseInt(sub.minutesPlayed || '0') || 0;

        const isOfficial = ['دوري', 'كأس', 'مباراة دولية'].includes(m.matchType);
        if (isOfficial) officialMins += mins;
        else friendlyMins += mins;

        const goals = m.events.filter(e => e.type === 'goal' && (e.player === player.name || e.player === player.id)).length;
        const assists = m.events.filter(e => e.type === 'assist' && (e.player === player.name || e.player === player.id)).length;
        const rating = state.evaluations.find(e => e.playerId === player.id && e.matchId === m.id)?.stars || 0;

        return { 
          opponent: m.opponent, 
          date: m.date, 
          type: m.matchType,
          isOfficial,
          mins, 
          goals, 
          assists,
          rating,
          played: !!(starter || sub) 
        };
      })
      .filter(s => s.played);

    return { officialMins, friendlyMins, goals: statsList.reduce((a, b) => a + b.goals, 0), assists: statsList.reduce((a, b) => a + b.assists, 0), list: statsList };
  }, [state.matches, state.evaluations, player, isStaff]);

  // إحصائيات الحضور
  const attendanceData = useMemo(() => {
    const sessions = state.sessions.filter(s => s.category === player.category);
    const sessionIds = sessions.map(s => s.id);
    const allRecords = state.attendance.filter(a => a.personId === player.id && sessionIds.includes(a.sessionId));
    const uniqueRecords = Array.from(new Map(allRecords.map(r => [r.sessionId, r])).values()) as AttendanceRecord[];
    const present = uniqueRecords.filter(r => r.status === 'حاضر').length;
    const late = uniqueRecords.filter(r => r.status === 'متأخر').length;
    const excused = uniqueRecords.filter(r => r.status === 'غياب بعذر').length;
    const totalSessions = sessions.length || 1;
    const weightedAttendance = present + excused + (late * 0.7);
    const rate = Math.min(100, Math.round((weightedAttendance / totalSessions) * 100));
    return { rate, total: sessions.length, present, late, excused };
  }, [state.attendance, state.sessions, player]);

  const radarData = useMemo(() => {
    return [
      { label: 'بدني', val: 8.5 },
      { label: 'تكتيك', val: 7.2 },
      { label: 'تقني', val: 9.0 },
      { label: 'ذهني', val: 6.5 },
      { label: 'سرعة', val: 8.8 }
    ];
  }, []);

  const handleGenerateAiAnalysis = async () => {
    setLoadingAi(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `أنت محلل تقني لنادي الكرامة السوري. حلل بيانات اللاعب ${player.name}: دقائق رسمية(${matchStats.officialMins}), ودية(${matchStats.friendlyMins}), أهداف(${matchStats.goals}), التزام(${attendanceData.rate}%). قدم تقريراً مختصراً واحترافياً.`;
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
      setAiAnalysis(response.text || "فشل توليد التحليل.");
    } catch (error: any) { setAiAnalysis("خطأ في الاتصال."); } finally { setLoadingAi(false); }
  };

  return (
    <div className="space-y-6 md:space-y-10 animate-in fade-in duration-500 pb-24 px-2 md:px-0 text-right font-['Tajawal']" dir="rtl">
      <div className="flex flex-row justify-between items-center no-print gap-3">
        <button onClick={onBack} className="flex items-center gap-2 text-[#001F3F] font-black bg-white border-2 border-[#001F3F] px-6 py-3 rounded-2xl text-sm shadow-md active:scale-95 transition-all"><ChevronRight size={20} /> رجوع للمديرية</button>
        <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-2xl font-black text-sm flex items-center gap-2 shadow-xl border-b-4 border-black hover:bg-black transition-all"><Printer size={20} /> تصدير الملف الشامل</button>
      </div>

      <div className="solid-panel overflow-hidden relative !shadow-none md:!shadow-[10px_10px_0px_0px_#001F3F] border-4 border-[#001F3F]">
        <div className="bg-[#001F3F] h-28 md:h-40 relative">
          <div className="absolute -bottom-14 right-8 md:right-16 flex items-end gap-6 md:gap-10">
            <div className="w-28 h-28 md:w-48 md:h-48 bg-white rounded-3xl md:rounded-[3rem] border-[6px] md:border-[10px] border-white flex items-center justify-center font-black text-5xl md:text-8xl text-[#001F3F] uppercase shadow-2xl relative z-10">{player.name.charAt(0)}</div>
            <div className="mb-4">
              <h1 className="text-2xl md:text-5xl font-black text-white drop-shadow-lg tracking-tight">{player.name}</h1>
              <div className="flex gap-3 mt-2"><span className="bg-orange-600 text-white text-[10px] md:text-[12px] font-black px-4 md:px-6 py-1.5 rounded-xl border-2 border-white uppercase shadow-lg">{player.role}</span><span className="bg-blue-600 text-white text-[10px] md:text-[12px] font-black px-4 md:px-6 py-1.5 rounded-xl border-2 border-white uppercase shadow-lg">{player.category}</span></div>
            </div>
          </div>
        </div>
        <div className="h-16 md:h-24"></div>

        <div className="px-6 md:px-16 pb-10 grid grid-cols-1 md:grid-cols-4 gap-6">
           <div className="bg-slate-50 p-6 rounded-3xl border-2 border-[#001F3F] text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase mb-2">متوسط نجوم المباريات</p>
              <div className="flex justify-center gap-1 mb-2">
                 {[1,2,3,4,5].map(s => <Star key={s} size={16} className={s <= Math.round(Number(avgMatchStars)) ? 'text-orange-500 fill-orange-500' : 'text-slate-200'}/>)}
              </div>
              <p className="text-3xl font-black text-[#001F3F]">{avgMatchStars}</p>
           </div>

           <div className="bg-slate-50 p-6 rounded-3xl border-2 border-[#001F3F] md:col-span-3">
              <p className="text-[10px] font-black text-orange-600 uppercase mb-3 border-r-4 border-orange-600 pr-2">أحدث تقييم شهري من الإدارة</p>
              {latestMonthlyEval ? (
                <div className="space-y-2">
                   <div className="flex gap-1">
                      {[1,2,3,4,5].map(s => <Star key={s} size={16} className={s <= latestMonthlyEval.stars ? 'text-orange-500 fill-orange-500' : 'text-slate-200'}/>)}
                      <span className="text-[10px] text-slate-400 mr-2 font-black tabular-nums">({latestMonthlyEval.date})</span>
                   </div>
                   <p className="text-sm font-bold text-[#001F3F] italic leading-relaxed">"{latestMonthlyEval.coachNote || 'لا توجد ملاحظات مكتوبة.'}"</p>
                </div>
              ) : (
                <p className="text-sm font-black text-slate-300 italic">لم يتم رصد تقييم شهري لهذا العضو حتى الآن.</p>
              )}
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 md:gap-10">
        <div className="lg:col-span-2 space-y-8 md:space-y-10">
          <div className="bg-white p-8 md:p-10 rounded-[2.5rem] border-4 border-[#001F3F] shadow-sm flex flex-col md:flex-row items-center gap-12">
             <div className="w-full md:w-1/2">
                <h3 className="text-lg md:text-xl font-black flex items-center gap-3 mb-8 text-[#001F3F]"><Target className="text-orange-600" size={24}/> البصمة الفنية (Radar Chart)</h3>
                <div className="relative w-full aspect-square max-w-[250px] mx-auto">
                   <svg viewBox="0 0 100 100" className="w-full h-full">
                      <circle cx="50" cy="50" r="45" fill="none" stroke="#001F3F" strokeWidth="0.5" strokeDasharray="2 2" />
                      <circle cx="50" cy="50" r="22.5" fill="none" stroke="#001F3F" strokeWidth="0.5" strokeDasharray="2 2" />
                      <polygon points={radarData.map((d, i) => { const angle = i * 72; const r = d.val * 4.5; return `${50 + r * Math.cos(angle * Math.PI / 180)},${50 + r * Math.sin(angle * Math.PI / 180)}`; }).join(' ')} fill="rgba(255, 107, 0, 0.4)" stroke="#FF6B00" strokeWidth="3" />
                   </svg>
                   {radarData.map((d, i) => { const angle = i * 72; return <div key={i} className="absolute font-black text-[10px] uppercase text-[#001F3F]" style={{ left: `${50 + 48 * Math.cos(angle * Math.PI / 180)}%`, top: `${50 + 48 * Math.sin(angle * Math.PI / 180)}%`, transform: 'translate(-50%, -50%)' }}>{d.label}</div>; })}
                </div>
             </div>
             <div className="w-full md:w-1/2 space-y-6">
                <div className="bg-slate-50 p-6 rounded-3xl border-2 border-slate-200 shadow-inner">
                   <h4 className="text-[11px] font-black text-slate-900 mb-3 uppercase tracking-widest">توجيه المحلل التكتيكي</h4>
                   <p className="text-[12px] font-black text-slate-800 leading-relaxed italic">"بناءً على دقائق المشاركة الأخيرة، يظهر العضو استجابة ممتازة في المباريات الرسمية، يحتاج لرفع منسوب الالتزام في الحصص الصباحية."</p>
                </div>
                <div className="bg-blue-900 text-white p-6 rounded-3xl shadow-lg border-b-4 border-black">
                   <p className="text-[10px] font-black uppercase opacity-60 mb-2">المؤشر العام للجاهزية</p>
                   <div className="flex items-center gap-3"><div className="h-4 flex-1 bg-white/20 rounded-full overflow-hidden"><div className="h-full bg-orange-500 w-[82%]"></div></div><span className="font-black text-lg">82%</span></div>
                </div>
             </div>
          </div>

          <div className="bg-white p-6 md:p-10 rounded-[2.5rem] border-2 border-[#001F3F] shadow-sm overflow-hidden">
             <h3 className="text-lg md:text-2xl font-black text-slate-900 mb-8 flex items-center gap-3"><ClipboardList className="text-[#001F3F]" size={28}/> سجل الأداء في المباريات (Match Log)</h3>
             <div className="overflow-x-auto -mx-6 md:mx-0">
               <table className="w-full text-right border-collapse min-w-[600px]">
                 <thead>
                    <tr className="bg-slate-100 border-y-2 border-[#001F3F] text-[11px] font-black uppercase text-slate-900">
                       <th className="p-4 border-l">المنافس / النوع</th>
                       <th className="p-4 border-l text-center">الدقائق</th>
                       <th className="p-4 border-l text-center">أهداف</th>
                       <th className="p-4 border-l text-center">تقييم نجوم</th>
                       <th className="p-4 text-center">أسيست</th>
                    </tr>
                 </thead>
                 <tbody>
                    {matchStats.list.length > 0 ? matchStats.list.map((m, i) => (
                      <tr key={i} className="border-b border-slate-200 text-[12px] md:text-sm font-black hover:bg-slate-50 transition-colors">
                         <td className="p-4 border-l"><div className="flex flex-col"><span className="text-[#001F3F]">{m.opponent}</span><span className={`text-[9px] font-black px-2 py-0.5 rounded w-fit mt-1.5 border ${m.isOfficial ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>{m.type}</span></div></td>
                         <td className="p-4 border-l text-center font-bold text-[#001F3F]">{m.mins} د</td>
                         <td className="p-4 border-l text-center text-emerald-700">{m.goals || '-'}</td>
                         <td className="p-4 border-l text-center">
                            <div className="flex justify-center gap-0.5">
                               {[1,2,3,4,5].map(s => <Star key={s} size={10} className={s <= m.rating ? 'text-orange-500 fill-orange-500' : 'text-slate-200'}/>)}
                            </div>
                         </td>
                         <td className="p-4 text-center text-blue-700">{m.assists || '-'}</td>
                      </tr>
                    )) : (
                      <tr><td colSpan={5} className="p-16 text-center text-slate-300 font-black italic">لا توجد سجلات مشاركة مؤرشفة.</td></tr>
                    )}
                 </tbody>
               </table>
             </div>
          </div>
        </div>

        <div className="space-y-8">
           <div className="bg-[#001F3F] p-8 md:p-10 rounded-[3rem] border-4 border-black text-white shadow-2xl relative overflow-hidden">
             <div className="flex items-center gap-3 mb-8 border-b border-white/10 pb-4"><ShieldCheck className="text-orange-500" size={24}/><h3 className="text-sm md:text-lg font-black uppercase tracking-tighter">البيانات الثبوتية والمالية</h3></div>
             <div className="space-y-6">
                <div className="flex justify-between items-center border-b border-white/5 pb-2"><span className="text-slate-400 font-black text-xs">الرقم الوطني:</span><span className="font-black text-sm">{player.nationalId || '--- --- ---'}</span></div>
                <div className="flex justify-between items-center border-b border-white/5 pb-2"><span className="text-slate-400 font-black text-xs">تاريخ الميلاد:</span><span className="font-black text-sm">{player.birthDate}</span></div>
                <div className="bg-white/5 p-6 rounded-3xl border border-white/10 mt-8 space-y-4">
                   <p className="text-orange-500 font-black text-[10px] uppercase tracking-widest flex items-center gap-2 mb-4"><CreditCard size={16}/> حالة التعاقد</p>
                   <div className="flex justify-between text-xs"><span className="text-slate-400">القيمة المالية:</span><span className="font-black text-emerald-400">{player.contractValue || '0.00 SP'}</span></div>
                </div>
             </div>
          </div>

          <div className="bg-white p-8 md:p-10 rounded-[2.5rem] border-2 border-red-900 shadow-md">
             <h4 className="text-sm md:text-lg font-black text-red-700 mb-6 flex items-center gap-3"><Gavel className="text-red-700" size={24}/> سجل العقوبات</h4>
             <div className="p-5 bg-red-50 rounded-2xl border-r-4 border-red-700">
                <p className="text-[13px] font-black text-slate-900 leading-relaxed italic">{player.penalties || "السجل نظيف إدارياً."}</p>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

