  id: string;
  playerId: string;
  matchId?: string; 
  date: string;
  stars: number; // 1-5 نجوم
  physical: number; // 1-10
  tactical: number;
  technical: number;
  mental: number;
  speed: number;
  coachNote?: string;
  evalType: 'match' | 'monthly';
