import React, { useState, useMemo } from 'react';
import { FileCheck, Trophy, Calendar, Star, TrendingUp, Save, Search, X, User, ChevronLeft, MapPin, Activity, Target, ShieldCheck, Heart } from 'lucide-react';
import { AppState, Match, Person, PlayerEvaluation } from '../types';
import { generateUUID } from '../App';

interface TechnicalReportsProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  onOpenPlayerReport: (player: Person) => void;
}

const TechnicalReports: React.FC<TechnicalReportsProps> = ({ state, setState, onOpenPlayerReport }) => {
  const [activeMode, setActiveMode] = useState<'match' | 'monthly'>('match');
  const [selectedMatchId, setSelectedMatchId] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [editingRadar, setEditingRadar] = useState<Person | null>(null);

  // بيانات الرادار للمؤقت
  const [radarFormData, setRadarFormData] = useState({
    physical: 7, tactical: 7, technical: 7, mental: 7, speed: 7
  });

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isViewer = currentUser?.role === 'مشاهد';

  const matches = useMemo(() => {
    return state.matches
      .filter(m => !restrictedCat || m.category === restrictedCat)
      .sort((a, b) => b.date.localeCompare(a.date));
  }, [state.matches, restrictedCat]);

  const activeMatch = useMemo(() => state.matches.find(m => m.id === selectedMatchId), [selectedMatchId, state.matches]);

  const members = useMemo(() => {
    return state.people.filter(p => !restrictedCat || p.category === restrictedCat);
  }, [state.people, restrictedCat]);

  const handleStarRating = (pid: string, stars: number, matchId?: string) => {
    if (isViewer) return;
    const date = matchId ? (matches.find(m => m.id === matchId)?.date || new Date().toISOString()) : `${selectedMonth}-01`;
    const type = matchId ? 'match' : 'monthly';

    const newEval: PlayerEvaluation = {
      id: generateUUID(),
      playerId: pid,
      matchId: matchId,
      date,
      stars,
      physical: 7, tactical: 7, technical: 7, mental: 7, speed: 7,
      evalType: type as any
    };

    setState(prev => ({
      ...prev,
      evaluations: [
        ...prev.evaluations.filter(e => !(e.playerId === pid && (matchId ? e.matchId === matchId : (e.evalType === 'monthly' && e.date.startsWith(selectedMonth))))),
        newEval
      ]
    }));
  };

  const handleUpdateRadar = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingRadar || isViewer) return;

    const evalId = generateUUID();
    const newEval: PlayerEvaluation = {
      id: evalId,
      playerId: editingRadar.id,
      date: new Date().toISOString().split('T')[0],
      stars: 0, // تحديث مقاييس فقط
      ...radarFormData,
      evalType: 'match' // افتراضي للرادار
    };

    setState(prev => ({
      ...prev,
      evaluations: [...prev.evaluations, newEval]
    }));

    setEditingRadar(null);
  };

  const getRating = (pid: string, matchId?: string) => {
    const ev = state.evaluations.find(e => 
      e.playerId === pid && 
      (matchId ? e.matchId === matchId : (e.evalType === 'monthly' && e.date.startsWith(selectedMonth)))
    );
    return ev?.stars || 0;
  };

  const StarRating: React.FC<{ pid: string, matchId?: string }> = ({ pid, matchId }) => {
    const current = getRating(pid, matchId);
    return (
      <div className="flex gap-1">
        {[1, 2, 3, 4, 5].map(s => (
          <button key={s} onClick={() => handleStarRating(pid, s, matchId)} className="transition-transform hover:scale-125">
            <Star size={18} className={s <= current ? 'text-orange-500 fill-orange-500' : 'text-slate-200'} />
          </button>
        ))}
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* الرأس والتبديل */}
      <div className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center shadow-sm gap-6">
        <div className="flex items-center gap-4">
          <div className="bg-[#001F3F] p-3 rounded-2xl text-white shadow-lg"><FileCheck size={28}/></div>
          <div>
            <h2 className="text-xl font-black text-slate-900 uppercase">مركز التقارير الفنية</h2>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">إدارة تقييمات الأداء وسجلات التميز الفني</p>
          </div>
        </div>

        <div className="flex p-1.5 bg-slate-100 border-2 border-slate-900 rounded-2xl">
          <button onClick={() => setActiveMode('match')} className={`px-8 py-2.5 rounded-xl font-black text-xs transition-all ${activeMode === 'match' ? 'bg-[#001F3F] text-white shadow-lg scale-105' : 'text-slate-500'}`}>تقييم مباراة</button>
          <button onClick={() => setActiveMode('monthly')} className={`px-8 py-2.5 rounded-xl font-black text-xs transition-all ${activeMode === 'monthly' ? 'bg-[#001F3F] text-white shadow-lg scale-105' : 'text-slate-500'}`}>التقييم الشهري</button>
        </div>
      </div>

      {activeMode === 'match' ? (
        <div className="space-y-6">
           <div className="bg-white p-8 rounded-[3rem] border-2 border-slate-900 shadow-sm">
              <label className="text-[10px] font-black text-slate-500 uppercase mb-3 block tracking-widest mr-2">1. حدد المواجهة من الأجندة</label>
              <select value={selectedMatchId} onChange={e => setSelectedMatchId(e.target.value)}
                className="w-full bg-slate-50 border-4 border-[#001F3F] rounded-[1.5rem] p-5 font-black text-xl text-[#001F3F] outline-none">
                <option value="">-- اختر المباراة المستهدفة بالتقييم --</option>
                {matches.map(m => <option key={m.id} value={m.id}>{m.date} | الكرامة × {m.opponent} ({m.category})</option>)}
              </select>
           </div>

           {activeMatch && (
             <div className="bg-white rounded-[3rem] border-2 border-slate-900 overflow-hidden shadow-xl animate-in slide-in-from-top-4 duration-300">
                <div className="bg-slate-900 p-6 flex justify-between items-center text-white border-b-4 border-orange-600">
                   <h3 className="font-black text-lg flex items-center gap-3"><Trophy className="text-orange-600"/> تقييم أداء اللاعبين: {activeMatch.opponent}</h3>
                   <span className="text-[10px] font-black bg-white/10 px-4 py-1.5 rounded-full uppercase tracking-widest">{activeMatch.category}</span>
                </div>
                <div className="overflow-x-auto">
                   <table className="w-full text-right border-collapse">
                      <thead className="bg-slate-50 border-b-2 border-slate-200">
                         <tr>
                            <th className="p-6 text-[10px] font-black uppercase text-slate-400">اللاعب</th>
                            <th className="p-6 text-[10px] font-black uppercase text-slate-400 text-center">التقييم (5 نجوم)</th>
                            <th className="p-6 text-[10px] font-black uppercase text-slate-400 text-left">إجراءات فنية</th>
                         </tr>
                      </thead>
                      <tbody>
                         {members.filter(p => p.role === 'لاعب' && p.category === activeMatch.category).map(p => (
                            <tr key={p.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                               <td className="p-6">
                                  <div className="flex items-center gap-4">
                                     <div className="w-10 h-10 bg-[#001F3F] text-white rounded-xl flex items-center justify-center font-black text-xs shadow-md">#{p.number}</div>
                                     <button onClick={() => onOpenPlayerReport(p)} className="font-black text-slate-900 hover:text-orange-600 hover:underline">{p.name}</button>
                                  </div>
                                  <div className="flex gap-1 mt-2">
                                     {activeMatch.events.filter(e => e.player === p.id).map(e => (
                                       <span key={e.id} title={e.type}>{e.type === 'goal' ? '⚽' : e.type === 'yellow' ? '🟨' : '👟'}</span>
                                     ))}
                                  </div>
                               </td>
                               <td className="p-6"><div className="flex justify-center"><StarRating pid={p.id} matchId={activeMatch.id} /></div></td>
                               <td className="p-6 text-left">
                                  <button onClick={() => { setEditingRadar(p); setRadarFormData({ physical: 7, tactical: 7, technical: 7, mental: 7, speed: 7 }); }} 
                                    className="bg-slate-100 border-2 border-slate-900 text-[#001F3F] px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 hover:bg-[#001F3F] hover:text-white transition-all ml-auto">
                                    <Target size={14}/> تحديث البصمة (Radar)
                                  </button>
                               </td>
                            </tr>
                         ))}
                      </tbody>
                   </table>
                </div>
             </div>
           )}
        </div>
      ) : (
        <div className="space-y-6">
           <div className="bg-white p-8 rounded-[3rem] border-2 border-slate-900 shadow-sm">
              <label className="text-[10px] font-black text-slate-500 uppercase mb-3 block tracking-widest mr-2">حدد الشهر المستهدف</label>
              <input type="month" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)}
                className="w-full bg-slate-50 border-4 border-[#001F3F] rounded-[1.5rem] p-5 font-black text-2xl text-[#001F3F] outline-none" />
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {members.map(p => (
                 <div key={p.id} className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 shadow-sm hover:border-orange-600 transition-all border-b-8">
                    <div className="flex justify-between items-start mb-6">
                       <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg text-white shadow-lg ${p.role === 'لاعب' ? 'bg-orange-600' : 'bg-[#001F3F]'}`}>
                          {p.name.charAt(0)}
                       </div>
                       <span className="text-[9px] font-black text-slate-400 bg-slate-50 px-3 py-1 rounded-lg border uppercase tracking-tighter">{p.role}</span>
                    </div>
                    <h4 className="font-black text-lg text-slate-900 mb-6">{p.name}</h4>
                    <div className="space-y-6">
                       <div className="flex flex-col items-center gap-2 bg-slate-50 p-4 rounded-2xl border-2 border-slate-100">
                          <span className="text-[9px] font-black text-slate-400 uppercase">التقييم العام للشهر</span>
                          <StarRating pid={p.id} />
                       </div>
                       <textarea 
                        placeholder="ملاحظات المدرب الفنية لهذا الشهر..."
                        className="w-full bg-white border-2 border-slate-200 rounded-2xl p-4 text-xs font-bold h-28 resize-none focus:border-orange-600 outline-none transition-all shadow-inner"
                        value={state.evaluations.find(e => e.playerId === p.id && e.evalType === 'monthly' && e.date.startsWith(selectedMonth))?.coachNote || ''}
                        onChange={e => {
                          const note = e.target.value;
                          setState(prev => ({
                            ...prev,
                            evaluations: [
                              ...prev.evaluations.filter(ev => !(ev.playerId === p.id && ev.evalType === 'monthly' && ev.date.startsWith(selectedMonth))),
                              { id: generateUUID(), playerId: p.id, date: `${selectedMonth}-01`, stars: getRating(p.id), physical: 7, tactical: 7, technical: 7, mental: 7, speed: 7, coachNote: note, evalType: 'monthly' }
                            ]
                          }));
                        }}
                       />
                    </div>
                 </div>
              ))}
           </div>
        </div>
      )}

      {/* نافذة تحديث البصمة الفنية */}
      {editingRadar && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-2xl z-[500] flex items-center justify-center p-4">
           <div className="bg-white rounded-[4rem] w-full max-w-xl border-[10px] border-white shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="bg-[#001F3F] p-8 flex justify-between items-center border-b-8 border-orange-600">
                 <div className="flex items-center gap-4 text-white">
                    <Target className="text-orange-600" size={42} />
                    <div>
                       <h4 className="font-black text-2xl tracking-tighter">تحديث البصمة: {editingRadar.name}</h4>
                       <p className="text-[9px] font-bold text-orange-400 uppercase tracking-widest mt-1">نظام رصد المقاييس الفنية الفردية (Radar Chart)</p>
                    </div>
                 </div>
                 <button onClick={() => setEditingRadar(null)} className="text-white hover:rotate-90 transition-all p-2 bg-white/10 rounded-full"><X size={32}/></button>
              </div>

              <form onSubmit={handleUpdateRadar} className="p-10 space-y-8 text-right" dir="rtl">
                 <div className="grid grid-cols-1 gap-6">
                    {Object.keys(radarFormData).map((key) => (
                       <div key={key} className="space-y-3">
                          <div className="flex justify-between items-center">
                             <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{key === 'physical' ? 'اللياقة البدنية' : key === 'tactical' ? 'الوعي التكتيكي' : key === 'technical' ? 'المهارة التقنية' : key === 'mental' ? 'القوة الذهنية' : 'السرعة والرشاقة'}</label>
                             <span className="bg-[#001F3F] text-white w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs shadow-md">{(radarFormData as any)[key]}</span>
                          </div>
                          <input 
                            type="range" min="1" max="10" 
                            className="w-full h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-orange-600"
                            value={(radarFormData as any)[key]}
                            onChange={e => setRadarFormData({...radarFormData, [key]: parseInt(e.target.value)})}
                          />
                       </div>
                    ))}
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-6 rounded-[2.5rem] font-black text-xl flex items-center justify-center gap-4 hover:bg-black transition-all border-b-8 border-black shadow-2xl active:translate-y-2">
                    <Save size={28} className="text-orange-600"/> تثبيت البصمة الفنية
                 </button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default TechnicalReports;

import React, { useMemo, useState } from 'react';
import { 
  ChevronRight, Printer, Target, AlertTriangle, Clock, Calendar, 
  TrendingUp, Users, Shield, MapPin, Activity, Globe, Trophy, 
  CheckCircle, Award, GraduationCap, Home, StickyNote, CreditCard, BarChart3, PieChart,
  Hash, ClipboardList, User, Timer, FileText, Briefcase, Sparkles, Loader2, X, BrainCircuit,
  HeartPulse, ShieldAlert, Gavel, Smartphone, CalendarDays, Wallet, Zap, ShieldCheck,
  Medal, Swords, Star, UserPlus, Info, Phone, Fingerprint
} from 'lucide-react';
import { AppState, Person, Match, AttendanceRecord, PlayerEvaluation } from '../types';
import ClubLogo from './ClubLogo';

interface PlayerReportProps {
  state: AppState;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';

  const playerEvals = useMemo(() => state.evaluations.filter(e => e.playerId === player.id), [state.evaluations, player.id]);

  const avgMatchStars = useMemo(() => {
    const matchEvals = playerEvals.filter(e => e.evalType === 'match');
    if (matchEvals.length === 0) return 0;
    const total = matchEvals.reduce((acc, curr) => acc + curr.stars, 0);
    return (total / matchEvals.length).toFixed(1);
  }, [playerEvals]);

  const latestMonthlyEval = useMemo(() => {
    return [...playerEvals].filter(e => e.evalType === 'monthly').sort((a, b) => b.date.localeCompare(a.date))[0];
  }, [playerEvals]);

  const latestRadar = useMemo(() => {
    return [...playerEvals].filter(e => e.physical > 0).sort((a, b) => b.date.localeCompare(a.date))[0] || {
      physical: 7, tactical: 7, technical: 7, mental: 7, speed: 7
    };
  }, [playerEvals]);

  const radarData = useMemo(() => [
    { label: 'بدني', val: latestRadar.physical },
    { label: 'تكتيك', val: latestRadar.tactical },
    { label: 'تقني', val: latestRadar.technical },
    { label: 'ذهني', val: latestRadar.mental },
    { label: 'سرعة', val: latestRadar.speed }
  ], [latestRadar]);

  const matchStats = useMemo(() => {
    if (isStaff) return { list: [] };
    const list = state.matches.filter(m => m.isCompleted).map(m => {
      const s = m.lineup.starters.find(x => x.playerId === player.id);
      const b = m.lineup.subs.find(x => x.playerId === player.id);
      if (!s && !b) return null;
      const goals = m.events.filter(e => e.type === 'goal' && e.player === player.id).length;
      const rating = state.evaluations.find(e => e.playerId === player.id && e.matchId === m.id)?.stars || 0;
      return { opponent: m.opponent, date: m.date, mins: s?.minutesPlayed || b?.minutesPlayed || '0', goals, rating };
    }).filter(x => x !== null);
    return { list };
  }, [state.matches, state.evaluations, player.id, isStaff]);

  return (
    <div className="space-y-6 md:space-y-10 animate-in fade-in duration-500 pb-24 px-2 md:px-0 text-right font-['Tajawal']" dir="rtl">
      <div className="flex justify-between items-center no-print">
        <button onClick={onBack} className="bg-white border-2 border-[#001F3F] px-6 py-3 rounded-2xl font-black text-[#001F3F] flex items-center gap-2 shadow-md"><ChevronRight size={20}/> رجوع</button>
        <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-2xl font-black shadow-xl flex items-center gap-2 border-b-4 border-black"><Printer size={20}/> طباعة الملف الفني</button>
      </div>

      <div className="solid-panel overflow-hidden border-4 border-[#001F3F] !shadow-none md:!shadow-[10px_10px_0px_0px_#001F3F]">
        <div className="bg-[#001F3F] h-32 relative">
           <div className="absolute -bottom-12 right-8 flex items-end gap-6">
              <div className="w-32 h-32 bg-white rounded-[2rem] border-8 border-white flex items-center justify-center font-black text-6xl text-[#001F3F] shadow-2xl relative">
                 {player.name.charAt(0)}
                 <div className="absolute -top-4 -left-4 bg-orange-600 text-white w-10 h-10 rounded-full flex items-center justify-center text-sm border-4 border-white">#{player.number}</div>
              </div>
