import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Star
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person, PlayerEvaluation } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة'
  });

  useEffect(() => {
    if (defaultSelectedId) {
      const match = state.matches.find(m => m.id === defaultSelectedId);
      if (match) setActiveMatch(match);
    }
  }, [defaultSelectedId, state.matches]);

  const handleSetMatchRating = (playerId: string, stars: number) => {
    if (!activeMatch || isViewer) return;

    const evalId = generateUUID();
    const newEval: PlayerEvaluation = {
      id: evalId,
      playerId,
      matchId: activeMatch.id,
      date: activeMatch.date,
      stars,
      physical: 7, // افتراضي
      tactical: 7,
      technical: 7,
      mental: 7,
      speed: 7,
      evalType: 'match'
    };

    setState(prev => ({
      ...prev,
      evaluations: [
        ...prev.evaluations.filter(e => !(e.playerId === playerId && e.matchId === activeMatch.id)),
        newEval
      ]
    }));
  };

  const getPlayerMatchRating = (playerId: string) => {
    return state.evaluations.find(e => e.playerId === playerId && e.matchId === activeMatch?.id)?.stars || 0;
  };

  const StarRating: React.FC<{ playerId: string }> = ({ playerId }) => {
    const currentRating = getPlayerMatchRating(playerId);
    return (
      <div className="flex gap-1 justify-center">
        {[1, 2, 3, 4, 5].map(star => (
          <button key={star} onClick={() => handleSetMatchRating(playerId, star)} className="transition-all hover:scale-125 active:scale-90">
            <Star size={16} className={star <= currentRating ? 'text-orange-500 fill-orange-500' : 'text-slate-300'} />
          </button>
        ))}
      </div>
    );
  };

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const updateLineup = (idx: number, pid: string) => {
    if (!activeMatch || isViewer) return;
    const p = state.people.find(x => x.id === pid);
    const nl = { ...activeMatch.lineup };
    nl.starters[idx] = { playerId: pid, name: p?.name || '', number: p?.number?.toString() || '', minutesPlayed: '90' };
    setActiveMatch({ ...activeMatch, lineup: nl });
  };

  const saveDetails = () => {
    if (!activeMatch || isViewer) return;
    setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, isCompleted: true } : m) }));
    setActiveMatch(null);
  };

  const getAvailablePlayers = (cid: string) => {
    const sel = [...activeMatch!.lineup.starters.map(s => s.playerId), ...activeMatch!.lineup.subs.map(s => s.playerId)].filter(id => id && id !== cid);
    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !sel.includes(p.id));
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div><h2 className="text-xl font-black text-slate-900 flex items-center gap-3"><Trophy size={24} className="text-orange-600" /> إدارة أجندة المباريات المركزية</h2></div>
        <div className="flex gap-3">
          <button onClick={() => setShowPrintView(true)} className="bg-white text-slate-900 border-2 border-slate-900 px-6 py-3 rounded-xl font-black text-sm">طباعة الأجندة</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative border-b-8 transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-6"><span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span><span className="text-[10px] font-black text-slate-900">{m.date} - {m.category}</span></div>
             <div className="text-center mb-6"><p className="text-3xl font-black text-slate-900">{m.ourScore} - {m.opponentScore}</p><p className="font-black text-sm text-slate-700 mt-2">{m.opponent}</p></div>
             <button onClick={() => setActiveMatch(m)} className="w-full bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs">التشكيل والتقرير</button>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/98 backdrop-blur-2xl z-[400] overflow-y-auto no-print">
           <div className="max-w-7xl mx-auto p-4 lg:p-12 min-h-screen text-right" dir="rtl">
              <div className="bg-white rounded-[4rem] border-[10px] border-slate-900 p-8 lg:p-12 shadow-2xl relative">
                <header className="flex flex-col md:flex-row justify-between items-center mb-12 border-b-8 border-slate-900 pb-10 gap-6">
                   <h2 className="text-4xl font-black text-slate-900 tracking-tighter">الكرامة <span className="text-orange-600">×</span> {activeMatch.opponent}</h2>
                   <div className="flex gap-4">
                      <button onClick={saveDetails} className="bg-emerald-600 text-white px-10 py-5 rounded-[2rem] font-black text-lg border-b-8 border-emerald-900">حفظ التقرير</button>
                      <button onClick={() => setActiveMatch(null)} className="bg-white text-slate-900 px-8 py-5 rounded-[2rem] font-black text-lg border-4 border-slate-900"><X size={24}/></button>
                   </div>
                </header>
                <div className="space-y-12">
                   <section>
                      <h3 className="text-2xl font-black text-slate-900 uppercase mb-8 border-r-4 border-orange-600 pr-4">التشكيلة والتقييم (النجوم)</h3>
                      <div className="overflow-x-auto">
                        <table className="w-full text-right border-collapse">
                           <thead className="bg-[#001F3F] text-white">
                              <tr>
                                 <th className="p-4 rounded-tr-2xl">الاسم</th>
                                 <th className="p-4 text-center">الرقم</th>
                                 <th className="p-4 text-center">الدقائق</th>
                                 <th className="p-4 rounded-tl-2xl text-center">التقييم الفني (نجوم)</th>
                              </tr>
                           </thead>
                           <tbody>
                              {activeMatch.lineup.starters.map((s, idx) => (
                                 <tr key={idx} className="border-b border-slate-100 hover:bg-slate-50">
                                    <td className="p-4"><select className="w-full bg-transparent font-black text-xs" value={s.playerId} onChange={e => updateLineup(idx, e.target.value)}><option value="">-- لاعب --</option>{getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></td>
                                    <td className="p-4 text-center font-black">{s.number || '--'}</td>
                                    <td className="p-4 text-center"><input type="number" className="w-16 bg-slate-50 border rounded p-1 text-center font-black text-xs" value={s.minutesPlayed || '90'} onChange={e => { const nl = {...activeMatch.lineup}; nl.starters[idx].minutesPlayed = e.target.value; setActiveMatch({...activeMatch, lineup: nl}); }} /></td>
                                    <td className="p-4">{s.playerId && <StarRating playerId={s.playerId} />}</td>
                                 </tr>
                              ))}
                              {activeMatch.lineup.subs.map((s, idx) => (
                                 <tr key={`sub-${idx}`} className="border-b border-slate-100 bg-blue-50/20">
                                    <td className="p-4"><select className="w-full bg-transparent font-black text-xs" value={s.playerId} onChange={e => { const p = state.people.find(x => x.id === e.target.value); const nl = {...activeMatch.lineup}; nl.subs[idx] = {...nl.subs[idx], playerId: e.target.value, name: p?.name || '', number: p?.number?.toString() || ''}; setActiveMatch({...activeMatch, lineup: nl}); }}><option value="">-- لاعب بديل --</option>{getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></td>
                                    <td className="p-4 text-center font-black">{s.number || '--'}</td>
                                    <td className="p-4 text-center"><input type="number" className="w-16 bg-slate-50 border rounded p-1 text-center font-black text-xs" value={s.minutesPlayed || '0'} onChange={e => { const nl = {...activeMatch.lineup}; nl.subs[idx].minutesPlayed = e.target.value; setActiveMatch({...activeMatch, lineup: nl}); }} /></td>
                                    <td className="p-4">{s.playerId && <StarRating playerId={s.playerId} />}</td>
                                 </tr>
                              ))}
                           </tbody>
                        </table>
                      </div>
                   </section>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState, useMemo } from 'react';
import { FileCheck, Trophy, Calendar, Star, TrendingUp, Save, Search, X, User, ChevronLeft, MapPin, Activity, Target, ShieldCheck, Heart } from 'lucide-react';
import { AppState, Match, Person, PlayerEvaluation } from '../types';
import { generateUUID } from '../App';

interface TechnicalReportsProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  onOpenPlayerReport: (player: Person) => void;
}

const TechnicalReports: React.FC<TechnicalReportsProps> = ({ state, setState, onOpenPlayerReport }) => {
  const [activeMode, setActiveMode] = useState<'match' | 'monthly'>('match');
  const [selectedMatchId, setSelectedMatchId] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [editingRadar, setEditingRadar] = useState<Person | null>(null);

  // بيانات الرادار للمؤقت
  const [radarFormData, setRadarFormData] = useState({
    physical: 7, tactical: 7, technical: 7, mental: 7, speed: 7
  });

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isViewer = currentUser?.role === 'مشاهد';

  const matches = useMemo(() => {
    return state.matches
      .filter(m => !restrictedCat || m.category === restrictedCat)
      .sort((a, b) => b.date.localeCompare(a.date));
  }, [state.matches, restrictedCat]);

  const activeMatch = useMemo(() => state.matches.find(m => m.id === selectedMatchId), [selectedMatchId, state.matches]);

  const members = useMemo(() => {
    return state.people.filter(p => !restrictedCat || p.category === restrictedCat);
  }, [state.people, restrictedCat]);

  const handleStarRating = (pid: string, stars: number, matchId?: string) => {
    if (isViewer) return;
    const date = matchId ? (matches.find(m => m.id === matchId)?.date || new Date().toISOString()) : `${selectedMonth}-01`;
    const type = matchId ? 'match' : 'monthly';

    const newEval: PlayerEvaluation = {
      id: generateUUID(),
      playerId: pid,
      matchId: matchId,
      date,
      stars,
      physical: 7, tactical: 7, technical: 7, mental: 7, speed: 7,
      evalType: type as any
    };

    setState(prev => ({
      ...prev,
      evaluations: [
        ...prev.evaluations.filter(e => !(e.playerId === pid && (matchId ? e.matchId === matchId : (e.evalType === 'monthly' && e.date.startsWith(selectedMonth))))),
        newEval
      ]
    }));
  };

  const handleUpdateRadar = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingRadar || isViewer) return;

    const evalId = generateUUID();
    const newEval: PlayerEvaluation = {
      id: evalId,
      playerId: editingRadar.id,
      date: new Date().toISOString().split('T')[0],
      stars: 0, // تحديث مقاييس فقط
      ...radarFormData,
      evalType: 'match' // افتراضي للرادار
    };

    setState(prev => ({
      ...prev,
      evaluations: [...prev.evaluations, newEval]
    }));

    setEditingRadar(null);
  };

  const getRating = (pid: string, matchId?: string) => {
    const ev = state.evaluations.find(e => 
      e.playerId === pid && 
      (matchId ? e.matchId === matchId : (e.evalType === 'monthly' && e.date.startsWith(selectedMonth)))
    );
    return ev?.stars || 0;
  };

  const StarRating: React.FC<{ pid: string, matchId?: string }> = ({ pid, matchId }) => {
    const current = getRating(pid, matchId);
    return (
      <div className="flex gap-1">
        {[1, 2, 3, 4, 5].map(s => (
          <button key={s} onClick={() => handleStarRating(pid, s, matchId)} className="transition-transform hover:scale-125">
            <Star size={18} className={s <= current ? 'text-orange-500 fill-orange-500' : 'text-slate-200'} />
          </button>
        ))}
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* الرأس والتبديل */}
      <div className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center shadow-sm gap-6">
        <div className="flex items-center gap-4">
          <div className="bg-[#001F3F] p-3 rounded-2xl text-white shadow-lg"><FileCheck size={28}/></div>
          <div>
            <h2 className="text-xl font-black text-slate-900 uppercase">مركز التقارير الفنية</h2>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">إدارة تقييمات الأداء وسجلات التميز الفني</p>
          </div>
        </div>

        <div className="flex p-1.5 bg-slate-100 border-2 border-slate-900 rounded-2xl">
          <button onClick={() => setActiveMode('match')} className={`px-8 py-2.5 rounded-xl font-black text-xs transition-all ${activeMode === 'match' ? 'bg-[#001F3F] text-white shadow-lg scale-105' : 'text-slate-500'}`}>تقييم مباراة</button>
          <button onClick={() => setActiveMode('monthly')} className={`px-8 py-2.5 rounded-xl font-black text-xs transition-all ${activeMode === 'monthly' ? 'bg-[#001F3F] text-white shadow-lg scale-105' : 'text-slate-500'}`}>التقييم الشهري</button>
        </div>
      </div>

      {activeMode === 'match' ? (
        <div className="space-y-6">
           <div className="bg-white p-8 rounded-[3rem] border-2 border-slate-900 shadow-sm">
              <label className="text-[10px] font-black text-slate-500 uppercase mb-3 block tracking-widest mr-2">1. حدد المواجهة من الأجندة</label>
              <select value={selectedMatchId} onChange={e => setSelectedMatchId(e.target.value)}
                className="w-full bg-slate-50 border-4 border-[#001F3F] rounded-[1.5rem] p-5 font-black text-xl text-[#001F3F] outline-none">
                <option value="">-- اختر المباراة المستهدفة بالتقييم --</option>
                {matches.map(m => <option key={m.id} value={m.id}>{m.date} | الكرامة × {m.opponent} ({m.category})</option>)}
              </select>
           </div>

           {activeMatch && (
             <div className="bg-white rounded-[3rem] border-2 border-slate-900 overflow-hidden shadow-xl animate-in slide-in-from-top-4 duration-300">
                <div className="bg-slate-900 p-6 flex justify-between items-center text-white border-b-4 border-orange-600">
