import React, { useMemo, useState } from 'react';
import { 
  ChevronRight, Printer, Target, AlertTriangle, Clock, Calendar, 
  TrendingUp, Users, Shield, MapPin, Activity, Globe, Trophy, 
  CheckCircle, Award, GraduationCap, Home, StickyNote, CreditCard, BarChart3, PieChart,
  Hash, ClipboardList, User, Timer, FileText, Briefcase, Sparkles, Loader2, X, BrainCircuit,
  HeartPulse, ShieldAlert, Gavel, Smartphone, CalendarDays, Wallet, Zap, ShieldCheck,
  Medal, Swords, Star, UserPlus, Info, Phone, Fingerprint
} from 'lucide-react';
import { AppState, Person, Match, AttendanceRecord, PlayerEvaluation } from '../types';
import ClubLogo from './ClubLogo';

interface PlayerReportProps {
  state: AppState;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';

  const playerEvals = useMemo(() => state.evaluations.filter(e => e.playerId === player.id), [state.evaluations, player.id]);

  const avgMatchStars = useMemo(() => {
    const matchEvals = playerEvals.filter(e => e.evalType === 'match' && e.stars > 0);
    if (matchEvals.length === 0) return 0;
    const total = matchEvals.reduce((acc, curr) => acc + curr.stars, 0);
    return (total / matchEvals.length).toFixed(1);
  }, [playerEvals]);

  const latestMonthlyEval = useMemo(() => {
    return [...playerEvals].filter(e => e.evalType === 'monthly').sort((a, b) => b.date.localeCompare(a.date))[0];
  }, [playerEvals]);

  const latestRadar = useMemo(() => {
    return [...playerEvals].filter(e => e.physical > 0).sort((a, b) => b.date.localeCompare(a.date))[0] || {
      physical: 7, tactical: 7, technical: 7, mental: 7, speed: 7
    };
  }, [playerEvals]);

  const radarData = useMemo(() => [
    { label: 'بدني', val: latestRadar.physical },
    { label: 'تكتيك', val: latestRadar.tactical },
    { label: 'تقني', val: latestRadar.technical },
    { label: 'ذهني', val: latestRadar.mental },
    { label: 'سرعة', val: latestRadar.speed }
  ], [latestRadar]);

  const matchStats = useMemo(() => {
    if (isStaff) return { list: [] };
    const list = state.matches.filter(m => m.isCompleted).map(m => {
      const s = m.lineup.starters.find(x => x.playerId === player.id);
      const b = m.lineup.subs.find(x => x.playerId === player.id);
      if (!s && !b) return null;
      const goals = m.events.filter(e => e.type === 'goal' && (e.player === player.id || e.player === player.name)).length;
      const rating = state.evaluations.find(e => e.playerId === player.id && e.matchId === m.id)?.stars || 0;
      return { opponent: m.opponent, date: m.date, mins: s?.minutesPlayed || b?.minutesPlayed || '0', goals, rating };
    }).filter(x => x !== null);
    return { list };
  }, [state.matches, state.evaluations, player.id, player.name, isStaff]);

  return (
    <div className="space-y-6 md:space-y-10 animate-in fade-in duration-500 pb-24 px-2 md:px-0 text-right font-['Tajawal']" dir="rtl">
      <div className="flex justify-between items-center no-print">
        <button onClick={onBack} className="bg-white border-2 border-[#001F3F] px-6 py-3 rounded-2xl font-black text-[#001F3F] flex items-center gap-2 shadow-md"><ChevronRight size={20}/> رجوع</button>
        <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-2xl font-black shadow-xl flex items-center gap-2 border-b-4 border-black"><Printer size={20}/> طباعة الملف الفني</button>
      </div>

      <div className="solid-panel overflow-hidden border-4 border-[#001F3F] !shadow-none md:!shadow-[10px_10px_0px_0px_#001F3F]">
        <div className="bg-[#001F3F] h-32 relative">
           <div className="absolute -bottom-12 right-8 flex items-end gap-6">
              <div className="w-32 h-32 bg-white rounded-[2rem] border-8 border-white flex items-center justify-center font-black text-6xl text-[#001F3F] shadow-2xl relative">
                 {player.name.charAt(0)}
                 <div className="absolute -top-4 -left-4 bg-orange-600 text-white w-10 h-10 rounded-full flex items-center justify-center text-sm border-4 border-white">#{player.number}</div>
              </div>
              <div className="mb-4">
                 <h1 className="text-3xl font-black text-white leading-tight">{player.name}</h1>
                 <div className="flex gap-2 mt-2"><span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{player.role}</span><span className="bg-blue-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{player.category}</span></div>
              </div>
           </div>
        </div>
        <div className="h-16"></div>
        <div className="px-8 pb-10 grid grid-cols-1 md:grid-cols-4 gap-6">
           <div className="bg-slate-50 p-6 rounded-3xl border-2 border-[#001F3F] text-center shadow-inner">
              <p className="text-[10px] font-black text-slate-400 uppercase mb-2">متوسط النجوم التاريخي</p>
              <div className="flex justify-center gap-1 mb-2">
                 {[1,2,3,4,5].map(s => <Star key={s} size={14} className={s <= Math.round(Number(avgMatchStars)) ? 'text-orange-500 fill-orange-500' : 'text-slate-200'}/>)}
              </div>
              <p className="text-3xl font-black text-[#001F3F] tabular-nums">{avgMatchStars}</p>
           </div>
           <div className="bg-slate-50 p-6 rounded-3xl border-2 border-[#001F3F] md:col-span-3">
              <p className="text-[10px] font-black text-orange-600 uppercase mb-3 border-r-4 border-orange-600 pr-2">آخر تقييم شهري من الإدارة</p>
              {latestMonthlyEval ? (
                <div className="space-y-2">
                   <div className="flex gap-1">
                      {[1,2,3,4,5].map(s => <Star key={s} size={16} className={s <= latestMonthlyEval.stars ? 'text-orange-500 fill-orange-500' : 'text-slate-200'}/>)}
                      <span className="text-[10px] text-slate-400 mr-2 font-black tabular-nums">({latestMonthlyEval.date})</span>
                   </div>
                   <p className="text-sm font-bold text-[#001F3F] italic leading-relaxed">"{latestMonthlyEval.coachNote || 'لا توجد ملاحظات مكتوبة.'}"</p>
                </div>
              ) : <p className="text-sm font-black text-slate-300 italic">لم يتم رصد تقييم شهري حالي.</p>}
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
         <div className="lg:col-span-2 space-y-8">
            <div className="bg-white p-8 rounded-[3rem] border-4 border-[#001F3F] shadow-sm flex flex-col md:flex-row items-center gap-12">
               <div className="w-full md:w-1/2">
                  <h3 className="text-lg font-black flex items-center gap-3 mb-8 text-[#001F3F]"><Target className="text-orange-600" size={24}/> البصمة الفنية المحدثة</h3>
                  <div className="relative w-full aspect-square max-w-[240px] mx-auto">
                    <svg viewBox="0 0 100 100" className="w-full h-full">
                       <circle cx="50" cy="50" r="45" fill="none" stroke="#e2e8f0" strokeWidth="0.5" />
                       <circle cx="50" cy="50" r="22.5" fill="none" stroke="#e2e8f0" strokeWidth="0.5" />
                       <polygon points={radarData.map((d, i) => { const angle = i * 72; const r = d.val * 4.5; return `${50 + r * Math.cos(angle * Math.PI / 180)},${50 + r * Math.sin(angle * Math.PI / 180)}`; }).join(' ')} fill="rgba(255, 107, 0, 0.4)" stroke="#FF6B00" strokeWidth="3" />
                    </svg>
                    {radarData.map((d, i) => { const angle = i * 72; return <div key={i} className="absolute font-black text-[10px] text-[#001F3F]" style={{ left: `${50 + 48 * Math.cos(angle * Math.PI / 180)}%`, top: `${50 + 48 * Math.sin(angle * Math.PI / 180)}%`, transform: 'translate(-50%, -50%)' }}>{d.label}</div>; })}
                  </div>
               </div>
               <div className="w-full md:w-1/2 space-y-6">
                  <div className="bg-slate-50 p-6 rounded-3xl border-2 border-slate-200 shadow-inner"><h4 className="text-[11px] font-black text-slate-900 mb-3 uppercase tracking-widest">توجيه فني</h4><p className="text-[12px] font-black text-slate-800 leading-relaxed italic">"تظهر سجلات الرادار استقراراً في المعدل البدني، يوصى بالتركيز على الوعي التكتيكي في مباريات الدوري القادمة."</p></div>
                  <div className="bg-blue-900 text-white p-6 rounded-3xl shadow-lg border-b-4 border-black"><p className="text-[10px] font-black uppercase opacity-60 mb-2">مؤشر الجاهزية الرقمي</p><div className="flex items-center gap-3"><div className="h-4 flex-1 bg-white/20 rounded-full overflow-hidden"><div className="h-full bg-orange-500 w-[82%]"></div></div><span className="font-black text-lg tabular-nums">82%</span></div></div>
               </div>
            </div>

            <div className="bg-white p-6 rounded-[2.5rem] border-2 border-[#001F3F] shadow-sm overflow-hidden">
               <h3 className="text-lg font-black text-slate-900 mb-6 flex items-center gap-3"><ClipboardList className="text-[#001F3F]" size={24}/> سجل الأداء الميداني (Match Log)</h3>
               <div className="overflow-x-auto">
                 <table className="w-full text-right border-collapse min-w-[500px]">
                    <thead><tr className="bg-slate-50 border-y-2 border-slate-200 text-[10px] font-black uppercase"><th className="p-4 border-l">المنافس</th><th className="p-4 border-l text-center">دقائق</th><th className="p-4 border-l text-center">أهداف</th><th className="p-4 text-center">النجوم</th></tr></thead>
                    <tbody>
                       {matchStats.list.length > 0 ? matchStats.list.map((m: any, i) => (
                         <tr key={i} className="border-b border-slate-100 text-xs font-black"><td className="p-4 border-l"><div className="flex flex-col"><span className="text-[#001F3F]">{m.opponent}</span><span className="text-[9px] text-slate-400 font-bold">{m.date}</span></div></td><td className="p-4 border-l text-center">{m.mins} د</td><td className="p-4 border-l text-center text-emerald-600">{m.goals || '-'}</td><td className="p-4"><div className="flex justify-center gap-0.5">{[1,2,3,4,5].map(s => <Star key={s} size={10} className={s <= m.rating ? 'text-orange-500 fill-orange-500' : 'text-slate-200'}/>)}</div></td></tr>
                       )) : <tr><td colSpan={4} className="p-10 text-center text-slate-300 font-black italic">لا توجد سجلات مؤرشفة.</td></tr>}
                    </tbody>
                 </table>
               </div>
            </div>
         </div>

         <div className="space-y-8">
            <div className="bg-[#001F3F] p-8 rounded-[3rem] border-4 border-black text-white shadow-2xl relative overflow-hidden">
               <div className="absolute top-0 right-0 w-32 h-32 bg-orange-600/10 rounded-full -mr-16 -mt-16"></div>
               <h3 className="text-lg font-black uppercase mb-6 flex items-center gap-3 border-b border-white/10 pb-4"><ShieldCheck className="text-orange-500" size={24}/> الحالة التعاقدية والمالية</h3>
               <div className="space-y-4">
                  <div className="flex justify-between border-b border-white/5 pb-2"><span className="text-slate-400 font-black text-[10px]">الرقم الوطني:</span><span className="font-black text-xs">{player.nationalId || '--- --- ---'}</span></div>
                  <div className="flex justify-between border-b border-white/5 pb-2"><span className="text-slate-400 font-black text-[10px]">تاريخ الميلاد:</span><span className="font-black text-xs">{player.birthDate}</span></div>
                  <div className="bg-white/5 p-5 rounded-2xl border border-white/10 mt-6"><p className="text-orange-500 font-black text-[9px] uppercase mb-3 flex items-center gap-2"><CreditCard size={14}/> القيمة المالية للعقد</p><p className="text-2xl font-black text-emerald-400 tabular-nums">{player.contractValue || '0.00 SP'}</p></div>
               </div>
            </div>
            <div className="bg-white p-8 rounded-[2.5rem] border-2 border-red-900 shadow-md">
               <h4 className="text-md font-black text-red-700 mb-6 flex items-center gap-3"><Gavel className="text-red-700" size={22}/> سجل العقوبات والانضباط</h4>
               <p className="text-[12px] font-black text-slate-900 leading-relaxed italic p-4 bg-red-50 rounded-2xl border-r-4 border-red-700">{player.penalties || "الملف نظيف إدارياً."}</p>
            </div>
         </div>
      </div>
    </div>
  );
};

