                </button>
             </div>
             {aiAnalysis ? (
               <div className="text-sm md:text-md font-bold text-slate-900 bg-blue-50 p-6 rounded-[2rem] border-r-8 border-blue-900 shadow-inner whitespace-pre-wrap">
