import React, { useState, useMemo } from 'react';
import { BarChart3, Users, Search, Filter, Trophy, Target, AlertTriangle, TrendingUp, ChevronLeft, Sparkles, Loader2, BrainCircuit } from 'lucide-react';
import { AppState, Person } from '../types';
import { GoogleGenAI } from "@google/genai";

interface StatsViewProps {
  state: AppState;
  onOpenReport: (player: Person) => void;
}

const StatsView: React.FC<StatsViewProps> = ({ state, onOpenReport }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const globalFilter = state.globalCategoryFilter;
  const restrictedCat = state.currentUser?.restrictedCategory;

  const playerStats = useMemo(() => {
    return state.people
      .filter(p => p.role === 'لاعب' && 
        (restrictedCat ? p.category === restrictedCat : (globalFilter === 'الكل' || p.category === globalFilter)) &&
        (p.name.includes(searchTerm))
      )
      .map(player => {
        const completedMatches = state.matches.filter(m => m.isCompleted);
        const playerMatches = completedMatches.filter(m => 
          m.lineup.starters.some(s => s.playerId === player.id) || 
          m.lineup.subs.some(s => s.playerId === player.id)
        );

        let goals = 0;
        let assists = 0;
        let yellows = 0;
        let reds = 0;

        playerMatches.forEach(m => {
          goals += m.events.filter(e => e.type === 'goal' && (e.player === player.id || e.player === player.name)).length;
          assists += m.events.filter(e => e.type === 'assist' && (e.player === player.id || e.player === player.name)).length;
          yellows += m.events.filter(e => e.type === 'yellow' && (e.player === player.id || e.player === player.name)).length;
          reds += m.events.filter(e => e.type === 'red' && (e.player === player.id || e.player === player.name)).length;
        });

        const sessions = state.sessions.filter(s => s.category === player.category);
        const records = state.attendance.filter(a => a.personId === player.id);
        const present = records.filter(r => r.status === 'حاضر').length;
        const late = records.filter(r => r.status === 'متأخر').length;
        const attendanceRate = sessions.length > 0 ? Math.round(((present + late * 0.7) / sessions.length) * 100) : 0;

        return {
          player,
          matchesPlayed: playerMatches.length,
          goals,
          assists,
          yellows,
          reds,
          attendanceRate
        };
      })
      .sort((a, b) => b.goals - a.goals);
  }, [state.people, state.matches, state.attendance, state.sessions, globalFilter, restrictedCat, searchTerm]);

  const generateFullClubAiReport = async () => {
    setLoadingAi(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const summary = playerStats.slice(0, 5).map(s => `${s.player.name}: أهداف(${s.goals}), التزام(${s.attendanceRate}%)`).join(' | ');
      const prompt = `بصفتك محلل أداء بنادي الكرامة السوري. بناءً على أعلى 5 لاعبين أداءً حالياً: ${summary}. قدم تقريراً إدارياً مختصراً لمكتب كرة القدم حول الوضع الفني العام لهذه الفئة (${globalFilter}) وتوصية واحدة للتطوير.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });
      setAiReport(response.text || "فشل توليد التقرير.");
    } catch (e) {
      console.error(e);
      setAiReport("خطأ في الاتصال بالذكاء الاصطناعي.");
    } finally {
      setLoadingAi(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="bg-slate-900 p-8 rounded-[3rem] border-4 border-[#001F3F] text-white shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
           <div className="bg-orange-600 p-4 rounded-3xl shadow-lg">
             <BarChart3 size={32} />
           </div>
