  const [loadingBrief, setLoadingBrief] = useState(false);

  const now = new Date();
  const todayStr = now.toLocaleDateString('en-CA');
  const currentTime = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');

  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowStr = tomorrow.toLocaleDateString('en-CA');

  const globalFilter = state.globalCategoryFilter;

  const generateDailyBriefing = async () => {
    setLoadingBrief(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `بصفتك كبير المستشارين الفنيين لنادي الكرامة السوري. لدينا اليوم ${state.people.length} عضو مسجل، و ${upcomingMatches.length} مباراة قادمة. أعطني نصيحة إدارية فنية واحدة جداً مركزة لمكتب كرة القدم لهذا اليوم بأسلوب رسمي وراقي.`;
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });
      setAiBriefing(response.text || null);
    } catch (e) { console.error(e); }
    finally { setLoadingBrief(false); }
  };

  useEffect(() => {
    generateDailyBriefing();
