                 <div>
                    <h2 className="text-3xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-lg font-black text-orange-600 uppercase tracking-widest">مكتب كرة القدم المركزي</p>
                 </div>
              </div>
              <div className="text-left font-black">
                 <p className="text-2xl uppercase tracking-tighter">تقرير ملخص المباراة</p>
                 <p className="text-sm text-slate-400">كود الأرشفة: {activeMatch.id.slice(0,8)}</p>
              </div>
           </div>

           <div className="grid grid-cols-2 gap-10 mb-12 bg-slate-50 p-8 border-2 border-slate-900 rounded-[2rem]">
              <div className="space-y-3">
                 <p className="text-[10px] font-black text-slate-400 uppercase">المنافسة والتوقيت</p>
                 <h3 className="text-2xl font-black text-slate-900">الكرامة × {activeMatch.opponent}</h3>
                 <p className="text-sm font-black text-slate-700 flex items-center gap-2"><Calendar size={14}/> {activeMatch.date} | {activeMatch.time}</p>
                 <p className="text-sm font-black text-slate-700 flex items-center gap-2"><MapPin size={14}/> {activeMatch.pitch}</p>
                 <span className="inline-block bg-orange-600 text-white text-[10px] font-black px-3 py-1 rounded-lg uppercase">{activeMatch.matchType} - {activeMatch.category}</span>
              </div>
              <div className="text-center flex flex-col justify-center border-r-4 border-slate-200">
                 <p className="text-[10px] font-black text-slate-400 uppercase mb-2">النتيجة النهائية</p>
                 <p className="text-7xl font-black tracking-widest text-[#001F3F]">{activeMatch.ourScore} - {activeMatch.opponentScore}</p>
              </div>
           </div>

           <div className="grid grid-cols-2 gap-12 mb-12">
              <section>
                 <h4 className="text-lg font-black border-r-4 border-blue-900 pr-3 mb-6 flex items-center gap-2 uppercase"><Users size={20}/> التشكيلة الأساسية</h4>
                 <div className="space-y-2">
                    {activeMatch.lineup.starters.map((s, i) => (
                      <div key={i} className="flex items-center justify-between p-3 border-b border-slate-200 text-sm font-black">
                         <div className="flex items-center gap-3">
                            <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center text-xs">#{s.number || (i+1)}</span>
                            <span>{s.name || '---'}</span>
                            {activeMatch.lineup.captain === s.playerId && <Crown size={14} className="text-orange-500" />}
