                         <span className="text-slate-400 text-xs">{s.minutesPlayed}د</span>
                      </div>
                    ))}
                 </div>
              </section>
              <section>
                 <h4 className="text-lg font-black border-r-4 border-orange-600 pr-3 mb-6 flex items-center gap-2 uppercase"><Zap size={20}/> أحداث المباراة</h4>
                 <div className="space-y-3">
                    {activeMatch.events.sort((a,b) => (parseInt(a.minute)||0)-(parseInt(b.minute)||0)).map((ev, i) => {
                      const p = state.people.find(x => x.id === ev.player);
                      return (
                        <div key={i} className="flex items-center gap-4 text-xs font-black p-2 bg-slate-50 rounded-xl border border-slate-100">
