                 <div className="mt-8">
                    <h4 className="text-lg font-black border-r-4 border-emerald-600 pr-3 mb-4 flex items-center gap-2 uppercase"><LogIn size={20}/> البدلاء والمشاركة</h4>
                    <div className="space-y-2">
                       {activeMatch.lineup.subs.filter(s => s.playerId).map((s, i) => (
                         <div key={i} className="flex items-center justify-between p-2 border-b text-[11px] font-black">
                            <span>{s.name} (دخول د.{s.substitutionMinute})</span>
