    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const fieldClass = "w-full bg-slate-50 border-3 border-[#001F3F] rounded-2xl py-4 px-5 font-black text-[#001F3F] outline-none focus:border-orange-600 transition-all text-sm placeholder:text-slate-500 shadow-sm";
  const labelClass = "text-[12px] font-black text-[#001F3F] mr-3 uppercase block mb-2 tracking-tight";

  if (showPrintView) {
    return (
      <div className="fixed inset-0 bg-white z-[500] overflow-y-auto p-12 text-right dir-rtl">
        <div className="max-w-5xl mx-auto border-4 border-slate-900 p-12 print:border-2">
