              <button onClick={() => setShowPrintView(false)} className="flex items-center gap-2 font-black text-slate-700 hover:text-orange-600 transition-all"><ChevronRight/> العودة للأجندة</button>
              <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-10 py-4 rounded-2xl font-black flex items-center gap-3 shadow-xl"><Printer size={20}/> طباعة التقرير A4</button>
           </div>
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-8 mb-10">
              <div className="flex items-center gap-6">
                 <ClubLogo size={100} />
                 <div>
                    <h2 className="text-3xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-lg font-black text-orange-600 uppercase tracking-widest">مكتب كرة القدم المركزي</p>
                 </div>
              </div>
           </div>
           <table className="w-full text-right border-collapse">
              <thead>
                 <tr className="bg-slate-100 border-y-2 border-slate-900 text-sm font-black">
                    <th className="p-4 border-l">التاريخ والوقت</th>
                    <th className="p-4 border-l">المنافس المستهدف</th>
                    <th className="p-4 border-l text-center">النتيجة النهائية</th>
                    <th className="p-4">موقع المباراة</th>
                 </tr>
              </thead>
              <tbody>
                 {filteredMatches.map(m => (
                    <tr key={m.id} className="border-b border-slate-200 text-sm font-black text-slate-900">
                       <td className="p-4 border-l">{m.date} - {m.time}</td>
                       <td className="p-4 border-l">{m.opponent}</td>
                       <td className="p-4 border-l text-center">{m.isCompleted ? `${m.ourScore} - ${m.opponentScore}` : 'قيد الانتظار'}</td>
                       <td className="p-4">{m.pitch}</td>
                    </tr>
                 ))}
              </tbody>
           </table>
        </div>
      </div>
    );
  }

  // معاينة تقرير المباراة الفردي الشامل
  if (showSingleMatchReport && activeMatch) {
    return (
      <div className="fixed inset-0 bg-white z-[600] overflow-y-auto p-4 md:p-12 text-right dir-rtl">
        <div className="max-w-[210mm] mx-auto border-[6px] border-slate-900 p-10 print:border-2 bg-white min-h-screen">
           <div className="no-print flex justify-between items-center mb-10 border-b pb-4">
              <button onClick={() => setShowSingleMatchReport(false)} className="flex items-center gap-2 font-black text-slate-600 hover:text-red-600 transition-all"><ChevronRight/> إغلاق التقرير الفني</button>
              <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-10 py-4 rounded-2xl font-black flex items-center gap-3 shadow-2xl"><Printer size={20}/> طباعة كوثيقة رسمية مختومة</button>
           </div>

           <div className="flex justify-between items-center border-b-8 border-slate-900 pb-10 mb-10">
              <div className="flex items-center gap-8">
                 <ClubLogo size={110} />
                 <div>
                    <h2 className="text-4xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-xl font-black text-orange-600 uppercase tracking-widest mt-1">مكتب كرة القدم المركزي</p>
                 </div>
              </div>
              <div className="text-left font-black">
                 <p className="text-2xl uppercase tracking-tighter text-[#001F3F]">تقرير ملخص المباراة</p>
                 <p className="text-sm text-slate-500 font-bold">كود الأرشفة الرقمي: {activeMatch.id.slice(0,10)}</p>
              </div>
           </div>

           <div className="grid grid-cols-2 gap-10 mb-12 bg-slate-50 p-10 border-3 border-slate-900 rounded-[3rem] shadow-inner">
              <div className="space-y-4">
                 <p className="text-[12px] font-black text-slate-500 uppercase tracking-widest">تفاصيل المنافسة والموقع</p>
                 <h3 className="text-3xl font-black text-[#001F3F] tracking-tighter">نادي الكرامة × {activeMatch.opponent}</h3>
                 <div className="space-y-2">
                    <p className="text-md font-black text-slate-800 flex items-center gap-3"><Calendar size={18} className="text-orange-600"/> {activeMatch.date} | {activeMatch.time}</p>
                    <p className="text-md font-black text-slate-800 flex items-center gap-3"><MapPin size={18} className="text-[#001F3F]"/> {activeMatch.pitch}</p>
                 </div>
                 <div className="flex gap-2 mt-4">
                    <span className="inline-block bg-orange-600 text-white text-[11px] font-black px-4 py-1.5 rounded-xl uppercase border-2 border-white shadow-sm">{activeMatch.matchType}</span>
                    <span className="inline-block bg-[#001F3F] text-white text-[11px] font-black px-4 py-1.5 rounded-xl uppercase border-2 border-white shadow-sm">فئة {activeMatch.category}</span>
                 </div>
              </div>
              <div className="text-center flex flex-col justify-center border-r-8 border-slate-200">
                 <p className="text-[12px] font-black text-slate-500 uppercase mb-4 tracking-widest">النتيجة النهائية المعتمدة</p>
                 <p className="text-8xl font-black tracking-widest text-[#001F3F] drop-shadow-lg">{activeMatch.ourScore} - {activeMatch.opponentScore}</p>
              </div>
           </div>

           <div className="grid grid-cols-2 gap-12 mb-12">
              <section>
                 <h4 className="text-xl font-black border-r-8 border-blue-900 pr-4 mb-8 flex items-center gap-3 uppercase text-[#001F3F] tracking-tighter"><Users size={24}/> التشكيلة الأساسية (Starting XI)</h4>
                 <div className="space-y-2.5">
                    {activeMatch.lineup.starters.map((s, i) => (
                      <div key={i} className="flex items-center justify-between p-4 border-b-2 border-slate-100 text-sm font-black bg-slate-50/30 rounded-xl">
                         <div className="flex items-center gap-4">
                            <span className="w-9 h-9 bg-[#001F3F] text-white rounded-xl flex items-center justify-center text-xs border-2 border-white shadow-md">#{s.number || (i+1)}</span>
                            <span className="text-[#001F3F] text-md">{s.name || '---'}</span>
                            {activeMatch.lineup.captain === s.playerId && <Crown size={16} className="text-orange-500 animate-pulse" />}
                         </div>
                         <span className="text-slate-800 text-xs bg-white px-2 py-1 rounded-lg border border-slate-200 shadow-sm">{s.minutesPlayed}د مشاركة</span>
                      </div>
                    ))}
                 </div>
              </section>
              <section>
                 <h4 className="text-xl font-black border-r-8 border-orange-600 pr-4 mb-8 flex items-center gap-3 uppercase text-[#001F3F] tracking-tighter"><Zap size={24} className="text-orange-600"/> الخط الزمني للأحداث الفنية</h4>
                 <div className="space-y-4">
                    {activeMatch.events.sort((a,b) => (parseInt(a.minute)||0)-(parseInt(b.minute)||0)).map((ev, i) => {
                      const p = state.people.find(x => x.id === ev.player);
                      return (
                        <div key={i} className="flex items-center gap-5 text-sm font-black p-3 bg-slate-50 rounded-2xl border-2 border-slate-100 shadow-sm transition-all hover:border-orange-200">
                           <span className="w-10 text-blue-900 font-black text-lg">{ev.minute}'</span>
                           <span className="text-2xl drop-shadow-sm">{ev.type==='goal'?'⚽':ev.type==='yellow'?'🟨':ev.type==='red'?'🟥':'👟'}</span>
                           <span className="flex-1 text-[#001F3F]">{p?.name || ev.player}</span>
                        </div>
                      );
                    })}
                    {activeMatch.events.length === 0 && <p className="text-center py-10 text-slate-400 font-black italic border-2 border-dashed rounded-3xl">لا توجد أحداث مسجلة</p>}
                 </div>
                 <div className="mt-10">
                    <h4 className="text-xl font-black border-r-8 border-emerald-600 pr-4 mb-6 flex items-center gap-3 uppercase text-[#001F3F] tracking-tighter"><LogIn size={24} className="text-emerald-600"/> التبديلات والمشاركة البديلة</h4>
                    <div className="space-y-2.5">
                       {activeMatch.lineup.subs.filter(s => s.playerId).map((s, i) => (
                         <div key={i} className="flex items-center justify-between p-3 border-b-2 border-emerald-50 text-sm font-black bg-emerald-50/20 rounded-xl">
                            <span className="text-[#001F3F]">{s.name} <span className="text-[10px] text-slate-500 mr-2">(دخول د.{s.substitutionMinute})</span></span>
                            <span className="text-emerald-800 font-black">{s.minutesPlayed} دقيقة</span>
                         </div>
                       ))}
                    </div>
                 </div>
              </section>
           </div>

           <section className="mb-12">
              <h4 className="text-xl font-black border-r-8 border-[#001F3F] pr-4 mb-6 flex items-center gap-3 uppercase text-[#001F3F] tracking-tighter"><FileText size={24}/> التقرير الفني والتحليل الإداري للمدرب</h4>
              <div className="p-10 bg-slate-50 border-3 border-slate-900 rounded-[3rem] text-md font-black leading-relaxed text-[#001F3F] italic shadow-inner">
                 {activeMatch.notes || "لا توجد ملاحظات فنية مسجلة لهذه المباراة في أرشيف مكتب كرة القدم."}
              </div>
           </section>

           <div className="mt-28 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-16">
                 <p className="font-black text-md text-[#001F3F]">توقيع المدرب الفني</p>
                 <p className="text-[12px] font-black text-slate-300">........................................</p>
              </div>
              <div className="text-center space-y-16">
                 <p className="font-black text-md text-[#001F3F]">توقيع إداري الفئة</p>
                 <p className="text-[12px] font-black text-slate-300">........................................</p>
              </div>
              <div className="text-center space-y-16">
                 <div className="space-y-1">
                    <p className="font-black text-md text-[#001F3F]">مدير مكتب كرة القدم</p>
                    <p className="font-black text-sm text-blue-900">عزت عامر الشيخة</p>
                 </div>
                 <p className="text-[12px] font-black text-slate-300">........................................</p>
              </div>
           </div>
           <div className="mt-14 pt-6 border-t-2 border-slate-100 text-center hidden print:block">
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">وثيقة رسمية صادرة عن النظام الإلكتروني لنادي الكرامة الرياضي - Football Office Intelligence OS</p>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-6">
        <div>
           <h2 className="text-2xl font-black text-[#001F3F] flex items-center gap-4 tracking-tighter">
             <Trophy size={32} className="text-orange-600 drop-shadow-md" /> إدارة أجندة المباريات والتقارير الفنية
           </h2>
        </div>
        <div className="flex gap-3">
          <button onClick={() => setShowPrintView(true)} className="bg-white text-[#001F3F] border-3 border-[#001F3F] px-8 py-4 rounded-2xl font-black text-sm hover:bg-slate-50 shadow-md transition-all active:scale-95">طباعة كامل الأجندة</button>
          {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-10 py-4 rounded-2xl font-black text-sm shadow-xl hover:bg-black transition-all border-b-4 border-black">جدولة مواجهة رسمية</button>}
        </div>
      </div>

