                                        {!activeMatch.isCompleted && <button onClick={() => removeEvent(ev.id)} className="text-red-400 hover:text-red-700 opacity-0 group-hover:opacity-100 transition-all scale-125"><X size={16}/></button>}
                                     </div>
                                     <div className="flex gap-3">
                                       <select disabled={activeMatch.isCompleted} className="flex-1 text-[13px] font-black bg-transparent outline-none cursor-pointer border-b-2 border-[#001F3F] text-[#001F3F] py-1" value={ev.player} onChange={e => {
                                          const evs = [...activeMatch.events];
                                          const idxInOrig = evs.findIndex(x => x.id === ev.id);
                                          evs[idxInOrig].player = e.target.value;
                                          setActiveMatch({...activeMatch, events: evs});
                                       }}>
                                          <option value="">-- اختر اللاعب المعني --</option>
                                          {state.people.filter(p => p.category === activeMatch.category).map(p => <option key={p.id} value={p.id} className="text-slate-900 font-black">{p.name} (#{p.number})</option>)}
                                       </select>
                                       <input disabled={activeMatch.isCompleted} type="number" placeholder="د" className="w-14 bg-slate-100 border-2 border-slate-300 rounded-xl px-2 py-1 text-center text-sm font-black text-[#001F3F] shadow-inner" value={ev.minute} onChange={e => {
                                          const evs = [...activeMatch.events];
                                          const idxInOrig = evs.findIndex(x => x.id === ev.id);
                                          evs[idxInOrig].minute = e.target.value;
                                          setActiveMatch({...activeMatch, events: evs});
                                       }} />
                                     </div>
                                  </div>
                               </div>
                            ))}
                            {activeMatch.events.length === 0 && <div className="text-center py-20 bg-slate-50 rounded-[3rem] border-3 border-dashed border-slate-200 font-black text-slate-400 italic">لا توجد وقائع مسجلة حتى اللحظة</div>}
                         </div>
                      </section>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

