      const prompt = `بصفتك محلل أداء بنادي الكرامة السوري. بناءً على أعلى 5 لاعبين أداءً حالياً: ${summary}. قدم تقريراً إدارياً مختصراً لمكتب كرة القدم حول الوضع الفني العام لهذه الفئة (${globalFilter}) وتوصية واحدة للتطوير.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });
      setAiReport(response.text || "فشل توليد التقرير.");
    } catch (e) {
      console.error(e);
      setAiReport("خطأ في الاتصال بالذكاء الاصطناعي.");
    } finally {
      setLoadingAi(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="bg-[#001F3F] p-10 rounded-[3rem] border-4 border-white/20 text-white shadow-2xl flex flex-col md:flex-row justify-between items-center gap-8">
        <div className="flex items-center gap-6">
           <div className="bg-orange-600 p-5 rounded-[2rem] shadow-xl border-2 border-white/20">
             <BarChart3 size={48} />
           </div>
           <div>
             <h2 className="text-3xl font-black uppercase drop-shadow-lg tracking-tighter">إحصائيات الأداء التجميعية</h2>
             <p className="text-[12px] font-black text-orange-400 uppercase tracking-[0.2em] mt-1 drop-shadow-md">تحليل الأرقام الفنية المعتمدة لمكتب كرة القدم</p>
           </div>
        </div>
        <button 
          onClick={generateFullClubAiReport}
          disabled={loadingAi}
          className="bg-white text-[#001F3F] px-10 py-5 rounded-2xl font-black text-md flex items-center gap-4 hover:bg-orange-600 hover:text-white transition-all shadow-2xl border-b-8 border-slate-200 active:translate-y-2 active:border-b-0 uppercase tracking-tighter"
        >
          {loadingAi ? <Loader2 className="animate-spin" size={24}/> : <Sparkles size={24} className="text-orange-600 group-hover:text-white"/>}
          توليد تقرير الذكاء الفني للفئة
        </button>
      </div>

      {aiReport && (
        <div className="bg-white p-10 rounded-[3rem] border-[6px] border-orange-600 shadow-2xl animate-in slide-in-from-top-6 duration-700 relative overflow-hidden">
           <div className="absolute top-0 left-0 w-3 h-full bg-orange-600"></div>
           <div className="flex items-center gap-4 mb-6 text-orange-600">
              <BrainCircuit size={36}/>
              <h3 className="font-black text-2xl uppercase tracking-tighter">ملخص استخبارات مكتب كرة القدم (AI)</h3>
           </div>
           <p className="text-lg font-black text-[#001F3F] leading-relaxed italic border-r-8 border-slate-100 pr-6">{aiReport}</p>
        </div>
      )}

      <div className="relative max-w-5xl mx-auto">
