          className="w-full bg-white border-4 border-[#001F3F] rounded-[2.5rem] py-6 pr-16 pl-8 font-black outline-none focus:border-orange-600 transition-all text-xl placeholder:text-slate-500 shadow-xl"
        />
      </div>

      <div className="bg-white rounded-[4rem] shadow-2xl border-4 border-slate-900 overflow-hidden">
        <div className="overflow-x-auto">
