                <th className="px-6 py-6 text-[12px] font-black text-emerald-800 uppercase tracking-widest text-center">الأهداف</th>
                <th className="px-6 py-6 text-[12px] font-black text-blue-800 uppercase tracking-widest text-center">تمريرات</th>
                <th className="px-6 py-6 text-[12px] font-black text-slate-900 uppercase tracking-widest text-center">معدل الانضباط</th>
                <th className="px-10 py-6"></th>
              </tr>
            </thead>
            <tbody className="divide-y-2 divide-slate-100">
              {playerStats.map(({ player, matchesPlayed, goals, assists, attendanceRate }) => (
                <tr key={player.id} className="hover:bg-slate-50 transition-all group">
                  <td className="px-10 py-5">
                    <div className="flex items-center gap-5">
