                  <td className="px-6 py-5 text-center">
                    <span className={`px-5 py-2 rounded-2xl font-black text-xl border-2 ${assists > 0 ? 'bg-blue-50 text-blue-800 border-blue-500 shadow-md' : 'bg-slate-50 text-slate-300 border-slate-100'}`}>
