                          className={`h-full transition-all duration-1000 ${attendanceRate > 80 ? 'bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]' : attendanceRate > 50 ? 'bg-orange-500 shadow-[0_0_10px_rgba(249,115,22,0.5)]' : 'bg-red-600 shadow-[0_0_10px_rgba(220,38,38,0.5)]'}`} 
                          style={{ width: `${attendanceRate}%` }}
                         />
