                <header className="flex flex-col md:flex-row justify-between items-center mb-8 border-b-4 border-slate-900 pb-6 gap-4">
                   <div className="text-center md:text-right">
                      <h2 className="text-xl md:text-3xl font-black text-[#001F3F] high-contrast-text">الكرامة × {activeMatch.opponent}</h2>
                      <div className="flex gap-2 mt-2 justify-center md:justify-start">
                         <span className="bg-slate-100 text-[#001F3F] text-[9px] font-black px-3 py-1 rounded-full border border-slate-900">{activeMatch.date}</span>
                         {activeMatch.isCompleted && <span className="bg-red-50 text-red-600 text-[9px] font-black px-3 py-1 rounded-full border border-red-200 flex items-center gap-1"><Lock size={10}/> مقفل</span>}
                      </div>
                   </div>
                   <div className="flex flex-wrap gap-2 justify-center">
                      <button onClick={() => setShowSingleMatchReport(true)} className="bg-white text-[#001F3F] border-2 border-[#001F3F] px-4 py-2 rounded-xl font-black text-[10px] shadow-sm flex items-center gap-2"><FileText size={16}/> التقرير</button>
                      {isManager && (
                        <button onClick={() => saveMatchDetails(!activeMatch.isCompleted)} className={`${activeMatch.isCompleted ? 'bg-red-600' : 'bg-emerald-600'} text-white px-4 py-2 rounded-xl font-black text-[10px] shadow-md flex items-center gap-2`}>
                          {activeMatch.isCompleted ? <Unlock size={16}/> : <Lock size={16}/>} {activeMatch.isCompleted ? 'فتح' : 'اعتماد وقفل'}
                        </button>
                      )}
                      {!activeMatch.isCompleted && <button onClick={() => saveMatchDetails(false)} className="bg-blue-600 text-white px-4 py-2 rounded-xl font-black text-[10px] shadow-md flex items-center gap-2"><Save size={16}/> حفظ</button>}
                      <button onClick={() => setActiveMatch(null)} className="bg-slate-100 p-2 rounded-xl border-2 border-slate-300"><X size={20}/></button>
                   </div>
                </header>

                <div className={`grid grid-cols-1 lg:grid-cols-12 gap-8 ${activeMatch.isCompleted ? 'opacity-80 pointer-events-none' : ''}`}>
                   <div className="lg:col-span-8 space-y-8">
                      <section>
                         <h3 className="text-md font-black text-[#001F3F] mb-4 border-r-4 border-orange-600 pr-2 uppercase">التشكيلة الأساسية (Starting XI)</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="bg-slate-50 p-4 rounded-2xl border-2 border-slate-900 shadow-sm flex flex-col gap-3">
                                  <div className="flex justify-between items-center">
                                     <span className="w-8 h-8 bg-[#001F3F] text-white rounded-lg flex items-center justify-center font-black text-xs border border-white">#{s.number || (idx+1)}</span>
                                     <div className="flex items-center gap-2">
                                        <Timer size={12} className="text-emerald-600"/>
                                        <input type="number" className="w-12 bg-white border border-slate-300 rounded-lg text-center font-bold text-[10px]" value={s.minutesPlayed || '90'} onChange={e => {
                                           const nl = {...activeMatch.lineup}; nl.starters[idx].minutesPlayed = e.target.value; setActiveMatch({...activeMatch, lineup: nl});
                                        }} />
                                     </div>
                                  </div>
                                  <select className={inputStyle} value={s.playerId} onChange={e => updateActiveMatchLineup(idx, e.target.value, true)}>
                                     <option value="">-- اختر لاعب --</option>
                                     {getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>)}
                                  </select>
                               </div>
                            ))}
                         </div>
                      </section>

                      {/* خانة التبديلات اللانهائية المجددة */}
                      <section className="bg-slate-50 p-4 md:p-6 rounded-[2rem] border-2 border-dashed border-[#001F3F]">
                         <div className="flex justify-between items-center mb-6">
                            <h3 className="text-md font-black text-[#001F3F] uppercase flex items-center gap-2"><TrendingUp size={20} className="text-blue-600"/> التبديلات اللانهائية</h3>
                            <button onClick={addSub} className="bg-[#001F3F] text-white px-4 py-2 rounded-xl font-black text-[10px] flex items-center gap-1 shadow-md"><Plus size={14}/> إضافة تبديل</button>
                         </div>
                         <div className="space-y-4">
                            {activeMatch.lineup.subs.map((s, idx) => (
                               <div key={idx} className="bg-white p-4 rounded-2xl border-2 border-slate-300 flex flex-col md:flex-row gap-3 items-center shadow-sm">
                                  <div className="flex-1 w-full">
                                     <label className={labelStyle}>اللاعب البديل</label>
                                     <select className={inputStyle} value={s.playerId} onChange={e => updateSub(idx, e.target.value)}>
                                        <option value="">-- اختر لاعب --</option>
                                        {getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>)}
                                     </select>
                                  </div>
                                  <div className="flex-1 w-full">
                                     <label className={labelStyle}>بدلاً من</label>
                                     <select className={inputStyle} value={s.replacedPlayerId || ''} onChange={e => handleSubstitutionCalculation(idx, e.target.value, s.substitutionMinute || '0')}>
                                        <option value="">-- خروج لاعب --</option>
                                        {activeMatch.lineup.starters.map(st => <option key={st.playerId} value={st.playerId}>{st.name}</option>)}
                                     </select>
                                  </div>
                                  <div className="w-20">
                                     <label className={labelStyle}>دقيقة</label>
                                     <input type="number" className={inputStyle + " text-center"} value={s.substitutionMinute || ''} placeholder="0" onChange={e => handleSubstitutionCalculation(idx, s.replacedPlayerId || '', e.target.value)} />
                                  </div>
                                  <button onClick={() => removeSub(idx)} className="mt-4 md:mt-0 p-2 text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={16}/></button>
                               </div>
                            ))}
                            {activeMatch.lineup.subs.length === 0 && <p className="text-center py-6 text-slate-400 font-bold italic text-xs">لا توجد تبديلات مسجلة بعد.</p>}
                         </div>
                      </section>
                   </div>

                   <div className="lg:col-span-4 space-y-6">
                      <section className="bg-slate-900 text-white p-6 rounded-[2rem] border-4 border-orange-600 text-center shadow-xl">
                         <h3 className="text-xs font-black text-orange-400 mb-6 uppercase tracking-widest">النتيجة الحية</h3>
                         <div className="flex justify-center items-center gap-4">
                            <input type="number" className="w-16 h-16 bg-white text-slate-900 rounded-2xl text-center font-black text-2xl outline-none" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                            <span className="text-4xl font-black text-orange-600">:</span>
                            <input type="number" className="w-16 h-16 bg-white text-slate-900 rounded-2xl text-center font-black text-2xl outline-none" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                         </div>
                      </section>

                      <section className="bg-white p-6 rounded-[2rem] border-2 border-slate-900 shadow-sm space-y-4">
                         <div className="flex justify-between items-center">
                            <h3 className="font-black text-sm text-[#001F3F] flex items-center gap-2"><FileText size={18} className="text-blue-600"/> التقرير الفني</h3>
                            <button onClick={generateMatchTechnicalReport} disabled={generatingReport} className="text-blue-600 text-[9px] font-black flex items-center gap-1">
                               {generatingReport ? <Loader2 size={12} className="animate-spin"/> : <Sparkles size={12}/>} توليد ذكي
                            </button>
                         </div>
                         <textarea className="w-full bg-slate-50 border-2 border-slate-200 rounded-xl p-3 font-bold text-[11px] text-[#001F3F] outline-none focus:border-blue-600 min-h-[120px] resize-none" value={activeMatch.notes || ''} onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})} placeholder="تحليل الأداء الفني..."></textarea>
                      </section>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Sparkles, Loader2, BrainCircuit, Lock, Unlock
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';
import { GoogleGenAI } from "@google/genai";

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [showSingleMatchReport, setShowSingleMatchReport] = useState(false);
  const [aiSuggesting, setAiSuggesting] = useState(false);
  const [generatingReport, setGeneratingReport] = useState(false);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة'
  });

  // Define filteredMatches for the match list view
  const filteredMatches = useMemo(() => {
    return state.matches
      .filter(m => {
        if (restrictedCat) return m.category === restrictedCat;
        return state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter;
      })
      .sort((a, b) => b.date.localeCompare(a.date) || b.time.localeCompare(a.time));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const suggestLineup = async () => {
    if (!activeMatch || activeMatch.isCompleted) return;
    setAiSuggesting(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const players = state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch.category);
      const playersData = players.map(p => ({ id: p.id, name: p.name, number: p.number }));
      const prompt = `أقترح تشكيلة أساسية من 11 لاعباً فقط من هذه القائمة: ${JSON.stringify(playersData)}. رد بصيغة JSON array للمعرفات فقط: ["id1", "id2", ...]`;
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
      const suggestedIds = JSON.parse(response.text?.trim() || "[]");
      if (Array.isArray(suggestedIds)) {
        const newLineup = { ...activeMatch.lineup };
        suggestedIds.slice(0, 11).forEach((id, idx) => {
          const p = players.find(x => x.id === id);
          if (p) newLineup.starters[idx] = { playerId: p.id, name: p.name, number: p.number?.toString() || '', minutesPlayed: '90' };
        });
        setActiveMatch({ ...activeMatch, lineup: newLineup });
      }
    } catch (e) { console.error(e); } finally { setAiSuggesting(false); }
  };

  const generateMatchTechnicalReport = async () => {
    if (!activeMatch || activeMatch.isCompleted) return;
    setGeneratingReport(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const eventsSummary = activeMatch.events.map(e => `${e.type} في الدقيقة ${e.minute}`).join(', ');
      const prompt = `اكتب تقريراً فنياً مختصراً جداً لمباراة الكرامة ضد ${activeMatch.opponent}. الأحداث: ${eventsSummary}. النتيجة: ${activeMatch.ourScore}-${activeMatch.opponentScore}.`;
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
      setActiveMatch({ ...activeMatch, notes: response.text?.trim() });
    } catch (e) { console.error(e); } finally { setGeneratingReport(false); }
  };

  const updateActiveMatchLineup = (index: number, playerId: string, isStarter: boolean) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const person = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (isStarter) {
      if (!person) newLineup.starters[index] = { playerId: '', name: '', number: '', minutesPlayed: '90' };
      else newLineup.starters[index] = { playerId: person.id, name: person.name, number: person.number?.toString() || '', minutesPlayed: '90' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addSub = () => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    setActiveMatch({
      ...activeMatch,
      lineup: {
        ...activeMatch.lineup,
        subs: [...activeMatch.lineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0', substitutionMinute: '', replacedPlayerId: '' }]
      }
    });
  };

  const updateSub = (index: number, playerId: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const person = state.people.find(p => p.id === playerId);
    if (!person) return;
    const newSubs = [...activeMatch.lineup.subs];
    newSubs[index] = { ...newSubs[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const handleSubstitutionCalculation = (subIndex: number, replacedPlayerId: string, subMinute: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newLineup = { ...activeMatch.lineup };
    const minute = parseInt(subMinute) || 0;
    const starterIdx = newLineup.starters.findIndex(s => s.playerId === replacedPlayerId);
    if (starterIdx !== -1) {
      newLineup.starters[starterIdx].minutesPlayed = minute.toString();
    }
    newLineup.subs[subIndex].replacedPlayerId = replacedPlayerId;
    newLineup.subs[subIndex].substitutionMinute = subMinute;
    newLineup.subs[subIndex].minutesPlayed = (90 - minute).toString();
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const removeSub = (index: number) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newSubs = activeMatch.lineup.subs.filter((_, i) => i !== index);
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const saveMatchDetails = (lockStatus: boolean = false) => {
    if (!activeMatch || isViewer) return;
    const finalLockStatus = isManager ? lockStatus : activeMatch.isCompleted;
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, isCompleted: finalLockStatus } : m)
    }));
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [...activeMatch!.lineup.starters.map(s => s.playerId), ...activeMatch!.lineup.subs.map(s => s.playerId)].filter(id => id && id !== currentId);
    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  // أسلوب الخطوط الجديد
  const inputStyle = "w-full bg-slate-50 border-2 border-[#001F3F] rounded-xl py-2 px-3 font-bold text-[#001F3F] text-sm legible-text";
  const labelStyle = "text-[11px] font-black text-[#001F3F] mr-1 uppercase block mb-1";

  if (showSingleMatchReport && activeMatch) {
    return (
      <div className="fixed inset-0 bg-white z-[600] overflow-y-auto p-4 md:p-12 text-right dir-rtl">
        <div className="max-w-[210mm] mx-auto border-2 border-slate-900 p-6 print:border-1 bg-white min-h-screen shadow-2xl">
           <div className="no-print flex justify-between items-center mb-6 border-b pb-4">
              <button onClick={() => setShowSingleMatchReport(false)} className="text-slate-500 font-bold text-sm flex items-center gap-1"><ChevronRight size={16}/> إغلاق</button>
              <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2 shadow-lg"><Printer size={18}/> طباعة التقرير</button>
           </div>

           <div className="flex justify-between items-center border-b-2 border-slate-900 pb-4 mb-6">
              <div className="flex items-center gap-4">
                 <ClubLogo size={70} />
                 <div>
                    <h2 className="text-xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-xs font-bold text-orange-600">مكتب كرة القدم المركزي</p>
                 </div>
              </div>
              <div className="text-left">
                 <p className="text-lg font-black text-[#001F3F]">تقرير المباراة</p>
                 <p className="text-[10px] text-slate-400">{activeMatch.date}</p>
              </div>
           </div>

           <div className="bg-slate-50 p-4 rounded-2xl border border-slate-200 mb-6 flex justify-between items-center">
              <div>
                 <h3 className="text-lg font-black text-[#001F3F]">الكرامة × {activeMatch.opponent}</h3>
                 <p className="text-xs font-bold text-slate-600">{activeMatch.pitch} | {activeMatch.category}</p>
              </div>
              <p className="text-4xl font-black text-[#001F3F]">{activeMatch.ourScore} - {activeMatch.opponentScore}</p>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <section>
                 <h4 className="text-sm font-black border-r-4 border-blue-900 pr-2 mb-4">التشكيلة الأساسية</h4>
                 {activeMatch.lineup.starters.map((s, i) => (
                    <div key={i} className="flex justify-between p-2 border-b text-xs font-bold">
                       <span>{s.name || '---'}</span>
                       <span className="text-slate-400">#{s.number} | {s.minutesPlayed}د</span>
                    </div>
                 ))}
              </section>
              <section>
                 <h4 className="text-sm font-black border-r-4 border-emerald-600 pr-2 mb-4">التبديلات والأحداث</h4>
                 <div className="space-y-2">
                    {activeMatch.events.map((ev, i) => (
                       <div key={i} className="text-xs font-bold flex gap-2 items-center bg-slate-50 p-1.5 rounded-lg">
                          <span className="text-blue-900 w-6">{ev.minute}'</span>
                          <span className="text-sm">{ev.type==='goal'?'⚽':ev.type==='yellow'?'🟨':'🟥'}</span>
                          <span>{ev.player}</span>
                       </div>
                    ))}
                    <div className="mt-4 pt-4 border-t border-slate-100">
                       <p className="text-[10px] font-black text-slate-400 uppercase mb-2">قائمة البدلاء المشاركين:</p>
                       {activeMatch.lineup.subs.filter(s => s.playerId).map((s, i) => (
                          <div key={i} className="text-xs font-bold flex justify-between py-1">
                             <span>{s.name} (د.{s.substitutionMinute})</span>
                             <span className="text-emerald-700">{s.minutesPlayed}د</span>
                          </div>
                       ))}
                    </div>
                 </div>
              </section>
           </div>

           <section className="mt-8">
              <h4 className="text-sm font-black border-r-4 border-slate-900 pr-2 mb-2 uppercase">التقرير الفني</h4>
              <div className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-xs leading-relaxed italic font-bold">
                 {activeMatch.notes || "لا توجد ملاحظات مسجلة."}
              </div>
           </section>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 md:space-y-6 pb-24 px-1">
      <div className="bg-white p-4 rounded-2xl border-2 border-slate-900 flex justify-between items-center no-print shadow-sm">
        <h2 className="text-sm md:text-xl font-black text-[#001F3F] flex items-center gap-2">
          <Trophy size={20} className="text-orange-600" /> إدارة المباريات
        </h2>
        {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-4 py-2 rounded-xl font-black text-[11px] shadow-md border-b-4 border-black">جدولة مواجهة</button>}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-4 rounded-[2rem] border-2 border-slate-900 relative shadow-sm border-b-4 ${m.isCompleted ? 'border-red-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-4">
                <span className="bg-orange-600 text-white text-[8px] font-black px-2 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[9px] font-black text-slate-500">{m.date}</span>
             </div>
             <div className="text-center mb-4">
                <p className="text-3xl font-black text-[#001F3F]">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-sm text-slate-800 mt-1">{m.opponent}</p>
             </div>
             <button onClick={() => setActiveMatch(m)} className="w-full bg-[#001F3F] text-white py-2 rounded-xl font-black text-[10px] uppercase shadow-lg">
               {m.isCompleted ? 'عرض التقرير الفني' : 'التشكيل والتبديلات'}
             </button>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-xl z-[400] overflow-y-auto no-print">
           <div className="max-w-4xl mx-auto p-3 md:p-8 min-h-screen text-right" dir="rtl">
              <div className="bg-white rounded-[2.5rem] border-[6px] border-slate-900 p-5 md:p-10 shadow-2xl relative">

                <header className="flex flex-col md:flex-row justify-between items-center mb-8 border-b-4 border-slate-900 pb-6 gap-4">
                   <div className="text-center md:text-right">
                      <h2 className="text-xl md:text-3xl font-black text-[#001F3F] high-contrast-text">الكرامة × {activeMatch.opponent}</h2>
                      <div className="flex gap-2 mt-2 justify-center md:justify-start">
                         <span className="bg-slate-100 text-[#001F3F] text-[9px] font-black px-3 py-1 rounded-full border border-slate-900">{activeMatch.date}</span>
                         {activeMatch.isCompleted && <span className="bg-red-50 text-red-600 text-[9px] font-black px-3 py-1 rounded-full border border-red-200 flex items-center gap-1"><Lock size={10}/> مقفل</span>}
                      </div>
                   </div>
                   <div className="flex flex-wrap gap-2 justify-center">
                      <button onClick={() => setShowSingleMatchReport(true)} className="bg-white text-[#001F3F] border-2 border-[#001F3F] px-4 py-2 rounded-xl font-black text-[10px] shadow-sm flex items-center gap-2"><FileText size={16}/> التقرير</button>
                      {isManager && (
                        <button onClick={() => saveMatchDetails(!activeMatch.isCompleted)} className={`${activeMatch.isCompleted ? 'bg-red-600' : 'bg-emerald-600'} text-white px-4 py-2 rounded-xl font-black text-[10px] shadow-md flex items-center gap-2`}>
                          {activeMatch.isCompleted ? <Unlock size={16}/> : <Lock size={16}/>} {activeMatch.isCompleted ? 'فتح' : 'اعتماد وقفل'}
                        </button>
