                      {!activeMatch.isCompleted && <button onClick={() => saveMatchDetails(false)} className="bg-blue-600 text-white px-4 py-2 rounded-xl font-black text-[10px] shadow-md flex items-center gap-2"><Save size={16}/> حفظ مسودة</button>}
