import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, Calendar, Trophy, Clock, MapPin, AlertCircle, ChevronLeft, 
  ShieldAlert, Filter, Printer, FileText, ClipboardCheck, Zap, 
  Activity, TrendingUp, Search, X, BellRing, AlertTriangle, Timer, Edit, Save, Loader2, Package 
} from 'lucide-react';
import { AppState, Person, Match, TrainingSession } from '../types';

interface DashboardProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onMatchClick: (id: string) => void;
  onSessionClick: (id: string) => void;
  onPlayerClick?: (player: Person) => void;
}

const ActivityCountdown: React.FC<{ date: string; time: string }> = ({ date, time }) => {
  const [timeLeft, setTimeLeft] = useState<{ d: number; h: number; m: number; s: number } | null>(null);

  useEffect(() => {
    const calculateTime = () => {
      const target = new Date(`${date}T${time}`);
      const now = new Date();
      const diff = target.getTime() - now.getTime();
      if (diff <= 0) { setTimeLeft(null); return; }
      setTimeLeft({
        d: Math.floor(diff / (1000 * 60 * 60 * 24)),
        h: Math.floor((diff / (1000 * 60 * 60)) % 24),
        m: Math.floor((diff / (1000 * 60)) % 60),
        s: Math.floor((diff / 1000) % 60)
      });
    };
    calculateTime();
    const timer = setInterval(calculateTime, 1000);
    return () => clearInterval(timer);
  }, [date, time]);

  if (!timeLeft) {
    return (
      <div className="flex items-center gap-1.5 px-2 py-0.5 bg-emerald-100 text-emerald-700 rounded-lg animate-pulse border border-emerald-200">
        <Zap size={12} />
        <span className="text-[9px] font-black uppercase">جارٍ الآن</span>
      </div>
    );
  }

  return (
    <div className="flex gap-1.5 items-center text-[#001F3F] bg-slate-50 px-2 py-1 rounded-xl border border-slate-100 shadow-sm">
      <div className="flex flex-col items-center">
        <span className="text-xs font-black tabular-nums leading-none">{timeLeft.d}</span>
        <span className="text-[7px] font-bold opacity-50 uppercase">يوم</span>
      </div>
      <span className="font-bold opacity-20 text-[10px]">:</span>
      <div className="flex flex-col items-center">
        <span className="text-xs font-black tabular-nums leading-none">{String(timeLeft.h).padStart(2, '0')}</span>
        <span className="text-[7px] font-bold opacity-50 uppercase">سا</span>
      </div>
      <span className="font-bold opacity-20 text-[10px]">:</span>
      <div className="flex flex-col items-center">
        <span className="text-xs font-black tabular-nums leading-none">{String(timeLeft.m).padStart(2, '0')}</span>
        <span className="text-[7px] font-bold opacity-50 uppercase">د</span>
      </div>
      <span className="font-bold opacity-20 text-[10px]">:</span>
      <div className="flex flex-col items-center">
        <span className="text-xs font-black tabular-nums leading-none text-orange-600">{String(timeLeft.s).padStart(2, '0')}</span>
        <span className="text-[7px] font-bold opacity-50 uppercase">ث</span>
      </div>
    </div>
  );
};

const Dashboard: React.FC<DashboardProps> = ({ state, setState, onMatchClick, onSessionClick, onPlayerClick }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [quickEditMatch, setQuickEditMatch] = useState<Match | null>(null);
  const [isSavingEdit, setIsSavingEdit] = useState(false);

  const now = new Date();
  const todayStr = now.toLocaleDateString('en-CA');
  const currentTime = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
  const tomorrowStr = new Date(now.getTime() + 86400000).toLocaleDateString('en-CA');

  const globalFilter = state.globalCategoryFilter;
  const isManager = state.currentUser?.role === 'مدير';

  const upcomingMatches = useMemo(() => {
    return state.matches
      .filter(m => {
        const matchCat = (globalFilter === 'الكل' || m.category === globalFilter);
        if (!matchCat || m.isCompleted) return false;
        if (m.date < todayStr) return false;
        if (m.date === todayStr && m.time < currentTime) return false;
        return true;
      })
      .sort((a, b) => a.date.localeCompare(b.date) || a.time.localeCompare(b.time));
  }, [state.matches, globalFilter, todayStr, currentTime]);

  const upcomingSessions = useMemo(() => {
    return state.sessions
      .filter(s => {
        const sessCat = (globalFilter === 'الكل' || s.category === globalFilter);
        if (!sessCat || s.isCompleted) return false;
        if (s.date < todayStr) return false;
        if (s.date === todayStr && s.time < currentTime) return false;
        return true;
      })
      .sort((a, b) => a.date.localeCompare(b.date) || a.time.localeCompare(b.time));
  }, [state.sessions, globalFilter, todayStr, currentTime]);

  const hasMatchTomorrow = state.matches.some(m => m.date === tomorrowStr && !m.isCompleted && (globalFilter === 'الكل' || m.category === globalFilter));
  const hasSessionTomorrow = state.sessions.some(s => s.date === tomorrowStr && !s.isCompleted && (globalFilter === 'الكل' || s.category === globalFilter));

  const searchResults = searchTerm.length > 1 
    ? state.people.filter(p => p.name.includes(searchTerm) || p.number?.toString() === searchTerm).slice(0, 5)
    : [];

  const handleQuickSaveMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!quickEditMatch) return;
    setIsSavingEdit(true);
    setTimeout(() => {
      setState(prev => ({
        ...prev,
        matches: prev.matches.map(m => m.id === quickEditMatch.id ? quickEditMatch : m)
      }));
      setQuickEditMatch(null);
      setIsSavingEdit(false);
    }, 500);
  };

  const stats = [
    { label: 'الكوادر', value: state.people.filter(p => globalFilter === 'الكل' || p.category === globalFilter).length, icon: Users, color: '#001F3F', textColor: '#FF6B00' },
    { label: 'الأنشطة', value: upcomingMatches.length + upcomingSessions.length, icon: Activity, color: '#FF6B00', textColor: '#FFFFFF' },
    { label: 'المخزون', value: state.warehouse.length, icon: Package, color: '#FFFFFF', textColor: '#001F3F' },
  ];

  return (
    <div className="space-y-4 md:space-y-6 animate-in fade-in duration-700 px-1 md:px-0 pb-20">

      {/* قسم البحث وفلتر الفئات للمديرين */}
      <div className="relative z-[60] no-print max-w-4xl mx-auto space-y-3">
         <div className="flex flex-col md:flex-row gap-3">
            {/* مربع البحث */}
            <div className="flex-1 bg-white p-1 flex items-center border-2 border-[#001F3F] rounded-2xl shadow-sm focus-within:border-orange-600 transition-all">
               <div className="p-3"><Search size={22} className="text-[#001F3F]" /></div>
               <input 
                 type="text" 
                 placeholder="البحث السريع..." 
                 value={searchTerm}
                 onChange={e => setSearchTerm(e.target.value)}
                 className="flex-1 bg-transparent py-2.5 font-bold text-sm outline-none text-[#001F3F] placeholder:text-slate-300"
               />
               {searchTerm && <button onClick={() => setSearchTerm('')} className="p-3 text-slate-400 hover:text-red-500"><X size={18}/></button>}
            </div>

            {/* فلتر الفئات - يظهر للمديرين فقط */}
            {isManager && (
              <div className="md:w-64 bg-[#001F3F] p-1 rounded-2xl flex items-center border-2 border-orange-600 shadow-sm">
                 <div className="p-3 text-orange-400"><Filter size={20}/></div>
                 <select 
                   value={state.globalCategoryFilter}
                   onChange={e => setState(prev => ({ ...prev, globalCategoryFilter: e.target.value }))}
                   className="flex-1 bg-transparent py-2.5 font-black text-xs text-white outline-none cursor-pointer"
                 >
                    <option value="الكل" className="text-slate-900">كل الفئات</option>
                    {state.categories.map(c => <option key={c} value={c} className="text-slate-900">{c}</option>)}
                 </select>
              </div>
            )}
         </div>

         {searchResults.length > 0 && (
           <div className="absolute top-full left-0 right-0 mt-2 bg-white border-2 border-[#001F3F] rounded-2xl shadow-xl overflow-hidden animate-in slide-in-from-top-2 duration-300">
              {searchResults.map(p => (
                <button 
                  key={p.id} 
                  onClick={() => { onPlayerClick?.(p); setSearchTerm(''); }}
                  className="w-full p-4 flex items-center justify-between border-b border-slate-50 hover:bg-slate-50 text-right"
                >
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-[#001F3F] text-white rounded-xl flex items-center justify-center font-black text-sm border-2 border-orange-600">#{p.number || '0'}</div>
                    <div>
                      <p className="font-bold text-sm text-[#001F3F]">{p.name}</p>
                      <p className="text-[9px] font-bold text-orange-600 uppercase">{p.role} | {p.category}</p>
                    </div>
                  </div>
                  <ChevronLeft size={18} className="text-slate-200"/>
                </button>
              ))}
           </div>
         )}
      </div>

      {(hasMatchTomorrow || hasSessionTomorrow) && (
        <div className="bg-white border-2 border-orange-600 rounded-2xl p-6 shadow-md flex flex-col md:flex-row items-center justify-between gap-4 relative overflow-hidden">
           <div className="flex items-center gap-4 relative z-10">
              <div className="bg-orange-600 p-3 rounded-2xl text-white animate-bounce shadow-lg">
                 <BellRing size={24} />
              </div>
              <div className="text-right">
                 <h3 className="text-lg font-black text-[#001F3F]">مهام ميدانية لغدٍ</h3>
                 <div className="flex flex-wrap gap-2 mt-2">
                    {hasMatchTomorrow && <span className="bg-orange-600 text-white px-3 py-1 rounded-lg font-black text-[9px] uppercase">مباراة رسمية</span>}
                    {hasSessionTomorrow && <span className="bg-[#001F3F] text-white px-3 py-1 rounded-lg font-black text-[9px] uppercase">تمرين رياضي</span>}
                 </div>
              </div>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {stats.map((s, i) => (
          <div key={i} className="p-6 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm" style={{ backgroundColor: s.color, color: s.textColor }}>
             <s.icon size={28} className="mb-2" />
             <h3 className="text-[9px] font-black uppercase tracking-widest opacity-80">{s.label}</h3>
             <p className="text-2xl md:text-4xl font-black tabular-nums">{s.value}</p>
          </div>
        ))}
      </div>

      <div className="space-y-6">
        <section className="space-y-4">
          <div className="flex items-center justify-between border-r-4 border-orange-600 pr-3">
             <h2 className="text-xl md:text-2xl font-black text-white tracking-tighter uppercase high-contrast-text">الأنشطة القادمة</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 max-h-[600px] overflow-y-auto custom-scrollbar">
            {upcomingMatches.map(m => (
              <div key={m.id} className="bg-white p-6 rounded-2xl border-2 border-[#001F3F] shadow-sm relative overflow-hidden group border-b-8">
                 <div className="flex justify-between items-start mb-6">
                    <div className="flex items-center gap-3">
                       <div className="bg-orange-100 p-2.5 rounded-xl text-orange-600"><Trophy size={20}/></div>
                       <div>
                          <span className="bg-slate-900 text-white text-[8px] font-black px-2 py-0.5 rounded uppercase">{m.matchType}</span>
                          <span className="text-[10px] font-black text-slate-400 mt-0.5 block tabular-nums">{m.date}</span>
                       </div>
                    </div>
                    <ActivityCountdown date={m.date} time={m.time} />
                 </div>
                 <h4 className="text-lg font-black text-[#001F3F] mb-1 line-clamp-1 leading-tight">{m.opponent} × الكرامة</h4>
                 <p className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-1 mb-6">
                    <MapPin size={10}/> {m.pitch}
                 </p>
                 <button onClick={() => onMatchClick(m.id)} className="w-full bg-[#001F3F] text-white py-3 rounded-xl font-black text-[10px] uppercase shadow-md flex items-center justify-center gap-2">
                    عرض التقرير <ChevronLeft size={14}/>
                 </button>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
};

export default Dashboard;

