      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });
      setAiAnalysis(response.text || "فشل توليد التحليل.");
    } catch (error: any) {
      setAiAnalysis("خطأ في الاتصال بخادم الذكاء الاصطناعي.");
