                                     {ev.type === 'assist' && <Zap className="text-blue-600" size={16}/>}
                                     {ev.type === 'yellow' && <div className="w-3 h-5 bg-yellow-400 rounded-sm"></div>}
                                     {ev.type === 'red' && <div className="w-3 h-5 bg-red-600 rounded-sm"></div>}
