import { generateUUID } from '../App';

interface TechnicalReportsProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const TechnicalReports: React.FC<TechnicalReportsProps> = ({ state, setState, addLog }) => {
  const [activeSubTab, setActiveSubTab] = useState<'matches' | 'monthly'>('matches');
  const [selectedMatchId, setSelectedMatchId] = useState('');
  const [selectedMemberId, setSelectedMemberId] = useState('');
  const [loading, setLoading] = useState(false);

  const [ratingData, setRatingData] = useState<Partial<TechnicalReport>>({
    rating: 3,
    metrics: { physical: 5, tactical: 5, technical: 5, mental: 5, speed: 5 }
  });

  const isViewer = state.currentUser?.role === 'مشاهد';
  const restrictedCat = state.currentUser?.restrictedCategory;

  const completedMatches = useMemo(() => 
    state.matches.filter(m => m.isCompleted && (restrictedCat ? m.category === restrictedCat : true)),
    [state.matches, restrictedCat]
  );

  const eligibleMembers = useMemo(() => 
    state.people.filter(p => (restrictedCat ? p.category === restrictedCat : true)),
    [state.people, restrictedCat]
  );

  const selectedMatch = completedMatches.find(m => m.id === selectedMatchId);
  const playersInMatch = useMemo(() => {
    if (!selectedMatch) return [];
    const ids = [
      ...selectedMatch.lineup.starters.map(s => s.playerId),
      ...selectedMatch.lineup.subs.map(s => s.playerId)
    ];
    return state.people.filter(p => ids.includes(p.id));
  }, [selectedMatch, state.people]);

  const saveReport = async (targetId: string, matchId?: string) => {
    if (isViewer) return;
    setLoading(true);
    const newReport: TechnicalReport = {
      id: generateUUID(),
      targetId,
      matchId,
      type: activeSubTab === 'matches' ? 'match_rating' : 'monthly_feedback',
      raterId: state.currentUser?.id || 'unknown',
      date: new Date().toISOString().split('T')[0],
      rating: ratingData.rating || 3,
      note: ratingData.note,
      metrics: ratingData.metrics as any
    };

    setState(prev => ({
      ...prev,
      technicalReports: [newReport, ...prev.technicalReports]
    }));

    addLog?.('تقرير فني', `تم تسجيل تقييم لـ ${state.people.find(p => p.id === targetId)?.name}`, 'success');
