    <div className="flex gap-1">
      {[1, 2, 3, 4, 5].map(s => (
        <button key={s} onClick={() => onChange(s)} className={`transition-all ${s <= value ? 'text-orange-500' : 'text-slate-200'}`}>
          <Star size={24} fill={s <= value ? "currentColor" : "none"} />
        </button>
