  );

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="flex items-center gap-4">
           <div className="bg-[#001F3F] p-3 rounded-2xl text-white">
             <Activity size={28} />
           </div>
           <div>
             <h2 className="text-xl font-black text-slate-900 uppercase">مركز التقارير الفنية</h2>
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">رصد التطور الفني والتقييم الرقمي المستمر</p>
           </div>
