             className={`px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeSubTab === 'matches' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}>
             تقييم المباريات
           </button>
           <button onClick={() => setActiveSubTab('monthly')} 
             className={`px-6 py-2.5 rounded-xl font-black text-xs transition-all ${activeSubTab === 'monthly' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}>
             ملاحظات تطويرية
           </button>
        </div>
      </div>

      {activeSubTab === 'matches' ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
           <div className="bg-white p-8 rounded-[3rem] border-2 border-slate-900 shadow-sm space-y-6">
              <h3 className="font-black text-lg flex items-center gap-2 border-r-4 border-orange-600 pr-3">المواجهة</h3>
              <select value={selectedMatchId} onChange={e => setSelectedMatchId(e.target.value)}
                className="w-full bg-slate-50 border-2 border-slate-200 rounded-xl py-3 px-4 font-black text-sm outline-none">
                <option value="">-- اختر مباراة مكتملة --</option>
