              {selectedMatch && (
                <div className="bg-slate-50 p-4 rounded-2xl border-2 border-slate-100 space-y-3">
                  <p className="text-[10px] font-black text-slate-400 uppercase">قائمة المشاركين</p>
                  <div className="max-h-[300px] overflow-y-auto space-y-2 custom-scrollbar">
                    {playersInMatch.map(p => (
                      <button key={p.id} onClick={() => setSelectedMemberId(p.id)}
                        className={`w-full text-right p-3 rounded-xl border-2 transition-all flex justify-between items-center ${selectedMemberId === p.id ? 'bg-[#001F3F] text-white border-orange-600' : 'bg-white text-slate-700 border-slate-100'}`}>
