                   </div>
                   <div className="space-y-6">
                      <label className="text-[10px] font-black text-slate-400 uppercase block mb-3">ملاحظات المدرب حول الأداء</label>
                      <textarea value={ratingData.note || ''} onChange={e => setRatingData({...ratingData, note: e.target.value})}
                        placeholder="تحدث عن نقاط التطور أو القوة في هذه المباراة..."
