const RadarChart = ({ metrics }: { metrics: TechnicalReport['metrics'] }) => {
  if (!metrics) return null;

  const size = 300;
  const center = size / 2;
  const radius = center * 0.8;
  const keys = ['physical', 'tactical', 'technical', 'mental', 'speed'];
  const labels = ['بدني', 'تكتيكي', 'تقني', 'ذهني', 'سرعة'];

  const getPoint = (value: number, index: number) => {
    const angle = (Math.PI * 2 * index) / keys.length - Math.PI / 2;
    const r = (value / 10) * radius;
    return {
      x: center + r * Math.cos(angle),
      y: center + r * Math.sin(angle)
    };
  };

  const points = keys.map((key, i) => getPoint((metrics as any)[key], i));
  const polygonPoints = points.map(p => `${p.x},${p.y}`).join(' ');

  return (
    <div className="relative flex items-center justify-center bg-white p-4 rounded-[2rem] border-2 border-slate-100 shadow-inner">
      <svg width={size} height={size} className="overflow-visible">
        {/* Grids */}
        {[2, 4, 6, 8, 10].map(v => (
          <polygon key={v} points={keys.map((_, i) => {
            const p = getPoint(v, i);
            return `${p.x},${p.y}`;
          }).join(' ')} fill="none" stroke="#e2e8f0" strokeWidth="1" />
        ))}
        {/* Axes */}
        {keys.map((_, i) => {
          const p = getPoint(10, i);
          return <line key={i} x1={center} y1={center} x2={p.x} y2={p.y} stroke="#cbd5e1" strokeDasharray="4" />;
        })}
        {/* Data Polygon */}
        <polygon points={polygonPoints} fill="rgba(255, 107, 0, 0.2)" stroke="#FF6B00" strokeWidth="3" />
        {/* Points */}
        {points.map((p, i) => (
          <circle key={i} cx={p.x} cy={p.y} r="4" fill="#FF6B00" />
        ))}
        {/* Labels */}
        {labels.map((label, i) => {
          const p = getPoint(11.5, i);
          return <text key={i} x={p.x} y={p.y} textAnchor="middle" className="text-[10px] font-black fill-[#001F3F]">{label}</text>;
        })}
      </svg>
    </div>
  );
};

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  if (!player || !state.currentUser) return null;

  const technicalReports = useMemo(() => 
    state.technicalReports.filter(r => r.targetId === player.id).sort((a,b) => b.date.localeCompare(a.date)),
    [state.technicalReports, player]
  );

  const avgMetrics = useMemo(() => {
    const matchReports = technicalReports.filter(r => r.type === 'match_rating' && r.metrics);
    if (matchReports.length === 0) return null;
    const totals = { physical: 0, tactical: 0, technical: 0, mental: 0, speed: 0 };
    matchReports.forEach(r => {
      totals.physical += r.metrics?.physical || 0;
      totals.tactical += r.metrics?.tactical || 0;
      totals.technical += r.metrics?.technical || 0;
      totals.mental += r.metrics?.mental || 0;
      totals.speed += r.metrics?.speed || 0;
    });
    const count = matchReports.length;
    return {
      physical: totals.physical / count,
      tactical: totals.tactical / count,
      technical: totals.technical / count,
      mental: totals.mental / count,
      speed: totals.speed / count,
    };
  }, [technicalReports]);

  const matchStats = useMemo(() => {
    let officialMins = 0;
    let friendlyMins = 0;
    const statsList = state.matches.filter(m => m.isCompleted).map(m => {
      const starter = m.lineup.starters.find(s => s.playerId === player.id);
      const sub = m.lineup.subs.find(s => s.playerId === player.id);
      let mins = 0;
      if (starter) mins = parseInt(starter.minutesPlayed || '90') || 0;
      else if (sub) mins = parseInt(sub.minutesPlayed || '0') || 0;
      if (['دوري', 'كأس'].includes(m.matchType)) officialMins += mins; else friendlyMins += mins;
      const goals = m.events.filter(e => e.type === 'goal' && e.player === player.id).length;
      return { mins, goals, played: !!(starter || sub), opponent: m.opponent, date: m.date };
    }).filter(s => s.played);
    return { officialMins, friendlyMins, list: statsList };
  }, [state.matches, player]);

  const handleGenerateAiAnalysis = async () => {
