           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center">
             <Star className="text-orange-500 mb-1" size={18}/><span className="text-[8px] font-black text-slate-900">متوسط التقييم</span>
             {/* Fix: Cast average calculation result explicitly as number to use toFixed safely */}
             <p className="text-xl font-black">{technicalReports.length > 0 ? (Number(technicalReports.reduce((a, b) => a + b.rating, 0) / technicalReports.length)).toFixed(1) : '-'}/5</p>
