                {avgMetrics && (
                  <div className="grid grid-cols-2 gap-2 mt-6">
                    {Object.entries(avgMetrics).map(([k,v]) => (
                      <div key={k} className="flex justify-between items-center p-2 bg-slate-50 rounded-lg border border-slate-100">
                        <span className="text-[10px] font-black uppercase text-slate-400">{k}</span>
                        {/* Fix: Cast mapped value v as number to resolve the property 'toFixed' does not exist on type 'unknown' error */}
                        <span className="text-xs font-black text-[#001F3F]">{(v as number).toFixed(1)}</span>
                      </div>
                    ))}
                  </div>
                )}
             </div>
             <div className="shrink-0">
                {avgMetrics ? <RadarChart metrics={avgMetrics as any} /> : <div className="p-20 text-slate-300 font-black italic">لا توجد بيانات رادار كافية</div>}
             </div>
