    syncManager.current.isDeleting = true;
    setSyncStatus('syncing');
    try {
      const { error } = await supabase.from('sessions').delete().eq('id', id);
      if (error) throw error;
      setState(prev => ({ ...prev, sessions: prev.sessions.filter(s => s.id !== id) }));
      addLog('حذف تمرين', 'تم الحذف بنجاح من السحاب', 'success');
    } catch (err) {
      alert('خطأ في الاتصال بالسحاب');
    } finally {
      setTimeout(() => { syncManager.current.isDeleting = false; }, 3000);
    }
  };

  useEffect(() => {
    if (!state.currentUser) return;
    fetchData();
    const channel = supabase.channel('cloud-v6-sync-final')
      .on('postgres_changes', { event: '*', schema: 'public' }, () => {
        if (!syncManager.current.isPushing && !syncManager.current.isDeleting) {
          fetchData();
        }
      })
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [state.currentUser, fetchData]);

