          <ChevronRight size={20} /> رجوع للمديرية
        </button>
        <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-2xl font-black text-sm flex items-center gap-2 border-b-4 border-black">
          <Printer size={20} /> تصدير التقرير
        </button>
      </div>

      <div className="solid-panel overflow-hidden border-4 border-[#001F3F]">
        <div className="bg-[#001F3F] h-40 relative">
          <div className="absolute -bottom-14 right-16 flex items-end gap-10">
            <div className="w-48 h-48 bg-white rounded-[3rem] border-[10px] border-white flex items-center justify-center font-black text-8xl text-[#001F3F] shadow-2xl relative z-10">
               {player.name.charAt(0)}
               <div className="absolute -top-4 -left-4 bg-orange-600 text-white w-12 h-12 rounded-full flex items-center justify-center text-xl border-4 border-white">#{player.number}</div>
            </div>
            <div className="mb-4">
              <h1 className="text-4xl font-black text-white drop-shadow-lg leading-tight">{player.name}</h1>
              <div className="flex gap-3 mt-2">
                 <span className="bg-orange-600 text-white text-[12px] font-black px-6 py-1.5 rounded-xl border-2 border-white uppercase">{player.role}</span>
                 <span className="bg-blue-600 text-white text-[12px] font-black px-6 py-1.5 rounded-xl border-2 border-white uppercase">{player.category}</span>
              </div>
            </div>
          </div>
        </div>
        <div className="h-24"></div>
        <div className="px-16 pb-10 grid grid-cols-2 md:grid-cols-4 gap-4">
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center">
