          {/* Recent Technical Reports */}
          <div className="bg-white p-8 rounded-[2.5rem] border-2 border-slate-900 shadow-sm">
             <h3 className="text-xl font-black mb-6 flex items-center gap-3"><StickyNote className="text-orange-600"/> سجل الملاحظات الفنية والتقييمات</h3>
             <div className="space-y-4">
                {technicalReports.map(report => (
                  <div key={report.id} className="p-5 bg-slate-50 rounded-2xl border-2 border-slate-100 group relative">
                    <div className="flex justify-between items-start mb-2">
                       <div className="flex gap-1 text-orange-500">
                          {[...Array(report.rating)].map((_,i) => <Star key={i} size={14} fill="currentColor"/>)}
                       </div>
                       <span className="text-[10px] font-black text-slate-400 tabular-nums">{report.date}</span>
                    </div>
                    <p className="text-sm font-bold text-slate-800 leading-relaxed italic">"{report.note || 'بدون ملاحظات مكتوبة'}"</p>
                    <div className="mt-2 text-[9px] font-black text-slate-400 uppercase tracking-widest">{report.type === 'match_rating' ? 'تقييم مباراة' : 'ملاحظة تطويرية'}</div>
                  </div>
                ))}
                {technicalReports.length === 0 && <p className="text-center py-10 text-slate-300 font-black italic">لا توجد تقارير فنية مسجلة لهذا اللاعب</p>}
             </div>
          </div>
        </div>

        {/* Sidebar Data */}
        <div className="space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border-2 border-slate-900 shadow-md space-y-4">
             <h4 className="font-black text-[#001F3F] flex items-center gap-2 border-r-4 border-orange-600 pr-3">بيانات الهوية</h4>
             <div className="space-y-3">
                {[
                  { l: 'الأب', v: player.fatherName },
                  { l: 'الأم', v: player.motherName },
                  { l: 'الميلاد', v: player.birthDate },
                  { l: 'الرقم الوطني', v: player.nationalId },
                  { l: 'الاتحادي', v: player.federalNumber },
                ].map((item, i) => (
                  <div key={i} className="flex justify-between border-b border-slate-100 pb-1 text-xs">
                    <span className="text-slate-400 font-bold">{item.l}</span>
                    <span className="font-black">{item.v || '---'}</span>
                  </div>
                ))}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PlayerReport;
